BEGIN;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"be01db60-c4b1-4ca0-9833-13b0f42f5e63": {"definition": "A stretch fabric wall system is a site-assembled acoustic finish in which acoustically transparent fabric is stretched into and tucked behind a perimeter track frame fixed to the wall, concealing an infill of porous absorbent (typically mineral wool or glass fibre) in the cavity. It turns an entire wall into a seamless broadband porous absorber behind a flat decorative surface, and is field-fabricated to any dimension and around obstructions.", "plain_english": "A stretch fabric wall system covers a wall with cloth pulled tight into an edge track. Soft absorbing material sits behind the cloth. The cloth lets sound through, so the material soaks it up. It gives a smooth, neat wall that hides the treatment.", "purpose_function": "It exists to turn a whole wall into a hidden broadband absorber with a clean, seamless finish. The perimeter track lets installers stretch fabric neatly to any size and shape on site.", "practical_application": "An installer fixes perimeter track around a wall, packs the cavity with mineral wool, and stretches fabric into the track to absorb reflections in a studio, control room, or conference space.", "category": "Absorber system", "related_terms": ["Fabric-wrapped panel", "Acoustically transparent fabric", "Porous absorber", "Speaker cloth", "Flow resistance", "False wall"], "common_mistakes": ["Using a fabric with too high airflow resistance, which reflects sound and reduces the absorption behind it.", "Leaving the cavity empty or under-filled, so the wall reflects rather than absorbs.", "Assuming the fabric itself absorbs the sound, when the porous infill does the absorbing."], "scenario_contexts": ["Finishing a studio or control-room wall as a seamless broadband absorber.", "Treating a conference room or auditorium wall for speech clarity.", "Hiding absorbent and cabling behind a decorative fabric surface."]}, "07393dd2-3208-4db9-8b55-6710919a297a": {"definition": "A suspended acoustic ceiling is a secondary ceiling formed by laying sound-absorptive tiles or panels into a metal grid hung below the structural deck, leaving a plenum airspace above. The tiles (commonly mineral fibre or glass fibre) provide broadband absorption rated by the Noise Reduction Coefficient (ASTM C423), while the assembly also conceals services and can limit sound passing between adjacent rooms through the shared plenum (rated by Ceiling Attenuation Class, ASTM E1414).", "plain_english": "A suspended acoustic ceiling hangs below the real ceiling on a metal grid. Soft tiles drop into the grid and soak up sound. The gap above the tiles hides pipes and wires. It cuts echo and noise in offices, schools, and studios.", "purpose_function": "It exists to lower echo and noise by adding overhead absorption, while hiding ducts, pipes, and wiring in the plenum above. The tile type and plenum depth set how much sound it absorbs.", "practical_application": "A fit-out crew lays mineral-fibre tiles into a T-bar grid to control reverberation in an office, classroom, or vocal booth and to conceal building services.", "category": "Ceiling treatment", "related_terms": ["Ceiling cloud", "Porous absorber", "Plenum", "Noise reduction coefficient (NRC)", "Overhead absorber", "Reverberation time"], "common_mistakes": ["Choosing decorative tiles with low absorption and expecting good echo control.", "Ignoring the plenum path, so noise passes over a partition into the next room.", "Assuming a suspended ceiling blocks sound between floors, when the tiles mainly absorb rather than isolate."], "scenario_contexts": ["Controlling reverberation in an open-plan office.", "Adding overhead absorption in a project studio or booth.", "Reducing sound leakage between rooms that share a ceiling plenum."]}, "5df21193-8873-4455-ac18-d96b7aea2eac": {"definition": "Symmetrical treatment is the practice of arranging acoustic materials and room boundaries so that the left and right halves of the room, about the listener's front-facing centre axis, are acoustically identical. Matching side-wall reflection points, absorption, and diffusion on both sides preserves accurate stereo imaging by ensuring the two loudspeakers' early reflections arrive at the listener with equal timing and level.", "plain_english": "Symmetrical treatment means the left and right sides of the room match each other. You put the same panels in the same spots on both sides. Then sound from the two speakers bounces the same way on each side. This keeps the stereo image centered and even.", "purpose_function": "It exists to keep stereo imaging accurate and balanced by giving both loudspeakers matched acoustic surroundings. Unequal sides shift or smear the phantom centre and skew the stereo picture.", "practical_application": "When treating a control room, a technician mirrors panels, diffusers, and furniture left-to-right about the listening axis so the mix translates correctly.", "category": "Layout principle", "related_terms": ["Early reflections", "First reflection point", "Reflection-free zone", "Stereo imaging", "Listening position", "Mirror point"], "common_mistakes": ["Treating one side wall but not the other, which pulls the stereo image toward the reflective side.", "Placing a desk, rack, or door on only one side and ignoring the resulting acoustic imbalance.", "Focusing only on how much is absorbed while overlooking left-right matching."], "scenario_contexts": ["Laying out a stereo control room or mix room.", "Positioning first-reflection absorbers equally on both side walls.", "Diagnosing a stereo image that leans to one side."]}, "6e64300f-d538-47b9-87f4-773879a88e62": {"definition": "A triangular panel is an acoustic absorber or reflector cut to a triangular (usually right-angled) outline. In room treatment it is most often a right-triangle porous absorber mounted diagonally across a wall-to-wall corner, spanning the corner so a triangular air cavity is left behind it, which raises low-frequency absorption in the corner where modal sound pressure is highest.", "plain_english": "A triangular panel is an absorber shaped like a triangle. It is often set across a corner where two walls meet. This leaves an air gap in the corner behind it. Corners hold the most low-sound energy, so the panel traps bass well there.", "purpose_function": "Its shape lets it fit or span a corner and use the corner air gap to boost low-frequency absorption. It exists to treat awkward corner and angled spaces that rectangular panels do not suit.", "practical_application": "A technician mounts triangular absorber panels diagonally across the vertical corners of a room to act as straddle-mounted bass traps.", "category": "Corner treatment", "related_terms": ["Bass trap", "Corner treatment", "Trihedral corner treatment", "Air cavity", "Porous absorber", "Stand-off mount"], "common_mistakes": ["Assuming the triangular shape alone traps bass, when the corner air gap behind it does much of the work.", "Mounting it tight into the corner with no air gap, losing the low-frequency benefit.", "Using thin triangular panels and expecting deep bass control."], "scenario_contexts": ["Straddling a wall-to-wall corner as a bass trap.", "Fitting an absorber into a triangular soffit or angled space.", "Building faceted, angled surfaces from triangular panels."]}, "0d033a33-dc22-4f06-af12-79160e0fc74e": {"definition": "Trihedral corner treatment is the placement of acoustic absorption, usually low-frequency bass trapping, at a trihedral corner: the junction where three room surfaces (two walls and the floor, or two walls and the ceiling) meet. Because all axial room modes reach a pressure maximum at these tri-corners, absorbers sited there act on the widest range of low-frequency modes, making them the most effective single locations for bass traps.", "plain_english": "A trihedral corner is where three surfaces meet, like two walls and the ceiling. Low sounds pile up strongest at these points. So this is the best place to put bass traps. Treating these corners tames boomy, uneven bass in a room.", "purpose_function": "It targets the tri-corners where every axial room mode peaks, so a trap there absorbs the widest range of bass problems. It exists to control uneven, boomy low-frequency response efficiently.", "practical_application": "An installer stacks floor-to-ceiling bass traps into the vertical wall-wall corners and the wall-wall-ceiling junctions to smooth a room's low end.", "category": "Corner treatment", "related_terms": ["Bass trap", "Room mode", "Corner treatment", "Axial mode", "Triangular panel", "Pressure maximum"], "common_mistakes": ["Treating only flat mid-wall areas and skipping the corners where bass builds up most.", "Using thin porous panels in the corner and expecting strong low-frequency control.", "Assuming one corner trap fixes every mode, when several corners usually need treatment."], "scenario_contexts": ["Placing bass traps at wall-wall-ceiling and wall-wall-floor junctions.", "Smoothing modal bass buildup in a small control room.", "Prioritising the most effective locations when treatment budget is limited."]}, "cedd78a2-6b70-4efa-9d13-8da2c25594de": {"definition": "A variable acoustic panel is a treatment element whose acoustic effect can be physically changed, for example by rotating, flipping, sliding, or hinging a panel that is absorptive on one face and reflective or diffusive on the other. Adjusting these panels changes a room's absorption, and therefore its reverberation time and liveness, so one space can be tuned to suit different program material.", "plain_english": "A variable acoustic panel can change how it treats sound. One side may soak up sound while the other bounces it back. You rotate or flip the panel to switch. This lets one room be made livelier or deader as needed.", "purpose_function": "It exists to let a single room change its reverberation and liveness on demand, rather than being fixed to one acoustic. Flipping or moving the panels adjusts how much sound is absorbed.", "practical_application": "In a live room or multipurpose space, an engineer turns variable panels to their absorptive side for a dry, tight sound or their reflective side for a livelier one.", "category": "Variable acoustics", "related_terms": ["Variable reflector", "Reverberation time", "Absorption coefficient", "Diffuser", "Reflective diffuser", "Acoustic banner"], "common_mistakes": ["Expecting a large reverberation change from only a few small panels.", "Forgetting that the absorptive side mainly affects mid and high frequencies, not deep bass.", "Leaving panels half-set, so the room's acoustic is uneven and inconsistent."], "scenario_contexts": ["Switching a live room between dry and lively settings.", "Tuning a multipurpose room for speech versus music.", "Adjusting a tracking room's ambience for different instruments."]}, "479bee86-a4d0-4ee3-a34e-3ac1f6c7f85c": {"definition": "A variable reflector is an adjustable reflective surface whose angle, height, or deployment can be changed to alter the direction, timing, and strength of sound reflections in a space. Examples include movable overhead reflector panels and rotatable elements with a hard reflective face, used to tune early reflections and liveness for different uses of a room or stage.", "plain_english": "A variable reflector is a hard surface you can move or angle. Changing it aims sound reflections in different directions. Raising, lowering, or turning it changes how lively the room feels. This lets one space be tuned for speech or music.", "purpose_function": "It exists to let a room's reflection pattern be tuned rather than left fixed, controlling early reflections and liveness. Moving it changes where and how strongly sound bounces to listeners or performers.", "practical_application": "A hall's crew raises, lowers, or angles overhead variable reflectors to set the right early reflections for an orchestra or for amplified speech.", "category": "Variable acoustics", "related_terms": ["Variable acoustic panel", "Stage reflector", "Overhead canopy", "Early reflections", "Specular reflection", "Reverberation time"], "common_mistakes": ["Confusing a variable reflector with an absorber, when it redirects sound rather than removing it.", "Setting overhead reflectors too high, so reflections arrive late and reduce clarity.", "Assuming small reflectors redirect low frequencies, which pass around panels that are too small."], "scenario_contexts": ["Adjusting overhead reflectors in a concert hall for different programs.", "Tuning stage reflections so performers hear each other.", "Changing a room's liveness without adding or removing absorption."]}, "1bec2efa-bef5-4eb4-b2c1-8c6a30fcf6c1": {"definition": "A velocity trap is a low-frequency absorber that works on the particle-velocity component of the sound field, using porous, resistive material placed where air particle velocity is high, typically spaced off the boundary or spanning a corner with an air gap behind it. Because particle velocity peaks about a quarter-wavelength from a rigid boundary, positioning porous material there (rather than tight to the wall, where velocity approaches zero) maximises frictional low-frequency absorption; this contrasts with pressure-operated membrane absorbers that work best at boundaries.", "plain_english": "Air both pushes and moves as sound passes by. A velocity trap uses soft, airy material where the air moves fastest. That spot is a short way out from the wall, not right against it. Placing the material there, with an air gap behind, soaks up low sounds best.", "purpose_function": "It exists to absorb low frequencies efficiently by placing resistive material in the high-velocity region of the sound field. This is why porous bass traps use an air gap or corner standoff instead of sitting flat on the wall.", "practical_application": "A technician mounts porous bass traps out from the wall or across corners, leaving an air gap, so the material sits in the high-velocity zone and traps more bass.", "category": "Bass trapping", "related_terms": ["Porous absorber", "Bass trap", "Particle velocity", "Stand-off mount", "Air cavity", "Pressure trap"], "common_mistakes": ["Mounting porous material flat against the wall, where particle velocity is low, and getting weak bass absorption.", "Confusing a velocity (porous) trap with a pressure-based membrane trap.", "Assuming a thin porous panel traps deep bass without an air gap or corner placement."], "scenario_contexts": ["Placing porous bass traps with an air gap for stronger low-frequency absorption.", "Choosing between porous (velocity) and membrane (pressure) trapping for a room mode.", "Explaining why absorbers work better when spaced off the wall."]}, "5c28727b-f3fc-4006-a2c8-affd57dcc61f": {"definition": "A vertical ceiling baffle is a sound-absorptive panel hung edge-down from the ceiling, suspended vertically and usually installed in parallel rows or arrays. Because both faces are exposed to the sound field, each baffle absorbs on both sides, giving high absorption per unit; baffles are widely used to reduce reverberation and noise in gyms, pools, factories, and other large or high-ceilinged spaces where wall or flat-ceiling treatment is impractical.", "plain_english": "A vertical ceiling baffle is a soft panel hung straight down from the ceiling, like a banner. Rows of them fill the ceiling area. Because sound hits both sides, each one soaks up a lot. They cut echo in gyms, pools, and factories.", "purpose_function": "It exists to add a large amount of absorption overhead where flat ceiling or wall treatment is not enough or not possible. Hanging vertically exposes both faces, so each baffle absorbs on both sides.", "practical_application": "An installer hangs rows of vertical baffles from the deck of a gym or plant room to cut reverberation and lower noise levels.", "category": "Ceiling treatment", "related_terms": ["Ceiling cloud", "Suspended acoustic ceiling", "Porous absorber", "Overhead absorber", "Reverberation time", "Absorption coefficient"], "common_mistakes": ["Hanging too few baffles or spacing them too far apart to control reverberation.", "Assuming baffles block sound between areas, when they absorb rather than isolate.", "Ignoring that low-frequency control needs thickness and depth, not just surface area."], "scenario_contexts": ["Reducing reverberation in a gymnasium or swimming-pool hall.", "Lowering noise in a factory or plant room with a high deck.", "Adding overhead absorption where a flat cloud cannot be mounted."]}, "8e71cc81-abea-4d7d-9e4d-e63f138b653b": {"definition": "A wall anchor system is the set of fasteners and hardware used to fix acoustic treatment (panels, traps, clouds, or their frames and rails) securely to a wall, chosen to match the wall substrate - for example wood screws into studs, toggle or expansion anchors for hollow drywall, and masonry anchors into concrete or brick - so the treatment's weight is safely transferred into the structure. It typically comprises the anchor, the fixing screw or bolt, and often an intermediate bracket, rail, or French cleat.", "plain_english": "A wall anchor system is the hardware that holds acoustic panels on a wall. The right anchor depends on what the wall is made of. Screws go into wood studs. Special anchors grip hollow drywall or concrete. This keeps heavy panels from falling.", "purpose_function": "It transfers the weight of the treatment into the wall structure so panels stay put and do not fall. Matching the anchor to the substrate prevents the fixing from pulling out.", "practical_application": "A technician locates the studs, selects anchors rated for the panel weight and wall type, then mounts brackets or cleats to hang the treatment level and secure.", "category": "Mounting method", "related_terms": ["Stand-off mount", "French cleat", "Impaling clip", "Wall panel", "Acoustic cloud", "Wall treatments"], "common_mistakes": ["UNSAFE: Screwing a heavy panel or bass trap into drywall alone, with no rated hollow-wall anchor and no stud behind it, so the fixing pulls out and the treatment falls.", "UNSAFE: Using an anchor not rated for the panel's weight or the wall substrate, such as a light plastic plug in crumbling masonry.", "Assuming every wall has studs at a fixed spacing and drilling blind instead of locating the framing.", "Ignoring the added weight of dense mineral-wool or membrane traps when sizing the anchors."], "scenario_contexts": ["Hanging first-reflection panels on a drywall control-room wall using toggle anchors and a French cleat.", "Fixing a heavy corner bass trap into a concrete wall with masonry anchors.", "Installing a rail system so panels can be repositioned later without drilling new holes."]}, "f89cba21-40cb-4c16-9726-70ec267b8d8d": {"definition": "A wall panel is a prefabricated acoustic treatment element mounted on a wall surface, typically an absorptive core (such as rigid mineral wool or fibreglass) wrapped in an acoustically transparent fabric within a frame, used to absorb sound reflections. Its absorption depends on core thickness, density and flow resistivity, and any air gap behind it, giving broadband mid and high-frequency absorption that reaches lower in frequency as thickness and gap increase.", "plain_english": "A wall panel is a framed pad of absorbing material you fix to a wall. It soaks up sound that hits the wall instead of letting it bounce back. Thicker panels, or ones spaced off the wall, also catch lower notes.", "purpose_function": "It reduces reflections and reverberation from wall surfaces to control clarity and flutter echo. Panels are the basic building block of most room-treatment schemes.", "practical_application": "An engineer places panels at first-reflection points and across large bare wall areas to tame reflections and shorten reverberation time.", "category": "Acoustic panel", "related_terms": ["Wall treatments", "Porous absorber", "Mirror point treatment", "First reflection", "Reverberation time", "Wall anchor system"], "common_mistakes": ["Thinking thin foam or fabric panels absorb bass, when thin porous panels only work at mid and high frequencies.", "Covering a panel's face with a non-porous fabric or paint, which reflects highs and defeats the absorption.", "Spreading panels evenly for looks instead of placing them where the reflections actually occur."], "scenario_contexts": ["Treating the side walls of a control room at the mirror points.", "Adding panels to a bare-walled live room to shorten reverberation.", "Mounting panels with an air gap behind them to improve low-mid absorption."]}, "94a546e3-ea8a-4555-bc2f-2522b93e903d": {"definition": "Wall treatments are the acoustic materials and devices applied to a room's wall surfaces - porous absorbers, diffusers, resonant or membrane panels, and reflective finishes - selected and positioned to control reflections, reverberation, flutter echo, and modal behaviour. Because the walls carry most of a room's early reflections, the choice and placement of these treatments strongly shape how a listening or recording space sounds.", "plain_english": "Wall treatments are the things you put on a room's walls to fix its sound. They can absorb, scatter, or reflect sound. Walls cause many of the early echoes we hear. Treating them controls clarity and reverb.", "purpose_function": "They manage how the walls reflect sound so a room sounds clear and even rather than echoey or harsh. Different types - absorbing, diffusing, reflecting - are combined to reach the target acoustic.", "practical_application": "A technician surveys the room, then places a mix of absorbers and diffusers on the walls to control first reflections and flutter while keeping the room lively enough.", "category": "Wall treatment", "related_terms": ["Wall panel", "Diffuser", "Porous absorber", "Flutter echo", "First reflection", "Wall-ceiling corner treatment"], "common_mistakes": ["Over-absorbing every wall, leaving the room dead and lifeless instead of balanced.", "Using only absorption and no diffusion, so the room loses its sense of space.", "Ignoring the walls that carry the strongest first reflections while treating less important surfaces."], "scenario_contexts": ["Planning a control-room scheme that mixes absorbers and diffusers on the walls.", "Fixing flutter echo between two parallel bare walls.", "Balancing a vocal booth so it is controlled but not completely dead."]}, "38caf021-4003-4bbe-adc3-8e3135d3d141": {"definition": "Wall-ceiling corner treatment is the placement of acoustic absorption - commonly broadband porous absorbers or purpose-made corner traps - along the horizontal edge where a wall meets the ceiling, exploiting the fact that room boundaries, and especially corners, are regions of maximum sound pressure where low-frequency modal energy concentrates. Treating this edge adds low-frequency absorption and helps control modal buildup as well as wall-to-ceiling reflections.", "plain_english": "This is treatment placed along the line where a wall meets the ceiling. Sound pressure piles up in corners and along edges, especially low notes. Putting absorbers there soaks up the extra bass. It helps smooth out boomy low frequencies.", "purpose_function": "It targets the low-frequency energy that builds at the wall-ceiling edge, adding bass absorption where it works best. It also tames reflections along that boundary.", "practical_application": "A technician mounts broadband traps across the top wall-ceiling edge, often bridging the corner with an air gap behind, to add bass control without using floor space.", "category": "Corner treatment", "related_terms": ["Bass trap", "Room modes", "Broadband absorber", "Pressure trap", "Wall treatments", "Wall panel"], "common_mistakes": ["Using thin foam at the corner and expecting bass control, when thin porous material does little at low frequencies.", "Treating only the vertical corners and ignoring the horizontal wall-ceiling edges where bass also builds.", "Fitting the trap tight into the corner with no air gap, which reduces its low-frequency reach."], "scenario_contexts": ["Adding bass control to a small control room by trapping the wall-ceiling edges.", "Bridging the top corners with broadband traps to tame modal boom.", "Combining wall-ceiling edge traps with vertical corner traps for fuller low-end control."]}, "110775e0-c9a0-4695-953d-a65770266c77": {"definition": "Wedge foam is open-cell acoustic foam moulded with a repeating wedge (angled ridge) surface profile, functioning as a porous absorber that converts sound energy to heat through air friction within its cells. Like all thin porous absorbers it is effective at mid and high frequencies and increasingly ineffective toward low frequencies, where its thickness is small relative to the wavelength; its rated absorption (for example NRC measured per ASTM C423) rises with thickness.", "plain_english": "Wedge foam is soft open foam with a row of angled ridges on its face. It soaks up sound as air moves through its tiny holes and rubs against them. It works well on high and mid sounds. It does little for deep bass unless it is very thick.", "purpose_function": "It absorbs mid and high-frequency reflections to reduce flutter echo and brightness in a room. The wedge profile mainly adds surface area and looks; it does not change the porous absorbing mechanism.", "practical_application": "A technician fixes wedge foam to walls to cut high-frequency reflections and flutter, knowing it will not solve low-frequency problems on its own.", "category": "Acoustic foam", "related_terms": ["Pyramid foam", "Porous absorber", "Melamine foam", "Flutter echo", "NRC", "Wall panel"], "common_mistakes": ["Believing wedge foam soundproofs a room or blocks sound passing through walls, when it only absorbs reflections inside the room.", "Expecting thin foam to absorb bass, which it cannot do effectively.", "UNSAFE: Using non-fire-rated foam in occupied studios, since ordinary polyurethane foam can be highly flammable - use fire-rated or melamine products per the maker's fire-safety data."], "scenario_contexts": ["Reducing high-frequency flutter in a small vocal booth.", "Deadening a bright, reflective home-studio wall.", "Choosing thicker foam or a bass trap when real low-end control is needed."]}, "7079e50b-d0c9-4c8e-ab68-410c0d77c9a5": {"definition": "A wood acoustic wall is a wall surface finished with wood-based acoustic elements - such as slatted, grooved, or perforated wood panels backed by absorptive material and/or an air cavity - that combines the appearance of timber with tuned acoustic function. It typically absorbs selected mid and low-mid frequencies through resonant or panel action while scattering or reflecting higher frequencies, with its behaviour set by the slot or perforation geometry, cavity depth, and backing.", "plain_english": "A wood acoustic wall is a wall covered in wood panels made to shape sound. The wood often has slots, grooves, or holes over an absorber and air space. This lets it soak up chosen frequencies while looking like a timber wall. It mixes good looks with sound control.", "purpose_function": "It gives a room acoustic control with a natural wood finish, absorbing problem frequencies and scattering highs instead of leaving a hard reflective surface. It exists where designers want both good looks and good acoustics.", "practical_application": "An installer fits slatted or perforated wood panels over mineral wool and a cavity, tuning the slot width and depth to target the room's problem frequency range.", "category": "Wall treatment", "related_terms": ["Wood slat wall", "Slat resonator", "Perforated wood panel", "Resonant absorber", "Diffuser", "Wall treatments"], "common_mistakes": ["Assuming a solid wood wall absorbs sound, when a solid, hard wood surface mostly reflects it.", "Fitting slatted wood with no absorptive backing, so it neither absorbs nor performs as intended.", "Copying a look without matching the slot spacing and cavity depth to the target frequency."], "scenario_contexts": ["Finishing a broadcast studio with a wood feature wall that also controls reflections.", "Building a slatted timber wall over mineral wool to absorb low-mids.", "Choosing wood acoustic panels to keep a room lively but controlled."]}, "ed2c08b8-08ae-4448-8570-58b68577b950": {"definition": "A wood slat acoustic panel is a prefabricated panel of parallel wood slats mounted over a porous backing (typically acoustic felt or mineral wool) with regular gaps between the slats, forming a slotted or slat resonant absorber. The slats and the air gaps over the absorptive backing tune the panel toward mid and low-mid absorption - the geometry acting like a distributed Helmholtz/slot resonator - while the wood face scatters and reflects higher frequencies.", "plain_english": "A wood slat acoustic panel has thin wood strips with gaps, fixed over a soft backing. Sound passes through the gaps and is soaked up by the backing behind. The strip-and-gap pattern tunes it to absorb mid and lower notes. The wood face scatters the highs.", "purpose_function": "It provides tuned mid and low-mid absorption in a decorative panel, so a room can be controlled without looking clinical. The slat spacing and backing set which frequencies it absorbs.", "practical_application": "A technician mounts these panels on walls or ceilings to absorb problem mid frequencies while keeping a warm wooden look and some high-frequency liveliness.", "category": "Resonant absorber", "related_terms": ["Slat resonator", "Wood slat wall", "Perforated wood panel", "Helmholtz resonator", "Porous absorber", "Diffuser"], "common_mistakes": ["Leaving out the porous backing, so the panel reflects instead of absorbs.", "Thinking any slat panel is a broadband bass trap, when its absorption is tuned by slat width, gap, and cavity depth.", "Expecting strong high-frequency absorption, when the wood slats mostly scatter or reflect highs."], "scenario_contexts": ["Absorbing low-mid buildup on a studio wall with a decorative slat panel.", "Fitting slat panels over felt on a ceiling to tame reflections.", "Choosing the slat spacing to target a specific problem frequency."]}, "fbd7c424-25bb-43c1-8593-0d0907b338e0": {"definition": "A wood slat feature wall is an architectural wall of evenly spaced wood slats installed as a visual centrepiece that also provides acoustic function; when the slats are backed by absorptive material and an air cavity it behaves as a slat/slot resonant absorber, whereas slats over a hard, reflective backing mainly scatter sound. Its acoustic effect therefore depends entirely on what lies behind the slats.", "plain_english": "A wood slat feature wall is a row of wood strips built as a room's eye-catching wall. What it does to sound depends on what sits behind the strips. Over a soft absorber it soaks up sound. Over a hard wall it just scatters it.", "purpose_function": "It serves first as a design feature and second as acoustic treatment, absorbing or scattering depending on its backing. It lets a striking wood wall double as sound control.", "practical_application": "A designer specifies the backing - an absorber plus cavity, or a hard surface - based on whether the room needs absorption or diffusion behind the feature wall.", "category": "Wall treatment", "related_terms": ["Wood slat wall", "Wood slat acoustic panel", "Slat resonator", "Diffuser", "Resonant absorber", "Wall treatments"], "common_mistakes": ["Assuming any slat feature wall improves acoustics, when slats over a hard wall mostly just scatter sound.", "Skipping the absorptive backing and cavity, so the wall looks acoustic but does little.", "Choosing the slat spacing for looks alone and ignoring its effect on absorption."], "scenario_contexts": ["Building a slat feature wall in a podcast studio with mineral wool behind it for absorption.", "Using a slat wall over a hard surface to add diffusion behind the listening position.", "Balancing appearance and acoustic goals when specifying the backing."]}, "6502a245-55c8-4357-aa42-e7c4a19ab92f": {"definition": "A wood slat wall is a wall clad in parallel wood slats separated by regular gaps; acoustically it acts as a slat (slot) resonator when the slats are mounted over a porous absorber and an air cavity, giving tuned mid and low-mid absorption, and as a scattering or reflecting surface for higher frequencies. The absorbed frequency band is governed by slat width, gap size, cavity depth, and the backing material.", "plain_english": "A wood slat wall is a wall covered with spaced wood strips. Over a soft backing and air gap, it soaks up mid and lower notes. It scatters the higher notes off the wood. The strip and gap sizes decide which notes it absorbs.", "purpose_function": "It provides tuned absorption and some scattering in a decorative form, controlling a room's mid and low-mid range while looking like natural timber. Its tuning is set by the slat and cavity geometry.", "practical_application": "An installer builds a slat wall over mineral wool and an air gap, sizing the slats and gaps to absorb the room's problem frequencies while keeping the highs alive.", "category": "Resonant absorber", "related_terms": ["Slat resonator", "Wood slat acoustic panel", "Wood acoustic wall", "Helmholtz resonator", "Porous absorber", "Diffuser"], "common_mistakes": ["Mounting slats directly on a hard wall with no absorber, expecting an absorption that does not happen.", "Believing a slat wall absorbs broadband bass, when its absorption is tuned to a limited band.", "Ignoring slat width, gap, and cavity depth, which together set the absorbed frequency range."], "scenario_contexts": ["Cladding a control-room rear wall with a slat wall over an absorber for low-mid control.", "Using a slat wall to add warmth and scattering to a bright room.", "Tuning the slat spacing and cavity depth to a measured room problem."]}, "9fa76bef-40b2-46c7-bc14-b7aca4012fee": {"definition": "Wood veneer is a thin slice of natural wood, usually only a fraction of a millimetre to a few millimetres thick, bonded to a rigid substrate such as MDF, plywood, or particleboard to give the surface the appearance and grain of solid timber. In room acoustics it is applied as a decorative finish over the hard, reflective bodies of diffusers, slat systems, and panels; because it is very thin and adhered to a rigid backing, it leaves the underlying reflective or diffusing behaviour of that surface essentially unchanged.", "plain_english": "Wood veneer is a very thin layer of real wood glued onto a cheaper, sturdy board. It makes the board look like solid timber. In studios it is used to finish diffusers and panels. Because it is so thin and stuck to a hard board, it barely changes how the surface handles sound.", "purpose_function": "It gives acoustic devices the look of solid, high-grade timber at lower cost and weight than using solid wood. Because it sits on a rigid backing, it supplies this finish without changing the reflective or diffusing behaviour of the device.", "practical_application": "A builder glues wood veneer onto the MDF or plywood body of a diffuser or slat panel, then trims, sands, and seals it so the finished treatment looks like solid hardwood.", "category": "Facing material", "related_terms": ["MDF", "Plywood", "Diffuser", "Slat wall treatment", "Slotted wood wall", "Acoustic fabric"], "common_mistakes": ["Applying an unperforated wood veneer over a slotted or perforated absorber, which seals the openings and destroys its absorption.", "UNSAFE: Sanding or machining veneered panels without dust extraction and a rated respirator, since wood dust and the resin binders are respiratory hazards under OSHA wood-dust limits.", "Assuming a thin veneer turns a rigid panel into an absorber, when it stays a hard, reflective surface.", "Confusing real wood veneer with a printed vinyl or laminate wood-look finish."], "scenario_contexts": ["Veneering the MDF body of a diffuser so it matches hardwood trim in a control room.", "Finishing slat-panel treatment with matched veneer for a uniform look.", "Choosing a perforated veneer facing so an absorber behind it still works."]}, "d18cf599-16de-47d5-9e24-22454b1f010b": {"definition": "Wool felt is a non-woven textile made by matting, pressing, and heat- and moisture-treating natural wool fibres into a dense, coherent sheet without weaving. In acoustics its interconnected fibrous, porous structure dissipates sound energy through viscous and thermal losses as air is forced through it, making it a porous absorber that is most effective at mid and high frequencies and useful as a thin decorative absorptive facing, a panel core, or a damping and gasket layer.", "plain_english": "Wool felt is a dense mat of pressed sheep's wool, not woven like normal cloth. Its tangled fibres are full of tiny air paths. When sound pushes air through those paths, friction turns some of the sound into a little heat. This lets it soak up sound, mostly higher tones. It is used as thin absorbing panels or padding.", "purpose_function": "It absorbs sound to reduce reflections and reverberation, and its natural fibres offer a decorative, low-irritant alternative to mineral wool. As a soft, dense sheet it also damps vibration and seals small gaps between parts.", "practical_application": "A technician mounts wool-felt tiles or panels on walls and ceilings to tame mid- and high-frequency reflections, or uses felt strips as decoupling gaskets behind treatment and hardware.", "category": "Absorber material", "related_terms": ["Mineral wool", "Porous absorber", "Cotton fiber", "Melamine foam", "Absorption coefficient", "Flow resistivity"], "common_mistakes": ["Expecting thin wool felt to absorb deep bass, when its small thickness limits it to mid and high frequencies.", "Compressing the felt or coating it with an airtight layer, which raises its flow resistance and cuts absorption.", "Confusing pressed wool felt with loose sheep's-wool insulation batts, which behave differently.", "Assuming all acoustic felt is wool, when much of it is actually polyester (PET) fibre."], "scenario_contexts": ["Applying wool-felt panels to reduce high-frequency reflections and flutter echo in a room.", "Using felt as a decorative absorber where loose mineral-fibre insulation is unwanted.", "Placing felt gaskets behind panels or clips to decouple them and stop rattles."]}, "4495c874-9f3a-4a32-a0c1-340b1c0c8103": {"definition": "Z-clip mounting (also called Z-bar or interlocking cleat mounting) is a method of hanging acoustic panels, diffusers, or artwork using two matching Z- or L-profiled extruded metal brackets: one fixed to the wall and a mating one fixed to the back of the panel, which hook together so the panel's weight is carried on the interlock. It holds the panel flush and level with no visible fixings, lets the panel be lifted off for removal, and typically leaves a small air gap behind the panel.", "plain_english": "Z-clip mounting hangs a panel using two matching metal strips shaped like the letter Z. One strip screws to the wall and the other to the back of the panel. You lower the panel so the two strips hook together and lock. This holds the panel flat and level, and you can lift it off later. It works like a hidden shelf bracket that the panel drops onto.", "purpose_function": "It provides a strong, concealed, and level way to hang treatment so no fixings show on the face of the panel. Because the two halves simply unhook, panels can be taken down for access or rearrangement without damage.", "practical_application": "An installer screws the wall clip on level using a spirit or laser level, fixes the mating clip to the panel back, then hangs the panel by engaging the two clips and checks it sits tight and even.", "category": "Mounting method", "related_terms": ["Stand-off mount", "Air cavity", "Cavity depth", "Diffuser", "Fabric-wrapped panel", "Bass trap"], "common_mistakes": ["UNSAFE: Fixing the wall clip into plasterboard alone without hitting studs or using rated anchors, so a heavy panel can tear out and fall.", "Mounting the wall clip upside down or off level, so the mating clip cannot engage or the panel hangs crooked.", "Forgetting that the clip holds the panel slightly off the wall, changing the air gap and the low-frequency behaviour of an absorber.", "Using too few or too short clips for the weight of the panel."], "scenario_contexts": ["Hanging removable fabric-wrapped absorbers so they can be taken down for wiring access.", "Mounting heavy wood diffusers flush and level with concealed hardware.", "Fitting panels that must be repositioned while tuning a room."]}, "4c62b292-8e83-40b5-80cf-e446a8ab016a": {"definition": "Air compensation (air absorption compensation) is a signal-processing correction that boosts the high frequencies sent to a loudspeaker system to offset the frequency-dependent absorption of sound by air, which attenuates high frequencies increasingly with distance and varies with temperature and humidity. Applied per zone or per cabinet in array-processing and prediction software, it restores high-frequency balance for listeners far from the source; the underlying atmospheric absorption is defined in ISO 9613-1.", "plain_english": "As sound travels through air, the air soaks up high notes more than low ones. The farther the sound goes, the duller it gets. Air compensation adds back some highs for the distant seats. This keeps the far rows as bright as the near rows.", "purpose_function": "It exists because air absorbs high frequencies over distance, so far seats sound dull without correction. Boosting the highs sent to distant zones keeps the tone consistent across the whole audience.", "practical_application": "A system engineer enables air absorption compensation in array-processing software and enters the venue temperature and humidity, so the processor adds the right high-frequency lift for the throw distance.", "category": "Array optimization", "related_terms": ["Atmospheric correction", "Air absorption", "Line array", "Array processing", "Level tapering (gain shading)", "SPL"], "common_mistakes": ["Assuming air absorption is fixed, when it changes with temperature, humidity, and distance.", "Applying the same high-frequency boost to near and far zones, which over-brightens the near seats.", "Confusing air compensation with room EQ, when it corrects propagation loss rather than room reflections."], "scenario_contexts": ["Tuning a long-throw line array in a large arena so the back rows are not dull.", "Updating temperature and humidity settings between an empty afternoon check and a full evening show.", "Using prediction software to plan high-frequency compensation before a stadium concert."]}, "10ae1580-7f95-41ea-b8f8-76920dfdf45f": {"definition": "Alignment is the process of adjusting the relative level, time (delay), phase, and equalization of separate loudspeaker elements - such as subwoofers and main loudspeakers, or overlapping array sections - so that their outputs combine correctly through their shared frequency range and give even coverage. It is verified with a dual-channel FFT analyzer that measures the transfer function of each element and their summed response.", "plain_english": "Alignment means getting separate speakers to work together as one. You match their timing, level, and tone so they add up instead of fighting. For example, subs and main speakers must arrive together. Good alignment gives smooth, even sound across the room.", "purpose_function": "It exists so that multiple loudspeakers sum cleanly instead of causing cancellation, comb filtering, or uneven coverage. Matching time, level, and phase where the elements overlap is what makes separate boxes behave like one source.", "practical_application": "A system tech measures each element with a dual-channel analyzer, sets delay so the arrivals match, then trims level and EQ so subs and tops sum smoothly through the crossover.", "category": "System optimization", "related_terms": ["Transfer function", "Delay (time alignment)", "Phase", "Crossover", "Comb filtering", "Coherence"], "common_mistakes": ["Aligning only by level and ignoring time and phase, which leaves cancellation where the elements overlap.", "Setting delay by tape-measure distance alone, ignoring the acoustic and processing delay each path adds.", "Assuming one aligned position fixes the whole room, when alignment holds best near the measurement point."], "scenario_contexts": ["Time-aligning subwoofers to the main PA before doors open.", "Matching a delay speaker to the main system so both arrive together at the back.", "Aligning overlapping zones of a line array during system tuning."]}, "70582d81-84ee-4867-84e5-ef67404908eb": {"definition": "Amp gain matching is the practice of setting or selecting power amplifiers so they share the same voltage gain (or input sensitivity), meaning a given input voltage produces the same output level from each amplifier. Amplifier gain is expressed either as voltage gain in decibels (for example 26 or 32 dB) or as input sensitivity (the input voltage that drives the amplifier to rated output, such as 0.775 V or 1.4 V), and matching it keeps levels, crossover balance, and array shading correct when different amplifier models drive one system or when an amplifier is replaced.", "plain_english": "Amplifiers can differ in how much they boost a signal. If two amps in one system have different gains, the same input makes them play at different volumes. Amp gain matching sets them to the same gain. Then every speaker plays at the level the design intended.", "purpose_function": "It exists so that every amplifier in a system responds identically to the same input, keeping relative levels and crossover balance correct. Without matching, swapping or mixing amplifier models would shift the system tuning.", "practical_application": "When replacing a failed amplifier with a different model, a technician sets its gain or input-sensitivity switch to match the others so the system levels do not change.", "category": "Gain structure", "related_terms": ["Voltage gain", "Input sensitivity", "Gain structure", "Power amplifier", "Level tapering (gain shading)", "Crossover"], "common_mistakes": ["Assuming all amplifiers have the same gain, when models and switch settings vary widely.", "Confusing input sensitivity with voltage gain, which describe amplifier gain in different ways.", "Matching front-panel level-knob positions instead of the actual gain setting, which does not guarantee equal gain."], "scenario_contexts": ["Replacing one amplifier in a multi-amp rack with a different model.", "Combining amps of different gains across the sub and top channels of a system.", "Setting input-sensitivity switches so all amplifiers in an array shade correctly."]}, "62d260d2-c631-4b84-bfca-2d0b20dd5483": {"definition": "In FFT-based measurement, the analysis window (also called the time record) is the segment of the time-domain signal captured for a single Fourier transform. Its length sets the analyzer's frequency resolution - equal to the sample rate divided by the FFT size, or one divided by the window length in seconds - so a longer window gives finer low-frequency resolution but spans more time, embodying the time-frequency trade-off. The captured samples are usually multiplied by a tapering window function, such as Hann, before the transform to reduce spectral leakage.", "plain_english": "An FFT analyzer (a tool that breaks sound into its frequencies) looks at sound in short time slices. The analysis window is the length of one slice. A longer window sees low notes clearly but reacts more slowly. A shorter window reacts fast but blurs the low notes. You pick the length to fit the job.", "purpose_function": "It exists because an FFT works on a finite chunk of signal, and that chunk's length sets how finely the analyzer can resolve frequency. Choosing the window length trades frequency detail against speed and time detail.", "practical_application": "An operator picks a longer FFT window to resolve low-frequency detail when tuning subwoofers, and a shorter window for faster, broadband high-frequency measurements.", "category": "FFT analysis", "related_terms": ["FFT", "Frequency resolution", "Window function", "Spectral leakage", "Real-time analyzer (RTA)", "Time constant"], "common_mistakes": ["Confusing the analysis window (the time-record length) with the window function, such as Hann.", "Expecting good low-frequency resolution from a short window, which cannot resolve closely spaced low tones.", "Forgetting that a longer window spans more time, so it responds more slowly to changes."], "scenario_contexts": ["Choosing a long FFT window to measure subwoofer response accurately.", "Setting a multi-time-window measurement so low and high frequencies each get suitable resolution.", "Explaining why a short window smooths out low-frequency detail on the display."]}, "8234bd80-2f5c-401b-9ebc-72f5cc58d429": {"definition": "Atmospheric correction is the adjustment of acoustic measurements, predictions, or system settings to account for how temperature, humidity, and barometric pressure affect sound propagation - chiefly the temperature dependence of the speed of sound (about 0.6 m/s per degree Celsius) and the temperature- and humidity-dependent absorption of high frequencies by air. It keeps time-of-flight and delay calculations and high-frequency balance accurate as conditions change.", "plain_english": "Air conditions change how sound travels. Warmer air makes sound move faster. Temperature and humidity also change how much of the high sound the air soaks up. Atmospheric correction adjusts the settings for these conditions. It keeps timing and tone right when the weather changes.", "purpose_function": "It exists because the speed of sound and air absorption both change with the weather, which shifts speaker timing and tone. Correcting for the conditions keeps delay alignment and high-frequency balance accurate outdoors and in changing rooms.", "practical_application": "Before an outdoor evening show cools the air, a system engineer updates the temperature and humidity values so delay times and air-absorption compensation stay correct.", "category": "Measurement correction", "related_terms": ["Air compensation", "Speed of sound", "Air absorption", "Delay (time alignment)", "Line array", "SPL"], "common_mistakes": ["Ignoring the temperature change between afternoon setup and evening show, which leaves delay times slightly off.", "Assuming humidity does not matter, when it strongly affects high-frequency air absorption.", "Correcting tone but not delay, when a temperature shift changes the speed of sound and thus arrival times."], "scenario_contexts": ["Re-checking delay alignment outdoors after a large temperature drop at sunset.", "Entering the current weather into prediction software for an outdoor festival.", "Updating array-processing air settings as a venue warms with a full audience."]}, "6d27bb2e-db36-4530-bf33-89d14f2279da": {"definition": "Average Mode is the setting on a measurement analyzer that determines whether and how successive FFT frames or measurements are combined to stabilize the display and improve the estimate. It selects the averaging method - such as RMS (power/magnitude) averaging, vector (complex) averaging, or exponential (time-weighted) averaging - together with the number of frames or the time constant used.", "plain_english": "A single quick measurement jumps around a lot. Average Mode tells the analyzer to blend many readings into one steadier result. You choose how it blends them and how many it uses. This makes the display calmer and easier to trust.", "purpose_function": "It exists to reduce the random frame-to-frame variation in FFT measurements so the display is stable enough to make decisions from. The chosen mode sets the trade-off between steadiness and how fast the display responds.", "practical_application": "An operator selects an averaging method and count so a noisy trace settles down, using more averaging for a stable reference and less for fast, responsive tuning.", "category": "Analyzer operation", "related_terms": ["Averaging - RMS", "Averaging - Vector (Complex)", "Averaging - Exponential", "FFT", "Coherence", "Transfer function"], "common_mistakes": ["Using too little averaging, so a jumpy trace leads to chasing noise instead of real response.", "Using very heavy averaging during live tuning, so the display responds too slowly to changes.", "Assuming averaging removes noise from the signal itself, when it only steadies the measurement estimate."], "scenario_contexts": ["Increasing averaging to capture a stable reference curve.", "Lowering averaging for a responsive display while ringing out monitors.", "Choosing an averaging method suited to noisy versus quiet measurement conditions."]}, "eb4076d6-94d4-4296-9ce6-3518964231cf": {"definition": "Exponential averaging is a continuously running average in which each new FFT frame is weighted most heavily and the contribution of older frames decays exponentially over time, so the result always reflects recent data within a fixed 'memory' set by the time constant or averaging number. Unlike linear (fixed-count) averaging, which averages a set number of frames equally and then stops, exponential averaging never stops updating, making it well suited to continuously changing signals.", "plain_english": "Exponential averaging blends readings but keeps favoring the newest ones. Older readings slowly fade away. The result keeps updating and never stops. This suits live sound, where the signal keeps changing and you want the latest picture.", "purpose_function": "It exists to give a smoothed but always-current measurement of a changing signal. By fading out old data, it stays responsive to the present while still reducing random jumpiness.", "practical_application": "During live tuning a technician uses exponential averaging so the display stays smooth yet keeps tracking the current program material and room.", "category": "Signal averaging", "related_terms": ["Average Mode", "Averaging - RMS", "Averaging - Vector (Complex)", "Time constant", "FFT", "Real-time analyzer (RTA)"], "common_mistakes": ["Confusing exponential averaging with linear averaging, which weights all frames equally and stops after a set count.", "Setting the time constant too long, so the display lags behind real changes.", "Expecting a single final answer, when exponential averaging keeps updating continuously."], "scenario_contexts": ["Watching a smoothed but live response while mixing changing program material.", "Tuning a room with music playing, where the signal never repeats exactly.", "Keeping an RTA readable during soundcheck without freezing the data."]}, "6fec0688-dfd7-45d9-9ea6-81ef472fe293": {"definition": "RMS averaging (also called power or magnitude averaging) combines the magnitudes of successive FFT frames - effectively averaging their power or decibel values - to reduce the frame-to-frame variance of the estimate and smooth the display. Because it averages magnitudes rather than the complex signal, it stabilizes and better estimates the true level of noisy or random signals, but it does not lower the noise floor or cancel noise.", "plain_english": "RMS averaging blends the loudness of many readings into one steady number. It calms down a jumpy display. But it does not remove noise from the signal. It just shows a better estimate of how much noise or level is really there.", "purpose_function": "It exists to stabilize the magnitude display of random or noisy signals so a reliable level can be read. It smooths the variance without needing the signal to repeat or to be triggered.", "practical_application": "An engineer uses RMS averaging on an RTA or spectrum so a fluctuating noise or music measurement settles into a steady, readable magnitude curve.", "category": "Signal averaging", "related_terms": ["Average Mode", "Averaging - Vector (Complex)", "Averaging - Exponential", "RMS", "Real-time analyzer (RTA)", "Noise floor"], "common_mistakes": ["Believing RMS averaging lowers the noise floor, when it only steadies the magnitude estimate.", "Expecting it to show phase, when RMS averaging discards phase information.", "Confusing it with vector averaging, which needs a coherent signal and can reduce noise."], "scenario_contexts": ["Averaging a pink-noise spectrum into a stable curve for EQ decisions.", "Reading the steady level of a noisy signal on an RTA.", "Smoothing a magnitude trace where the signal does not repeat frame to frame."]}, "43e287fe-a26f-4991-b7ab-ea79543d8bb1": {"definition": "Vector averaging (also called complex, time, or synchronous averaging) averages the real and imaginary parts of successive FFT frames separately, preserving both magnitude and phase. Because components that are coherent with the reference add together while random noise, having varying phase, tends to cancel, vector averaging lowers the noise floor and improves the signal-to-noise ratio - but only for signals that repeat with a stable phase relationship, so it typically requires a trigger or a fixed time reference such as a dual-channel transfer-function measurement.", "plain_english": "Vector averaging keeps track of both level and timing as it blends readings. Steady, repeating sound adds up, while random noise cancels out. So it can lower the noise and clean up the measurement. But the signal must repeat the same way each time.", "purpose_function": "It exists to pull a coherent signal out of noise by letting random, out-of-phase noise cancel across frames. Preserving phase also makes it the basis of transfer-function measurements.", "practical_application": "In a dual-channel transfer-function measurement a technician relies on complex averaging so uncorrelated room noise cancels and the true system response and phase emerge.", "category": "Signal averaging", "related_terms": ["Average Mode", "Averaging - RMS", "Averaging - Exponential", "Transfer function", "Phase", "Coherence"], "common_mistakes": ["Using vector averaging on a non-repeating signal with no time reference, so the wanted content also cancels.", "Confusing it with RMS averaging, which keeps only magnitude and cannot cancel noise.", "Forgetting it needs coherence, so a loose time reference makes the average decay toward zero."], "scenario_contexts": ["Measuring a system transfer function where room noise must be rejected.", "Improving signal-to-noise on a repeatable test signal with a stable trigger.", "Comparing complex versus magnitude averaging when a measurement is contaminated by reverberation."]}, "487c2a57-42dd-4d39-adf9-5ebc80552c2d": {"definition": "Bit depth conversion is the process of changing the number of bits used to represent each digital audio sample, for example converting a 24-bit recording to 16-bit for CD. Reducing bit depth (requantization) coarsens amplitude resolution and raises the quantization noise floor, so dither is normally added to decorrelate the quantization error and prevent low-level distortion; increasing bit depth adds least-significant bits that carry no new information.", "plain_english": "Bit depth is how many bits store each tiny sample of digital sound. More bits give a lower noise floor and finer detail. Bit depth conversion changes that number, such as moving from 24-bit to 16-bit. When you drop bits, a soft noise called dither is added. Dither hides the harsh distortion that cutting bits would cause.", "purpose_function": "It matches an audio file's word length to a target format or process, such as 16-bit for CD or a plugin's internal precision. Adding dither during reduction trades a small rise in steady noise for the removal of harsh, signal-dependent quantization distortion.", "practical_application": "A mastering or post engineer converts a 24-bit or 32-bit float mix down to 16-bit at export, choosing a dither type so quiet fades and reverb tails stay smooth instead of grainy.", "category": "Digital audio", "related_terms": ["Bit depth", "Dither", "Quantization", "Requantization", "dBFS", "Downsampling"], "common_mistakes": ["Reducing bit depth without adding dither, which turns quantization error into audible distortion on quiet passages.", "Believing that converting 16-bit up to 24-bit adds detail or quality, when it only pads the word with zeros.", "Confusing bit depth conversion with sample-rate conversion; one changes amplitude resolution, the other changes time resolution.", "Applying dither more than once through a chain, which stacks extra noise for no benefit."], "scenario_contexts": ["Exporting a finished master from a 24-bit session to 16-bit for CD replication.", "Delivering 16-bit files for a client while keeping 24-bit archives.", "Setting the correct dither on the last processor in a mastering chain before truncation."]}, "dbac5dc3-4744-47a7-a957-f1ddf6245b99": {"definition": "A bit meter is a display in digital audio software or hardware that shows how many bits of the digital audio word are actively carrying signal at a given moment, indicating the effective word length in use. It reveals whether the full available resolution is being used and whether processing has extended the word length or truncation has shortened it, helping decide when dither or requantization is needed.", "plain_english": "A bit meter shows how many of the digital bits are actually carrying sound. It tells you if the full word length is being used. This helps you spot when a signal has been cut short or needs dither.", "purpose_function": "It lets an engineer see the real resolution of a signal rather than assuming it from the file format. Seeing active bits helps catch accidental truncation, confirm that processing has raised the word length, and decide when dither is required.", "practical_application": "In a mastering DAW an engineer watches a bit meter to confirm a level or plugin has pushed the signal beyond 16 bits, so they add dither before exporting a 16-bit file.", "category": "Digital metering", "related_terms": ["Bit depth", "Bit depth conversion", "Dither", "Truncation", "Quantization", "dBFS"], "common_mistakes": ["Assuming a 24-bit project always uses all 24 bits, when a quiet or low-resolution source may light only a few.", "Ignoring the bit meter and truncating to 16-bit without dither.", "Reading momentary active bits as the file's stored bit depth, which are not the same thing.", "Trusting the bit meter alone to judge quality instead of also listening."], "scenario_contexts": ["Checking whether a processed signal now exceeds 16 bits and needs dither before export.", "Verifying that a signal path is passing full 24-bit resolution end to end.", "Spotting unintended truncation introduced by a plugin or gain stage."]}, "b0e1afa5-f075-484d-9104-3f859b6f2e41": {"definition": "To calibrate is to adjust or verify a device, meter, or system so that its indicated values agree with a known reference standard, establishing a defined relationship between the true quantity and the reading. In audio this includes aligning a meter to a reference level (for example 0 VU to +4 dBu), setting monitor gain to a target SPL, and referencing a measurement microphone or sound level meter against an acoustic calibrator, typically 94 dB SPL at 1 kHz.", "plain_english": "To calibrate means to adjust a tool so its readings match a known, trusted standard. Think of it like setting a scale to zero before you weigh something. In audio, you might calibrate a meter, the loudness of your monitors, or a test microphone.", "purpose_function": "Calibration makes measurements accurate and repeatable, so different meters, rooms, and engineers all agree on what a given reading means. Without it, levels and SPL readings drift and cannot be trusted or compared.", "practical_application": "Before measuring show levels, a technician places an acoustic calibrator on the measurement microphone to set the sound level meter to a known 94 dB SPL reference, then trusts the readings for the rest of the day.", "category": "Measurement practice", "related_terms": ["Reference level", "Sound level meter", "Monitor calibration", "VU meter", "Acoustic calibrator", "dBFS"], "common_mistakes": ["Assuming a meter reads correctly out of the box and skipping calibration against a reference.", "Confusing calibration (matching a known standard) with simply adjusting a control until it looks right.", "Calibrating once and never rechecking, when instruments and microphones drift over time.", "Calibrating a sound level meter with the wrong weighting or environment for the measurement."], "scenario_contexts": ["Referencing a measurement microphone with a 94 dB SPL acoustic calibrator before taking SPL readings.", "Aligning a console's meters so 0 VU equals a defined line level.", "Setting monitor gain so a reference signal reaches a target SPL in the room."]}, "295771be-3fde-4be3-b0ee-ea126a561cdc": {"definition": "In audio metering, correlation (phase correlation) is a measure of the phase and polarity relationship between two channels, usually the left and right of a stereo signal, shown by a correlation meter on a scale from +1 to -1. A reading of +1 means the channels are identical and in phase (fully mono-compatible), 0 means they are uncorrelated (a wide stereo image), and -1 means they are opposite in polarity and will largely cancel when summed to mono; it is derived from the normalized cross-correlation of the two signals.", "plain_english": "A correlation meter shows how well the left and right channels match in phase. A reading near plus one means they agree and sum well to mono. A reading near minus one means they fight and cancel in mono. Zero means a wide stereo spread.", "purpose_function": "It warns an engineer about phase problems that would weaken or hollow out the sound when a stereo mix is folded to mono, as often happens on club, broadcast, and phone playback. It also gives a quick read on how wide the stereo image is.", "practical_application": "A mix or broadcast engineer watches the correlation meter and treats sustained negative readings as a phase warning, checking mic polarity or stereo effects before the mix is heard in mono.", "category": "Metering", "related_terms": ["Phase", "Polarity", "Mono compatibility", "Goniometer", "Stereo image", "Comb filtering"], "common_mistakes": ["Reading a low or negative correlation as automatically 'wrong', when some out-of-phase content is normal in wide stereo material.", "Confusing correlation (a phase relationship) with level balance between the two channels.", "Ignoring sustained negative correlation, which signals serious cancellation when summed to mono.", "Confusing polarity inversion with a time delay between channels; both lower correlation but need different fixes."], "scenario_contexts": ["Checking a stereo mix for mono compatibility before broadcast.", "Diagnosing a hollow, thin sound caused by an inverted microphone or channel.", "Watching correlation while adding a wide stereo effect to avoid phase cancellation."]}, "ca07f431-aa89-4dfc-9a73-901fe0007a05": {"definition": "In the context of dynamic range, the decibel (dB) scale expresses the ratio between two signal levels logarithmically; for amplitudes, the level difference in decibels equals 20 times the base-10 logarithm of the amplitude ratio. Dynamic range is the span, stated in dB, between the highest level a system can pass without clipping and its noise floor; for an ideal linear PCM system it is approximately 6.02 times the number of bits plus 1.76 dB.", "plain_english": "The decibel, or dB, compares two levels as a ratio. Dynamic range is the gap between the loudest and softest sound a system can handle. We measure that gap in dB. In digital audio, each extra bit adds about 6 dB of range.", "purpose_function": "The dB scale lets very large ratios of level be written as small, manageable numbers that track how we perceive loudness. Stating dynamic range in dB gives a single figure for how much usable window a system has between distortion and noise.", "practical_application": "An engineer compares the quoted dynamic range in dB of converters, mixers, or a bit depth to confirm a system's noise floor sits far enough below the loudest expected signal.", "category": "Measurement units", "related_terms": ["Decibel (dB)", "Dynamic range", "Noise floor", "Headroom", "dBFS", "Signal-to-noise ratio"], "common_mistakes": ["Treating the dB as an absolute level rather than a ratio between two levels.", "Using the 20-times-log rule for a power ratio, where the correct factor is 10.", "Assuming more dynamic range always sounds better, when the room noise floor may set the real limit.", "Confusing dynamic range (max level to noise floor) with headroom (level above a working reference)."], "scenario_contexts": ["Comparing the dynamic range spec of two audio interfaces before a purchase.", "Estimating the usable range of a 16-bit versus 24-bit recording.", "Judging whether a system's noise floor is low enough for a quiet acoustic session."]}, "b55334e2-c48a-4ec7-8da0-e56b9090d4e9": {"definition": "dBA and dBC metering are sound pressure level measurements taken through the standardized A-weighting and C-weighting frequency filters defined in IEC 61672. A-weighting rolls off low and very high frequencies to approximate the ear's reduced sensitivity at moderate levels and correlates with hearing-damage risk, so it is used for occupational and event noise limits; C-weighting is nearly flat across the audible band with gentle roll-off at the extremes and is used for peak measurements and for assessing high-level and low-frequency content.", "plain_english": "These are two ways to measure loudness with a sound level meter. dBA filters the sound to match how our ears hear at normal levels. It is used to judge the risk of hearing damage. dBC is much flatter and captures more deep bass. It is often used for loud peaks.", "purpose_function": "The two weightings let a meter report a single number that reflects either hearing-hazard risk (A) or full-band and low-frequency energy (C). This makes readings comparable to legal noise limits and to each other across different meters.", "practical_application": "A live-sound engineer logs LAeq in dBA against a venue's noise limit and checks dBC to catch heavy sub-bass energy that A-weighting understates during a loud show.", "category": "Sound level metering", "related_terms": ["A-weighting", "C-weighting", "Sound level meter", "LAeq", "SPL", "Noise exposure"], "common_mistakes": ["UNSAFE: Assuming a safe dBA average means momentary peaks are also safe, when high peaks can still damage hearing.", "UNSAFE: Trusting an uncalibrated phone SPL app to prove a show is within a hearing-safety limit.", "Reading dBA and dBC as the same measurement, when they weight the low end very differently.", "Reporting an SPL figure without stating the weighting and time response, making it meaningless."], "scenario_contexts": ["Measuring LAeq in dBA at front of house to stay under a venue noise limit.", "Comparing dBC with dBA to reveal excessive sub-bass in a mix.", "Assessing crew noise exposure over a shift against occupational limits."]}, "8103814a-7f94-4b9a-8f0f-0874dc690dd1": {"definition": "A delay reference is the arrival used as the timing baseline when aligning loudspeakers in a distributed system or when measuring a transfer function: the propagation time of a chosen source, typically the main system at a given listening point, against which the delay for other loudspeakers is set so their sound arrives in step. In measurement software such as Smaart, it is the delay applied to the reference signal to time-align it with the measurement signal before the analysis is computed.", "plain_english": "The delay reference is the main sound source that other speakers are timed to. Sound takes time to travel through air. To line up extra speakers, you first pick this main arrival as your starting point. Then you set delays so the other speakers match it.", "purpose_function": "It gives a fixed timing anchor so that fill and delay loudspeakers can be set to arrive in step with the main system rather than by guesswork. In transfer-function measurement, matching the reference delay is required before phase and impulse data are meaningful.", "practical_application": "A system tech measures the propagation time from the main array to a delay-speaker position, uses that as the reference, and dials the matching delay into the fill speaker.", "category": "System alignment", "related_terms": ["Delay-to-align (delaying delays)", "Transfer function", "Propagation delay", "Time alignment", "Impulse response", "Haas effect"], "common_mistakes": ["Choosing a reference point that does not represent the real listening area, so the alignment is wrong for the audience.", "Forgetting that air temperature changes the speed of sound and therefore the reference delay.", "Confusing the delay reference (the timing baseline) with the delay speaker being aligned to it.", "Failing to set the reference delay in measurement software, which corrupts the phase and impulse data."], "scenario_contexts": ["Setting the timing baseline from a main array before aligning a rear delay speaker.", "Applying reference-signal delay in Smaart so a transfer-function measurement is time-aligned.", "Re-checking the reference delay after a temperature swing at an outdoor show."]}, "a19eb77d-603c-446e-a63b-7dd382906afe": {"definition": "Delay-to-align, informally 'delaying delays', is the practice of adding electronic delay to a fill or delay loudspeaker so its sound reaches the listener in step with the sound from the main system, matching the acoustic propagation time between the two sources. A small extra offset is often added so the delayed speaker arrives slightly after the main system, using the Haas (precedence) effect to keep the perceived image at the main source while still reinforcing level and intelligibility.", "plain_english": "Extra fill speakers sit closer to some listeners than the main system. Their sound would arrive too early and blur the mix. Delay-to-align adds a short electronic delay to those speakers. This makes their sound reach the listener in step with the main system.", "purpose_function": "It restores correct timing between a main system and its fill or delay speakers, preventing smeared sound, comb filtering, and a pulled image. Adding a small Haas offset keeps listeners hearing the image as coming from the stage.", "practical_application": "A system engineer measures the distance or arrival time from the main PA to a delay tower, then sets that delay (often plus a few milliseconds) on the tower so both arrivals line up for the audience behind it.", "category": "System alignment", "related_terms": ["Delay reference", "Haas effect", "Propagation delay", "Time alignment", "Comb filtering", "Delay speaker"], "common_mistakes": ["Setting the delay from the physical distance only and ignoring that air temperature changes the speed of sound.", "Omitting the small Haas offset, so the image pulls toward the nearer delay speaker.", "Aligning at one seat and assuming the whole delay zone is aligned, when timing varies across the area.", "Confusing this acoustic time alignment with adding delay as a creative echo effect."], "scenario_contexts": ["Timing a delay tower to the main array in a large outdoor audience area.", "Aligning under-balcony fills to the main system in a theater.", "Setting front-fill delay so the stage image stays centered for the front rows."]}, "374ba0ee-0815-46f3-ba2d-68bea2e2f3e9": {"definition": "Downsampling (decimation) is reducing the sample rate of a digital audio signal, for example from 96 kHz to 48 kHz, by discarding samples after applying an anti-alias low-pass (decimation) filter. The filter removes any content above the new, lower Nyquist frequency first, because sampling at the reduced rate cannot represent it and would otherwise fold that content back into the audible band as aliasing distortion.", "plain_english": "Downsampling lowers the sample rate of digital audio, such as going from 96k to 48k. Before samples are removed, a filter cuts the highest frequencies. That filter stops errors called aliasing, which add false, unwanted tones.", "purpose_function": "It converts audio to a lower sample rate needed by a target format, device, or delivery spec while using the anti-alias filter to keep the reduction clean. This saves data and matches files to systems that run at the lower rate.", "practical_application": "An engineer downsamples a 96 kHz session to 44.1 kHz for CD or 48 kHz for video, relying on the sample-rate converter's anti-alias filter to avoid aliasing artifacts.", "category": "Digital audio", "related_terms": ["Sample rate", "Sample rate conversion", "Nyquist frequency", "Aliasing", "Anti-aliasing filter", "Bit depth conversion"], "common_mistakes": ["Believing downsampling just deletes samples, when an anti-alias filter must run first to prevent aliasing.", "Confusing downsampling (lower sample rate) with reducing bit depth (fewer bits per sample).", "Expecting a lower sample rate to keep high frequencies above the new Nyquist limit, which are removed.", "Using a poor-quality sample-rate converter and accepting audible artifacts."], "scenario_contexts": ["Converting a 96 kHz mix to 44.1 kHz for CD delivery.", "Downsampling high-rate recordings to 48 kHz to match a video project.", "Preparing audio for a device or codec that only supports a lower sample rate."]}, "3c04ba9a-6f4b-4221-b739-b3d907953292": {"definition": "A dual-FFT analyzer, also called a dual-channel FFT or transfer-function analyzer, performs a Fast Fourier transform on two signals at once - a reference taken from the source and the output measured through the system - and compares them to compute the system's transfer function (magnitude and phase versus frequency) plus coherence. Because it divides the measured signal by the reference, it can use music or any program material instead of a dedicated test signal, and it shows how the system alters the input rather than only what the loudspeaker radiates.", "plain_english": "A dual-FFT analyzer listens to two signals at once. One is the original sound sent to the system. The other is what comes back through the speakers and room. It compares them to show how the system changed the sound. This lets you tune a PA using music, not just test tones.", "purpose_function": "It exists to measure how a sound system alters a signal - its frequency response, timing, and phase - so an engineer can correct it. Comparing output against a reference lets the measurement work with real program material and reject some noise through the coherence reading.", "practical_application": "A system engineer feeds the console output as the reference and a measurement microphone as the output, then adjusts EQ, level, and delay while watching the transfer-function trace settle.", "category": "Analyzer type", "related_terms": ["Transfer function", "Coherence", "Fast Fourier transform processing", "Frequency bin", "Real-time analyzer (RTA)", "Smaart"], "common_mistakes": ["Confusing a dual-FFT (transfer-function) measurement with a single-channel RTA, which shows only the output spectrum, not how the system changed the signal.", "Ignoring the coherence trace and trusting data at frequencies where coherence is low and the measurement is unreliable.", "Forgetting to time-align (delay) the reference to the measured signal, which corrupts the phase and coherence readings."], "scenario_contexts": ["Tuning a PA system's EQ and delay using a dual-FFT analyzer and a measurement microphone.", "Aligning a subwoofer to the main array by matching phase on the transfer-function display.", "Verifying a loudspeaker's response against a target curve during system commissioning."]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"bec5a921-24fc-478e-898d-035e7c143e5a": {"definition": "Even coverage is the sound-system design and alignment goal in which the system delivers a consistent sound pressure level and tonal balance to every part of the intended listening area, so that listeners at the front, back, and sides all hear a similar level and frequency response. It is achieved through loudspeaker placement, splay and aim angles, level tapering, and delay, and is verified by measuring SPL and response at multiple audience positions.", "plain_english": "Even coverage means everyone in the audience hears about the same thing. The front rows are not much louder than the back. The sound quality stays similar across all the seats. Engineers aim and level the speakers to spread sound evenly.", "purpose_function": "It exists so that every seat gets a usable, similar experience instead of some areas being too loud, too quiet, or dull. Even coverage protects intelligibility and fairness across the whole audience.", "practical_application": "A system engineer aims and splays the loudspeakers, tapers levels, then walks the room or uses prediction software and measurements to confirm the level and tone stay consistent from seat to seat.", "category": "Coverage", "related_terms": ["Coverage", "Level tapering (gain shading)", "Line array", "Splay angle", "SPL", "Sound level meter"], "common_mistakes": ["Assuming one loud measurement at the mix position means the whole room is covered evenly.", "Confusing even coverage (consistent level and tone across seats) with simply making the system loud.", "Overlooking high-frequency loss at the coverage edges, where tonal balance changes even when the level is similar."], "scenario_contexts": ["Designing a line array's splay angles so the back rows match the front in level.", "Checking SPL at several audience positions to confirm coverage before a show.", "Adding delay speakers under a balcony to keep coverage even in shadowed seats."]}, "29551610-eada-477f-b78c-a48a3886878e": {"definition": "Fast Fourier transform (FFT) processing is the use of the FFT - an efficient algorithm for computing the discrete Fourier transform - to convert a block of time-domain samples into a frequency-domain spectrum of amplitude and phase across a set of evenly spaced frequency bins. The FFT yields the same result as the discrete Fourier transform but with far fewer calculations, which is what makes real-time spectral analysis of audio practical.", "plain_english": "Sound arrives as a wave that changes over time. FFT processing is a fast math method. It breaks that wave into the separate frequencies inside it. This turns a signal into a chart of how much of each pitch is present. It is quick enough to work in real time.", "purpose_function": "It exists to reveal the frequency content of a signal quickly, turning a waveform into a spectrum. Its speed is what allows analyzers and processors to show or act on frequency information live.", "practical_application": "A technician relies on FFT processing every time they read an RTA, a spectrograph, or a transfer-function display while tuning a system or hunting a problem frequency.", "category": "Analysis method", "related_terms": ["Frequency bin", "Frequency analyzer", "Dual-FFT analyzer", "Real-time analyzer (RTA)", "Fractional-Octave Banding", "Windowing"], "common_mistakes": ["Thinking the FFT is a different transform from the discrete Fourier transform, when it is just a fast way to compute the same result.", "Expecting fine low-frequency detail from a short FFT, when frequency resolution depends on the length of the block.", "Ignoring the window applied before the FFT, which affects how clearly nearby frequencies are separated."], "scenario_contexts": ["Reading a real-time FFT display to find a resonant frequency to notch out.", "Using a transfer-function analyzer, which runs FFTs on two channels, to tune a PA.", "Viewing a spectrogram of a recording to spot noise or hum."]}, "f3eee68f-aa4a-481e-91ec-7fc9551928a6": {"definition": "Feedback suppression is the automatic detection and reduction of acoustic feedback - the sustained howl or ring that builds when a microphone picks up its own amplified sound - typically by identifying the offending frequencies and applying narrow notch filters to attenuate them. Dedicated feedback suppressors or built-in algorithms place these filters dynamically as feedback emerges, aiming to raise usable gain-before-feedback while altering the overall tone as little as possible.", "plain_english": "Feedback is the loud howl when a mic hears its own sound from the speakers. Feedback suppression finds the exact pitch that is ringing. Then it turns down just that narrow pitch with a filter. This lets you run the system a bit louder before it howls.", "purpose_function": "It exists to increase gain-before-feedback and to stop feedback quickly during a show, protecting the mix and the audience. Using narrow notches instead of broad cuts keeps the sound as natural as possible.", "practical_application": "A technician inserts a feedback suppressor or enables the console's feedback feature on a wireless handheld or lectern mic, letting it place notches automatically as the talker moves around.", "category": "Signal processing", "related_terms": ["Gain before feedback", "Notch filter", "Ringing out", "Parametric EQ", "Graphic equalizer", "Frequency analyzer"], "common_mistakes": ["UNSAFE: Trusting a feedback suppressor to allow ever-higher gain, pushing levels that risk hearing damage instead of fixing mic and speaker placement.", "Relying on automatic notches instead of first ringing out the system and correcting gain structure and monitor position.", "Setting too many or too wide notch filters, which dulls the sound while chasing feedback.", "Assuming feedback suppression removes the need for good microphone technique and stage layout."], "scenario_contexts": ["Keeping a roaming presenter's lavalier mic from feeding back during a conference.", "Enabling feedback suppression on stage monitors during a fast changeover.", "Ringing out a system by hand, then leaving a suppressor active to catch surprises."]}, "041ea273-eda2-4db9-965d-cfe42c390a8e": {"definition": "Fractional-octave banding is the division of the audio spectrum into a series of contiguous bands whose widths are a fixed fraction of an octave - such as 1/1 (full octave), 1/3, 1/6, 1/12, or 1/24 octave - each band being proportionally wider at high frequencies and narrower at low frequencies. Standardized centre frequencies and filter tolerances for octave-band and fractional-octave-band filters are defined in IEC 61260 and ANSI S1.11, and the approach matches the ear's roughly logarithmic response by holding resolution constant in percentage-of-frequency terms.", "plain_english": "Human hearing works by ratios of pitch, not fixed steps. Fractional-octave banding splits the sound range into bands based on those ratios. Common choices are one-third octave or finer. Each band is wider at high pitches and narrower at low ones. This matches how we hear better than equal-width bands.", "purpose_function": "It exists to display and measure a spectrum in a way that matches how we hear, with resolution set in fractions of an octave rather than in fixed hertz steps. Choosing a finer fraction trades a smooth, broad view for more detail.", "practical_application": "A technician sets an RTA to 1/3-octave for a quick tonal overview, or to 1/12- or 1/24-octave for detailed room and system tuning.", "category": "Analysis method", "related_terms": ["Real-time analyzer (RTA)", "Frequency analyzer", "Octave", "Graphic equalizer", "Fast Fourier transform processing", "Frequency bin"], "common_mistakes": ["Assuming a 1/3-octave RTA shows enough detail to find a narrow resonance, when finer banding or an FFT is needed.", "Confusing fractional-octave bands (constant percentage width) with FFT bins (constant hertz width).", "Reading fine 1/24-octave data as more 'accurate' without realizing it is also noisier and needs averaging."], "scenario_contexts": ["Using a 1/3-octave RTA to set a graphic equalizer, whose sliders match those bands.", "Switching to 1/12-octave resolution to see a room mode clearly.", "Comparing octave-band noise measurements against a specification."]}, "6c2b1102-1bbf-4205-b3ca-434fbecf58dc": {"definition": "A frequency analyzer is a measurement instrument or software tool that displays the distribution of a signal's energy across frequency - its spectrum - showing amplitude (level) as a function of frequency. Audio frequency analyzers include real-time analyzers (RTAs) that use fractional-octave bands or FFT processing, and they let an engineer see tonal balance, individual tones, noise, and problem frequencies in a signal.", "plain_english": "A frequency analyzer shows what pitches make up a sound. It draws a chart with low notes on the left and high notes on the right. The height shows how strong each part is. Engineers use it to see a system's tone and to spot problem pitches.", "purpose_function": "It exists to turn a signal into a visible spectrum so tonal balance and problems can be judged by eye, not only by ear. Seeing the spectrum guides EQ, noise hunting, and system tuning.", "practical_application": "A technician watches a frequency analyzer while equalizing a PA, finding a ringing frequency, or checking a room's response with pink noise.", "category": "Analyzer type", "related_terms": ["Real-time analyzer (RTA)", "Fast Fourier transform processing", "Fractional-Octave Banding", "Frequency bin", "Dual-FFT analyzer", "Spectrum"], "common_mistakes": ["Thinking the analyzer's picture replaces careful listening, when the ear must confirm what the display suggests.", "Reading a jumpy spectrum instantly instead of averaging it for a stable, trustworthy view.", "Assuming a flat analyzer trace guarantees good sound, ignoring phase, coverage, and room effects."], "scenario_contexts": ["Using an RTA with pink noise to check a system's tonal balance.", "Finding a feedback frequency on a frequency analyzer in order to notch it out.", "Inspecting a recording's spectrum to locate hum or hiss."]}, "aec38014-273f-4946-81aa-0e0404fb9931": {"definition": "A frequency bin is one of the evenly spaced discrete frequency points produced by an FFT (discrete Fourier transform), each representing the signal's amplitude and phase within a small band centred on that frequency. The spacing between bins - the bin width in hertz - equals the sampling rate divided by the FFT size (the number of samples in the analyzed block), so a larger FFT gives narrower bins and finer frequency resolution.", "plain_english": "An FFT splits a signal into many equal-width slots called bins. Each bin covers a small range of frequency. It tells how much sound sits in that range. Using more samples makes the bins narrower. Narrower bins show finer detail.", "purpose_function": "Bins are the fixed frequency steps an FFT reports, and they set how finely close frequencies can be told apart. Their width, chosen by FFT size and sample rate, is the trade-off between frequency detail and time detail.", "practical_application": "When choosing an FFT size on an analyzer, a technician is really choosing bin width - a larger FFT gives narrower bins to resolve low-frequency detail, at the cost of slower updates.", "category": "Spectral analysis", "related_terms": ["Fast Fourier transform processing", "Frequency analyzer", "Dual-FFT analyzer", "Frequency resolution", "Windowing", "Fractional-Octave Banding"], "common_mistakes": ["Confusing constant-width FFT bins with constant-percentage fractional-octave bands.", "Expecting good low-frequency resolution from a small FFT, when narrow bins require a large FFT size.", "Forgetting that narrowing the bins (a larger FFT) slows the time response of the measurement."], "scenario_contexts": ["Increasing FFT size to get bins narrow enough to separate two close low-frequency tones.", "Reading a spectral display and relating each point to its bin's centre frequency.", "Choosing a measurement resolution that balances bin width against update speed."]}, "cf12461f-b354-4915-a000-5051cceb5306": {"definition": "A-frequency-weighting (A-weighting) is a standardized frequency response applied in a sound level meter that de-emphasizes low frequencies and, to a lesser extent, very high frequencies, approximating the relative loudness the ear perceives at moderate levels (based on the 40-phon equal-loudness contour). Defined with 1 kHz as the 0 dB reference in IEC 61672-1 (and ANSI S1.4 / S1.42), it is the weighting used for most environmental and occupational noise measurements, reported in dB(A) or as quantities such as LAeq and LAmax.", "plain_english": "Our ears do not hear all pitches as equally loud. Deep rumble sounds quieter than a midrange tone of the same power. A-weighting is a filter in sound meters that copies this. It lowers the weight given to deep bass. The result, in dB(A), tracks loudness better and is used for noise rules.", "purpose_function": "It exists to make a meter's single number follow perceived loudness and hearing-damage risk, since the ear is less sensitive to low frequencies. This is why most noise limits and exposure rules are written in dB(A).", "practical_application": "A technician sets a sound level meter to A-weighting to log show levels, check a venue's noise limit, or measure workplace noise exposure in dB(A).", "category": "Sound level metering", "related_terms": ["Frequency Weighting C", "Sound level meter", "LAeq", "Equal-loudness contour", "SPL", "Noise exposure"], "common_mistakes": ["UNSAFE: Assuming a low dB(A) reading means loud bass is safe, when A-weighting discounts low-frequency energy that still adds to exposure and can damage hearing over time.", "UNSAFE: Using A-weighting to judge sharp impulsive sounds, which should be assessed as C-weighted (or unweighted) peak level for hearing safety.", "Reporting a level in dB without stating the weighting, so dB(A) and unweighted values get confused.", "Believing A-weighting is correct at all levels, when it best matches the ear only at moderate loudness."], "scenario_contexts": ["Measuring LAeq in dB(A) to keep a concert under a venue's noise limit.", "Checking workplace noise exposure in dB(A) against an occupational limit.", "Logging environmental noise in dB(A) for a permit or complaint investigation."]}, "b88de8d8-9f0c-456b-9aaa-9c086d6628f2": {"definition": "C-frequency-weighting (C-weighting) is a standardized sound-level-meter response that is nearly flat across the mid band but rolls off gently at the low and high extremes, with its -3 dB points near 31.5 Hz and 8 kHz and 1 kHz as the 0 dB reference. Defined in IEC 61672-1 (and ANSI S1.4 / S1.42) and based roughly on the 100-phon equal-loudness contour, it is used for high-level and peak measurements - reported as dB(C), LCpeak, or LCeq - and to assess low-frequency content that A-weighting discounts.", "plain_english": "C-weighting is another filter setting in sound meters. It treats most pitches almost the same. It trims only the very lowest and highest ends a little. This keeps deep bass in the reading. It is used for very loud sounds, sharp peaks, and checking bass energy.", "purpose_function": "It exists to measure loud sounds and short peaks more fairly than A-weighting, because at high levels the ear responds more evenly across frequency. It also captures low-frequency energy that A-weighting removes.", "practical_application": "A technician uses C-weighting to log peak levels (LCpeak) for hearing-safety checks and to gauge sub-bass content that a dB(A) reading would understate.", "category": "Sound level metering", "related_terms": ["Frequency Weighting A", "Sound level meter", "LCpeak", "Equal-loudness contour", "SPL", "Noise exposure"], "common_mistakes": ["UNSAFE: Substituting a C-weighted average for a required peak (LCpeak) measurement, missing brief impulses that can damage hearing.", "Confusing C-weighting (nearly flat) with A-weighting (bass discounted) and comparing the two numbers directly.", "Reporting a level as dB without noting C-weighting, causing confusion with dB(A) values.", "Assuming C-weighting is fully flat, when it still rolls off below about 31.5 Hz and above about 8 kHz."], "scenario_contexts": ["Measuring peak impulsive noise as LCpeak for a hearing-protection assessment.", "Checking sub-bass energy at a concert that a dB(A) meter would understate.", "Comparing dB(C) minus dB(A) to judge how much low-frequency content a signal holds."]}, "4d7ba11f-63b8-4926-b3b8-e6b384a9c481": {"definition": "Frequency weighting Z (zero, or 'zero-frequency' weighting), standardized in IEC 61672-1, is a nominally flat frequency weighting applied in a sound level meter, with a defined near-flat response over the 10 Hz to 20 kHz band and specified tolerances. It replaces the older 'Flat' or 'Linear' weightings and is used when a measurement should not be shaped to human hearing, unlike A- or C-weighting; results are reported with the subscript Z, for example LZeq or dB(Z).", "plain_english": "Frequency weighting Z means the meter treats all pitches almost the same. It does not boost or cut any part of the sound. This gives a raw, unshaped reading. A- and C-weighting instead copy how our ears react to loudness.", "purpose_function": "It provides an unweighted reference level so the true energy across the audio band is measured without the ear-based shaping of A- or C-weighting. This makes it useful for equipment and octave-band analysis where a flat baseline is needed.", "practical_application": "A technician selects Z-weighting on a sound level meter or analyzer when capturing raw spectra or comparing octave bands, rather than an ear-weighted level for noise-exposure work.", "category": "Frequency weighting", "related_terms": ["A-weighting", "C-weighting", "Sound level meter", "IEC 61672", "Octave band analysis", "SPL"], "common_mistakes": ["Assuming Z-weighting is perfectly flat at all frequencies, when IEC 61672 defines it as flat only within stated tolerances over roughly 10 Hz to 20 kHz.", "Using Z-weighted levels to judge hearing-exposure risk, which requires A-weighting under standards such as OSHA 1910.95.", "Confusing Z-weighting with C-weighting, when C rolls off the low and high extremes and Z does not."], "scenario_contexts": ["Capturing an unweighted room spectrum for octave-band analysis with a sound level meter.", "Reporting a level as dB(Z) so it can be compared against a flat, unweighted reference.", "Measuring low-frequency content that A-weighting would heavily discount."]}, "c4c763ad-7065-4ddc-acc4-f1893830fbf9": {"definition": "Front-to-back consistency is the degree to which sound level and tonal balance stay uniform along the depth of a listening area, from the seats nearest the loudspeakers to those farthest away. It is a coverage-uniformity goal in system design and measurement: minimizing the front-to-back variation caused by distance loss and by differences between near and far coverage, often assessed by comparing transfer-function measurements taken at front, middle, and rear positions.", "plain_english": "Front-to-back consistency means the sound is about the same from the front row to the back row. The goal is that far seats are not much quieter or duller than close ones. Engineers check this by measuring at several spots in the room.", "purpose_function": "It exists as a design and tuning target so every listener hears a similar level and tone, not just the people near the speakers. Achieving it drives choices such as array splay, level tapering, and delay speakers.", "practical_application": "A system engineer measures level and response at front, middle, and rear seats and adjusts array angles, gain shading, or fill speakers until the readings match closely.", "category": "Coverage uniformity", "related_terms": ["Coverage", "Level tapering (gain shading)", "Line array", "Transfer function", "Delay speaker", "SPL"], "common_mistakes": ["Judging consistency from one mix-position measurement, when the point of the goal is to compare front, middle, and rear seats.", "Trying to fix a distance level drop with EQ alone, when array design, tapering, or fill loudspeakers are the real tools.", "Assuming a flat response at the front guarantees the same response at the back, ignoring air loss at high frequencies over distance."], "scenario_contexts": ["Tuning a line array in a deep room so the back rows match the front in level and tone.", "Adding and aligning delay speakers to hold consistency down a long space.", "Comparing transfer-function traces from several audience depths during system optimization."]}, "032939ff-5007-4e66-a508-24cdc728e2da": {"definition": "FTW is a transfer-function smoothing method in Rational Acoustics Smaart that is the functional equivalent of applying a time window to a system's impulse response and transforming the result back to the frequency domain, but computed directly on the complex frequency-domain data. Set by a nominal half-window length in milliseconds, it limits the effective time constant of the measurement to reject reflections and late-arriving energy, applying to magnitude and phase together; because its bandwidth is linear, its effect is strongest at low frequencies and it sets the lowest valid (resolvable) frequency.", "plain_english": "FTW is a way to clean up a measurement in Smaart. It acts like ignoring late echoes in a room, then showing the smoothed result. You set it by a time length in milliseconds. A shorter window smooths more, but it hides the lowest notes.", "purpose_function": "It lets an operator reduce the effect of room reflections in a transfer-function measurement without hand-editing the impulse response. This produces a cleaner view of the direct sound for tuning decisions.", "practical_application": "A system engineer turns on FTW smoothing while measuring a loudspeaker in a reflective room, choosing a window length that tames reflections while keeping the low-frequency range they need valid.", "category": "Measurement smoothing", "related_terms": ["Transfer function", "Impulse response", "Fractional-octave smoothing", "Complex averaging", "Smaart", "Time window"], "common_mistakes": ["Trusting data below the window's lowest valid frequency, which Smaart marks and which should be disregarded.", "Confusing FTW smoothing with fractional-octave smoothing, when FTW uses a linear (time-based) bandwidth and also affects phase.", "Setting too short a window, which over-smooths and discards real low-frequency detail."], "scenario_contexts": ["Measuring a PA in a reverberant room and using FTW to reduce reflection artifacts.", "Cleaning up a transfer-function trace to see direct-sound response before setting EQ.", "Choosing a window length that balances reflection rejection against low-frequency resolution."]}, "9c3b8664-220f-4087-b49b-79e42fdda777": {"definition": "Generator level is the output amplitude produced by a signal generator, such as the internal generator of an audio analyzer, set by the operator and expressed in a chosen unit (for example Vrms, dBu, dBV, or dBFS for a digital generator). It defines the stimulus level driving the device under test, and in analyzers with level regulation it can be held constant or adjusted automatically to reach a target level at a monitored point.", "plain_english": "Generator level is how strong the test tone is that a measuring tool sends out. You set it in volts or decibels. It is the signal fed into the gear you are testing. Picking the right level keeps the test fair and avoids overload.", "purpose_function": "It sets the drive level for a measurement so results are made under known, repeatable conditions. Choosing an appropriate generator level keeps the device under test within its normal operating range and avoids clipping or a poor signal-to-noise ratio.", "practical_application": "A bench technician sets the analyzer's generator level, for example to a standard reference such as +4 dBu, before measuring gain, frequency response, or distortion of a device.", "category": "Signal generation", "related_terms": ["Signal generator", "Device under test", "Reference level", "dBu", "dBFS", "Frequency response"], "common_mistakes": ["Setting the generator level too high, which overloads the device under test and produces false distortion readings.", "Assuming a dBFS setting on a digital generator equals a fixed analog voltage, when that depends on the converter's reference.", "Forgetting that with output regulation the requested level may differ from the level actually reaching a monitored point."], "scenario_contexts": ["Setting a +4 dBu generator level before sweeping a preamp's frequency response.", "Lowering generator level to keep a device below clipping during a THD measurement.", "Using automatic level setting so a target level is reached at the analyzer input."]}, "6524d4e0-c77d-411e-8795-a5788935e3ab": {"definition": "A golden trace is a stored, known-good reference measurement, most often a frequency-response or transfer-function curve captured from a unit or system confirmed to perform correctly (a 'golden unit'), against which later measurements are compared to judge whether they match. It serves as the pass/fail or alignment reference in production test and in system tuning, where new traces are overlaid on the golden trace to reveal deviations.", "plain_english": "A golden trace is a saved 'good' measurement you trust. You take it from gear that is known to work right. Later you compare new readings against it. If a new curve strays far from the golden one, something is wrong.", "purpose_function": "It gives a fixed benchmark of correct performance so testers and engineers can spot faults or drift by comparison rather than by memory. This speeds pass/fail decisions and makes repeated setups consistent.", "practical_application": "On a production line or during system setup, a technician overlays each new measurement on the golden trace and flags any unit or channel that departs from it beyond an allowed tolerance.", "category": "Reference measurement", "related_terms": ["Reference measurement", "Transfer function", "Frequency response", "Target curve", "Tolerance", "Device under test"], "common_mistakes": ["Capturing the golden trace from a unit that is not actually known-good, which sets a faulty benchmark for everything after.", "Comparing against a golden trace taken under different settings or conditions, so real differences are masked or exaggerated.", "Treating a golden trace as an exact target with no tolerance band, and rejecting normal, acceptable variation."], "scenario_contexts": ["Overlaying a device's response on a golden trace during production-line audio testing.", "Storing a reference trace of a tuned PA to check it again before the next show.", "Comparing a repaired unit against a golden trace to confirm it now performs correctly."]}, "3ab48531-8953-4ce7-9212-c26b6c566d83": {"definition": "Graphic EQ ring-out is the procedure of deliberately raising a monitor or sound-system's gain until it begins to feed back, identifying the ringing frequency by ear or on an analyzer, and cutting that frequency on a graphic equalizer, repeating the process to raise usable gain before feedback. It is a practical tuning method that trades small notches in the response for increased gain-before-feedback on stage.", "plain_english": "Ringing out is a way to stop squeal in stage monitors. You slowly turn up the level until it starts to howl. You find the pitch that howls and turn just that band down on a graphic EQ. Repeat until the system is loud enough without feedback.", "purpose_function": "It raises how much level a monitor or microphone can produce before feedback starts, by trimming the exact frequencies that ring first. This gives performers more level while keeping the system stable.", "practical_application": "Before a show, an engineer brings up each monitor mix until it rings, pulls down the offending band on the graphic EQ, and repeats to set a safe, usable level.", "category": "System tuning", "related_terms": ["Graphic equalizer", "Feedback", "Gain before feedback", "Stage monitor", "Real-time analyzer (RTA)", "Notch filter"], "common_mistakes": ["UNSAFE: Driving the system hard into sustained feedback while ringing out, which can reach damaging levels and harm hearing and drivers; raise gain only until it just begins to ring, then stop.", "Cutting too many bands or too deeply, which thins the sound instead of adding usable gain.", "Ringing out with no one at the microphones, so the result does not match how the system behaves in use.", "Confusing the true feedback frequency with a nearby band and cutting the wrong slider."], "scenario_contexts": ["Ringing out wedge monitors before a band's soundcheck to raise gain before feedback.", "Notching a graphic EQ on a lectern microphone to stop feedback in a speech system.", "Using an RTA to help identify feedback frequencies while ringing out a room."]}, "f8a369f6-b0b3-43e6-a3d1-aa9b85a6ae1b": {"definition": "Horizontal coverage is the side-to-side angular width over which a loudspeaker radiates useful output, conventionally defined as the included angle between the points where the sound pressure level has fallen 6 dB below the on-axis level in the horizontal plane. Because directivity varies with frequency, a single stated horizontal coverage angle is a nominal figure, and full behavior is better shown by polar or balloon plots across the band.", "plain_english": "Horizontal coverage is how wide a speaker throws sound left to right. It is measured by finding where the sound drops 6 dB below the level dead ahead. The angle between those two points is the coverage. Real speakers cover wider at low pitches and narrower at high ones.", "purpose_function": "It tells the designer how wide an area one loudspeaker can serve, so boxes can be chosen and aimed to cover the audience with even level and few gaps or overlaps. It is a core input to layout and array design.", "practical_application": "A system designer picks a loudspeaker whose horizontal coverage matches the width of the seating from its position, then aims and overlaps boxes so the whole audience is covered.", "category": "Loudspeaker coverage", "related_terms": ["Vertical coverage", "Coverage angle", "Directivity", "Polar pattern", "Beamwidth", "Off-axis response"], "common_mistakes": ["Treating the single published coverage angle as valid at all frequencies, when coverage narrows toward high frequencies.", "Assuming equal level everywhere inside the coverage angle, when the -6 dB edge is already noticeably quieter and distance adds further loss.", "Confusing horizontal with vertical coverage when a specification is written as horizontal by vertical (for example 90 by 40)."], "scenario_contexts": ["Choosing a 90-degree horizontal box to cover a wide seating block from the stage.", "Aiming and overlapping loudspeakers so their -6 dB edges meet for even coverage.", "Reading a polar plot to see how horizontal coverage changes with frequency."]}, "b40fc7f1-4cd1-487e-be6b-0e91f3c6bef7": {"definition": "Image stability is the degree to which the perceived location and size of sound sources in a stereo or multichannel reproduction stay fixed and well defined, rather than shifting, blurring, or collapsing, as program content changes or as the listener moves within the listening area. In monitoring and loudspeaker evaluation it is a spatial-quality attribute, influenced by inter-channel level and time matching, loudspeaker directivity and matching, room reflections, and listener position relative to the sweet spot.", "plain_english": "Image stability is how solidly a sound sits in one place between the speakers. With good stability, a voice stays put and clear as the music changes. With poor stability, it drifts or smears. Matched speakers, good placement, and sitting centered all help.", "purpose_function": "It matters because reliable mixing and mastering decisions depend on hearing where sounds sit and how wide the image is. Good image stability lets an engineer trust panning, balance, and spatial choices across a session.", "practical_application": "An engineer checks image stability by confirming a centered mono signal images as a tight center and that panned sources hold position, using it to judge monitor setup, matching, and room treatment.", "category": "Spatial quality", "related_terms": ["Phantom center", "Stereo image", "Sweet spot", "Monitor calibration", "Localization", "Inter-channel level difference"], "common_mistakes": ["Blaming a wandering image on the recording when mismatched monitor levels or an off-center listening position are the cause.", "Judging image stability from far off the sweet spot, where the image naturally pulls toward the nearer loudspeaker.", "Ignoring early room reflections, which blur the image even when the loudspeakers themselves are well matched."], "scenario_contexts": ["Checking that a mono sum images as a tight phantom center when setting up monitors.", "Comparing two monitors' image stability while auditioning them in the same room.", "Adding early-reflection treatment to firm up a smeared stereo image at the mix position."]}, "377dd5b3-685c-44e1-9bd0-27461988ed67": {"definition": "Input range is the span of signal levels a measuring instrument or input stage can accept and process correctly, from its noise floor up to its maximum level before overload or clipping, often selectable in steps (for example on an audio analyzer or measurement front end). Setting the input range to suit the incoming signal maximizes usable dynamic range: too low a range clips high peaks, while too high a range buries low-level detail in noise.", "plain_english": "Input range is the band of levels a meter or analyzer can read without trouble. Below it, signals vanish into noise. Above it, they overload and clip. You pick a range that fits the signal so the reading stays clean and accurate.", "purpose_function": "It lets the instrument's front end handle a wide variety of signal levels while keeping the best signal-to-noise ratio and avoiding overload. Correct range selection is what makes a measurement both clean and undistorted.", "practical_application": "A technician chooses or auto-sets the input range on an analyzer so the signal sits well below clipping but well above the noise floor before taking a reading.", "category": "Measurement setup", "related_terms": ["Dynamic range", "Clipping", "Noise floor", "Headroom", "Full scale", "Gain staging"], "common_mistakes": ["Setting the input range too low, so signal peaks clip and the measurement reads false distortion.", "Setting the input range too high, which sinks low-level signals into the noise floor.", "Assuming a fixed input range fits every signal, rather than adjusting it or using auto-ranging for each measurement."], "scenario_contexts": ["Selecting an input range on an audio analyzer before measuring a device's output.", "Using auto-ranging so the analyzer sets a suitable input range for the signal.", "Raising the input range after an overload indicator lights during a test."]}, "76126331-49f9-4c1d-a60d-01be88f20b45": {"definition": "Inter-sample distortion is the degradation that occurs when the continuous waveform reconstructed from PCM samples overshoots the highest stored sample values, creating peaks between samples (inter-sample peaks) that can exceed 0 dBFS; if a digital-to-analog converter, sample-rate converter, or lossy codec lacks the headroom to pass these overshoots, they clip and add harmonic and intermodulation distortion. Ordinary sample-reading meters do not show these peaks, so true-peak meters as defined in ITU-R BS.1770, which oversample the signal by at least four times and read in dBTP, are used to detect them.", "plain_english": "Digital audio stores sound as a row of dots called samples. The smooth wave that plays back can rise higher than the tallest dot. If that hidden peak goes past the top limit, the gear may clip it and add harsh distortion. True-peak meters catch these hidden peaks.", "purpose_function": "The concept explains why audio that never shows an over on a normal sample meter can still distort on playback. It drives the use of true-peak (dBTP) metering and a headroom margin so reconstructed peaks stay within a converter's or codec's limits.", "practical_application": "A mastering or broadcast engineer watches a true-peak meter and sets a limiter ceiling below full scale, commonly -1 dBTP, so inter-sample peaks do not clip listeners' converters or streaming codecs.", "category": "Digital metering", "related_terms": ["True peak (dBTP)", "dBFS", "Sample peak", "Oversampling", "Digital clipping", "Crest factor"], "common_mistakes": ["Believing that keeping every sample at or below 0 dBFS guarantees no clipping, when inter-sample peaks can still exceed 0 dBFS after reconstruction.", "Reading only a sample-peak meter and ignoring true-peak (dBTP) level, so overshoots go unseen.", "Assuming inter-sample overshoots are harmless, when lossy encoders and converter filters can turn them into audible distortion."], "scenario_contexts": ["Mastering a loud track for streaming and setting a -1 dBTP ceiling to meet a platform's true-peak requirement.", "Diagnosing crackle that appears only after MP3 or AAC encoding of a hot master.", "Checking a broadcast mix against EBU R128, which caps true peak at -1 dBTP."]}, "a5117cd7-c56e-49d3-ad76-199bab3915d3": {"definition": "K-12 is the narrowest-headroom scale of Bob Katz's K-System metering standard, in which 0 dB on the meter is aligned to -12 dBFS, leaving 12 dB of headroom above the reference for peaks. Its monitor gain is calibrated so that a 0 dB (-12 dBFS) reference signal produces about 83 dB SPL (C-weighted, slow) per channel, and it is intended for broadcast and radio material, where limited dynamic range and higher average loudness are expected.", "plain_english": "K-12 is a setting of Bob Katz's metering system. Its zero mark sits 12 dB below the digital ceiling. That leaves the least room for peaks of the three scales. It suits broadcast and radio, where a steady, loud level matters most.", "purpose_function": "K-12 gives the least headroom of the K-System scales so it fits broadcast and radio, which run at high average loudness with little dynamic range. Its calibrated monitor level keeps loudness judgments consistent between rooms.", "practical_application": "An engineer preparing content for radio or television selects K-12 metering and calibrates the monitor gain, mixing so average level sits near meter 0 with peaks using the modest headroom above.", "category": "Metering scale", "related_terms": ["K-System metering", "K-14", "K-20", "Crest factor", "Loudness (LUFS)", "Monitor calibration"], "common_mistakes": ["Thinking the '12' is a loudness target, when it is the number of headroom decibels above the meter's 0 reference (0 = -12 dBFS).", "Using K-12 for wide-dynamic material such as film or classical, where its narrow headroom forces heavy limiting.", "Reading the K-12 meter without calibrating the monitor gain, which discards the system's consistent loudness reference."], "scenario_contexts": ["Mastering a spot or programme for radio broadcast to a loud, narrow-range target.", "Preparing television audio that must sit at a high, steady average level.", "Comparing a broadcast mix on K-12 against the same content on K-14 or K-20."]}, "82660dbb-22ae-4523-90ef-395d79f3052c": {"definition": "K-14 is the middle-headroom scale of Bob Katz's K-System metering standard, in which 0 dB on the meter is aligned to -14 dBFS, leaving 14 dB of headroom above the reference for peaks. Its monitor gain is calibrated so that a 0 dB (-14 dBFS) reference signal produces about 83 dB SPL (C-weighted, slow) per channel, and it is intended for high-fidelity home-listening music such as rock, pop, and folk.", "plain_english": "K-14 is a setting of Bob Katz's metering system. Its zero mark sits 14 dB below the digital ceiling. That leaves a medium amount of room for peaks. It suits rock, pop, and folk made for home listening.", "purpose_function": "K-14 gives a moderate headroom that balances loudness and dynamics for mainstream music aimed at home listeners. Its calibrated monitor level ties what the meter shows to how loud the mix actually sounds.", "practical_application": "A mastering engineer working on a pop or rock album selects K-14 metering and calibrates the monitors, keeping average level near meter 0 (-14 dBFS) with peaks in the 14 dB above.", "category": "Metering scale", "related_terms": ["K-System metering", "K-12", "K-20", "Crest factor", "Loudness (LUFS)", "Monitor calibration"], "common_mistakes": ["Thinking the '14' is a loudness target, when it is the number of headroom decibels above the meter's 0 reference (0 = -14 dBFS).", "Assuming K-14 forces a 'loudness war' master, when it simply defines headroom and a monitoring reference.", "Using the K-14 meter without setting the calibrated monitor gain, which breaks the link between metered level and heard loudness."], "scenario_contexts": ["Mastering a rock or pop record for streaming and CD release to home listeners.", "Choosing K-14 over K-20 because the genre expects less dynamic range.", "Calibrating a mastering room so K-14 0 dB reads about 83 dB SPL per channel."]}, "877108dd-bdb3-4534-af53-a22a5517d30c": {"definition": "K-20 is the widest-headroom scale of Bob Katz's K-System metering standard, in which 0 dB on the meter is aligned to -20 dBFS, leaving 20 dB of headroom above the reference for peaks. Its monitor gain is calibrated so that a 0 dB (-20 dBFS) reference signal produces about 83 dB SPL (C-weighted, slow) per channel, and it is intended for wide-dynamic-range material such as film, classical, and other audiophile productions.", "plain_english": "K-20 is a setting of Bob Katz's metering system. Its zero mark sits 20 dB below the digital ceiling. That leaves lots of room for loud peaks. It suits music with big soft-to-loud swings, like film scores and classical.", "purpose_function": "K-20 gives the most headroom of the K-System scales so engineers mixing dynamic material never have to squash peaks. Pairing the meter with a fixed monitor level keeps loudness judgments consistent between rooms.", "practical_application": "A film or classical mastering engineer selects K-20 metering and calibrates each monitor to about 83 dB SPL, mixing so average level sits near meter 0 (-20 dBFS) with peaks using the headroom above.", "category": "Metering scale", "related_terms": ["K-System metering", "K-14", "K-12", "Crest factor", "Loudness (LUFS)", "Monitor calibration"], "common_mistakes": ["Thinking the '20' is a loudness target, when it is the number of headroom decibels above the meter's 0 reference (0 = -20 dBFS).", "Choosing K-20 for a loud pop master, where its wide headroom leaves the level below what the genre expects.", "Using the K-20 meter without calibrating the monitor gain, which discards the system's consistent loudness reference."], "scenario_contexts": ["Mixing or mastering a film soundtrack that needs wide dynamic range.", "Working on an orchestral or classical recording with quiet and very loud passages.", "Calibrating monitoring so K-20 0 dB reads about 83 dB SPL per channel for critical work."]}, "2364809c-77a8-4190-a6bf-917f7e7c7f61": {"definition": "K-System metering is an integrated metering and monitoring standard devised by mastering engineer Bob Katz that pairs a level meter, whose 0 dB reference sits a fixed number of decibels below full scale, with a matching calibrated monitor gain. It offers three scales - K-20, K-14, and K-12 - placing 0 dB at -20, -14, or -12 dBFS respectively, each calibrated so that meter 0 produces about 83 dB SPL (C-weighted) per channel, thereby linking the level shown on the meter to the loudness heard in the room.", "plain_english": "The K-System is a way to meter and monitor made by Bob Katz. It links the meter's zero mark to a set listening loudness. You pick one of three scales for different kinds of work. This keeps what you see and what you hear in step across rooms.", "purpose_function": "It exists to stop the loudness war by tying metered level to a calibrated monitoring level, so engineers judge loudness by ear against a fixed reference rather than pushing meters ever higher. The three scales suit different amounts of dynamic range.", "practical_application": "An engineer chooses the scale that fits the job (K-20 for film, K-14 for pop, K-12 for broadcast), calibrates the monitors so meter 0 reads about 83 dB SPL per channel, then mixes with average level around 0.", "category": "Metering system", "related_terms": ["K-20", "K-14", "K-12", "Monitor calibration", "Loudness (LUFS)", "Crest factor"], "common_mistakes": ["Using a K-System meter but skipping the monitor calibration, which removes the loudness reference that makes the system work.", "Treating the scale number as a target loudness, when it is the headroom in decibels above the meter's 0 reference.", "Assuming the three scales are different meters, when they are the same meter referenced to different points below full scale."], "scenario_contexts": ["Setting up a mastering room with calibrated monitoring and a chosen K-System scale.", "Switching scales when moving from a film project to a pop project.", "Explaining to a client why a K-System mix is not pushed to maximum loudness."]}, "a95ecefb-38c3-4a9c-8814-74a862bdec1a": {"definition": "An LAeq show limit is a maximum permitted A-weighted equivalent continuous sound level (LAeq), averaged over a defined window such as 15 minutes or the whole performance, that is imposed on a live event by the venue's licence, a local authority, or a promoter contract to protect audience and worker hearing and to control off-site noise. LAeq, defined for sound level meters in IEC 61672, is the steady level that would carry the same A-weighted sound energy as the fluctuating programme over the measurement period.", "plain_english": "An LAeq show limit is a cap on how loud a show can be on average. The level is measured over a set time, like 15 minutes, not just one instant. Venues or local officials set it to protect ears and to limit noise for neighbours.", "purpose_function": "It exists to keep the average sound energy of an event within a safe and legally allowed level, protecting hearing and reducing noise complaints. Averaging over time, rather than reading peaks, matches how sound exposure affects the ear.", "practical_application": "A front-of-house engineer watches a running LAeq reading on a calibrated meter or monitoring system and holds the mix below the contracted limit, easing back when the average creeps up.", "category": "Sound level metering", "related_terms": ["LAeq", "A-weighting", "Sound level meter", "Leq", "Noise exposure", "SPL"], "common_mistakes": ["UNSAFE: Treating the LAeq limit as a peak ceiling, so brief bursts far above it are allowed even though they still risk hearing damage.", "UNSAFE: Assuming that staying under the LAeq limit removes any need for hearing protection for crew exposed all day.", "Confusing the time-averaged LAeq with the instantaneous SPL on the meter, and mixing to the higher instant reading.", "Forgetting that LAeq is A-weighted, so heavy sub-bass energy counts less toward the number than it feels."], "scenario_contexts": ["A festival stage running under a council noise limit measured as LAeq over 15-minute periods.", "A house engineer holding a mix below a venue's contracted LAeq figure.", "A monitoring system at front of house displaying live LAeq so the operator can stay legal."]}, "6e7ce4a1-d664-402b-a92b-58f535065c95": {"definition": "Level tapering, also called gain shading, is the deliberate setting of different drive levels to individual loudspeakers or zones within an array - most often reducing the level of the top and/or bottom boxes of a line array - so that sound pressure level is distributed more evenly across the audience from front to back. By trading some level where the array is closest to listeners for more where it is farthest, and by softening the array's acoustic aperture at its edges, tapering smooths coverage and reduces uneven lobing.", "plain_english": "Level tapering means feeding some speakers in an array less power than others. Often the top and bottom boxes are turned down. This spreads the sound more evenly from the front row to the back. It stops the near seats being far louder than the far ones.", "purpose_function": "It exists to even out front-to-back loudness in a room, since boxes aimed at nearby seats otherwise sound much louder than those covering the distant seats. Shading the array edges also reduces coverage irregularities caused by the array's aperture.", "practical_application": "A system engineer assigns amplifier channels or zones to sections of a line array and lowers the drive to the lower boxes so the back rows and front rows hear a similar level.", "category": "Array optimization", "related_terms": ["Line array", "Amplitude shading", "Coverage", "SPL", "Splay angle", "Array processing"], "common_mistakes": ["Confusing level tapering with splay-angle adjustment, when tapering changes drive level and splay changes the angle between boxes.", "Tapering the top boxes too much, which starves the distant seats the upper boxes are meant to reach.", "Assuming one amplifier channel per box is always available, when boxes often must be grouped, limiting how finely the array can be shaded."], "scenario_contexts": ["Tuning a line array in a flat-floor room so the back rows are not much quieter than the front.", "Reducing near-field level from the bottom boxes to protect front-row listeners.", "Using prediction software to plan gain shading before a show."]}, "d37389e0-45f0-4c47-9da4-7ae42bcd94e4": {"definition": "In audio measurement software such as Smaart, Live Mode is the operating state in which the analysis engine continuously acquires the signal at its inputs and updates the on-screen measurements in real time, as opposed to reviewing captured, stored, or recalled data. In Live Mode the displayed traces (RTA, spectrum, transfer function) reflect what is happening at the inputs at that moment rather than a frozen snapshot.", "plain_english": "Live Mode is when a measurement tool shows the sound coming in right now. The display keeps updating in real time. It is the opposite of looking back at a saved reading.", "purpose_function": "It lets an operator watch a system respond as they make changes, so tuning decisions are based on the current state of the signal. Separating live from stored data keeps real-time measurements distinct from saved references.", "practical_application": "A system tech runs the analyzer in Live Mode while adjusting EQ or delay, watching the live trace move, then captures a snapshot to compare against later changes.", "category": "Analyzer operation", "related_terms": ["Live trace", "Real-time analyzer (RTA)", "Transfer function", "Capture", "Smaart", "Averaging"], "common_mistakes": ["Confusing a live, updating measurement with a captured trace, and adjusting the system against old stored data.", "Forgetting that a noisy live trace often needs averaging before it can be trusted for decisions.", "Assuming the live display is frozen, and missing that it is changing with the room and program material."], "scenario_contexts": ["Tuning a PA in real time while watching the analyzer's live response.", "Ringing out monitors and watching feedback frequencies appear on the live display.", "Switching between live measurement and a stored reference curve during system alignment."]}, "2600880a-1ae0-4732-bb09-d9f1d0389465": {"definition": "A live trace is the continuously updating, real-time measurement curve shown by an audio analyzer - such as an RTA, spectrum, or transfer-function display - that reflects the signal present at the inputs at the current moment. It is distinguished from a captured or stored (static) trace, which is a frozen snapshot saved for comparison or reference.", "plain_english": "A live trace is the line on an analyzer that updates in real time. It shows what the signal is doing right now. You can freeze a copy to compare it against a saved trace later.", "purpose_function": "It shows the immediate effect of any change to the system, so an engineer can tune EQ, level, and delay while watching the result. Keeping it separate from stored traces lets the current state be compared with a saved target.", "practical_application": "During PA alignment a technician watches the live trace shift as they change a filter, then captures it to build up a set of reference curves.", "category": "Analyzer display", "related_terms": ["Live Mode", "Real-time analyzer (RTA)", "Transfer function", "Capture", "Trace (measurement)", "Averaging"], "common_mistakes": ["Reading a jumpy live trace instantly, when it needs averaging over time to be reliable.", "Mistaking a captured (static) trace for the live one, and tuning against outdated data.", "Assuming a single live trace is a full picture, when several measurement points may be needed."], "scenario_contexts": ["Watching the live trace respond while EQ-ing a loudspeaker system.", "Comparing the live trace to a stored target curve during alignment.", "Spotting a bad cable or driver when the live trace shows an unexpected dip."]}, "19e305a9-5acb-4e24-b24f-d5046c52c5d6": {"definition": "In sound level metering per IEC 61672, Lmax is the highest time-weighted (Fast, Slow, or Impulse) sound level reached during a measurement period, and Lmin is the lowest, both expressed in decibels with a stated frequency weighting (such as A) and time weighting. They mark the extremes of a fluctuating level over the period and are distinct from the peak sound level, which uses peak rather than time-weighted detection.", "plain_english": "Lmax is the loudest reading a sound meter shows during a set time. Lmin is the quietest reading in that same time. They mark the high and low points of a changing sound level. They are not the same as the true peak.", "purpose_function": "They capture the loudest and quietest moments of a varying sound level, so a single average like Leq is not the only figure reported. This helps flag brief loud events that an average can hide.", "practical_application": "A technician logging show or environmental noise reads Lmax to check the loudest moment against a limit, and Lmin to gauge the quiet background level.", "category": "Sound level metering", "related_terms": ["LAeq", "Sound level meter", "Leq", "Peak sound level", "A-weighting", "Time weighting (Fast/Slow)"], "common_mistakes": ["Confusing Lmax with the peak level, when Lmax uses a time weighting (Fast or Slow) and peak detection does not.", "Reporting Lmax without stating the frequency and time weighting, so the number cannot be compared meaningfully.", "UNSAFE: Treating a low Lmax as proof a space is safe, ignoring that steady exposure measured as Leq over hours still risks hearing damage."], "scenario_contexts": ["Logging a concert's loudest moment (Lmax) against a venue noise limit.", "Measuring environmental noise where Lmin shows the quiet background level.", "Comparing Lmax with Leq to judge how peaky a sound source is."]}, "1591a834-3fc0-4f97-a411-146823a9bf14": {"definition": "Lobing is the pattern of alternating constructive and destructive interference lobes that forms in the combined radiation of two or more sound sources, or of the separate drivers of a multi-way loudspeaker, when their outputs overlap where path-length differences to a listener span a significant fraction of a wavelength. In a multi-way loudspeaker the crossover region produces lobing error, in which the main radiation lobe tilts off the design axis and secondary lobes and nulls shift as the listening angle changes.", "plain_english": "Lobing happens when two or more speakers or drivers play the same sound. Their waves meet and either add up or cancel out. This makes the sound louder in some directions and weaker in others. That pattern of strong and weak spots is called lobing.", "purpose_function": "The idea explains why coverage is uneven when several sources overlap, and why response changes with listening angle near a crossover. It guides driver spacing, crossover design, and array layout to keep coverage smooth.", "practical_application": "A system technician sets driver spacing, crossover, and delay to limit lobing, and checks off-axis response so the tilted lobe and nulls do not land on the audience.", "category": "Loudspeaker behavior", "related_terms": ["Comb filtering", "Crossover", "Line array", "Polar pattern", "Interference", "Coverage angle"], "common_mistakes": ["Confusing lobing with comb filtering, when lobing is the angular pattern of lobes and nulls while comb filtering is the resulting frequency response.", "Assuming a two-way speaker radiates evenly through its crossover, when lobing tilts the main lobe off axis there.", "Spacing stacked boxes far apart to gain level, which worsens lobing and creates narrow nulls across the audience."], "scenario_contexts": ["Stacking two subwoofers and finding cancellation nulls at certain angles.", "Measuring a two-way monitor off-axis and seeing a dip at the crossover frequency.", "Choosing driver spacing so the crossover lobe stays on the audience."]}, "6b542824-11c6-489b-a31a-690ff4e37355": {"definition": "Loudness Range (LRA), defined in EBU Tech 3342, is a single-figure descriptor, expressed in Loudness Units (LU), of the macro-dynamic variation of loudness across a programme. It is computed from the statistical distribution of short-term loudness (a 3-second sliding window using ITU-R BS.1770 K-weighting) as the difference between the 10th and 95th percentiles, after applying an absolute gate of -70 LUFS and a relative gate 20 LU below the ungated mean.", "plain_english": "Loudness Range, or LRA, shows how much the loudness of a program changes from soft to loud. It is one number measured in loudness units. A big number means big swings between quiet and loud parts. A small number means a fairly steady loudness.", "purpose_function": "It gives one figure for how dynamic a programme is, complementing the single integrated loudness value, so an engineer can tell if material is too squashed or too dynamic for its platform. The percentile method ignores brief extremes and fade-outs.", "practical_application": "A broadcast or mastering engineer reads LRA to check a mix against a delivery spec, applying compression if the range is too wide for the target platform.", "category": "Loudness metering", "related_terms": ["LUFS Integrated", "LUFS Short-Term", "EBU R128", "Dynamic range", "Loudness Units (LU)", "Crest factor"], "common_mistakes": ["Confusing LRA with dynamic range or crest factor, when LRA is a gated statistical measure of loudness variation, not a peak-to-RMS figure.", "Reading LRA from a very short clip, which gives an unreliable value.", "Assuming a low LRA is always better, when over-compressing just to hit a number can harm the material."], "scenario_contexts": ["Checking a programme's LRA against a broadcaster's delivery specification.", "Comparing the LRA of a dynamic film mix with that of a loud pop master.", "Deciding how much compression a mix needs to suit a streaming platform."]}, "a3ecae7c-9a06-41ce-bb4d-7739cc377a7c": {"definition": "A loudspeaker management system is a dedicated digital signal processor placed between a mixing console's outputs and the power amplifiers that performs the crossover, equalization, time alignment (delay), gain, routing, and protective limiting needed to drive a multi-way loudspeaker system correctly. Also called a loudspeaker processor or system controller, it commonly holds factory or user presets tailored to specific loudspeaker models and configurations.", "plain_english": "A loudspeaker management system is a processor between the mixer and the amplifiers. It splits the sound into the right frequency bands for each driver. It also adds delay, EQ, and limiting to protect the speakers. Presets set it up for a certain speaker model.", "purpose_function": "It conditions and protects a loudspeaker system by splitting the signal to each driver, aligning timing, shaping response, and limiting levels so amplifiers and drivers operate safely and as designed. Centralizing these functions keeps a large PA consistent and manageable.", "practical_application": "A system engineer loads the manufacturer preset for the deployed boxes, then sets crossover points, delay, EQ, and limiter thresholds in the processor before sending signal to the amplifiers.", "category": "System processing", "related_terms": ["Crossover", "Limiter", "Delay", "Signal processing", "Power amplifier", "Line array"], "common_mistakes": ["UNSAFE: Bypassing or raising the processor's protective limiters to gain more level, which can overheat and destroy drivers.", "Loading the wrong loudspeaker preset, so crossover and limiter settings do not match the boxes in use.", "Confusing the management system with the power amplifier, when it processes signal but does not itself drive the speakers."], "scenario_contexts": ["Setting up a line array with the manufacturer's processor preset before a show.", "Time-aligning subwoofers and tops using delay in the loudspeaker processor.", "Protecting drivers with limiter thresholds set in the system controller."]}, "19044f47-4059-4bff-ab85-9de625e23fb2": {"definition": "Integrated loudness, measured in LUFS (Loudness Units relative to Full Scale), is the single loudness value for an entire programme or segment, computed per ITU-R BS.1770 using K-weighting and mean-square energy over the whole duration with two-stage gating: an absolute gate at -70 LUFS and a relative gate 10 LU below the absolute-gated level, which exclude silence and low-level passages. EBU R128 sets a target integrated loudness of -23 LUFS.", "plain_english": "Integrated LUFS is one loudness number for a whole track or program. It measures the average loudness from start to finish. Quiet gaps are left out so they do not drag the number down. Streaming and TV use this figure to keep programs at a steady loudness.", "purpose_function": "It provides one representative loudness figure for a whole programme, so different tracks or shows can be matched to a common target. The gating removes silence and quiet passages so the value reflects the main content.", "practical_application": "A mastering or broadcast engineer measures integrated LUFS over the full mix and adjusts overall gain to hit a target such as -23 LUFS (EBU R128) or a streaming platform's spec.", "category": "Loudness metering", "related_terms": ["LUFS Momentary", "LUFS Short-Term", "Loudness Range (LRA)", "EBU R128", "True peak (dBTP)", "Loudness Units (LU)"], "common_mistakes": ["Confusing integrated LUFS with peak level, when it measures average gated loudness, not the highest sample or true peak.", "Measuring only part of a track, which gives an integrated value that does not represent the whole.", "Assuming that raising integrated loudness is free, when it usually costs dynamic range or true-peak headroom."], "scenario_contexts": ["Mastering a song to a streaming target such as -14 LUFS integrated.", "Checking a television programme meets the -23 LUFS EBU R128 target.", "Matching the loudness of several tracks across an album."]}, "bd963941-eec4-4cf6-886d-939620e39508": {"definition": "Momentary loudness (M), defined in EBU Tech 3341, is a loudness reading in LUFS taken over a 0.4-second (400 ms) sliding rectangular window using ITU-R BS.1770 K-weighting, and it is not gated. It tracks very short-term loudness fluctuations and updates rapidly, so an operator can see near-instantaneous changes in programme loudness.", "plain_english": "Momentary LUFS measures loudness over a very short window of 0.4 seconds. It updates fast, so it follows quick changes in loudness. It has no gate, so it reacts to everything. It shows roughly how loud the sound is right now.", "purpose_function": "It shows the loudness of the last fraction of a second, letting an operator catch sudden loud moments in real time. Its short window makes it the most responsive of the three loudness time scales.", "practical_application": "A live or broadcast operator watches momentary LUFS to spot sudden loud events, such as a shout or an effect, as they happen.", "category": "Loudness metering", "related_terms": ["LUFS Short-Term", "LUFS Integrated", "Loudness Range (LRA)", "EBU R128", "K-weighting", "True peak (dBTP)"], "common_mistakes": ["Using momentary loudness to set overall program level, when integrated LUFS is the value for that.", "Expecting momentary and integrated readings to match, when the short ungated window swings far more.", "Forgetting momentary is ungated, so it reacts even to brief low-level material."], "scenario_contexts": ["Watching momentary LUFS during a live broadcast to catch sudden loud moments.", "Checking how a loud effect reads on the momentary meter.", "Teaching the difference between momentary, short-term, and integrated loudness."]}, "51d0ee9e-bf1d-476f-89d9-caaa40a433e0": {"definition": "Short-term loudness (S), defined in EBU Tech 3341, is a loudness reading in LUFS taken over a 3-second sliding rectangular window using ITU-R BS.1770 K-weighting, and it is not gated. Sitting between momentary (0.4 s) and integrated (whole-programme) measurements, it shows loudness trends over the last few seconds.", "plain_english": "Short-term LUFS measures loudness over the last 3 seconds. It is slower than the momentary meter but faster than the whole-program number. It has no gate. It shows the loudness trend over a few seconds.", "purpose_function": "It reveals how loudness moves over a few seconds, smoothing the very fast swings of the momentary meter while still responding to change. This helps an operator judge the general loudness of a passage.", "practical_application": "A broadcast or mastering engineer watches short-term LUFS to keep a scene or section within a loudness range, mixing so it stays near the target.", "category": "Loudness metering", "related_terms": ["LUFS Momentary", "LUFS Integrated", "Loudness Range (LRA)", "EBU R128", "K-weighting", "Loudness Units (LU)"], "common_mistakes": ["Confusing short-term with integrated loudness, when short-term uses a 3-second window and integrated covers the whole programme.", "Expecting short-term loudness to be gated, when it is ungated like the momentary meter.", "Setting final program loudness from short-term values instead of the integrated figure."], "scenario_contexts": ["Keeping a dialogue scene within a loudness window using the short-term meter.", "Watching short-term LUFS to spot a section that drifts too loud or too soft.", "Building the loudness range measurement, which is derived from short-term values."]}, "35d747e7-5484-41cb-aaf1-082f31b8d7bc": {"definition": "In audio measurement software such as Smaart, the magnitude display is the portion of a transfer-function (frequency-response) measurement that plots level in decibels against frequency, showing how much a system boosts or cuts each frequency relative to its input. It is presented alongside, but separately from, the phase display, which shows the timing relationship across frequency.", "plain_english": "The magnitude display is a graph of level against frequency. It shows how much a system makes each frequency louder or quieter. Peaks mean boosts and dips mean cuts. It is one half of a transfer-function measurement, the other half being phase.", "purpose_function": "It shows the frequency response of a system under test, so an engineer can see tonal balance and where the response is uneven. Separating magnitude from phase lets level and timing be read independently.", "practical_application": "A system technician reads the magnitude display while adjusting EQ, aiming for a smooth response and flattening peaks or filling dips shown on the curve.", "category": "Analyzer display", "related_terms": ["Transfer function", "Phase display", "Magnitude spectrum", "Real-time analyzer (RTA)", "Smaart", "Frequency response"], "common_mistakes": ["Adjusting EQ from the magnitude curve alone while ignoring phase and coherence.", "Chasing every small bump flat, when some are measurement artifacts or room reflections.", "Confusing the transfer-function magnitude with a raw spectrum, when magnitude compares output to input."], "scenario_contexts": ["Tuning a PA's frequency response on the magnitude display in Smaart.", "Aligning a subwoofer to the mains by reading magnitude and phase together.", "Spotting a resonant peak in a room from the magnitude curve."]}, "0dcbf14d-c5e9-49ee-acd6-45d21b983801": {"definition": "The magnitude spectrum is the plot of the magnitude (amplitude) of each frequency component of a signal against frequency, obtained by taking the absolute value of the signal's Fourier transform, commonly computed with an FFT. It shows how much energy the signal holds at each frequency and discards the phase information carried by the complementary phase spectrum.", "plain_english": "The magnitude spectrum shows how much of each frequency, or pitch, is in a sound. Tall bars mean strong frequencies and short bars mean weak ones. It comes from a math tool that splits a sound into its frequencies. It leaves out timing, which the phase spectrum shows.", "purpose_function": "It reveals the frequency content of a signal, so an engineer can see which frequencies are strong or weak. This underpins spectrum analyzers, EQ decisions, and noise hunting.", "practical_application": "An engineer reads the magnitude spectrum on an analyzer to find a hum, a resonant frequency, or the overall tonal balance of a source.", "category": "Frequency analysis", "related_terms": ["FFT", "Magnitude Display", "Phase spectrum", "Frequency response", "Real-time analyzer (RTA)", "Spectrum analyzer"], "common_mistakes": ["Thinking the magnitude spectrum holds all information about a signal, when the phase is discarded.", "Confusing the magnitude spectrum with the time waveform, when one is frequency-based and the other time-based.", "Reading FFT bin levels without accounting for the window and frequency-resolution settings."], "scenario_contexts": ["Finding a 50 or 60 Hz hum by its spike in the magnitude spectrum.", "Checking the tonal balance of a mix on a spectrum analyzer.", "Identifying a resonant ring by a peak in the spectrum."]}, "95430c01-19d9-4e55-957d-dacbdfa7da0d": {"definition": "Main-to-delay alignment is the process of time-adjusting a delay (relay) loudspeaker so its output arrives in step with sound from the main system in the zone where their coverage overlaps. The delay speaker's electronic delay is set to the acoustic travel time from the mains to that zone, usually plus a small offset (roughly 5-15 ms, the Haas or precedence offset) so listeners still localize the sound to the distant main source rather than the nearby delay box.", "plain_english": "A delay speaker covers seats far from the stage. Sound from the main speakers needs time to reach those seats. We hold the delay speaker back by that same amount of time. A tiny extra delay keeps people hearing the sound as if it came from the stage.", "purpose_function": "It makes the main system and a distant delay loudspeaker sum cleanly instead of arriving at different times, which would smear clarity and cause comb filtering. The added Haas offset preserves the sense that the sound comes from the stage.", "practical_application": "A system tech measures the arrival-time difference with a dual-channel analyzer, then sets that delay (plus a few milliseconds) in the delay speaker's processor before the show.", "category": "System alignment", "related_terms": ["Delay speaker", "Haas effect", "Time alignment", "Comb filtering", "Transfer function", "Main-to-fill alignment"], "common_mistakes": ["Setting the delay time by tape-measure distance alone and skipping a measurement, so processing latency is ignored.", "Forgetting the small Haas offset, so the sound seems to come from the delay box instead of the stage.", "UNSAFE: Turning a delay speaker up too loud to 'reach' the back, raising sound exposure for people seated directly beneath it."], "scenario_contexts": ["Aligning under-balcony or lawn delay towers at an outdoor concert.", "Setting relay speakers down a long conference or convention hall.", "Re-checking delay times after the main array is moved or re-hung."]}, "f62621a3-a234-4bc8-b7e7-bf3fa19788cd": {"definition": "Main-to-fill alignment is the time- and level-matching of a fill loudspeaker (such as a front-fill, in-fill, or out-fill) to the main system so their responses combine coherently where both cover. Because a fill sits much closer to its listeners than the mains do, it is delayed to the mains' arrival time and set to an appropriate level so the transition between the two systems is smooth and the image stays on the stage.", "plain_english": "Fill speakers cover spots the main speakers miss, like the front row. A fill sits much closer to those seats than the mains do. We delay the fill to line up with the mains and set its level to match. This makes the handoff between speakers smooth.", "purpose_function": "It blends a fill loudspeaker with the mains so coverage gaps are filled without creating a loud, early, mislocalized source. Matching time and level keeps the combined response even across the seating area.", "practical_application": "An engineer measures the main system's arrival at the fill zone, delays the front-fills to match, and trims their level so the front row hears a balanced, stage-located image.", "category": "System alignment", "related_terms": ["Front-fill", "Delay speaker", "Time alignment", "Main-to-delay alignment", "Coverage", "Transfer function"], "common_mistakes": ["Running front-fills undelayed, so the near source arrives first and pulls the image down to the stage lip.", "Setting fills too loud, which makes the front rows brighter and louder than the rest of the room.", "Aligning only time and ignoring level and spectral match between the fill and the mains."], "scenario_contexts": ["Delaying front-fills to the main array before a concert.", "Blending out-fills that cover wide side seats.", "Adding in-fills for center seats a left-right main system misses."]}, "b461a901-585b-4c6f-974e-8000ea781cb8": {"definition": "Main-to-sub alignment is the process of adjusting the relative timing (delay) and polarity/phase of the subwoofers and the main loudspeakers so they sum constructively through the crossover region where both radiate. It is typically verified with a dual-channel transfer-function measurement, adjusting sub delay and any polarity or all-pass settings until the two systems are phase-aligned at the crossover frequency, producing maximum and even output there.", "plain_english": "Subwoofers handle the lowest sounds and the mains take the rest. Near where they split, both play the same notes. If they are not lined up in time, those shared notes get weaker. We adjust the sub timing so the two add together instead of fighting.", "purpose_function": "It ensures the subs and mains add rather than cancel around the crossover, giving full, even low-frequency output. Phase alignment at the crossover prevents a dip or bump right where the two systems overlap.", "practical_application": "Using a transfer-function analyzer, a tech overlays the sub and main phase traces near the crossover and adjusts sub delay (and polarity if needed) until they match, then checks the summed response.", "category": "System alignment", "related_terms": ["Subwoofer", "Crossover", "Phase", "Transfer function", "Polarity", "Time alignment"], "common_mistakes": ["Assuming subs and mains sum correctly by default, without checking phase at the crossover.", "Flipping polarity at random instead of measuring which setting gives the strongest crossover output.", "Aligning at only one spot and ignoring how the sub-to-main relationship changes across the audience."], "scenario_contexts": ["Phase-aligning ground-stacked subs with a flown main array.", "Setting sub delay in the loudspeaker processor during system tuning.", "Diagnosing a weak spot at the crossover frequency during soundcheck."]}, "0497e3e1-b41b-4021-b533-4b800b5573b2": {"definition": "A measurement trace is a plotted curve produced by an audio analyzer that represents a measured quantity - such as magnitude, phase, or coherence - as a function of frequency or time. Traces can be live (continuously updating) or captured and stored for comparison, and several are often overlaid to compare loudspeakers, measurement positions, or before-and-after settings.", "plain_english": "A measurement trace is a line drawn by an analyzer. It shows something you measured, such as level, across frequency. You can save traces and lay them over each other. That lets you compare speakers or settings side by side.", "purpose_function": "It turns a measurement into a visible curve so an engineer can read a system's response and compare it to a target or to another measurement. Storing traces lets before-and-after changes be judged directly.", "practical_application": "A tech captures a trace of each loudspeaker's response, overlays them, and adjusts EQ and delay until the stored traces match the desired target curve.", "category": "Measurement display", "related_terms": ["Live trace", "Transfer function", "Real-time analyzer (RTA)", "Coherence", "Capture", "Target curve"], "common_mistakes": ["Trusting a single noisy trace without averaging or checking coherence first.", "Comparing traces taken with different settings or smoothing, so the comparison is misleading.", "Forgetting to label captured traces, then mixing up which speaker or setting each one shows."], "scenario_contexts": ["Overlaying stored traces to compare the left and right arrays.", "Saving a baseline trace before changing EQ during tuning.", "Reading a phase trace to align subs and mains."]}, "74ca28e4-6f88-495d-ac03-8548511f3ea9": {"definition": "Meter calibration is the process of adjusting or verifying a meter's readings against a known reference so what it displays is accurate and traceable. For a sound level meter this uses an acoustic calibrator producing a defined level (commonly 94 dB SPL at 1 kHz per IEC 60942), with the meter conforming to IEC 61672 or ANSI S1.4; for an electrical level meter it means aligning the display to a reference signal, such as a digital line-up level defined in AES17.", "plain_english": "Meter calibration means checking a meter against a known signal so its numbers are correct. For a sound level meter, you fit a small calibrator that makes a set tone at a known loudness. You then adjust the meter to read that exact value. Now you can trust what it shows.", "purpose_function": "It makes meter readings accurate and repeatable, so measurements can be trusted, compared, and legally defended. Without calibration, drift or error could make a meter read too high or too low.", "practical_application": "Before measuring show levels, a technician fits an acoustic calibrator to the microphone, confirms the meter reads the reference (for example 94 dB at 1 kHz), and adjusts it if needed.", "category": "Measurement practice", "related_terms": ["Sound level meter", "Acoustic calibrator", "SPL", "Reference level", "A-weighting", "dBFS"], "common_mistakes": ["UNSAFE: Reporting show or workplace noise levels from an uncalibrated meter, which can hide exposure that risks hearing damage.", "Skipping the calibration check before a session and assuming the meter is still accurate.", "Calibrating with the wrong weighting or a worn calibrator, so the reference itself is off.", "Confusing calibration (setting accuracy against a reference) with simply zeroing or resetting the display."], "scenario_contexts": ["Field-calibrating an SPL meter before logging a concert's levels.", "Verifying a DAW or console meter against a known reference tone.", "Sending a meter for periodic lab calibration to keep it traceable."]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"b98cb833-b62c-4769-8438-0bbb8b36ac53": {"definition": "In Mid-Side (M-S) stereo, the Mid channel is the component carrying the sum of the left and right information (L+R), corresponding to the center of the stereo image; it is typically captured by a forward-facing microphone (often cardioid or omnidirectional) aimed at the source. Combined with the Side channel through an M-S matrix, the Mid signal sets the level of centered, mono-compatible content in the stereo image.", "plain_english": "In Mid-Side recording, the Mid channel holds the sound from straight ahead. It is the center of the stereo picture. A microphone points right at the source to capture it. The Side channel then adds the width around it.", "purpose_function": "The Mid channel provides the centered, mono-compatible core of an M-S recording, so the balance of center versus width can be set later. It also stays fully mono-compatible when the stereo signal is summed.", "practical_application": "An engineer records the forward-facing mic as the Mid, then blends it with the Side mic in an M-S matrix to widen or narrow the stereo image after the take.", "category": "Stereo imaging", "related_terms": ["Mid-Side matrix", "Side channel", "M-S recording", "Mono compatibility", "Stereo image", "Sum and difference"], "common_mistakes": ["Thinking the Mid channel is 'mono only', when it is one part of a stereo pair that also needs the Side signal.", "Confusing Mid (the L+R sum) with a single left or right channel.", "Assuming the Mid mic alone sets stereo width, when width comes from the Side channel level."], "scenario_contexts": ["Recording an acoustic ensemble with an M-S microphone pair.", "Adjusting stereo width by changing the Mid-to-Side balance in the mix.", "Checking mono compatibility by soloing the Mid channel."]}, "1bbee702-b21b-4f4f-a7aa-aa245bdb56b6": {"definition": "A Mid-Side (M-S) matrix is the sum-and-difference network that converts between a Mid/Side signal pair and a left/right stereo pair. Encoding forms Mid = L + R and Side = L - R; decoding recovers Left = Mid + Side and Right = Mid - Side, so adjusting the relative level of the Side signal before decoding widens or narrows the stereo image while keeping the Mid (center) mono-compatible.", "plain_english": "A Mid-Side matrix is a simple mixing trick that swaps between two stereo formats. It turns left and right into a center (Mid) and a difference (Side), and back again. By changing how much Side you add back, you make the stereo sound wider or narrower.", "purpose_function": "It lets an engineer control stereo width and check mono compatibility by working in center/difference form instead of left/right. The same matrix both encodes an M-S mic setup and decodes it to normal stereo.", "practical_application": "A mastering engineer inserts an M-S matrix to raise the Side level for more width, or lower it for a tighter center, then decodes back to left and right.", "category": "Stereo imaging", "related_terms": ["Mid channel", "Side channel", "M-S recording", "Mono compatibility", "Stereo width", "Sum and difference"], "common_mistakes": ["Forgetting to decode M-S back to L-R, leaving the sum/difference signal on the stereo bus.", "Boosting the Side too far, which hollows out the center and breaks mono compatibility.", "Mixing up encode and decode, since both use the same sum-and-difference math."], "scenario_contexts": ["Decoding an M-S microphone recording into stereo.", "Widening a stereo mix during mastering with an M-S processor.", "Checking a mix in mono by muting the Side leg of the matrix."]}, "b5e38b72-4c64-4559-8e01-2a554595c32a": {"definition": "Needed acoustic gain (NAG) is the amount of gain a sound-reinforcement system must add so the most distant listener hears the source at the same level as an unaided listener at a chosen reference (equivalent acoustic) distance. It is calculated as NAG = 20 log10 (D0 / EAD), where D0 is the distance from the talker to the farthest listener and EAD is the equivalent acoustic distance at which the talker would be loud enough without reinforcement; NAG is compared with potential acoustic gain (PAG) to see whether a system can meet the requirement with adequate feedback-stability margin.", "plain_english": "Needed acoustic gain is how much louder a sound system must make a talker for the back row. The farther away a listener sits, the quieter the natural voice reaches them. NAG is the boost needed so the far seats hear as well as a close listener. Engineers compare it to how much gain the system can safely give.", "purpose_function": "NAG defines the loudness target a system must hit for distant listeners, based purely on geometry. Comparing NAG with potential acoustic gain (PAG) shows whether a design can reach that target before feedback.", "practical_application": "During system design a technician measures the talker-to-audience distances, computes NAG, and checks it against PAG to confirm the system will be loud enough without ringing.", "category": "System design", "related_terms": ["Potential acoustic gain (PAG)", "Gain before feedback", "Feedback", "Equivalent acoustic distance", "Critical distance", "Sound reinforcement"], "common_mistakes": ["Confusing needed acoustic gain (what is required) with potential acoustic gain (what the system can deliver).", "Using the wrong distances, such as measuring to the front row instead of the farthest listener.", "Assuming extra open microphones have no effect, when they reduce the gain available versus what is needed."], "scenario_contexts": ["Designing a speech system for a large lecture hall.", "Checking whether a house of worship PA can cover the back pews without feedback.", "Comparing NAG and PAG when choosing microphone and loudspeaker placement."]}, "2fe12fb5-c632-4090-8ff5-d9f51114fe8d": {"definition": "Noise at the property line is the level of sound from a source (such as a venue, plant, or event) measured at the legal boundary of the property, used to judge compliance with community-noise ordinances or permit conditions. It is measured with a sound level meter conforming to IEC 61672 or ANSI S1.4, usually as an A-weighted level and often as a time-averaged (Leq) or maximum value over a stated period, with day and night limits set by the local jurisdiction.", "plain_english": "Noise at the property line is how loud a place sounds measured at the edge of its land. Officials use it to check whether a venue is too loud for neighbors. A meter is placed at the boundary to take the reading. Limits are usually stricter at night.", "purpose_function": "It gives a fair, fixed point to judge whether sound escaping a site meets legal noise limits and protects neighbors. Measuring at the boundary, rather than at the source, reflects what nearby people actually receive.", "practical_application": "Before and during a loud event, a technician measures the A-weighted level at the property line and adjusts the system so it stays under the local limit.", "category": "Environmental noise", "related_terms": ["Sound level meter", "A-weighting", "Leq", "LAeq", "Noise ordinance", "SPL"], "common_mistakes": ["Assuming an indoor mix level tells you the level at the property line, which depends on distance and building loss.", "Ignoring stricter night-time limits and measuring against the daytime figure.", "Measuring at the source instead of the legal boundary, so the reading does not match the ordinance."], "scenario_contexts": ["Checking an outdoor festival against a city noise ordinance.", "Responding to a neighbor complaint by logging levels at the boundary.", "Setting a nightclub's limiter so escaping noise stays legal after hours."]}, "b000b6f9-16f3-423e-beb8-d24b444762cf": {"definition": "The NOM 3 dB rule states that each doubling of the number of open microphones (NOM) feeding a common mix raises the summed output level, and the system's tendency to feed back, by about 3 dB, while lowering the available potential acoustic gain by the same amount. The general correction is 10 log(N) decibels for N open mics, so two mics add about 3 dB, four mics about 6 dB, and eight mics about 9 dB relative to a single open mic.", "plain_english": "Every open microphone adds noise and feedback risk to a mix. Doubling the number of open mics raises the combined level by about 3 dB. So two mics are 3 dB hotter than one, and four mics are 6 dB hotter. Turning off unused mics keeps the system louder before it squeals.", "purpose_function": "It quantifies how the open-mic count erodes gain before feedback and raises background noise, guiding how many live mics a system can safely support. This is why mic discipline and automatic mixers exist.", "practical_application": "An operator mutes or gates unused microphones so the mix keeps the most level before feedback, applying the rule when planning how many live mics a room can support.", "category": "Gain before feedback", "related_terms": ["Number of open mics (NOM)", "Potential acoustic gain (PAG)", "Gain before feedback", "Automatic microphone mixer", "Feedback", "Needed acoustic gain (NAG)"], "common_mistakes": ["Thinking each extra mic adds 3 dB, when the loss follows 10 log of the total open-mic count, so it takes a doubling to add 3 dB.", "Leaving unused microphones open, which needlessly lowers gain before feedback and raises noise.", "Assuming the rule depends on how loud each talker is, when it counts open mics regardless of whether anyone is speaking."], "scenario_contexts": ["Planning a panel discussion and deciding how many live mics the room's PA can support.", "Using an automatic mixer to keep the open-mic count low during a conference.", "Troubleshooting feedback that worsens as more presenter mics are switched on."]}, "68ec24bb-7d20-438e-9915-bf4a420862db": {"definition": "Nominal directivity is a loudspeaker's rated, published directional behavior - its nominal coverage angles (for example 90 degrees horizontal by 40 degrees vertical) and/or its directivity factor Q and directivity index (DI) - describing how the device concentrates radiated sound into a defined pattern. The word nominal indicates a manufacturer's stated design value, typically averaged over a stated frequency band, rather than the exact frequency-by-frequency behavior.", "plain_english": "A loudspeaker does not spray sound evenly in every direction. Nominal directivity is the maker's stated coverage shape, such as 90 degrees wide by 40 degrees tall. It is a rounded headline figure. The real pattern changes with frequency.", "purpose_function": "It gives designers a single, comparable figure for how tightly a loudspeaker aims its output, so boxes can be chosen and aimed to cover an audience. It exists to summarize complex, frequency-dependent coverage in a usable spec.", "practical_application": "A system designer reads the nominal coverage angle from a datasheet to pick and aim loudspeakers so their patterns cover the seats with minimal overlap or gaps.", "category": "Loudspeaker directivity", "related_terms": ["Directivity factor (Q)", "Directivity index (DI)", "Coverage angle", "Pattern control", "Beamwidth", "Polar pattern"], "common_mistakes": ["Treating the nominal coverage angle as exact at every frequency, when real directivity narrows at high frequencies and widens at low ones.", "Confusing the -6 dB coverage-angle convention with a -3 dB or full-null angle, which yields a different number.", "Assuming two boxes with the same nominal pattern behave identically, when their off-axis and frequency response can differ."], "scenario_contexts": ["Choosing a horn's nominal pattern to match the shape of a seating area.", "Comparing two loudspeakers' datasheets by their nominal coverage angles.", "Aiming a point-source box using its rated horizontal and vertical coverage."]}, "4f6d5025-e589-46a4-b877-39eb102c39a6": {"definition": "A notch feedback controller (feedback suppressor) is a signal processor that detects the narrow-band ringing frequencies at which a sound system is about to feed back and automatically inserts narrow, deep notch (band-reject) filters at those frequencies to attenuate them, raising gain before feedback while minimally altering overall tonal balance. Units may use fixed filters set during setup or adaptive filters that track new feedback tones as they emerge.", "plain_english": "When a mic and speaker form a loop, the system rings at certain pitches and squeals. A notch feedback controller listens for those pitches. It drops a very narrow cut right on each one. This tames the squeal while leaving most of the sound untouched.", "purpose_function": "It exists to increase usable gain before feedback and stop howling automatically, without an operator hunting for problem frequencies by hand. Narrow notches remove the ringing tone while preserving the rest of the response.", "practical_application": "A technician runs a feedback suppressor on a monitor or speech system, lets it ring out the rig and set notch filters, then locks the fixed filters before the show.", "category": "Feedback control", "related_terms": ["Feedback", "Gain before feedback", "Notch filter", "Graphic equalizer", "Ringing out", "Number of open mics (NOM)"], "common_mistakes": ["Relying on the suppressor instead of fixing gain structure and mic placement, so the root cause remains.", "Setting notches so wide or deep that they audibly dull the system's tone.", "Assuming adaptive filters make a system feedback-proof, when they only buy a few extra decibels of gain."], "scenario_contexts": ["Ringing out stage monitors before a live band's soundcheck.", "Stabilizing a lectern microphone in a reverberant conference room.", "Adding a dynamic feedback suppressor to a portable speech PA for touring use."]}, "c2a42840-f420-41ee-af21-6abb169baca8": {"definition": "In FFT-based audio measurement (spectrum, RTA, and transfer-function displays), the Number of Averages is how many successive FFT frames are combined into the displayed result to reduce the variance of the estimate. Increasing the count produces a smoother, more stable trace and a higher signal-to-noise ratio - roughly a 3 dB improvement per doubling of averages - at the cost of a slower time response.", "plain_english": "Measurement software takes many quick snapshots of the sound. The number of averages is how many snapshots it blends into one display. More snapshots give a smoother, steadier reading. But the display then reacts more slowly to changes.", "purpose_function": "It trades speed for stability, letting the user smooth out random noise so a measurement can be trusted for tuning decisions. Fewer averages track fast changes; more averages settle the trace.", "practical_application": "A system tech raises the number of averages when measuring a loudspeaker in a noisy room to steady the trace, and lowers it to watch fast changes such as finding a delay time.", "category": "Measurement averaging", "related_terms": ["Averaging", "FFT", "Transfer function", "Real-time analyzer (RTA)", "Signal-to-noise ratio", "Coherence"], "common_mistakes": ["Using too few averages in a noisy room, so a jumpy trace is mistaken for a real response.", "Leaving averaging very high while adjusting the system, then wondering why the display lags behind changes.", "Confusing frame averaging with frequency (fractional-octave) smoothing, which are different operations."], "scenario_contexts": ["Increasing averages for a stable transfer-function trace outdoors with wind and crowd noise.", "Lowering averages to see fast movement when aligning subwoofer delay.", "Setting a high average count for a final documentation measurement of a room."]}, "d81473bb-e47f-4855-9308-192157f59bb8": {"definition": "Number of open mics (NOM) is the count of microphone (or other) channels simultaneously contributing - unmuted and with faders up - to a common mix at a given moment. Because each open input adds acoustic and electronic noise and increases feedback tendency, summed level rises by about 10 log(N) decibels, roughly 3 dB per doubling of N, making NOM a key factor in a system's gain before feedback and noise performance.", "plain_english": "NOM stands for the number of open mics feeding a mix at once. Every open mic adds hiss, room noise, and feedback risk. The more mics that are live, the less loud the system can get before it squeals. So good engineers keep only the needed mics open.", "purpose_function": "It is a design and operating figure that predicts how mic count limits gain before feedback and raises noise, informing mic discipline and the use of automatic mixers. Keeping NOM low preserves headroom and clarity.", "practical_application": "An operator or automatic mixer keeps only active microphones open during a talk or performance, watching NOM to protect gain before feedback and reduce picked-up noise.", "category": "Gain before feedback", "related_terms": ["NOM 3 dB rule", "Potential acoustic gain (PAG)", "Automatic microphone mixer", "Gain before feedback", "Feedback", "Needed acoustic gain (NAG)"], "common_mistakes": ["Leaving every channel open just in case, which raises noise and lowers gain before feedback.", "Assuming NOM counts only mics with someone speaking, when any unmuted, faded-up mic counts.", "Forgetting NOM in gain calculations, then being surprised when a multi-mic system feeds back early."], "scenario_contexts": ["Managing microphones at a multi-speaker panel to keep NOM as low as possible.", "Setting up an automatic mixer that gates mics to control NOM at a conference.", "Calculating potential acoustic gain, which subtracts 10 log(NOM) for the open-mic count."]}, "d4c97255-70b0-4df6-85f6-c27350eb96cd": {"definition": "An overs indicator is a digital meter element that flags a likely converter clip by detecting a run of consecutive full-scale (0 dBFS) samples, on the assumption that several back-to-back maximum-value samples mean the analog signal exceeded full scale between them. The threshold count is a set convention - the Sony 1630 standard used three consecutive full-scale samples - and many meters let the user set the count and display a running total of overs.", "plain_english": "In digital audio, the loudest possible value is 0 dBFS, the full-scale ceiling. If several samples in a row all sit at that ceiling, the real signal probably went over and clipped. An overs indicator lights up to warn you when this happens. It is stricter than a plain 0 dB light.", "purpose_function": "It warns the engineer that clipping distortion has likely occurred, so levels can be lowered before more takes are ruined. Counting consecutive full-scale samples separates true clipping from a signal that merely touches full scale once.", "practical_application": "A tracking engineer watches the overs indicator and its running count during recording and pulls back input gain when overs appear, so takes are not spoiled by digital clipping.", "category": "Digital metering", "related_terms": ["dBFS", "Digital clipping", "Sample peak", "True peak (dBTP)", "Headroom", "Peak hold"], "common_mistakes": ["Treating a single sample touching 0 dBFS as an over, when the indicator waits for several consecutive full-scale samples.", "Ignoring the overs count and leaving input gain too high, so clipping distortion is baked into the recording.", "Assuming zero overs means zero distortion, when inter-sample peaks can still clip a converter on playback."], "scenario_contexts": ["Setting record levels on an interface and backing off gain when the overs light triggers.", "Checking a delivered master for overs before release.", "Configuring a meter's over threshold to the number of consecutive full-scale samples a facility requires."]}, "b2644ae4-de1a-44c6-aa44-90a408b5b890": {"definition": "Pattern control is a loudspeaker's ability to confine its radiated sound to a defined coverage pattern (directivity) and to maintain that pattern consistently across frequency. Control is easiest at high frequencies and grows harder as wavelength becomes large relative to the source size, so a device loses pattern control at the low frequency where it can no longer hold its rated directivity and begins to radiate more omnidirectionally.", "plain_english": "Pattern control is how well a speaker aims its sound into a set area instead of spilling everywhere. High notes are easy to aim. Low notes spread out and are hard to control. Below a certain pitch, the speaker stops aiming and radiates in all directions.", "purpose_function": "It determines how predictably a loudspeaker covers the audience and avoids spraying energy onto walls, ceilings, and open mics. Consistent pattern control keeps tonal balance even across the coverage area.", "practical_application": "A designer picks horns or arrays with pattern control down to the needed frequency so coverage stays tight, and uses directional subwoofer techniques where single boxes lose control.", "category": "Loudspeaker directivity", "related_terms": ["Nominal directivity", "Directivity index (DI)", "Coverage angle", "Beamwidth", "Line array", "Constant directivity horn"], "common_mistakes": ["Assuming a horn's rated coverage holds at all frequencies, when pattern control is lost below a cutoff frequency.", "Expecting a single small subwoofer to be directional, when low frequencies radiate nearly omnidirectionally.", "Confusing pattern control with raw output level, when it concerns the shape of coverage, not loudness."], "scenario_contexts": ["Selecting a constant-directivity horn that keeps pattern control across the vocal range.", "Building a cardioid or end-fire subwoofer array to add pattern control at low frequencies.", "Diagnosing why a room sounds harsh off to the sides where a speaker has lost pattern control."]}, "2126fbe8-1339-43d3-aff8-60bed8502cc9": {"definition": "On a sound level meter, Peak (Lpeak, commonly C-weighted as LCpeak) is the highest instantaneous sound pressure level reached during the measurement, captured by a peak detector with no RMS averaging and no time weighting (Fast or Slow). It differs from Lmax, the maximum of the time-weighted RMS level: for a steady sine the peak reads about 3 dB above the RMS-based level, while for transients the difference is far larger. Peak measurement is defined for sound level meters in IEC 61672.", "plain_english": "A sound level meter usually shows a smoothed, averaged level. The Peak reading is different. It catches the single highest pressure spike, with no smoothing at all. It matters for sudden bangs, like a gunshot or a drum hit, which can harm hearing in an instant.", "purpose_function": "It captures brief, high-energy transients that time-averaged readings miss, which is why hearing-protection rules set a separate peak limit for impulsive sounds. It records the true worst-case pressure rather than an average.", "practical_application": "A technician or safety officer uses the meter's C-weighted peak (LCpeak) to check impulsive sounds such as pyrotechnics or gunfire against a peak exposure limit.", "category": "Sound level metering", "related_terms": ["Sound level meter", "Lmax", "C-weighting", "LAeq", "Time weighting (Fast/Slow)", "Crest factor"], "common_mistakes": ["UNSAFE: Judging impulsive noise such as gunfire or pyrotechnics by the averaged level, when the peak can far exceed it and damage hearing instantly.", "Confusing Peak with Max (Lmax): Peak has no time weighting, while Lmax is the highest time-weighted RMS level.", "Assuming Peak is always RMS plus 3 dB, which only holds for a steady sine, not for real transients."], "scenario_contexts": ["Measuring the LCpeak of a starter pistol or pyrotechnic against an occupational peak limit.", "Checking peak levels at a shooting range or during a stage-effect rehearsal.", "Documenting worst-case impulse levels for a hearing-conservation program."]}, "55b15b32-3f2f-4c32-a1dc-30be5f76fa9e": {"definition": "Phase response is the part of a system's frequency response that describes the phase shift, or timing relationship, it imposes on each frequency component, plotted as phase angle versus frequency. Together with the magnitude (amplitude) response it fully defines a linear system's transfer function; a frequency-dependent phase shift means different frequencies are delayed by different amounts, which can change waveform shape and, at crossovers, affect how sources sum.", "plain_english": "Any part of a sound system can delay some frequencies more than others. Phase response is a graph of that timing shift across all frequencies. When two speakers or drivers meet, their phase decides whether they add up or cancel. So it matters most at crossover points.", "purpose_function": "It reveals timing differences between frequencies and between sources, which is why engineers check it when aligning drivers, crossovers, and multiple loudspeakers so their outputs add rather than cancel. Magnitude alone cannot show these timing problems.", "practical_application": "Using a transfer-function analyzer, a technician compares the phase response of two loudspeakers through their crossover region and adjusts delay or polarity until the traces align and sum correctly.", "category": "Frequency response", "related_terms": ["Magnitude response", "Frequency response", "Transfer function", "Group delay", "Crossover alignment", "Polarity"], "common_mistakes": ["Confusing phase with polarity, when polarity is a simple plus/minus inversion and phase is a frequency-dependent time shift.", "Judging a system by magnitude response alone and ignoring phase problems at crossovers.", "Reading raw phase wrap without removing the measurement delay, so the trace looks worse than it is."], "scenario_contexts": ["Aligning a subwoofer to a main speaker by matching phase through the crossover region.", "Setting driver delays in a multi-way loudspeaker so the phase traces overlap.", "Diagnosing a thin, hollow sound caused by phase cancellation between two sources."]}, "91dd5ae8-9bac-497e-9c80-328e90a546d0": {"definition": "A phase scope (also called a goniometer or audio vectorscope) is a display that plots a stereo signal's left and right channels against each other on a rotated X-Y graph, showing the amplitude and phase relationship between the two channels as a moving pattern. A vertical trace indicates a mono or in-phase signal, a horizontal trace indicates out-of-phase channels that will cancel in mono, and a rounded, centred cloud indicates a wide, well-correlated stereo image.", "plain_english": "A phase scope draws a picture of how the left and right channels relate. A tall up-and-down line means the sides match and sum well in mono. A flat side-to-side line warns the sides fight and cancel. It helps you spot phase problems by eye.", "purpose_function": "It lets an engineer see, at a glance, the phase and stereo relationship between two channels, revealing mono-compatibility problems and cancellation before they cause trouble downstream. It exists because phase errors are hard to judge from level meters alone.", "practical_application": "A mastering or broadcast engineer watches the phase scope while checking a mix, making sure the shape stays mostly vertical so the material still sums cleanly to mono.", "category": "Metering display", "related_terms": ["Goniometer", "Correlation meter", "Vectorscope", "Mono compatibility", "Stereo image", "Polarity alignment"], "common_mistakes": ["Confusing the phase scope with a correlation meter, when the scope shows a moving pattern and the correlation meter shows a single number.", "Reading a horizontal (out-of-phase) trace as a wide stereo image, when it actually warns of mono cancellation.", "Assuming a narrow vertical trace is a fault, when it simply shows a mono or near-mono signal."], "scenario_contexts": ["Checking a stereo mix for mono compatibility before broadcast.", "Spotting a wiring or polarity error that flips one channel out of phase.", "Watching stereo width while mastering a track."]}, "64a59545-786f-4d59-8166-6bc322f87ac7": {"definition": "A phase spectrum is the representation, produced by a Fourier transform, of the phase angle of each frequency component of a signal plotted against frequency, complementing the magnitude (amplitude) spectrum that gives each component's level. Together the magnitude and phase spectra fully describe the signal in the frequency domain, the phase spectrum encoding the relative timing or starting angle of each sinusoidal component.", "plain_english": "Any sound can be seen as a stack of simple tones. The phase spectrum shows the timing, or starting point, of each tone. It works with the loudness view, which shows how strong each tone is. Together they fully describe the sound by frequency.", "purpose_function": "It captures the timing relationships between a signal's frequency components, information the magnitude spectrum alone discards. This matters because phase affects waveform shape, transients, and how signals combine.", "practical_application": "An engineer reads the phase spectrum in a transfer-function measurement to check a loudspeaker's or filter's phase response and to set delay for alignment.", "category": "Signal analysis", "related_terms": ["Magnitude spectrum", "Fourier transform", "Transfer function", "Phase response", "Group delay", "Frequency domain"], "common_mistakes": ["Thinking a spectrum is only the magnitude plot, and ignoring the equally real phase spectrum.", "Assuming phase values are meaningless because they look random, when they carry each component's timing.", "Confusing the phase spectrum with a phase response, which is the phase of a system's output relative to its input."], "scenario_contexts": ["Reading phase alongside magnitude in a transfer-function measurement of a PA.", "Analysing why two summed signals cancel at certain frequencies.", "Studying an FFT of a waveform in measurement software."]}, "7716553b-d24a-435c-b1ed-b8026a1fd93f": {"definition": "A phase vocoder is a signal-processing technique that analyses a signal with a short-time Fourier transform (STFT) into time-varying magnitude and phase in a bank of frequency bins, then modifies and resynthesises it, using the phase information to keep components coherent. Because analysis and synthesis are decoupled, it can independently change a sound's time scale (time-stretching) and its pitch (pitch-shifting) without one forcing a change in the other.", "plain_english": "A phase vocoder breaks a sound into many narrow frequency bands. It tracks how loud each band is and how its wave is timed. Then it rebuilds the sound. This lets you stretch the length or change the pitch on their own.", "purpose_function": "It exists to let engineers change duration and pitch independently and smoothly, which simple resampling cannot do. Tracking phase across frames keeps the rebuilt sound coherent instead of smeared.", "practical_application": "A producer uses a phase-vocoder-based tool to time-stretch a loop to a new tempo, or to shift a vocal's pitch, without changing the other property.", "category": "Signal processing", "related_terms": ["Short-time Fourier transform (STFT)", "Time-stretching", "Pitch shifting", "Vocoder", "FFT", "Spectral processing"], "common_mistakes": ["Confusing a phase vocoder with a musical (channel) vocoder that imposes one sound's spectrum on another.", "Expecting perfect results on sharp transients, which phase vocoders can smear.", "Assuming time-stretching and pitch-shifting are the same operation, when the vocoder handles them separately."], "scenario_contexts": ["Time-stretching a drum loop to match a project's tempo.", "Pitch-shifting a vocal without speeding it up.", "Building spectral effects from analysed magnitude and phase data."]}, "cc5557d7-19db-454d-82a1-d611cf4b350e": {"definition": "Polarity alignment is the process of ensuring that two or more signals representing the same source have matching absolute polarity - so that a positive-going pressure or voltage in one appears as positive-going in the others - allowing them to add rather than partially cancel when summed. It is distinct from time (phase) alignment: polarity is a fixed 180-degree inversion corrected with a polarity switch or by rewiring, whereas phase differences vary with frequency and are corrected with delay.", "plain_english": "Polarity alignment makes sure two mics or signals push and pull together, not against each other. If one is flipped, they cancel and the sound gets thin and weak. Flipping it back, often with a switch, lets them add up. It is not the same as fixing timing with delay.", "purpose_function": "It prevents the level loss and thin sound that occur when combined signals partly cancel because one is inverted. It exists because inverted wiring, opposite-facing mics, or gear can flip a signal's polarity.", "practical_application": "An engineer flips the polarity switch on the channel for a bottom snare mic, or on a DI paired with a mic, choosing whichever setting sounds fuller.", "category": "Signal alignment", "related_terms": ["Polarity", "Phase (audio)", "Time alignment", "Comb filtering", "Mono compatibility", "Phase scope"], "common_mistakes": ["Confusing polarity with phase; a polarity flip is a fixed inversion, while a phase shift changes with frequency.", "Assuming a polarity switch fixes a timing offset, when only delay aligns arrival times.", "Forgetting to check polarity on multi-mic sources, leaving the summed sound thin from partial cancellation."], "scenario_contexts": ["Setting polarity on top and bottom snare-drum mics so they reinforce each other.", "Aligning a DI and a mic on a bass guitar.", "Checking subwoofer-to-main polarity during PA setup."]}, "d4f2991a-9e3a-4755-90d3-0d86f9a41059": {"definition": "Potential acoustic gain (PAG) is the maximum increase in level, in decibels, that a sound-reinforcement system can add before the onset of feedback, calculated from the distances between the talker, microphone, loudspeaker, and listener. The standard calculation subtracts a feedback stability margin (typically 6 dB) and, for multiple microphones, a 10-log(NOM) term for the number of open mics; a system is workable when PAG is greater than or equal to the needed acoustic gain (NAG).", "plain_english": "Potential acoustic gain is how much louder a PA can go before it feeds back and squeals. It is worked out from the distances between the talker, the mic, the speakers, and the listeners. Engineers compare it to the gain the room really needs. If it is too low, feedback strikes first.", "purpose_function": "It lets designers predict, before feedback happens, whether a system can be loud enough for the audience. Comparing PAG with needed acoustic gain shows if the layout will work or must be changed.", "practical_application": "A system designer estimates PAG from a room's distances and open-mic count, then moves mics closer to talkers or loudspeakers closer to listeners when PAG falls short of NAG.", "category": "Sound system design", "related_terms": ["Needed acoustic gain (NAG)", "Feedback", "Number of open mics (NOM)", "Feedback stability margin", "Gain before feedback", "Ringing out"], "common_mistakes": ["Ignoring the number of open microphones, which lowers PAG by about 3 dB each time the open-mic count doubles.", "Leaving out the feedback stability margin, which makes the predicted gain unsafely optimistic.", "Confusing PAG, what the system can deliver, with NAG, what the room actually needs."], "scenario_contexts": ["Designing a conference room's mic and loudspeaker layout to avoid feedback.", "Deciding whether adding microphones will push a system into feedback.", "Checking that a lectern system can reach the back row before feedback."]}, "523eebd2-6982-495d-8b67-e83da6565713": {"definition": "A reconstruction filter is the low-pass (anti-imaging) filter applied at the output of a digital-to-analog converter that removes the spectral images produced above the Nyquist frequency by the sampling process, smoothing the converter's stepped output into a continuous analog waveform. It is the output-side counterpart of the anti-aliasing filter used before an analog-to-digital converter, and in oversampling designs it is combined with digital interpolation so the analog filter's requirements can be relaxed.", "plain_english": "A digital-to-analog converter puts out sound as tiny steps, like a staircase. A reconstruction filter smooths those steps into a flowing wave. It also removes copies of the signal that sit above the hearing range. This turns the raw output into clean analog audio.", "purpose_function": "It exists to strip the high-frequency images left by sampling and to turn the converter's staircase output into a smooth analog signal. Without it, those images could cause distortion or stress later equipment.", "practical_application": "A technician relies on the reconstruction filter built into every DAC; in converter or interface design it sets how clean and flat the analog output is near the top of the audio band.", "category": "Digital audio", "related_terms": ["Anti-aliasing filter", "Digital-to-analog converter (DAC)", "Nyquist frequency", "Oversampling", "Sampling", "Imaging"], "common_mistakes": ["Confusing the reconstruction (anti-imaging) filter after the DAC with the anti-aliasing filter before the ADC.", "Assuming the DAC output is already smooth, when it needs the reconstruction filter to remove the steps and images.", "Thinking oversampling removes the need for any analog filter, when it only relaxes its requirements."], "scenario_contexts": ["Understanding why a DAC's analog output is smooth rather than stepped.", "Comparing converter designs by how their reconstruction filtering affects high-frequency response.", "Diagnosing high-frequency artefacts traced to converter output filtering."]}, "92f3038a-d242-49a6-a41d-01fd0c69cfe5": {"definition": "A reference position is the defined, repeatable location at which a measurement or calibration is taken and against which other positions or later measurements are compared. In loudspeaker specification it is tied to the reference point and reference axis defined in IEC 60268-5; in system tuning and room acoustics it is the chosen microphone location, often representing the main listening or audience area, used as the baseline for alignment and comparison.", "plain_english": "A reference position is the exact spot you choose to measure from. You always measure at that same spot so results can be compared fairly. In sound work it is often a mic placed where the audience sits. Everything else is judged against what you find there.", "purpose_function": "It gives measurements a fixed, repeatable baseline, so readings taken at different times or places can be compared meaningfully. Without an agreed reference position, results cannot be trusted or repeated.", "practical_application": "A system engineer places the measurement mic at a chosen reference position in the seating area, tunes the system there, then checks other seats against it.", "category": "Measurement method", "related_terms": ["Reference axis", "Measurement microphone", "Calibration", "On-axis", "Coverage", "Sound pressure level (SPL)"], "common_mistakes": ["Moving the measurement mic between readings, so results no longer share a common reference position.", "Choosing a reference position sitting in a strong reflection or null, which biases every comparison.", "Assuming one reference position describes the whole room, when several positions are usually needed."], "scenario_contexts": ["Placing a measurement mic at a fixed seat to tune a PA.", "Specifying a loudspeaker's response on its reference axis at a stated distance.", "Returning to the same reference position to verify a system after changes."]}, "a5138f54-34ae-42c9-b3c1-7da4139ff9cf": {"definition": "Ringing is a decaying oscillation that a system produces in response to a sudden input, appearing as damped cycles following a transient or step. In filters it arises from sharp, high-Q or brick-wall responses (a steep low-pass can add pre- and post-ringing from its underlying sinc-like impulse response); in acoustics and loudspeakers it appears as a resonance that continues to sound briefly after the driving signal stops.", "plain_english": "Ringing is when a sound or signal keeps oscillating for a moment after it should have stopped. It is like a bell that hums on after being struck. Sharp filters and room or speaker resonances can cause it. It smears the timing of the sound.", "purpose_function": "The term describes an unwanted after-oscillation that reveals resonances or overly sharp filtering. Recognising ringing helps engineers judge filter quality and find resonant problems in rooms and loudspeakers.", "practical_application": "An engineer sees ringing as a lingering tail in an impulse response or waterfall plot, and reduces it by lowering filter Q or treating a resonant room mode.", "category": "Time response", "related_terms": ["Impulse response", "Resonance", "Q factor", "Gibbs phenomenon", "Group delay", "Waterfall plot"], "common_mistakes": ["Assuming a sharper filter is always better, when very steep filters add audible ringing.", "Confusing ringing, a decaying oscillation, with sustained feedback, which grows rather than decays.", "Overlooking that a narrow, high-Q EQ boost can make a frequency ring."], "scenario_contexts": ["Seeing post-ringing on a steep brick-wall low-pass filter's impulse response.", "Spotting a room mode that rings on in a waterfall plot.", "Hearing a resonant loudspeaker or enclosure ring after a transient."]}, "b005c428-478f-40e0-b2fe-1e51d0c37035": {"definition": "Ringing out (ringing out a system) is the live-sound procedure of deliberately raising a microphone or monitor's gain until it just begins to feed back, identifying each feedback frequency by ear or on an analyzer, and cutting it with a narrow equalizer filter, then repeating to raise overall gain-before-feedback. It trades a small amount of tonal smoothness for extra usable level and stability on stage.", "plain_english": "Ringing out is a way to get more level before a mic or monitor squeals. You slowly turn the mic up until it just starts to ring. You find that pitch and cut it with a narrow EQ. You repeat this to push the volume higher safely.", "purpose_function": "It raises how much gain a mic or monitor can run before feedback, giving performers more level. It works by removing the exact frequencies that feed back first, which are usually room or system resonances.", "practical_application": "A monitor engineer rings out each wedge before a show, nudging gain up and notching each feedback frequency on a graphic or parametric EQ.", "category": "Feedback control", "related_terms": ["Feedback", "Gain before feedback", "Potential acoustic gain (PAG)", "Graphic equalizer", "Notch filter", "Stage monitor"], "common_mistakes": ["UNSAFE: Cranking gain far past the first ring to chase feedback, risking a loud feedback burst that can harm hearing and damage drivers.", "Cutting too many wide EQ bands, which dulls the sound instead of just removing the ringing frequencies.", "Ringing out with the room empty and forgetting that an audience changes the acoustics.", "Assuming ringing out replaces good mic and monitor placement, when placement matters more."], "scenario_contexts": ["Tuning stage monitors before doors open at a concert.", "Setting up a lectern mic in a reverberant room to reduce feedback.", "Notching feedback frequencies on a house EQ during soundcheck."]}, "04e7f538-902b-4d83-a7a4-fd9f436fc0a7": {"definition": "An RMS/thermal limiter is a dynamics processor, usually inside a loudspeaker controller or amplifier DSP, that acts on the root-mean-square (average, energy-related) level of the signal rather than its instantaneous peaks, using a relatively long time constant chosen to model the thermal time constant of a driver's voice coil. By holding the long-term average power delivered to the driver below a set threshold, it protects the voice coil from overheating and thermal failure, and is typically used alongside a faster peak limiter that guards against over-excursion and clipping.", "plain_english": "This limiter watches the average power going to a speaker over time, not just the quick loud spikes. Average power is what heats a speaker's voice coil. The limiter holds that average down so the coil does not overheat and burn out. A separate fast limiter handles sudden peaks.", "purpose_function": "It exists to protect a driver from thermal (heat) damage by capping the long-term average power it receives, matching the slow way a voice coil heats up. This lets a system run loud without cooking the speaker.", "practical_application": "A system engineer sets the RMS/thermal limiter threshold from the manufacturer's driver power ratings in a loudspeaker processor, then pairs it with a fast peak limiter for full protection.", "category": "Dynamics protection", "related_terms": ["Peak limiter", "RMS (root mean square)", "Loudspeaker management system", "Voice coil", "Crest factor", "Threshold"], "common_mistakes": ["UNSAFE: Relying on the RMS/thermal limiter alone, which is too slow to stop the fast peaks that cause over-excursion and mechanical driver damage.", "Confusing RMS/thermal limiting with peak limiting, when the two use different time constants and protect against different failures (heat vs. excursion/clipping).", "Setting the threshold from an amplifier's rating rather than the driver's power handling, leaving the speaker unprotected.", "Using a very short attack/release, which defeats the point of averaging and no longer tracks the coil's slow heating."], "scenario_contexts": ["Configuring driver protection in a loudspeaker processor before a tour so a PA can run at high level all night.", "Setting long-term power limits on a subwoofer amplifier to prevent voice-coil burnout.", "Diagnosing an intermittent driver that fails after long, loud passages, pointing to thermal overload."]}, "9838c0d1-15b9-4901-9406-26732df761f0": {"definition": "Sample peak is the maximum absolute value of the individual digital audio samples in a signal, read directly from the stored PCM sample values and expressed in dBFS relative to digital full scale. Because it examines only the discrete sample points, it does not account for the higher inter-sample peaks that can appear in the reconstructed analog waveform, which is why it is distinguished from true peak (dBTP), measured on an oversampled version of the signal.", "plain_english": "Digital audio is stored as a row of dots called samples. Sample peak is simply the tallest dot, measured against the digital ceiling. It only looks at the stored dots. The smooth wave played back can rise higher between them, so this reading can miss real peaks.", "purpose_function": "It gives a fast, simple readout of the loudest stored sample so engineers can see how close a signal sits to digital full scale. It underpins classic digital peak meters and clip indicators.", "practical_application": "An engineer watches a sample-peak (dBFS) meter while tracking or mixing to keep levels below 0 dBFS, then switches to a true-peak meter for final delivery to catch inter-sample overs.", "category": "Digital metering", "related_terms": ["True peak (dBTP)", "dBFS", "Inter-sample distortion", "Digital clipping", "Peak meter", "Full scale (0 dBFS)"], "common_mistakes": ["Assuming that if no sample reaches 0 dBFS the signal cannot clip, when inter-sample peaks can still exceed full scale on playback.", "Treating sample peak and true peak (dBTP) as the same measurement, when true peak reads an oversampled waveform.", "Using a sample-peak reading as a loudness measure, when it shows only the single loudest sample, not perceived level."], "scenario_contexts": ["Setting recording levels so the sample-peak meter stays safely below 0 dBFS.", "Comparing a sample-peak meter against a true-peak meter on a hot master to see hidden overs.", "Checking a clip indicator that lights when consecutive samples hit full scale."]}, "ea833a2b-939b-4a06-8466-0c9cfb67bbc8": {"definition": "A pink-noise signal generator produces a random broadband test signal whose power spectral density is inversely proportional to frequency (a 1/f, or -3 dB per octave, slope), so that equal power falls within each octave or each fractional-octave band. This makes pink noise appear flat on a constant-percentage-bandwidth (octave or fractional-octave) analyzer and approximates the ear's octave-based perception, which is why it is the standard excitation signal for acoustic and loudspeaker measurement.", "plain_english": "Pink noise is a steady 'shhh' test sound with equal energy in every octave. Because each octave carries the same power, it sounds evenly balanced and not harsh. Engineers play it through a system and measure the result. It is the go-to signal for checking speakers and rooms.", "purpose_function": "It provides a repeatable broadband stimulus with equal energy per octave, so a system's response can be measured across the whole spectrum at once. Its slope matches octave-based analyzers and hearing, giving readings that relate to how we perceive balance.", "practical_application": "A system tech feeds pink noise into a PA and reads a real-time analyzer or transfer-function display to set EQ and check tonal balance and coverage.", "category": "Test signal", "related_terms": ["Signal Generator - White Noise", "Real-time analyzer (RTA)", "Transfer function", "Octave band", "Power spectral density", "Signal Generator - Sine"], "common_mistakes": ["Confusing pink noise with white noise, when white noise has equal energy per hertz and pink has equal energy per octave.", "Expecting pink noise to read as a flat line on a linear (per-hertz) FFT display, where it actually slopes down at about 3 dB per octave.", "UNSAFE: Sending full-level pink noise through a PA without limiting or ear protection, exposing crew to sustained high SPL and risking speaker and hearing damage."], "scenario_contexts": ["Tuning a sound system's EQ while watching pink noise on an RTA.", "Setting relative levels between loudspeaker zones using a steady pink-noise reference.", "Checking a room's frequency balance during acoustic measurement."]}, "b30b9d78-93d3-4691-85ce-f4f9b05f22b9": {"definition": "A sine signal generator produces a single-frequency sinusoidal tone of defined frequency, amplitude, and phase, containing energy at only that one frequency (a pure tone with, ideally, no harmonics). It is the fundamental stimulus for measuring level, gain, frequency response at discrete points, and distortion, since any added harmonic content at the output reveals nonlinearity in the device under test.", "plain_english": "A sine generator makes one pure, steady tone at a single pitch. It is the cleanest test sound there is, with no extra tones mixed in. Because it is so pure, any new tones that appear after gear show the gear is adding distortion. Engineers use it to check levels and cleanliness.", "purpose_function": "It delivers a single, precisely known frequency and level so a technician can measure gain, set reference levels, and expose distortion or noise added by equipment. Its purity makes any output impurity easy to spot.", "practical_application": "A technician sends a 1 kHz sine at a reference level (for example 0 dBu or -20 dBFS) to line up console meters, set gain structure, or measure THD on a device.", "category": "Test signal", "related_terms": ["Signal Generator - Sweep", "Total harmonic distortion (THD)", "Reference level", "Frequency response", "Signal Generator - Pink Noise", "Oscillator"], "common_mistakes": ["Driving a sine tone so hot that the device or generator itself clips, adding harmonics and giving a false distortion reading.", "Using a single spot frequency to judge a whole system's response, missing problems at other frequencies a sweep would reveal.", "UNSAFE: Leaving a sustained loud sine tone running through loudspeakers, which concentrates energy at one frequency and can overheat a driver and harm hearing."], "scenario_contexts": ["Sending 1 kHz at a reference level to calibrate meters and set gain structure.", "Measuring total harmonic distortion of a preamp or converter at a fixed frequency.", "Checking channel level matching or verifying a signal path with a steady tone."]}, "b591efc1-efba-4658-aaef-6557f8c04a5a": {"definition": "A sweep signal generator produces a sine tone whose frequency changes continuously over a defined range and time, either linearly or logarithmically (a logarithmic sweep is often called a log or exponential sine sweep). Sweeping a pure tone across the band lets a measurement system capture frequency response, and, with modern deconvolution techniques, the impulse response, distortion products, and delay of a device or acoustic space with a high signal-to-noise ratio.", "plain_english": "A sweep is a single tone that slides smoothly from low pitch to high pitch over a set time. Playing it through a system tests every frequency in turn, not just one. From the recorded result, software can work out the system's response and timing. It is a powerful, low-noise way to measure gear and rooms.", "purpose_function": "It exercises the whole frequency band in one controlled pass, so a measurement system can derive response, impulse response, and delay with strong noise rejection. The moving tone also lets distortion be separated from the wanted response.", "practical_application": "An engineer runs a log sine sweep through a loudspeaker or room and uses measurement software to extract the impulse response, frequency response, and reverberation time.", "category": "Test signal", "related_terms": ["Signal Generator - Sine", "Impulse response", "Frequency response", "Deconvolution", "Transfer function", "Reverberation time (RT60)"], "common_mistakes": ["Sweeping too fast, so low frequencies are not excited long enough for an accurate low-end measurement.", "Confusing a slow measurement sweep with an audible 'chirp' effect, when the two serve different purposes.", "UNSAFE: Running a high-level sweep through a PA without hearing protection or limiting, exposing crew to concentrated, moving high-SPL energy."], "scenario_contexts": ["Capturing a room's impulse response with a log sine sweep for acoustic analysis.", "Measuring a loudspeaker's frequency response and distortion in the lab.", "Deriving system delay and reverberation time during venue tuning."]}, "258c4ea9-7710-4bc4-9599-384c4ed3e0ab": {"definition": "A white-noise signal generator produces a random broadband test signal with a flat power spectral density, meaning equal power in every equal-width frequency band (equal energy per hertz) across the audio range. Because bandwidth doubles with each rising octave, white noise carries progressively more power in higher octaves (rising about 3 dB per octave on an octave-band analyzer), which is why pink noise is usually preferred for octave-based acoustic measurement.", "plain_english": "White noise is a random 'hiss' with the same energy in every equal slice of frequency. Because higher octaves are wider, they end up holding more of its power. That makes it sound bright and hissy, like TV static. It is used for tests, masking, and as a source in synthesis.", "purpose_function": "It provides a broadband signal with equal energy per hertz, useful as a controlled stimulus, as a masking sound, and as a raw source in synthesizers. Its flat per-hertz spectrum is a mathematical reference point for other noise types.", "practical_application": "An engineer uses white noise as a synth source or masking signal, and, when octave-band balance matters, switches to pink noise or applies filtering for acoustic measurement.", "category": "Test signal", "related_terms": ["Signal Generator - Pink Noise", "Power spectral density", "Octave band", "Masking", "Real-time analyzer (RTA)", "Subtractive synthesis"], "common_mistakes": ["Confusing white noise with pink noise, when white has equal energy per hertz and pink has equal energy per octave.", "Using white noise for octave-based room or PA measurement, where its rising high-end can overstate treble and stress tweeters.", "Expecting white noise to sound tonally balanced, when its energy climbs with frequency and sounds bright."], "scenario_contexts": ["Feeding white noise into a synthesizer filter to create wind or percussion sounds.", "Using white noise as a masking signal to cover distracting background sound.", "Comparing white and pink noise on an analyzer to see the difference in spectral slope."]}, "886e65f2-0e5d-4ffd-ac56-4c1eb3da1219": {"definition": "Sinusoidal resynthesis is the reconstruction of an audio signal from a sinusoidal model, in which analysis first represents the sound as a set of time-varying sinusoids (partials) each described by an amplitude, frequency, and phase trajectory, and synthesis then regenerates the sound by summing those sinusoids. It is the synthesis stage of sinusoidal modeling techniques such as the McAulay-Quatieri method and the deterministic part of spectral modeling synthesis, and it allows the resynthesized signal to be transformed (time-stretched, pitch-shifted, or filtered) by altering the model parameters before reconstruction.", "plain_english": "Any sound can be described as a stack of pure tones that change over time. Sinusoidal resynthesis first measures those tones inside a recording. Then it rebuilds the sound by adding the tones back together. Because the tones are now adjustable, you can stretch time or shift pitch before rebuilding.", "purpose_function": "It turns a sound into an editable set of sinusoids and then rebuilds it, so the sound can be stretched, pitch-shifted, or reshaped independently of its original timing. This flexible model underlies many analysis-based synthesis and audio-effect tools.", "practical_application": "A sound designer or engineer uses spectral or sinusoidal-modeling software to analyze a recording, edit its partials, and resynthesize a time-stretched or pitch-shifted version without the usual artifacts.", "category": "Analysis/synthesis", "related_terms": ["Additive synthesis", "Partial (harmonic)", "Spectral modeling synthesis", "Fourier analysis", "Phase vocoder", "Time stretching"], "common_mistakes": ["Assuming a purely sinusoidal model can perfectly recreate noisy or transient sounds, when those need a separate noise/residual component (as in spectral modeling synthesis).", "Confusing sinusoidal resynthesis with simple resampling, when it rebuilds sound from measured partials rather than replaying stored samples.", "Ignoring phase trajectories, which can smear transients and cause artifacts in the resynthesized result."], "scenario_contexts": ["Time-stretching a vocal without changing its pitch using sinusoidal-modeling software.", "Pitch-shifting an instrument by scaling the frequencies of its analyzed partials.", "Creating morphing or hybrid timbres by editing partials before resynthesis."]}, "d2f67d1d-2c49-45c3-8bb8-1bfc860e2af9": {"definition": "Sound exposure is the total A-weighted sound energy a person receives over a stated period, combining sound level and duration, while noise dose expresses that exposure as a percentage of an allowable daily limit set by a standard. Under OSHA 29 CFR 1910.95, 100% dose corresponds to the permissible exposure limit of 90 dBA as an 8-hour time-weighted average using a 5 dB exchange rate (with an 85 dBA 8-hour action level), whereas NIOSH recommends a lower 85 dBA 8-hour limit with a 3 dB exchange rate, so a given exposure yields a higher dose under the NIOSH criterion.", "plain_english": "Sound exposure adds up how loud a sound is and how long you hear it. Dose turns that total into a percentage of a safe daily limit. Hitting 100% means you have reached the limit for the day. Louder sound uses up your daily dose much faster, so time at high volume matters a lot.", "purpose_function": "Dose combines level and time into one number so workers and engineers can track cumulative daily exposure against a legal or recommended limit. This drives decisions about hearing protection, breaks, and level control.", "practical_application": "An engineer or safety officer wears or places a noise dosimeter that logs a running dose over the shift, then uses the reading to decide on hearing protection and to keep exposure within OSHA or NIOSH limits.", "category": "Noise exposure", "related_terms": ["LAeq", "Time-weighted average (TWA)", "Exchange rate", "Noise dosimeter", "A-weighting", "Sound level meter"], "common_mistakes": ["UNSAFE: Assuming a reading below 100% dose is fully safe, when NIOSH warns any exposure above 85 dBA can cause hearing loss and 100% under OSHA's 90 dBA limit already carries risk.", "UNSAFE: Judging a loud event by peak SPL alone and ignoring accumulated dose, so hours at moderate-to-high level go unmanaged.", "Confusing OSHA and NIOSH numbers, since the 5 dB versus 3 dB exchange rate makes the same exposure read as very different doses.", "Forgetting that halving the exposure time does not halve the hearing risk, because dose rises steeply with level."], "scenario_contexts": ["A live-sound crew member wearing a dosimeter across a festival day to track cumulative noise dose.", "A venue setting show levels and break schedules so staff stay within occupational noise limits.", "A safety officer comparing measured dose against OSHA and NIOSH criteria to specify hearing protection."]}, "b546c7fc-b64f-4062-9a1d-9cf99f1e4cc6": {"definition": "Spatial averaging is the technique of combining measurements taken at several positions in a space, or with several microphones, into a single averaged result so that the outcome represents an area rather than one point. It reduces the influence of position-dependent effects such as room modes, reflections, and comb filtering, giving a more representative and stable estimate of a system's response over the listening area.", "plain_english": "Sound changes a lot from seat to seat because of reflections and room effects. Measuring at just one spot can be misleading. Spatial averaging combines readings from several positions into one. This gives a fairer picture of how the whole area sounds, not just one chair.", "purpose_function": "It exists to average out strong point-to-point variations so a measurement reflects the whole audience area, not a single lucky or unlucky spot. This yields more reliable data for EQ and system tuning decisions.", "practical_application": "A system engineer captures transfer-function or RTA measurements at multiple mic positions across the seating area and averages them before deciding on system EQ.", "category": "Measurement technique", "related_terms": ["Transfer function", "Comb filtering", "Room modes", "Real-time analyzer (RTA)", "Averaging", "Reverberation time (RT60)"], "common_mistakes": ["EQ-ing to a single measurement position and mistaking a local dip or peak for a system-wide problem.", "Averaging positions that are too far apart or too different, blending unrelated responses into a meaningless curve.", "Confusing spatial averaging (across positions) with time averaging (across successive samples at one point), which address different problems."], "scenario_contexts": ["Averaging measurements from several seats to set house EQ for a venue.", "Combining multiple mic positions when tuning a line array's front-to-back response.", "Reducing comb-filtering artifacts in data by averaging across nearby measurement points."]}, "e1d5a5f6-636c-4670-a678-93349f8dc034": {"definition": "The distribution of a program's sound energy across the stereo or surround field, describing how evenly signal levels sit between the left and right (and, in surround, front and rear) channels. It is assessed on balance meters, goniometers or vectorscopes to confirm the image is centered and not skewed to one side.", "plain_english": "Spatial balance is how evenly the sound sits between the left and right speakers. If one side is much louder, the mix feels lopsided instead of centered.", "purpose_function": "It tells the engineer whether the stereo image is even and phantom-centered, so listeners hear a stable, natural placement rather than a mix that pulls to one side.", "practical_application": "An engineer watches a balance meter or goniometer while mixing and mastering to catch a channel that is too loud or a lead vocal that has drifted off-center.", "category": "Spatial Metering", "related_terms": ["Goniometer", "Vectorscope", "Phase correlation meter", "Panning", "Stereo width"], "common_mistakes": ["Confusing overall channel balance with the pan position of individual sources", "Assuming a centered correlation meter guarantees good spatial balance", "Judging balance on unmatched or poorly placed monitors, which skews perception"], "scenario_contexts": ["Checking a stereo master so the mix is not louder on one side", "Setting up front-of-house so the sound field is even for the audience", "Verifying dialogue stays centered in a broadcast or film mix"]}, "a13f834e-6f23-47a9-9bd4-519657b840c3": {"definition": "The measurement and representation of a signal's energy as a function of frequency, typically computed with a Fast Fourier Transform (FFT) that converts a time-domain record into its constituent frequency components. It reveals the amplitude (and often phase) present at each frequency, displayed as a spectrum or spectrogram.", "plain_english": "Spectral analysis breaks a sound into the separate frequencies it contains. It works like a prism splitting white light into a rainbow, but for sound.", "purpose_function": "It lets an engineer see the frequency content of a signal instead of just its level, so issues like resonances, noise or feedback can be spotted by where they sit in the spectrum.", "practical_application": "Technicians use a real-time analyzer or FFT display to ring out feedback, check room response, or find the frequency of a hum during measurement and tuning.", "category": "Spectral Analysis", "related_terms": ["FFT", "Spectral bin", "Real-time analyzer (RTA)", "Spectrogram", "Frequency resolution", "Window function"], "common_mistakes": ["Forgetting that larger FFT sizes give finer frequency resolution but slower time response", "Ignoring how the choice of window function shapes the displayed spectrum", "Reading an uncalibrated analyzer's absolute levels as if they were accurate"], "scenario_contexts": ["Identifying feedback frequencies before a live show", "Measuring a room's frequency response for system tuning", "Locating the frequency of an electrical hum in a recording"]}, "529f6b40-a0aa-42ab-b5b1-e336502f2a20": {"definition": "The width of the frequency range over which a signal's energy is significantly present, often specified between defined amplitude limits such as the -3 dB points or as an occupied bandwidth. In spectral feature extraction it is quantified as the spectral spread: the amplitude-weighted standard deviation of frequencies about the spectral centroid.", "plain_english": "Spectral bandwidth is how wide a range of frequencies a sound covers. A narrow one is like a single whistle; a wide one is like static spread across many pitches.", "purpose_function": "It summarizes how concentrated or spread out a signal's frequencies are, which helps tell pure tones apart from noisy or complex sounds.", "practical_application": "An engineer checks bandwidth to judge whether a signal is a narrow tone, such as feedback, or broadband noise, and to confirm it fits the frequency space it is allotted.", "category": "Spectral Analysis", "related_terms": ["Spectral centroid", "Spectral analysis", "Frequency response", "Q factor", "Occupied bandwidth"], "common_mistakes": ["Confusing spectral bandwidth with a filter's bandwidth or its Q factor", "Assuming wider bandwidth always means a better or fuller sound", "Mixing up the -3 dB definition with the -6 dB or occupied-bandwidth definitions"], "scenario_contexts": ["Describing whether a sound source is tonal or noise-like", "Confirming a signal stays within an allocated frequency band", "Comparing the spread of energy between two instruments in analysis"]}, "858bcfab-3df5-404a-b250-bf7096012eaa": {"definition": "One of the discrete frequency points produced by a Fast Fourier Transform, each representing the signal energy within a narrow frequency slice. The bin width (frequency resolution) equals the sample rate divided by the FFT size, and an N-point real FFT yields N/2 + 1 usable bins up to the Nyquist frequency.", "plain_english": "A spectral bin is one narrow frequency slot. A frequency analyzer (an FFT, or Fast Fourier Transform) measures the level in each one. Picture the spectrum as a row of buckets, each catching the energy near one frequency.", "purpose_function": "Bins are the building blocks of an FFT spectrum, and their width sets how finely an analyzer can tell nearby frequencies apart.", "practical_application": "When an engineer picks a larger FFT size for finer resolution, they are making each bin narrower so closely spaced tones show up as separate peaks.", "category": "Spectral Analysis", "related_terms": ["FFT", "Frequency resolution", "Nyquist frequency", "Spectral analysis", "Window function", "Spectral leakage"], "common_mistakes": ["Thinking more bins always mean more accuracy, ignoring the time-resolution tradeoff", "Assuming a tone falls exactly on a bin center, which causes leakage and scalloping", "Confusing bin width with the analyzer's displayed smoothing or averaging"], "scenario_contexts": ["Choosing an FFT size to resolve two close frequencies", "Interpreting exactly where a peak sits on an FFT display", "Understanding spectral leakage when a tone falls between bins"]}, "239b47ca-23f9-418c-be01-b57887ec58d2": {"definition": "The smearing of energy across time or frequency in a spectral representation, so that distinct events or frequencies become indistinct. It stems from the time-frequency resolution tradeoff of the short-time Fourier transform: longer analysis windows blur time detail, shorter windows blur frequency detail, and spectral leakage from windowing spreads a tone across neighboring bins.", "plain_english": "Spectral blurring is when the fine detail in a sound's frequency picture gets smeared. It is like an out-of-focus photo, where sharp edges turn fuzzy.", "purpose_function": "Knowing about it explains why an analyzer or processor cannot show exact timing and exact pitch at once, which limits how cleanly signals can be measured or separated.", "practical_application": "An engineer who sees a smeared spectrogram changes the window size or type to sharpen either the time detail or the frequency detail they need.", "category": "Spectral Analysis", "related_terms": ["Spectral leakage", "Window function", "Short-time Fourier transform", "Frequency resolution", "Spectral bin"], "common_mistakes": ["Blaming the source signal for blurring that actually comes from the window choice", "Expecting perfect time and frequency detail at the same time", "Using too short a window and then misreading the smeared frequencies"], "scenario_contexts": ["Reading a spectrogram during audio restoration", "Choosing STFT settings for a phase-vocoder time-stretch", "Diagnosing why two close tones merge into one on an analyzer"]}, "009adb76-f3c4-4bb8-b4d9-33ee3c4ff0cc": {"definition": "The amplitude-weighted mean frequency of a signal's spectrum, its center of gravity, calculated as the sum of each frequency times its magnitude divided by the total magnitude. It correlates strongly with the perceived brightness of a sound.", "plain_english": "The spectral centroid is the balance point of a sound's frequencies. A higher balance point sounds bright, like a cymbal; a lower one sounds dull, like a bass drum.", "purpose_function": "It gives a single number that shows where most of a sound's energy sits, which is why it is widely used as a brightness or timbre measure.", "practical_application": "In audio analysis and machine listening it helps sort or match sounds by brightness, and it guides EQ when comparing a dull mix to a brighter reference.", "category": "Spectral Analysis", "related_terms": ["Spectral bandwidth", "Brightness", "Timbre", "Spectral analysis", "FFT"], "common_mistakes": ["Treating the centroid as the single loudest frequency rather than the weighted average", "Assuming a high centroid always means higher perceived loudness", "Comparing centroids across clips at very different overall levels without care"], "scenario_contexts": ["Measuring brightness to match a mix to a reference", "Classifying instruments or sounds in machine-listening tools", "Tracking how a sound's brightness changes over time"]}, "985e1280-4cc1-48ab-b191-adfd54021929": {"definition": "The copying of spectral content from one region, time, or source to reconstruct or replace another part of a signal's spectrum. It underlies bandwidth-extension methods such as spectral band replication and the clone tools in spectral editors, where energy from a clean region is duplicated to fill a gap or a missing high band.", "plain_english": "Spectral cloning copies the frequency content from one spot and pastes it into another. It is like patching a hole in a photo by copying pixels from a clean area nearby.", "purpose_function": "It rebuilds or extends missing or damaged parts of a spectrum, restoring a fuller sound or recreating high frequencies lost to low-bitrate coding.", "practical_application": "A restoration engineer uses a spectral editor's clone tool to paint over a cough or dropout with clean spectral data from nearby, so the repair blends in.", "category": "Spectral Processing", "related_terms": ["Spectral band replication", "Spectral analysis", "Spectral editing", "Bandwidth extension", "Spectral repair"], "common_mistakes": ["Assuming cloned high frequencies add real detail rather than a synthetic estimate", "Cloning from a region whose tone does not match, leaving an audible seam", "Confusing spectral cloning with a simple copy-paste of the time-domain waveform"], "scenario_contexts": ["Repairing a dropout or noise burst in a spectral editor", "Extending the high-frequency band of a dull or coded recording", "Filling a gap left after removing an unwanted sound"]}, "b1bafae0-c270-43e4-8366-a2e0d69c4b7e": {"definition": "Dynamic-range compression applied independently across many narrow frequency regions of the spectrum, reducing level only in the bands that exceed threshold at a given moment. It extends multiband compression toward fine, per-band control, tightening tonal balance and taming resonances without acting on the whole signal at once.", "plain_english": "Spectral compression turns down only the frequencies that get too loud, moment to moment. It is like many tiny volume controls, each watching its own slice of the sound.", "purpose_function": "It evens out tonal balance and controls problem frequencies more surgically than one broadband compressor, leaving the rest of the sound untouched.", "practical_application": "A mixing or mastering engineer uses a spectral compressor to smooth harsh spikes or an uneven vocal tone while keeping the overall dynamics natural.", "category": "Spectral Processing", "related_terms": ["Multiband compression", "Dynamic range compression", "Dynamic EQ", "Threshold", "Spectral analysis"], "common_mistakes": ["Confusing spectral (audio dynamics) compression with data or file-size compression", "Overusing it until the sound becomes flat and lifeless", "Assuming it replaces good EQ rather than complementing it"], "scenario_contexts": ["Taming harsh resonances on a vocal during mixing", "Smoothing tonal balance on a master", "Controlling uneven frequency buildup in a live mix"]}, "0d391279-af49-4161-b016-446f2291b527": {"definition": "An audio feature that measures, within each of several frequency sub-bands (typically octave-spaced), the level difference between the spectral peaks and the spectral valleys in that band. High contrast indicates clear tonal (harmonic) content, while low contrast indicates flatter, noise-like content, making it a useful descriptor for timbre and music-type classification.", "plain_english": "Spectral contrast measures the gap between the loud peaks and quiet dips in each frequency range. A big gap means a clear tone; a small gap means noise.", "purpose_function": "It captures how tonal or noisy a sound is in different frequency regions, giving classifiers a compact way to tell genres, instruments, or speech apart.", "practical_application": "In machine-listening and music-analysis tools, a technician uses spectral contrast as an input feature to automatically sort or identify audio by its texture.", "category": "Spectral Analysis", "related_terms": ["Spectral flatness", "Spectral centroid", "Spectral envelope", "Timbre", "MFCC", "Spectral analysis"], "common_mistakes": ["Confusing spectral contrast with the spectral centroid or with overall brightness", "Assuming high contrast always means higher perceived loudness", "Ignoring that the sub-band count and octave spacing change the result"], "scenario_contexts": ["Classifying music by genre in an analysis tool", "Distinguishing tonal instruments from noisy percussion", "Feeding a machine-learning model features for audio tagging"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"89fc0147-5d4f-44b6-8486-91ccd67fc9ad": {"definition": "A spectral processing technique that creates a hybrid sound by combining features of two signals in the frequency domain, typically imposing the spectral envelope (formant shape) of one sound onto the fine spectral detail or excitation of another. It is commonly implemented with the short-time Fourier transform or phase vocoder and underlies classic vocoder-like and 'talking instrument' effects.", "plain_english": "Cross-synthesis blends two sounds by frequency. It can wrap the tone shape of a voice around a guitar, so the guitar seems to speak.", "purpose_function": "It lets a sound designer merge the character of one source with the pitch or energy of another, producing morphing and hybrid timbres that neither sound has alone.", "practical_application": "A sound designer uses a cross-synthesis or vocoder plugin to make a synth pad 'sing' words, or to graft the texture of one instrument onto another.", "category": "Spectral Processing", "related_terms": ["Vocoder", "Phase vocoder", "Spectral envelope", "Short-time Fourier transform", "Spectral morphing", "Convolution"], "common_mistakes": ["Confusing cross-synthesis with simply layering or mixing two sounds together", "Expecting intelligible results when the two sources have very different spectra", "Ignoring that window and frame settings strongly affect the outcome"], "scenario_contexts": ["Making a synthesizer speak, like a vocoder", "Morphing one instrument's timbre into another for sound design", "Creating hybrid textures for film and game audio"]}, "105a27db-af66-4d8a-aa42-1ee007a15811": {"definition": "A frequency-domain noise-reduction process that estimates the noise spectrum, then attenuates or subtracts that estimate from each time-frequency bin of the signal, most classically by spectral subtraction. It reduces steady broadband noise such as hiss, hum, or air-handling rumble while aiming to preserve the wanted signal.", "plain_english": "Spectral denoising learns what the background noise looks like across frequencies, then removes that much. It is like erasing a steady hiss while keeping the music.", "purpose_function": "It removes unwanted steady noise so the desired audio stands out, which is essential in restoration, dialogue cleanup, and forensic work.", "practical_application": "A restoration engineer captures a short noise-only sample to build a noise profile, then applies spectral denoising to strip hiss or air-conditioning rumble from a take.", "category": "Spectral Processing", "related_terms": ["Spectral subtraction", "Spectral gating", "Noise profile", "Audio restoration", "Short-time Fourier transform", "Musical noise"], "common_mistakes": ["Over-reducing until the signal sounds hollow with warbly 'musical noise' artifacts", "Building the noise profile from a section that still contains wanted signal", "Assuming it can remove sudden or moving sounds as well as steady noise"], "scenario_contexts": ["Cleaning hiss from an old tape transfer", "Removing air-conditioner rumble from dialogue", "Reducing steady background noise in a podcast recording"]}, "1dc62001-59b1-4f12-acbf-769518e6f09f": {"definition": "The smooth curve that describes the overall shape of a signal's magnitude spectrum as a function of frequency, following the tops of the harmonic peaks rather than the individual partials. In the source-filter model it represents the resonances (formants) applied to an excitation, and it strongly determines timbre and vowel identity.", "plain_english": "The spectral envelope is the overall outline of a sound's frequencies. Picture a smooth line drawn over the tops of all the peaks. This shape makes a vowel or instrument easy to recognize.", "purpose_function": "It captures the timbre or 'color' of a sound largely independently of its pitch, which is why it is central to synthesis, voice processing, and formant work.", "practical_application": "An engineer preserves or reshapes the spectral envelope when pitch-shifting a voice so it stays natural instead of sounding like a chipmunk.", "category": "Spectral Analysis", "related_terms": ["Formant", "Source-filter model", "Timbre", "Spectral centroid", "Spectral cross-synthesis", "Cepstrum"], "common_mistakes": ["Confusing the spectral envelope with the individual harmonic peaks it smooths over", "Shifting pitch without preserving the envelope, causing unnatural formants", "Assuming the envelope alone defines a sound, ignoring how it changes over time"], "scenario_contexts": ["Formant-preserving pitch correction on vocals", "Designing a vocoder or cross-synthesis effect", "Analyzing vowel sounds in speech processing"]}, "c9a1e492-c67d-4779-84cd-173456c76cdd": {"definition": "Dynamic-range expansion applied independently across many narrow frequency regions, increasing the level difference between loud and quiet content within each band. Downward spectral expansion attenuates low-level content per band and is widely used for noise reduction, while upward expansion can restore dynamics lost to over-compression.", "plain_english": "Spectral expansion makes the quiet parts quieter in each frequency range on its own. Turning down the soft bits per band gently pushes back background noise.", "purpose_function": "It increases the contrast between wanted signal and low-level noise band by band, so it can clean recordings or reopen dynamics more surgically than one broadband expander.", "practical_application": "A restoration or mastering engineer uses per-band downward expansion to reduce hiss between notes, or upward expansion to add life back to a squashed mix.", "category": "Spectral Processing", "related_terms": ["Expander", "Downward expansion", "Spectral compression", "Multiband compression", "Spectral denoising", "Dynamic range"], "common_mistakes": ["Confusing expansion with compression, which reduces rather than increases dynamic range", "Setting too aggressive a ratio, causing choppy or pumping artifacts", "Confusing audio-dynamics expansion with data or bit-depth expansion"], "scenario_contexts": ["Reducing hiss between musical phrases", "Restoring dynamics to an over-compressed master", "Cleaning low-level noise from a dialogue track"]}, "754001f2-3c90-4415-95db-0641631786d4": {"definition": "Filtering carried out in the frequency domain by transforming a signal with a short-time Fourier transform, scaling or zeroing selected frequency bins according to a desired response, then transforming back to the time domain. It allows arbitrary, fine-grained frequency shaping that is difficult to achieve with conventional time-domain filters.", "plain_english": "Spectral filtering splits a sound into its frequencies, turns chosen ones up or down, then puts it back. It is like sorting sound into bins and adjusting each bin by hand.", "purpose_function": "It gives very precise control over which frequencies pass or are removed, enabling surgical EQ, notching, and effects that shape the spectrum directly.", "practical_application": "An engineer uses an FFT-based filter or spectral editor to notch out a narrow whistle or isolate a frequency band that ordinary filters cannot cleanly reach.", "category": "Spectral Processing", "related_terms": ["FFT", "Short-time Fourier transform", "Spectral bin", "Linear-phase filter", "Equalization", "Spectral editing"], "common_mistakes": ["Ignoring window and overlap settings, which cause clicks or time smearing", "Assuming that zeroing bins gives a clean cut, when it can ring or pre-echo", "Confusing frequency-domain filtering with a simple time-domain EQ"], "scenario_contexts": ["Notching out a narrow tonal noise during restoration", "Building a steep linear-phase filter for mastering", "Isolating a frequency band for analysis or effects"]}, "997dd950-1628-4773-b4c7-87d623781f6d": {"definition": "An audio feature that quantifies how quickly the magnitude spectrum changes between successive analysis frames, computed as the (often half-wave-rectified) difference between the normalized spectra of consecutive frames. Large values mark abrupt spectral changes, which makes it a standard detection function for note onsets.", "plain_english": "Spectral flux measures how much a sound's frequencies change from one instant to the next. A big jump usually means a new note or hit has started.", "purpose_function": "It provides a single number per frame showing spectral change over time, which is why it is a go-to feature for onset and beat detection.", "practical_application": "A technician relies on spectral flux inside beat-tracking or onset-detection tools to find where notes begin for slicing, quantizing, or tempo analysis.", "category": "Spectral Analysis", "related_terms": ["Onset detection", "Spectral centroid", "Beat tracking", "Spectral analysis", "Transient", "Spectral flatness"], "common_mistakes": ["Forgetting to normalize spectra, so loudness changes look like spectral change", "Skipping half-wave rectification when only energy increases matter for onsets", "Assuming every flux peak is a true onset without applying a threshold"], "scenario_contexts": ["Detecting note onsets for automatic slicing", "Beat and tempo tracking in a DAW or analysis tool", "Segmenting audio into events for tagging"]}, "6193d68d-82aa-489c-818f-e578eb0d234f": {"definition": "A frequency-domain noise-reduction method that sets a threshold (gate) for each frequency bin, usually derived from a noise profile, then attenuates any time-frequency bin whose level falls below its threshold while passing bins above it. It is effectively a noise gate applied per frequency band rather than to the whole broadband signal.", "plain_english": "Spectral gating puts a tiny noise gate on each frequency band. If a band is quieter than the learned noise level, it gets turned down; louder bands pass through.", "purpose_function": "It removes steady background noise while keeping louder wanted sound, giving finer control than a single broadband gate that would clamp the whole signal at once.", "practical_application": "An engineer captures a noise-only sample, and the tool uses it to gate each band, stripping hiss or hum from speech or music during cleanup.", "category": "Spectral Processing", "related_terms": ["Noise gate", "Spectral denoising", "Spectral subtraction", "Noise profile", "Threshold", "Audio restoration"], "common_mistakes": ["Setting the threshold too high, which gates wanted low-level detail and sounds choppy", "Confusing per-band spectral gating with a single broadband noise gate", "Building the noise profile from audio that still contains wanted signal"], "scenario_contexts": ["Removing steady hiss from a voiceover", "Cleaning background hum from an interview recording", "Reducing broadband noise before mixing"]}, "1250ac14-5ecb-4468-95fa-32db595ce948": {"definition": "A display or capture function on a spectrum analyzer that retains, for each frequency bin, the maximum magnitude reached over time, so brief transient peaks stay visible after they occur. The same term also names a spectral-processing mode that freezes and sustains the current analysis frame, holding a sound's spectrum indefinitely.", "plain_english": "Spectral hold makes a frequency display remember the loudest level hit at each pitch. Short peaks flash by too fast to read. The hold keeps them on screen so you can see them. Some effects also use it to freeze and sustain a sound.", "purpose_function": "It exists so that brief spectral peaks are not missed on a fast-moving live analyzer, letting an engineer capture the worst-case level in each frequency band. In effects, it lets a spectrum be frozen and sustained for creative or diagnostic use.", "practical_application": "An engineer turns on peak hold while measuring a system with music or noise, then reads the retained maximum in each band to spot resonances or overloads.", "category": "Spectral Analysis", "related_terms": ["Peak hold", "Real-time analyzer (RTA)", "Spectrum analyzer", "Spectral bin", "FFT", "Peak meter"], "common_mistakes": ["Confusing spectral peak hold with an averaged display, when hold shows maxima rather than the ongoing average.", "Forgetting to reset the hold, so old peaks from an earlier signal linger and mislead.", "Assuming a held peak shows a steady level, when it may reflect a single brief transient."], "scenario_contexts": ["Catching momentary feedback frequencies on an analyzer during a soundcheck.", "Logging the worst-case level in each band while measuring a noisy system.", "Freezing a spectrum to study a resonance that comes and goes."]}, "99dd7fcc-23e5-47c6-9d0e-2951cb383209": {"definition": "The process of imposing the spectral characteristics of one signal - its frequency balance or spectral envelope - onto another signal, so the target takes on the tonal fingerprint of the reference. It is realized through techniques such as matching equalization, spectral-envelope transfer, or cross-synthesis.", "plain_english": "Spectral imprinting copies the tonal fingerprint of one sound onto another. You take the frequency shape of a reference sound. Then you stamp that shape onto your target. The target ends up with a similar tonal color.", "purpose_function": "It exists to make one signal share the tonal balance of another, for matching, restoration, or creative morphing. This lets an engineer force a target to sit tonally alongside a chosen reference.", "practical_application": "An engineer captures the average spectrum of a reference track and applies it, through a matching equalizer, to a new mix so both share the same tonal balance.", "category": "Spectral Processing", "related_terms": ["Spectral matching", "Spectral envelope", "Match EQ", "Cross-synthesis", "Equalization", "Tonal balance"], "common_mistakes": ["Expecting imprinting to fix arrangement or dynamics, when it only copies frequency balance.", "Imprinting from a noisy or narrow reference, which stamps its flaws onto the target.", "Applying an extreme match that adds harsh resonances instead of a natural balance."], "scenario_contexts": ["Making a re-recorded line match the tone of the original session.", "Matching dialogue from two locations so they sound like one room.", "Morphing one instrument's tone toward another for a creative effect."]}, "4acf0be0-15a0-4382-b284-4488d9eb62d5": {"definition": "The estimation of spectral values that fall between the discrete points of a computed spectrum. Within one spectrum it refines the frequency and amplitude of a peak lying between FFT bins, for example by quadratic interpolation; across time it generates intermediate spectra between two analysis frames, as used in spectral morphing and additive resynthesis.", "plain_english": "An FFT measures a spectrum only at fixed, evenly spaced points. A real peak often sits between two of them. Spectral interpolation estimates the true value in that gap. It can also blend two spectra to make in-between ones.", "purpose_function": "It exists to recover detail that the fixed spacing of a spectrum would otherwise hide, giving more accurate peak frequencies and smoother transitions. This improves both measurement precision and spectral morphing.", "practical_application": "An analysis tool uses quadratic interpolation around a bin peak to report a tone's frequency more precisely than the raw bin spacing allows.", "category": "Spectral Analysis", "related_terms": ["Spectral bin", "FFT", "Frequency resolution", "Spectral resynthesis", "Windowing", "Zero-padding"], "common_mistakes": ["Assuming a peak sits exactly on a bin center, which overstates the frequency accuracy.", "Confusing interpolation with true added resolution, when it only estimates between existing data points.", "Interpolating across noisy bins, where the estimate becomes unreliable."], "scenario_contexts": ["Reporting a tone's exact frequency from an FFT with coarse bin spacing.", "Blending between two spectra to morph one sound into another.", "Smoothing a spectral display drawn from a low-resolution FFT."]}, "d9f42bee-5fe6-4e5b-935a-3072b249b084": {"definition": "An operation that reverses or complements a signal's frequency spectrum. In FIR filter design it forms the complementary filter - turning a low-pass kernel into a high-pass one - by negating every sample of the impulse response and adding one to the center sample. In frequency-conversion and scrambling contexts it denotes a mirror flip of the spectrum about a center frequency, so low frequencies map to high and vice versa.", "plain_english": "Spectral inversion flips a sound's frequency content. In filter design it turns a low-pass filter into a high-pass one. In radio and scrambling it mirrors the spectrum, so low tones become high and high become low. Either way, the frequency picture is turned around.", "purpose_function": "It exists to derive one filter cheaply from its opposite, or to flip a spectrum for frequency conversion or simple scrambling. This saves design effort and enables useful spectrum manipulation.", "practical_application": "A technician builds a high-pass FIR filter by taking a finished low-pass kernel, inverting it, and adding one to the center tap, avoiding a separate design step.", "category": "Spectral Processing", "related_terms": ["FIR filter", "Impulse response", "High-pass filter", "Frequency inversion", "Spectral rotation", "Polarity"], "common_mistakes": ["Confusing spectral inversion with polarity inversion, which only flips the sign of the whole signal.", "Applying the filter-complement trick to a kernel that is not symmetric or linear phase, giving wrong results.", "Assuming the two senses are identical, when one is a filter trick and the other a spectrum flip."], "scenario_contexts": ["Creating a high-pass filter from an existing low-pass design.", "Flipping a spectrum in a frequency-inversion voice scrambler.", "Correcting an inverted spectrum after a frequency down-conversion."]}, "cb1af455-b47f-4833-8c1e-8f30dad007fd": {"definition": "The process of adjusting the spectrum of one signal, usually with equalization or filtering, so its long-term frequency balance approaches that of a chosen reference. Analysis software measures the average spectra of both target and reference, then derives a corrective curve that moves the target toward the reference.", "plain_english": "Spectral matching makes one sound's tonal balance copy another's. Software measures the average frequency shape of a reference. Then it builds an EQ curve to move your sound toward it. It is like tracing a target's tone with your own track.", "purpose_function": "It exists to give an engineer a measured starting point for tonal balance, based on a trusted reference, rather than guessing by ear alone. This speeds up matching mixes, masters, or dialogue.", "practical_application": "A mastering engineer loads a reference into a matching equalizer, captures its spectrum, and applies the generated curve to bring a new master closer to that tonal balance.", "category": "Spectral Processing", "related_terms": ["Match EQ", "Spectral balance", "Equalization", "Reference track", "Tonal balance", "Spectral imprinting"], "common_mistakes": ["Treating the matched curve as final, when it usually needs trimming to avoid harsh or hollow results.", "Matching to a poor or unsuitable reference, which drags the mix in the wrong direction.", "Expecting matching to fix level, dynamics, or arrangement, when it only addresses frequency balance."], "scenario_contexts": ["Bringing a master closer to the tonal balance of a commercial reference.", "Matching the tone of two microphones on the same source.", "Aligning dialogue tone between scenes recorded in different rooms."]}, "d826e182-59a9-46b3-8e32-6af330e510ce": {"definition": "The reconstruction of an audio signal from an analyzed spectral representation, converting frequency-domain data back into a time-domain waveform. It is the synthesis stage of analysis-resynthesis systems such as the phase vocoder and sinusoidal (additive) models, in which a sound is decomposed into spectral components, optionally modified, and then rebuilt.", "plain_english": "Spectral resynthesis rebuilds a sound from its frequency description. First a tool breaks the sound into its frequency parts. You can change those parts if you want. Then it puts them back together into audio you can hear.", "purpose_function": "It exists to turn analyzed or edited spectral data back into audible sound, closing the analysis-modification-synthesis loop. This lets engineers stretch, pitch-shift, or morph sounds by editing the spectrum first.", "practical_application": "An engineer time-stretches a vocal by analyzing it with a phase vocoder, editing the spectral frames, then resynthesizing the audio at a new length.", "category": "Spectral Processing", "related_terms": ["Phase vocoder", "Additive synthesis", "Spectral analysis", "Short-time Fourier transform (STFT)", "Overlap-add", "Spectral interpolation"], "common_mistakes": ["Expecting perfect reconstruction, when windowing and phase handling can add smearing or artifacts.", "Ignoring phase, so resynthesized transients smear or lose their punch.", "Confusing resynthesis with simple playback, when it actively rebuilds the signal from spectral data."], "scenario_contexts": ["Time-stretching audio without changing its pitch.", "Pitch-shifting a sound by editing its spectrum before rebuilding it.", "Morphing between two sounds by resynthesizing blended spectra."]}, "53dc0f7d-2595-4cfc-ad60-d2183b7a3db9": {"definition": "A spectral descriptor giving the frequency below which a specified fraction of the total spectral energy (or magnitude) is contained - commonly 85% or 95%. It summarizes where a spectrum's energy is concentrated and rises with the amount of high-frequency content, correlating with perceived brightness.", "plain_english": "Spectral rolloff is the frequency under which most of a sound's energy sits. You pick a share, such as 85 percent. The rolloff is the frequency that holds that much energy below it. Brighter sounds push this frequency higher.", "purpose_function": "It exists to give a single number describing how high in frequency a sound's energy reaches, useful for comparing timbres. Automated systems use it to tell bright sounds from dull ones.", "practical_application": "An audio-analysis or classification tool computes spectral rolloff for each frame to help separate bright, cymbal-heavy passages from darker, bass-heavy ones.", "category": "Spectral Analysis", "related_terms": ["Spectral centroid", "Spectral bandwidth", "Brightness", "Feature extraction", "Spectral analysis", "FFT"], "common_mistakes": ["Assuming one fixed percentage, when the threshold such as 85% or 95% must be stated to compare values.", "Confusing the spectral-rolloff feature with a filter's rolloff slope, which are different ideas.", "Comparing rolloff values computed with different thresholds as if they matched."], "scenario_contexts": ["Describing the brightness of a sound for a machine-learning classifier.", "Comparing the high-frequency reach of two instruments.", "Tracking how bright a mix is over time as a spectral feature."]}, "d52c635a-f5b7-4aa5-843d-de2ecc872f4d": {"definition": "An operation that flips a signal's spectrum about a center frequency, reversing the frequency ordering so the highest frequencies in the rotation band become the lowest and vice versa. Applied to speech it yields spectrally rotated speech that is largely unintelligible yet keeps overall spectral complexity, and the same principle underlies simple frequency-inversion scrambling.", "plain_english": "Spectral rotation turns a sound's frequencies upside down around a middle point. High tones become low and low tones become high. Speech treated this way sounds garbled but still busy. It has been used for scrambling and for hearing research.", "purpose_function": "It exists to reorder a spectrum in a controlled way, either to hide speech content or to build research signals that keep spectral richness while removing meaning. This makes it useful for scrambling and perception studies.", "practical_application": "A researcher rotates the speech spectrum about a fixed center frequency to create an unintelligible control signal that still carries speech-like spectral detail.", "category": "Spectral Processing", "related_terms": ["Spectral inversion", "Frequency inversion", "Center frequency", "Scrambling", "Spectral shifting", "Spectrum"], "common_mistakes": ["Confusing spectral rotation with pitch shifting, when rotation reverses the frequency order rather than moving pitch by a ratio.", "Assuming rotated speech is fully random, when it keeps much of the original spectral structure.", "Using the wrong rotation center frequency, which changes how the spectrum maps."], "scenario_contexts": ["Creating unintelligible but spectrally rich speech for a listening experiment.", "Scrambling a voice channel with frequency inversion.", "Studying how listeners adapt to a spectrally reordered voice."]}, "746d64d1-ca2e-4c6e-8a97-997a3cc78756": {"definition": "The translation of every frequency component of a signal upward or downward by a fixed number of hertz, a linear frequency shift produced by single-sideband modulation. Because it adds a constant offset rather than multiplying by a ratio, it breaks the harmonic relationships between partials, giving inharmonic, metallic, or clangorous timbres, unlike pitch shifting.", "plain_english": "Spectral shifting moves every frequency in a sound up or down by the same number of hertz. It does not keep the pitch relationships, so it differs from pitch shifting. Harmonics stop lining up neatly. The result often sounds metallic or bell-like.", "purpose_function": "It exists to move a whole spectrum by a fixed frequency offset, which detunes the natural harmonic spacing. Engineers use this to create inharmonic textures or to nudge a signal away from feedback frequencies.", "practical_application": "A sound designer applies a frequency shifter to a synth pad, offsetting the spectrum by a few hertz to add slow beating and a metallic character.", "category": "Spectral Processing", "related_terms": ["Frequency shifter", "Pitch shifting", "Single-sideband modulation", "Ring modulation", "Harmonics", "Spectral rotation"], "common_mistakes": ["Confusing frequency shifting with pitch shifting, when shifting adds a fixed hertz offset and breaks harmony.", "Expecting a shifted harmonic sound to stay musical, when the partials no longer form a harmonic series.", "Assuming small shifts are inaudible, when even a few hertz create noticeable beating."], "scenario_contexts": ["Adding metallic, inharmonic character to a synth or drum sound.", "Nudging a signal's frequencies slightly to reduce feedback in a sound system.", "Creating slow beating or phasing textures in sound design."]}, "ba9228bf-5bcb-4fe2-a650-90c1102829b9": {"definition": "Spectral smearing is the spreading of a signal's energy across neighbouring frequency bins in a spectral (FFT/DFT) analysis, so that energy truly belonging to one frequency appears blurred over a band of frequencies. It results from analysing a finite-length block of signal (equivalently, applying a window), which limits frequency resolution and, through spectral leakage, broadens each component into a widened peak with side lobes.", "plain_english": "Spectral smearing is when a frequency analyzer blurs a sound's tones together. It happens because the tool looks at only a short slice of sound. A short slice cannot pin down pitch exactly. So one clean tone shows up as a fuzzy bump, not a sharp spike.", "purpose_function": "The term names a basic limit of spectral analysis: a finite analysis window trades time resolution against frequency resolution, so energy smears. Knowing this lets engineers read spectrum and spectrogram displays correctly instead of trusting every blurred peak.", "practical_application": "When reading an FFT analyzer or spectrogram, a technician picks a longer analysis block or a suitable window to cut smearing and separate close frequencies, accepting slower time response in return.", "category": "Spectral analysis", "related_terms": ["Spectral leakage", "Window function", "Fast Fourier transform (FFT)", "Frequency resolution", "Spectrogram", "Real-time analyzer (RTA)"], "common_mistakes": ["Reading a smeared, widened peak as a real spread of frequencies in the source, when it is an artifact of the finite analysis window.", "Expecting a short analysis block to separate two close tones, when its coarse frequency resolution smears them into one.", "Assuming zero-padding improves true frequency resolution and removes smearing, when it only interpolates the display.", "Blaming smearing on a noisy or detuned source rather than on the analysis settings."], "scenario_contexts": ["Interpreting a spectrogram where two close harmonics blur into a single band.", "Choosing FFT size and window on an analyzer to separate nearby frequencies while tuning a system.", "Diagnosing why a steady sine appears as a broadened peak rather than a thin line on a spectrum display."]}, "6d5cbdbf-5115-4d8d-95f7-888f6aab14c3": {"definition": "Spectral stretching is a frequency-domain operation that scales a signal's spectrum along the frequency axis, multiplying the frequencies of its components by a common factor so the whole spectrum is expanded (or compressed) in frequency. It is used in spectral and phase-vocoder processing for pitch shifting and formant manipulation, since stretching the spectrum upward raises perceived pitch and carries the spectral envelope (formants) with it unless they are separately preserved.", "plain_english": "Spectral stretching spreads a sound's frequencies apart along the pitch scale. Multiply every frequency by the same amount and the whole tone moves higher. Software uses this trick to shift pitch. Stretch too far and voices can start to sound thin or unnatural.", "purpose_function": "It gives a way to change pitch and reshape tone by scaling frequency content directly in the spectrum, rather than by resampling in time. This lets pitch and duration be altered on their own in modern audio tools.", "practical_application": "An engineer uses a phase-vocoder or spectral-processing plug-in that stretches the spectrum to pitch-shift a recording, optionally preserving formants to keep vocals sounding natural.", "category": "Spectral processing", "related_terms": ["Phase vocoder", "Pitch shifting", "Time stretching", "Formant", "Spectral envelope", "Fourier analysis"], "common_mistakes": ["Confusing spectral stretching with time stretching, when one scales frequency and the other scales duration.", "Stretching the spectrum without preserving formants, which shifts vocal formants and gives an unnatural 'chipmunk' or 'monster' sound.", "Assuming spectral stretching adds no artifacts, when large factors smear transients and alter timbre."], "scenario_contexts": ["Pitch-shifting a vocal in a DAW while keeping its formants natural.", "Transposing a sampled instrument by scaling its spectrum in a spectral editor.", "Creating special effects with exaggerated stretching of a sound's spectrum."]}, "ef1e490d-2b8f-415d-bd62-c498deef6755": {"definition": "Spectral subtraction is a single-channel noise-reduction technique that estimates the magnitude spectrum of the background noise (typically from pauses or non-signal segments) and subtracts it, band by band, from the magnitude spectrum of the noisy signal, then reconstructs the output using the original phase. Introduced for speech enhancement, it reduces steady broadband noise but can leave a fluctuating 'musical noise' artifact when bands are over-subtracted.", "plain_english": "Spectral subtraction removes steady background noise, like hiss or hum. First it learns the noise from a quiet gap in the recording. Then it takes that noise away from every part of the sound. Push it too hard and it leaves odd, bubbly artifacts.", "purpose_function": "It exists to clean up recordings by removing a measured, roughly steady noise from the signal band by band. This improves the clarity and intelligibility of speech and other wanted sound.", "practical_application": "An engineer captures a noise profile from a silent section, then applies a spectral (broadband) noise-reduction tool that subtracts that profile from a dialogue or music recording.", "category": "Noise reduction", "related_terms": ["Noise profile", "Broadband noise reduction", "Musical noise", "Fast Fourier transform (FFT)", "Noise floor", "Signal-to-noise ratio (SNR)"], "common_mistakes": ["Over-subtracting the noise, which creates warbling 'musical noise' and a hollow sound.", "Capturing the noise profile from a section that also contains wanted signal, so real sound is removed.", "Expecting spectral subtraction to remove sudden or moving noises well, when it works best on steady broadband noise."], "scenario_contexts": ["Removing steady air-conditioning hiss from a location dialogue recording.", "Cleaning tape hiss from an archival music transfer.", "Reducing constant background hum before further restoration work."]}, "eb702d5e-5cdd-44cc-96cf-4bd5c0768449": {"definition": "An SPL limit (compliance) is a maximum sound pressure level that a venue, event, or workplace must not exceed to satisfy occupational-safety or local licensing/environmental noise rules, usually set as a time-averaged level (for example an LAeq over a defined period) and often paired with a peak limit such as LCpeak. Occupational limits protect workers' hearing (OSHA sets a 90 dBA 8-hour time-weighted-average permissible exposure limit with an 85 dBA action level), while entertainment-venue limits commonly cluster around 100 dB LAeq, in line with the WHO Global Standard for Safe Listening Venues and Events, which recommends 100 dB LAeq averaged over 15 minutes with a 140 dB LCpeak limit, with C-weighted peak caps in the 130-140 dB range.", "plain_english": "An SPL limit is the loudest a show or workplace is allowed to get. Rules set it to protect people's hearing. It is usually an average level over time, plus a cap on sudden peaks. Going over it can break the law and harm ears.", "purpose_function": "It exists to cap sound exposure at a level that protects hearing and meets legal or licensing rules. A clear maximum lets engineers, venues, and inspectors agree on what is safe and allowed.", "practical_application": "A front-of-house engineer watches a calibrated SPL meter against the venue's LAeq and peak limits, trimming system level so the show stays compliant across the required time window.", "category": "Noise exposure", "related_terms": ["LAeq", "Sound Exposure / Dose", "A-weighting", "C-weighting", "Sound level meter", "SPL management"], "common_mistakes": ["UNSAFE: Treating an average (LAeq) limit as met while ignoring the separate peak limit, letting dangerous transient peaks through.", "UNSAFE: Assuming that staying under a legal SPL limit guarantees no hearing damage, when long exposure even below the limit still carries risk.", "Measuring with the wrong weighting or time window (for example A-weighted when a C-weighted peak is specified), giving a false compliance reading.", "Placing the measurement microphone away from the specified position, so the reading does not reflect the regulated level."], "scenario_contexts": ["Keeping a concert within a city noise ordinance's LAeq and LCpeak limits.", "Meeting an occupational limit to protect stage and crew hearing over a long shift.", "Documenting sound levels to prove compliance to a licensing authority after an event."]}, "1daf44dd-5666-43e5-bbfb-0523095629b7": {"definition": "SPL management is the ongoing practice of measuring, monitoring, and controlling sound pressure levels during an event or in a workplace so that exposure stays within safe and compliant limits. It combines calibrated measurement (SPL meters or dosimeters reading levels such as LAeq and LCpeak), system design and tuning, real-time monitoring at front-of-house, and level decisions, together with documentation, to protect hearing and meet occupational or licensing requirements.", "plain_english": "SPL management means keeping a show's loudness under control on purpose. Engineers measure the sound level all night with a meter. They lower the system if it climbs too high. The goal is to protect hearing and stay within the rules.", "purpose_function": "It exists to keep sound at a level that is both safe for hearing and legal, by watching real levels instead of guessing. This protects audiences, performers, and crew and keeps a venue within its permit.", "practical_application": "An engineer sets up a calibrated SPL meter at front-of-house, logs LAeq and peak levels through the show, and adjusts system gain or limiting to hold within the venue's targets.", "category": "Noise exposure", "related_terms": ["SPL limit (compliance)", "LAeq", "Sound Exposure / Dose", "Noise dosimeter", "Sound level meter", "Hearing protection"], "common_mistakes": ["UNSAFE: Managing peak SPL alone while ignoring cumulative dose over the whole event, leaving long exposures unmanaged.", "UNSAFE: Relying on ear judgement instead of a calibrated meter, since ears adapt and underestimate loudness over time.", "Using an uncalibrated meter or wrong settings (weighting, time constant), giving readings that do not match the standard.", "Measuring at only one position and assuming the level is the same across the whole audience."], "scenario_contexts": ["Monitoring and trimming levels through a festival set to meet a site noise limit.", "Running a house SPL policy in a club to protect staff and patrons.", "Logging levels across a shift so exposure can be checked against occupational limits."]}, "41cd6178-3523-47cc-8ec5-221259e5fc55": {"definition": "SPL range is the span of sound pressure levels between a defined lowest and highest level of interest, expressed in decibels. In metering it refers to the range of levels a sound level meter can measure linearly, bounded below by its self-noise and above by overload as specified under IEC 61672; more generally it describes the spread from the quietest to the loudest sound in an environment or programme, from the ambient noise floor up to peak levels.", "plain_english": "SPL range is the gap between the softest and loudest sounds you care about. For a sound meter, it is the span of levels it can read correctly. In a room, it is the distance from the quiet background up to the loudest peak. A bigger range means more contrast.", "purpose_function": "It tells you the span of levels a measurement covers or that a situation contains, so you can pick a meter that will not run out of range or overload. It also frames how much contrast exists between soft and loud sound.", "practical_application": "A technician checks that a sound level meter's operating range covers the expected levels, then uses it to capture both the quiet noise floor and the loud peaks without under-reading or overloading.", "category": "SPL measurement", "related_terms": ["Sound pressure level (SPL)", "Sound level meter", "Dynamic range", "Noise floor", "Peak level", "A-weighting"], "common_mistakes": ["Confusing a meter's measurement range with the dynamic range of the sound itself.", "Choosing a meter or range setting that overloads on peaks or buries quiet sound in its self-noise.", "Assuming one range setting suits every situation, when very quiet and very loud scenes need different handling."], "scenario_contexts": ["Selecting a sound level meter whose range covers both a quiet room and a loud PA.", "Setting the range on a metering system before capturing a wide-dynamics performance.", "Describing the span from noise floor to peak SPL in a venue survey."]}, "33d3a44d-52ad-492d-8674-a1a9a3e75dbf": {"definition": "Stereo balance is the relative distribution of signal level between the left and right channels of a stereo signal, determining whether the overall energy and image sit centred or lean to one side. It is adjusted with a balance control, which changes the relative level of the two existing channels, and is assessed on level meters and on a correlation/vectorscope display; a well-balanced mix carries comparable long-term energy in both channels.", "plain_english": "Stereo balance is how evenly sound is shared between the left and right speakers. If both sides are equal, the sound feels centred. If one side is louder, the sound pulls that way. Engineers check meters to keep the two sides even.", "purpose_function": "It describes and controls left-right level distribution so a mix sits where it should and neither speaker dominates. Keeping balance even avoids a lopsided image and uneven loudness across the room.", "practical_application": "An engineer watches left and right meters, and a balance or correlation display, then uses the balance control to correct a mix that leans to one side.", "category": "Stereo imaging", "related_terms": ["Stereo field", "Panning", "Vectorscope", "Correlation meter", "Balance control", "Stereo image"], "common_mistakes": ["Confusing a balance control (which trims the level of the two existing channels) with a pan control (which places a mono source in the field).", "Judging balance from one speaker or an off-centre seat, giving a false impression.", "Assuming equal meter readings guarantee a centred image, when timing and phase differences also shift perceived position."], "scenario_contexts": ["Correcting a mix that sounds heavier on the left using meters and a balance control.", "Checking left-right energy on a vectorscope during mastering.", "Setting up a listening position so left and right arrive evenly before judging balance."]}, "36e8ea5f-3342-4164-ab54-67462804ffc5": {"definition": "Stereo depth is the perceived front-to-back dimension of a stereo image, the sense that some sources sit closer to the listener while others sit further back. It is not encoded directly like left-right position but is created by distance cues such as relative level, the ratio of direct to reverberant sound, early-reflection and pre-delay patterns, and high-frequency roll-off.", "plain_english": "Stereo depth is how near or far sounds seem in a mix. Some parts feel up close, others feel far behind them. Engineers create this with volume, reverb, and echo. More reverb and less treble make a sound feel further away.", "purpose_function": "It gives a mix a sense of distance and layering, so instruments do not all sound stuck on one flat line. This adds realism and helps separate parts front to back.", "practical_application": "An engineer uses level, reverb amount, pre-delay, and gentle high-frequency roll-off to push some sources back and pull others forward, building depth in a mix.", "category": "Stereo imaging", "related_terms": ["Stereo field", "Reverberation", "Pre-delay", "Direct-to-reverberant ratio", "Stereo image", "Panning"], "common_mistakes": ["Confusing depth (front-to-back distance) with width (left-right spread).", "Adding reverb to everything, which pushes the whole mix back and flattens depth instead of layering it.", "Ignoring level and high-frequency cues, so sources meant to sit far away still sound close."], "scenario_contexts": ["Placing a lead vocal up front and pads further back to create depth.", "Using reverb and pre-delay to set how distant a drum room sounds.", "Layering instruments front to back so a dense mix stays clear."]}, "3b3cdbca-0062-4222-85aa-13d87e208b9c": {"definition": "The stereo field is the perceived spatial area, spanning from the left channel through the centre to the right channel, within which sources in a two-channel stereo signal are positioned. Its horizontal extent (width) is set by inter-channel level and time differences and by panning; it is the space a mix engineer works within to place and spread sounds, and it is assessed by ear and on tools such as a vectorscope or goniometer.", "plain_english": "The stereo field is the space between the left and right speakers where sounds seem to sit. Panning moves a sound left, right, or centre inside it. A good mix spreads sounds across this space so they do not pile up. It is like arranging players across a stage.", "purpose_function": "It is the spatial canvas of a stereo mix, letting sources be separated left to right so each is easier to hear. Spreading parts across the field reduces clutter and adds a sense of space.", "practical_application": "An engineer pans and balances tracks across the stereo field, checking it on a vectorscope, to place instruments and keep a mix wide but mono-compatible.", "category": "Stereo imaging", "related_terms": ["Panning", "Stereo balance", "Stereo width", "Vectorscope", "Stereo image", "Mono compatibility"], "common_mistakes": ["Panning everything to the centre, wasting the field and crowding the mix.", "Over-widening the field so the mix collapses or loses key parts when summed to mono.", "Confusing the stereo field (left-right space) with depth (front-to-back distance)."], "scenario_contexts": ["Panning a drum kit across the stereo field for a natural spread.", "Checking a wide mix on a vectorscope for mono compatibility.", "Arranging instruments left to right so a busy mix stays clear."]}, "b892c2a6-d46c-4316-a772-4d9572fca7ab": {"definition": "A stereo vectorscope (also called a goniometer) is a metering display that plots the left and right channels of a stereo signal against each other as a real-time Lissajous figure, conventionally on axes rotated 45 degrees so an in-phase mono signal appears as a vertical line. It visualises stereo width, channel balance, and the phase/polarity relationship between the two channels, showing mono-compatibility problems as the trace collapses toward a horizontal line.", "plain_english": "A stereo vectorscope draws a live picture of how the left and right channels relate. A center (mono) sound makes a straight up-and-down line. A wide stereo sound fills the screen like a fuzzy ball. A flat, side-to-side line warns that the two channels fight each other.", "purpose_function": "It exists to let an engineer see stereo width and phase at a glance, so they can catch out-of-polarity or mono-incompatible signals that level meters alone would miss.", "practical_application": "A broadcast or mastering engineer watches the vectorscope to confirm a mix stays mono-compatible and to spot a miswired or polarity-flipped channel before it goes to air.", "category": "Metering display", "related_terms": ["Goniometer", "Phase correlation meter", "Lissajous figure", "Mono compatibility", "Peak program meter (PPM)", "Stereo imaging"], "common_mistakes": ["Assuming a narrow, near-vertical display is a fault, when it simply shows a mostly mono or centered signal.", "Confusing the vectorscope with a phase (correlation) meter; the vectorscope shows a shape while the correlation meter shows one numerical value.", "Ignoring a horizontal-tending trace, which warns of polarity inversion and serious loss of mono compatibility.", "Reading absolute loudness from the display, when most vectorscopes auto-scale gain and show relationship, not level."], "scenario_contexts": ["Checking mono compatibility of a stereo mix before broadcast.", "Diagnosing a channel with reversed polarity on a stereo feed.", "Judging stereo width while mastering a track.", "Verifying a stereo microphone pair is wired and phased correctly."]}, "0503c83b-26fe-411e-b9c3-699bb76cf7c3": {"definition": "Sub alignment is the process of time-, level-, and polarity-matching a subwoofer system to the main loudspeakers so their outputs sum coherently through the crossover overlap region. It is typically performed with a dual-channel FFT (transfer-function) analyzer, adjusting relative delay and polarity so the combined magnitude response is maximised and phase cancellation at the crossover is minimised.", "plain_english": "Subs and main speakers overlap in the low range. If their timing or polarity is off, the bass can cancel out and get weak. Sub alignment lines them up in time and polarity so the bass adds together instead of fighting. Engineers use a measurement mic and analyzer to get it right.", "purpose_function": "It exists to make the subs and mains behave as one system through their shared frequency range, preventing the deep response dip that misaligned low end causes.", "practical_application": "A system tech measures mains and subs with a dual-FFT tool such as Smaart, then adjusts sub delay and polarity until the two traces overlap and sum at the crossover.", "category": "System tuning", "related_terms": ["Crossover", "Transfer function measurement", "Polarity", "Time alignment", "Phase", "System optimization"], "common_mistakes": ["Setting sub delay by ear alone rather than by measurement, and locking in a cancellation.", "Forgetting to check polarity, so an inverted sub cancels the mains at the crossover.", "Aligning at one mic position and assuming it holds everywhere, ignoring how the overlap shifts across the room.", "Confusing level matching with time alignment; both must be set, not just one."], "scenario_contexts": ["Tuning a concert PA so subs and mains sum at the crossover.", "Setting sub delay relative to the main hangs before a show.", "Correcting a weak-bass complaint traced to sub/main cancellation.", "Integrating cardioid or end-fire sub arrays with the main system."]}, "b0b19aef-00ad-4bce-ae16-21364d4f946d": {"definition": "A system limiter setting is the configured threshold, attack, and release of the limiter(s) in a loudspeaker management system or amplifier DSP, chosen to keep signal levels within the safe voltage, excursion, and power limits of the drivers and amplifier. Correct values are derived from the manufacturer's driver power ratings and the amplifier gain, so the limiter engages before the system reaches damaging excursion, clipping, or thermal levels.", "plain_english": "A limiter sets a ceiling on how hard the signal can push a speaker. The system limiter setting is where that ceiling sits. Set right, it stops the amp and driver from being pushed past their safe limits. The numbers come from the maker's ratings, not from guessing.", "purpose_function": "It exists to protect drivers and amplifiers from over-excursion, clipping, and overheating by capping level before damage occurs, while still letting the system run as loud as it safely can.", "practical_application": "A system engineer enters the manufacturer's recommended peak and RMS limiter thresholds and time constants into the processor for each amplifier and driver combination during setup.", "category": "System tuning", "related_terms": ["Peak limiter", "RMS/thermal limiter", "Loudspeaker management system", "System processor", "Threshold", "Amplifier gain structure"], "common_mistakes": ["UNSAFE: Disabling or raising system limiters to gain more level, which exposes drivers and amps to damaging peaks and heat.", "UNSAFE: Copying limiter settings from a different amplifier or driver, since thresholds depend on the specific amp gain and driver ratings.", "Setting only a peak limiter and omitting the RMS/thermal limiter, leaving the voice coil unprotected from heat.", "Treating the limiter as a tone or loudness tool rather than a protection device."], "scenario_contexts": ["Configuring amplifier DSP limiters from a speaker maker's tuning file before a show.", "Protecting rental PA drivers that will be driven hard by inexperienced operators.", "Resetting thresholds after a gain-structure change in the signal chain.", "Loading a manufacturer preset that includes limiter thresholds for a matched amp/speaker pair."]}, "2656046c-421c-4896-879a-eef8d8d2dbb7": {"definition": "System optimization is the measurement-based process of adjusting a sound reinforcement system's level, delay, polarity, equalization, crossover, and limiter settings so its response at the audience meets the design targets. It is typically carried out with a dual-channel FFT analyzer, comparing the system's output to its input (transfer function) to guide corrections for coverage, spectral balance, and subsystem summation.", "plain_english": "System optimization means measuring a sound system and tuning it. The goal is for the audience to hear it the way it was designed. Engineers use a measurement mic and analyzer to check level, timing, and tone across the seats. Then they adjust EQ, delays, and levels to fix problems. The aim is even, clear sound everywhere.", "purpose_function": "It exists to turn a deployed system into one that delivers consistent coverage and tonal balance for the whole audience, not just at the mix position.", "practical_application": "A system engineer runs transfer-function measurements at several audience positions and sets delays, EQ, and levels to align subsystems and even out the response.", "category": "System tuning", "related_terms": ["Transfer function measurement", "Sub alignment", "System processor", "Equalization", "Time alignment", "Coverage"], "common_mistakes": ["Optimizing only at the mix position and ignoring the rest of the audience area.", "Using EQ to fix problems that are actually caused by timing or summation errors between subsystems.", "Trusting a single measurement without spatial averaging or checking multiple mic positions.", "Chasing a perfectly flat trace instead of a natural target response curve."], "scenario_contexts": ["Tuning a festival PA before doors using Smaart.", "Commissioning a fixed install in a theatre or house of worship.", "Aligning delay speakers to the main system for even coverage.", "Setting a house target curve across an arena's seating."]}, "6e8d2a4d-3509-4a9d-9bc4-1acfbda79deb": {"definition": "A system processor (loudspeaker management system or loudspeaker controller) is a dedicated DSP unit placed between the mixing console and the amplifiers that provides crossover filtering, equalization, delay, gain, polarity, and limiting for each loudspeaker output. It centralises a sound system's tuning and driver-protection functions in one device, replacing racks of separate analog crossovers, EQs, and limiters.", "plain_english": "A system processor is the control box between the mixer and the amplifiers. It splits the sound into the right frequency bands for each speaker. It also sets timing, tone, and volume, and protects the speakers with limiters. One unit handles the tuning and safety for the whole rig.", "purpose_function": "It exists to combine crossover, EQ, delay, and limiting in one place so a system can be tuned and protected consistently and recalled from stored presets.", "practical_application": "A tech loads or builds presets in the system processor for each speaker type, setting crossovers, delays, and limiters before patching the outputs to the amplifiers.", "category": "Processing hardware", "related_terms": ["Loudspeaker management system", "Crossover", "System limiter setting", "Delay", "Equalization", "Digital signal processing (DSP)"], "common_mistakes": ["Confusing the system processor with the mixing console; it sits after the console and feeds the amps.", "UNSAFE: Bypassing the processor's limiters or crossovers and sending full-range signal to a driver, risking driver damage.", "Loading a preset built for a different speaker model and assuming it protects the current one.", "Forgetting that output delay and polarity set in the processor affect overall system alignment."], "scenario_contexts": ["Patching a line-array system through its controller before the amps.", "Loading manufacturer presets for a matched speaker and amplifier system.", "Adding delay to a front-fill speaker within the processor.", "Storing tuning settings as a recallable preset for a touring rig."]}, "a373bd44-e791-4291-bccd-cad26c8b2f97": {"definition": "The temperature/humidity effect is the influence of air temperature and relative humidity on sound propagation, and therefore on acoustic measurements and system tuning. Temperature sets the speed of sound (approximately 331.4 m/s at 0 degrees C, rising about 0.6 m/s per degree C), which shifts propagation delay, while humidity strongly governs atmospheric absorption of high frequencies over distance, as standardised in ISO 9613-1.", "plain_english": "Sound travels a little faster when the air is warmer. Over an outdoor show, a temperature change shifts the timing between speakers. The air also soaks up high frequencies as sound travels, and how much depends on humidity. So the same system can sound and measure differently as the weather changes.", "purpose_function": "Understanding it lets engineers predict and correct how delay times and high-frequency response drift with changing weather, keeping alignment and tone stable over a long event.", "practical_application": "An engineer re-checks delay-speaker alignment and high-frequency EQ when the temperature drops after sunset at an outdoor show, because the speed of sound and air absorption have shifted.", "category": "Measurement fundamentals", "related_terms": ["Speed of sound", "Time alignment", "Atmospheric absorption", "Delay", "Transfer function measurement", "System optimization"], "common_mistakes": ["Assuming a morning delay alignment still holds for an evening show after the temperature has dropped.", "Blaming a system for losing high end over distance when air absorption and humidity are the cause.", "Treating the speed of sound as a fixed number when setting delays outdoors.", "Ignoring that a measurement mic and analyzer read the current air conditions, which change through the day."], "scenario_contexts": ["Re-aligning delay towers at an outdoor festival as evening cools the air.", "Explaining lost high frequencies at the back of a large outdoor audience.", "Setting delay times that depend on the speed of sound on a hot day.", "Interpreting transfer-function traces that drift as temperature and humidity change."]}, "1ae4d1a9-00af-4674-9aa2-154a46c29bc6": {"definition": "Time Weighting Fast (F) is a standardised exponential time-averaging characteristic used in sound level meters, defined in IEC 61672-1 with a nominal time constant of 125 ms. Its short time constant makes the meter respond quickly to rapid level changes, giving a reading (LAF) that tracks fluctuating sound more closely than the Slow weighting.", "plain_english": "Fast time weighting controls how quickly a sound level meter reacts. It uses a short averaging time of 125 milliseconds. That makes the needle or number jump quickly to follow changing sound. It is useful when you need to catch sounds that come and go fast.", "purpose_function": "It exists to give a standardised, repeatable way for meters to respond quickly to changing levels, so readings can be compared between instruments and against limits.", "practical_application": "A technician selects Fast (F) weighting on a sound level meter when checking short, changing sounds and reads the fast-weighted level, often shown as LAF or dB(A) Fast.", "category": "Measurement fundamentals", "related_terms": ["Time Weighting Slow", "Sound level meter", "A-weighting", "IEC 61672", "Equivalent continuous level (Leq)", "Sound pressure level (SPL)"], "common_mistakes": ["Confusing time weighting (how fast the meter responds) with frequency weighting such as A or C.", "Comparing Fast and Slow readings of the same source as if they should match exactly.", "Assuming Fast weighting captures true instantaneous peaks; peak hold, not Fast, is used for that.", "Forgetting to report the weighting used, so a level cannot be reproduced or compared."], "scenario_contexts": ["Measuring fluctuating traffic or crowd noise where the level changes quickly.", "Setting a meter to Fast when a regulation or method specifies F weighting.", "Reading LAF max on a sound level meter during a spot check.", "Teaching students the difference between Fast and Slow meter response."]}, "f5323f24-970a-42a8-bc43-b8a175074f61": {"definition": "Time Weighting Slow (S) is a standardised exponential time-averaging characteristic used in sound level meters, defined in IEC 61672-1 with a nominal time constant of 1 s. Its longer time constant heavily smooths the reading (LAS), so the meter responds gradually and gives a steadier value that is easier to read on fluctuating sound.", "plain_english": "Slow time weighting also controls how fast a sound level meter reacts. But it averages over a longer time of 1 second. That makes the reading move slowly and stay steady. It is easier to read when the sound keeps changing. You lose the quick detail that Fast weighting shows.", "purpose_function": "It exists to give a standardised, steady reading of fluctuating sound, making levels easier to read and compare between instruments and against limits.", "practical_application": "A technician selects Slow (S) weighting to get a stable dB(A) reading of a varying source, or when a standard or regulation specifies S weighting.", "category": "Measurement fundamentals", "related_terms": ["Time Weighting Fast", "Sound level meter", "A-weighting", "IEC 61672", "Equivalent continuous level (Leq)", "Sound pressure level (SPL)"], "common_mistakes": ["Confusing time weighting (how fast the meter responds) with frequency weighting such as A or C.", "Expecting Slow readings to match Fast readings of the same fluctuating source.", "Assuming Slow weighting captures peaks; its long averaging actually hides short transients.", "Failing to record that Slow was used, so the measurement cannot be reproduced."], "scenario_contexts": ["Reading a steady dB(A) Slow value for an environmental or workplace noise check.", "Selecting Slow when a measurement standard or regulation specifies S weighting.", "Getting a stable meter reading of a source that fluctuates too fast to read on Fast.", "Teaching students how averaging time changes what a meter shows."]}, "40120e38-1f36-4251-a1fa-d7e7656c2279": {"definition": "Upsampling is the digital signal processing operation that raises the sample rate of a signal by an integer factor L, done by inserting L-1 zero-valued samples between each original sample and then applying an interpolation (lowpass) filter to remove the resulting spectral images and fill in the new sample values. The result represents the same signal at a higher sample rate, not new information beyond the original bandwidth.", "plain_english": "Upsampling raises how many samples per second a digital signal has. First it slots extra empty samples between the real ones. Then a filter smooths those gaps to estimate the in-between values. It does not add real new detail; it just describes the same sound at a higher sample rate.", "purpose_function": "It exists to convert a signal to a higher sample rate for processing, mixing, or playback, and it underpins oversampling schemes that ease filtering and reduce aliasing.", "practical_application": "An engineer encounters upsampling when a plugin or converter oversamples internally to reduce aliasing, or when matching a file's sample rate to a session running at a higher rate.", "category": "Digital audio", "related_terms": ["Sample rate", "Downsampling", "Oversampling", "Interpolation filter", "Aliasing", "Sample rate conversion"], "common_mistakes": ["Believing upsampling adds real detail or quality above the original bandwidth; it cannot create information that was not captured.", "Confusing upsampling with the anti-imaging filter step; inserting zeros alone is not enough without filtering.", "Assuming any higher sample rate always sounds better, ignoring conversion quality and CPU cost.", "Mixing up upsampling (integer factor) with general sample-rate conversion between unrelated rates."], "scenario_contexts": ["A plugin oversampling internally to keep distortion artifacts below Nyquist.", "Importing a 44.1 kHz file into a 96 kHz session and matching rates.", "A DAC oversampling before conversion to relax its analog reconstruction filter.", "Preparing audio for processing that runs at a higher internal sample rate."]}, "b8487092-b0d4-4e60-9edc-6b66233a24c4": {"definition": "A verification measurement is a test made to confirm that each part of a sound system's signal chain is connected and working correctly — checking polarity, wiring, gain structure, level, distortion, and impedance — before any acoustic tuning or optimization of the system in the room is attempted. In measurement platforms such as Smaart it is treated as a distinct category of work from optimization/calibration, forming the first stage of a systematic alignment procedure.", "plain_english": "A verification measurement checks that every part of a sound system truly works before you tune it. You confirm the cables, polarity, gain, and that nothing distorts. It is like testing each bulb in a string of lights before you hang it. You fix wiring faults first, then tune the sound.", "purpose_function": "It exists to catch wiring, polarity, gain-structure, and component faults early, so that later tuning measures the system's real acoustic behavior rather than errors introduced by a broken signal path.", "practical_application": "Before optimizing a PA, a technician runs verification measurements on each channel and loudspeaker to confirm correct polarity, healthy gain structure, and no distortion or faulty cables.", "category": "Measurement workflow", "related_terms": ["Polarity check", "Gain structure", "System optimization", "Signal-to-noise ratio", "Total harmonic distortion (THD)", "Impedance measurement"], "common_mistakes": ["Skipping verification and jumping straight to EQ tuning, so wiring or polarity faults get masked with filters instead of fixed.", "Confusing verification (is the system working?) with optimization/calibration (does it sound right in the room?), which are separate stages.", "Assuming a system is fine because it makes sound, without checking polarity, gain structure, or distortion."], "scenario_contexts": ["Commissioning a newly installed sound system and confirming each zone is wired with correct polarity before tuning.", "Troubleshooting one weak loudspeaker in an array by verifying its cable, amplifier channel, and drive level.", "Checking gain structure and distortion across the signal chain during a pre-show system check."]}, "1ee36a08-0380-44cd-a6e1-4ab5f88e6379": {"definition": "Vertical coverage is the extent of the vertical plane over which a loudspeaker delivers useful, reasonably uniform sound pressure level, usually stated as the vertical coverage angle — the included angle between the off-axis points above and below the main axis at which the response has fallen 6 dB below the on-axis level at a given frequency or band. It describes how the loudspeaker distributes its output in the up-and-down dimension of the listening area.", "plain_english": "Vertical coverage is how far up and down a speaker spreads its sound. It is given as an angle. The edges are set where the sound level has dropped 6 dB below the center. Think of how wide a flashlight beam spreads, but aimed up and down. You use it to cover the audience, not the ceiling or floor.", "purpose_function": "It tells the designer how much of the audience's height range one loudspeaker can serve, so boxes can be aimed and arrayed to cover listeners evenly without wasting energy on ceilings or walls.", "practical_application": "When aiming a line array or point-source box, a technician uses the vertical coverage angle to set splay and tilt so the -6 dB edges land at the front and back rows.", "category": "Loudspeaker coverage", "related_terms": ["Coverage angle", "Horizontal coverage", "Directivity", "Beamwidth", "Splay angle", "Off-axis response"], "common_mistakes": ["Assuming coverage stays constant with frequency, when most loudspeakers narrow their vertical pattern as frequency rises.", "Reading the coverage angle as the point where sound stops, rather than the -6 dB down points, so aiming is off.", "Confusing vertical with horizontal coverage and rotating a box the wrong way."], "scenario_contexts": ["Choosing a loudspeaker with narrow vertical coverage to reach a deep balcony without splashing the ceiling.", "Setting splay angles between line-array boxes so vertical coverage overlaps smoothly down the seating rake.", "Aiming a stage monitor or fill so its vertical pattern lands at the performer's ear height."]}, "b805d845-77c6-493e-8c98-7e08ff985b38": {"definition": "Wind effect refers to the influence of moving air on acoustic measurements. Most directly, wind blowing across a microphone diaphragm produces turbulent pressure fluctuations that add spurious, predominantly low-frequency noise unrelated to the sound being measured; outdoors, wind-speed gradients also refract sound, bending it downward downwind and upward upwind and so altering measured level with distance. Windscreens and measurement standards are used to limit and account for these errors.", "plain_english": "Wind effect is how moving air spoils sound measurements. Air rushing across a microphone makes rumbling low-pitched noise that is not real sound. Outdoors, wind can also bend sound so it seems louder downwind. A foam or furry windscreen on the mic cuts most of the noise. This is why you watch the weather when measuring outside.", "purpose_function": "Recognizing wind effect lets technicians spot and reduce wind-induced error, using windscreens and calm conditions, instead of mistaking wind noise or wind-bent sound for the true performance of a source or system.", "practical_application": "When measuring SPL or system response outdoors, a technician fits a windscreen, notes wind speed and direction, and avoids gusty conditions to keep readings valid.", "category": "Measurement error", "related_terms": ["Windscreen", "Measurement microphone", "Sound pressure level (SPL)", "Signal-to-noise ratio", "Free field", "Ambient noise"], "common_mistakes": ["Measuring outdoors without a windscreen and treating the resulting low-frequency rumble as real signal or system output.", "Ignoring wind direction, so downwind readings run high and upwind readings run low compared with the true source level.", "Assuming a small foam ball fully removes wind noise, when strong gusts still corrupt the readings."], "scenario_contexts": ["Measuring an outdoor festival PA and fitting a foam or fur windscreen to block wind rumble on the mic.", "Explaining why an outdoor SPL reading drifts as gusts pass across the measurement position.", "Choosing a calm time of day for exterior noise measurements to reduce wind-induced error."]}, "f9e65e42-cac0-438c-a7a8-826bbd086982": {"definition": "Window overlap is the degree to which successive time-domain analysis frames (windows) in an FFT-based measurement share the same input samples, expressed as a percentage of the window length. Because window functions taper the signal toward zero at each frame's edges, overlapping consecutive frames (commonly 50–75%) recovers the data attenuated at those edges, smooths the analysis, and raises the display update rate and effective time resolution of a running spectrum or transfer-function measurement.", "plain_english": "Window overlap means each chunk of audio the analyzer looks at shares some samples with the chunk before it. The analyzer fades each chunk down at its edges, so overlapping fills in what those edges lose. It is like roof shingles that overlap so there are no gaps. More overlap gives a smoother, faster-updating result.", "purpose_function": "It compensates for the amplitude loss caused by window-function tapering and increases how often the analyzer produces a new result, giving smoother, more responsive spectra and transfer-function traces without missing short events between frames.", "practical_application": "In an FFT analyzer such as Smaart, a technician raises window overlap (for example to 75%) for a smoother, faster-updating live trace when aligning a system, accepting the extra CPU load.", "category": "FFT analysis", "related_terms": ["Window size", "Window function", "FFT", "Frequency resolution", "Spectrogram", "Transfer function measurement"], "common_mistakes": ["Thinking overlap improves frequency resolution, when only window size (frame length) sets frequency resolution.", "Using very high overlap needlessly, loading the processor for little added benefit.", "Using no overlap with a tapered window, so signal energy at the frame edges is under-represented and short events can be missed."], "scenario_contexts": ["Increasing overlap for a smoother real-time transfer-function trace while tuning a PA.", "Setting high overlap in a spectrogram to catch brief transients or feedback onsets.", "Balancing overlap against processor load on a laptop running measurement software live."]}, "a2c8909f-c48c-4069-9037-d805c740ca77": {"definition": "Window size (also called FFT size, block length, or time window) is the length of the time-domain segment of samples captured for a single FFT in a measurement, expressed in samples or in the time it spans. It sets the measurement's frequency resolution — the spacing between analysis bins equals the sample rate divided by the window size, equivalently one divided by the window's time length — so a longer window gives finer frequency resolution and a lower usable low-frequency limit, at the cost of poorer time resolution.", "plain_english": "Window size is how long a slice of sound the analyzer captures for one measurement. A longer slice lets it tell close frequencies apart, especially low ones. A shorter slice reacts faster in time but blurs frequency detail. It is a trade-off: you cannot have sharp frequency detail and sharp timing at the same time.", "purpose_function": "It determines the frequency resolution and low-frequency reach of an FFT measurement, letting the technician trade frequency detail against time detail to suit the signal being analyzed.", "practical_application": "A technician picks a large window (many samples) to resolve low-frequency room modes, and a smaller window for faster response or to examine high-frequency detail.", "category": "FFT analysis", "related_terms": ["Window overlap", "Frequency resolution", "FFT", "Sample rate", "Window function", "Frequency bins"], "common_mistakes": ["Expecting a short window to resolve low frequencies, when too few cycles are captured to separate them.", "Confusing window size (which sets frequency resolution) with overlap (which sets update rate).", "Forgetting that a longer window improves frequency detail but worsens time resolution, smearing transients."], "scenario_contexts": ["Choosing a long FFT window to measure and identify low-frequency room modes.", "Using a short window for quick, responsive metering of a changing signal.", "Setting multi-resolution or per-octave windowing in Smaart to match resolution across the spectrum."]}, "908a6f98-0fd2-4f73-aaf6-1d8649aa0afb": {"definition": "Word length reduction is the process of decreasing the number of bits used to represent each digital audio sample — for example converting a 24-bit signal to 16 bits — by discarding lower-order bits. Because truncating or rounding those bits introduces signal-correlated quantization error (distortion), word length reduction is normally performed with dither, and often noise shaping, to convert that error into a benign, decorrelated noise floor.", "plain_english": "Word length reduction means storing each digital audio sample with fewer bits, such as going from 24-bit to 16-bit. Fewer bits means less detail, which adds error. Simply chopping bits off causes harsh distortion. So engineers add a tiny bit of special noise called dither to turn that error into smooth, quiet hiss. This is a normal final step before making a CD.", "purpose_function": "It exists to fit higher-resolution audio into a lower-bit-depth format needed for delivery (such as 16-bit for CD) while, through dither, keeping the added quantization error low-level and free of audible harmonic distortion.", "practical_application": "When mastering a 24-bit mix down to 16-bit for CD or streaming, an engineer applies dither as the last processing step during word length reduction.", "category": "Digital audio", "related_terms": ["Dither", "Noise shaping", "Bit depth", "Quantization error", "Requantization", "dBFS"], "common_mistakes": ["Reducing word length without dither, producing signal-correlated harmonic distortion instead of benign noise.", "Applying dither more than once in a chain, adding unnecessary noise each time.", "Dithering to 16-bit early in the chain rather than as the final step before the target format.", "Assuming 24-to-16-bit reduction is lossless, when it always discards resolution."], "scenario_contexts": ["Exporting a 24-bit master down to 16-bit with dither for CD replication.", "Bouncing a session to a lower bit depth for a client deliverable.", "Setting dither type and noise shaping in a mastering limiter's output stage."]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"3b2020c5-60ec-4a39-91de-dcdd1623f487": {"definition": "An acoustic calibrator is a portable device that fits over a measurement microphone and produces a known, stable sound pressure level at a defined frequency, most commonly 94 dB (1 pascal) or 114 dB at 1 kHz, so a sound level meter or measurement system can be adjusted to read correctly. Its accuracy classes and requirements are defined by IEC 60942.", "plain_english": "An acoustic calibrator makes an exact, steady loudness at a set pitch. You slip it over a measurement microphone before you test. Then you adjust the meter until it reads the right number. This makes your later readings trustworthy.", "purpose_function": "It supplies a traceable acoustic reference so a microphone and meter system can be set to read true sound pressure level. Without it, level readings drift and cannot be trusted for safety or compliance work.", "practical_application": "Before a measurement a technician fits the calibrator over the microphone, plays its 94 dB tone, and adjusts the meter's sensitivity until it reads 94 dB, then removes it and measures.", "category": "Acoustic calibrator", "related_terms": ["Sound level meter", "Measurement microphone", "Sound pressure level (SPL)", "Pistonphone", "Calibration", "SPL calibrator"], "common_mistakes": ["Skipping the calibration check before and after a measurement, so a drifted or faulty reading goes unnoticed.", "Using a calibrator whose coupler diameter does not match the microphone, giving a poor seal and a wrong level.", "Forgetting that the stated level assumes standard atmospheric pressure, which shifts the reference at altitude."], "scenario_contexts": ["Calibrating a sound level meter before an occupational noise survey.", "Setting the reference level of a measurement microphone for room-acoustics work.", "Verifying at the end of a session that the meter has not drifted during measurements."]}, "7d896b67-a22e-4ba3-8dd4-5a15f4c11fc2": {"definition": "A broadband-noise source is a signal generator that produces random noise spread continuously across a wide frequency range, such as white or pink noise, for use as an excitation signal in acoustic and electronic measurement. Because it contains energy at all frequencies in the band at once, it lets an analyzer read a system's response across the whole spectrum simultaneously.", "plain_english": "A broadband-noise source makes a steady rushing sound that holds energy across the whole frequency range at once. It sounds a bit like rain or radio static. Engineers play it through a system to see how it responds at every frequency in one test.", "purpose_function": "It provides a wide, repeatable test signal so an analyzer can measure a system or room across all frequencies at the same time. This makes tuning and response checks faster than sweeping one tone at a time.", "practical_application": "A technician feeds broadband noise into a PA and reads the result on a real-time analyzer, then adjusts equalization until the measured response matches the target curve.", "category": "Test signal source", "related_terms": ["White noise", "Pink noise", "Real-time analyzer (RTA)", "Frequency response", "Pink-noise source", "Equalization"], "common_mistakes": ["Confusing white noise (equal energy per hertz) with pink noise (equal energy per octave), which look and sound different on an analyzer.", "UNSAFE: Running noise at high level through drivers or into ears for long tests without limiting the level, risking driver or hearing damage.", "Assuming a flat analyzer display means flat sound, when microphone placement and room reflections shape the reading."], "scenario_contexts": ["Exciting a room with noise to read its frequency response on an analyzer.", "Ringing out a PA system by driving it with noise and adjusting an equalizer.", "Testing a loudspeaker's response across the full audio band."]}, "d2a94732-adf7-4fbd-b029-838b2c8d5c66": {"definition": "A clamp meter is an electrical test instrument with a hinged jaw that clips around a single conductor to measure the current flowing in it without breaking the circuit, sensing the conductor's magnetic field by current transformer (AC) or Hall-effect (AC/DC) methods. Most models also include multimeter functions for voltage and resistance, and their safety ratings follow the measurement-category system of IEC 61010.", "plain_english": "A clamp meter measures electric current by clipping its jaws around a wire. You do not have to cut or unplug the wire to read it. Many models also measure voltage and resistance. It is the go-to tool for checking current safely.", "purpose_function": "It lets a technician measure current without opening the circuit or touching a live conductor, which is safer and faster than a series connection. This makes it the standard tool for checking loads and diagnosing electrical faults.", "practical_application": "A technician clips the jaws around one conductor of a mains cable to read how much current a rack or amplifier is drawing, checking it against the circuit rating.", "category": "Electrical test instrument", "related_terms": ["Digital multimeter", "Current transformer", "Hall effect", "Measurement category (CAT rating)", "Ground-resistance tester", "Ampere"], "common_mistakes": ["UNSAFE: Using a meter whose measurement-category (CAT) rating is too low for the circuit, risking arc flash and injury under a fault.", "Clamping around more than one conductor at once, so opposing currents cancel and the reading is wrong or near zero.", "Trusting an AC-only clamp to read DC current, when only a Hall-effect model measures DC."], "scenario_contexts": ["Measuring the current draw of a lighting or amplifier rack on a live event.", "Checking whether a circuit is overloaded before adding more equipment.", "Diagnosing an intermittent fault by watching current change as gear switches on."]}, "dfefa2b3-2c27-4220-b3e9-72d2db8a33f0": {"definition": "A component analyzer is a test instrument that measures the electrical characteristics of individual electronic components, such as the resistance, capacitance, and inductance of passive parts or the parameters of semiconductors like diodes and transistors. Instruments in this class range from LCR meters that report impedance values to component testers that identify a part and display its key parameters.", "plain_english": "A component analyzer measures what a single electronic part actually does. It can read a resistor, capacitor, coil, or transistor and show its values. Engineers use it to check a part before fitting it, or to find a faulty one on a board.", "purpose_function": "It exists to confirm the true value and health of a component rather than trusting its printed marking. This helps a technician find out-of-tolerance, damaged, or wrongly labeled parts.", "practical_application": "A repair technician connects a suspect capacitor to the analyzer to read its capacitance and check it against the marked value before deciding to replace it.", "category": "Test instrument", "related_terms": ["LCR meter", "Digital multimeter", "Capacitance", "Inductance", "Impedance", "Continuity test"], "common_mistakes": ["Testing a component while it is still in-circuit, so nearby parts skew the reading.", "UNSAFE: Measuring a capacitor without first discharging it, so a stored charge can damage the instrument or shock the user.", "Confusing a basic resistance check on a multimeter with a full impedance measurement at the component's working frequency."], "scenario_contexts": ["Checking a capacitor's value before soldering it into a repair.", "Identifying an unmarked part pulled from a board.", "Sorting components by measured value for a matched pair."]}, "eedeaaca-95c4-4085-bc41-664866813239": {"definition": "A differential probe is an oscilloscope probe with two inputs that measures the voltage difference between two points in a circuit, neither of which is referenced to earth ground, using an internal differential amplifier that rejects the voltage common to both points. It allows safe, accurate measurement of floating or high-voltage signals that a single-ended, ground-referenced probe cannot measure without risk.", "plain_english": "A differential probe measures the voltage between two points in a circuit, not between a point and ground. It has two tips and reads the difference. This lets you safely probe signals that float above ground, such as in a power amplifier. It also cancels noise shared by both tips.", "purpose_function": "It exists to measure voltages that are not tied to ground, and to reject noise common to both probe points, giving a clean and safe reading. This prevents the dangerous short circuit that grounding a normal probe on a floating point can cause.", "practical_application": "A technician uses a differential probe to view the switching waveform across a floating node in an amplifier's power supply without connecting the scope ground to that point.", "category": "Test probe", "related_terms": ["Oscilloscope", "Common-mode rejection", "Ground loop", "Digital multimeter", "Measurement category (CAT rating)", "Floating measurement"], "common_mistakes": ["UNSAFE: Clipping a standard ground-referenced probe onto a floating or live point, which can create a direct short and shock or arc-flash hazard.", "Exceeding the probe's rated common-mode or maximum input voltage, which damages the probe and gives false readings.", "Forgetting that the differential amplifier needs power and that the reading is scaled by an attenuation factor."], "scenario_contexts": ["Viewing a floating signal in a switch-mode power supply on an oscilloscope.", "Measuring the output of a bridge-tied amplifier where neither terminal is at ground.", "Rejecting common-mode noise when probing a small differential signal."]}, "379bc01c-76ac-4022-8294-d065f292d973": {"definition": "A digital multimeter (DMM) is a handheld or bench electrical test instrument that measures voltage, current, and resistance and displays the result as a numeric readout, usually adding functions such as continuity, diode test, capacitance, and frequency. Its input protection and safety are rated by the measurement-category (CAT) system of IEC 61010.", "plain_english": "A digital multimeter is the everyday electrical test tool. It measures voltage, current, and resistance and shows the value on a number display. Most also test continuity and diodes. Technicians reach for it first when checking wiring or finding a fault.", "purpose_function": "It combines several basic electrical measurements in one instrument, giving fast, accurate numeric readings for setup and troubleshooting. This makes it the core diagnostic tool for almost any electrical or electronic work.", "practical_application": "A technician uses a multimeter to check that a power supply outputs the right voltage, or to test a cable for continuity and shorts before installing it.", "category": "Electrical test instrument", "related_terms": ["Clamp meter", "Continuity test", "Resistance", "Voltage", "Measurement category (CAT rating)", "Component analyzer"], "common_mistakes": ["UNSAFE: Using a meter whose measurement-category (CAT) rating is too low for the circuit, risking arc flash under a transient or fault.", "Measuring resistance or continuity on a live circuit, which gives false readings and can damage the meter.", "Leaving the leads in the current jacks and then measuring voltage, which creates a near short across the source."], "scenario_contexts": ["Checking a DC power supply rail against its rated voltage.", "Testing an audio cable for continuity and shorts before a show.", "Measuring resistance to confirm a fuse or connection is intact."]}, "c960e258-268c-4877-a764-bf634a375aea": {"definition": "A frequency counter is a test instrument that measures the frequency of a repetitive electrical signal by counting the number of input cycles that occur within a precise time window set by an internal, stable timebase oscillator. It displays the result numerically, typically in hertz, and its accuracy depends chiefly on the stability of that timebase reference.", "plain_english": "A frequency counter measures how many times a signal repeats per second. It counts the signal's cycles over an exact slice of time and shows the pitch as a number. Engineers use it to check that a clock or tone sits at the right frequency.", "purpose_function": "It exists to give a precise numeric measurement of a signal's frequency, far more exact than reading a scope trace by eye. This lets a technician verify oscillators, clocks, and tone sources against their specified values.", "practical_application": "A technician connects a frequency counter to a signal generator's output to confirm it produces exactly the frequency set, or to check the master clock in a piece of digital gear.", "category": "Test instrument", "related_terms": ["Frequency generator", "Oscilloscope", "Timebase", "Signal generator", "Hertz", "Sample rate"], "common_mistakes": ["Ignoring the accuracy of the counter's timebase, which sets the limit of how precise the reading can be.", "Feeding a signal that is too small, noisy, or distorted, so the counter miscounts or reads erratically.", "Confusing a frequency counter, which measures a signal, with a frequency generator, which produces one."], "scenario_contexts": ["Verifying that a signal generator outputs the exact frequency dialed in.", "Checking a digital device's master clock against its specified rate.", "Measuring the frequency of an unknown tone during troubleshooting."]}, "d2dd9bd1-68df-446f-929c-3ae667332669": {"definition": "A frequency generator is a signal source that produces an electrical output, commonly a sine wave, whose frequency can be set across a range for testing and measuring audio and electronic equipment. The term is used broadly for signal and function generators, which may also offer other waveforms and adjustable output level.", "plain_english": "A frequency generator makes a test signal at a pitch you choose. You dial in the frequency, and it outputs a steady tone. Engineers feed this tone into gear to see how the gear handles different frequencies.", "purpose_function": "It supplies a controllable, repeatable test signal so an engineer can drive a device at known frequencies and see how it responds. This is the starting point for frequency response, alignment, and fault-finding tests.", "practical_application": "A technician sweeps a frequency generator across the audio band into an amplifier and watches the output level to map its frequency response.", "category": "Signal generator", "related_terms": ["Signal generator", "Function generator", "Frequency counter", "Sine wave", "Test tone", "Frequency response"], "common_mistakes": ["Setting the output level too high, which can overdrive and clip the device under test.", "Assuming the generator's own tone is perfectly clean, when a high-distortion source can mask the device's true behavior.", "Confusing a frequency generator, which produces a signal, with a frequency counter, which measures one."], "scenario_contexts": ["Sweeping tones through an amplifier to plot its frequency response.", "Sending a fixed reference tone to line up levels across a signal chain.", "Feeding a known frequency to test a filter or crossover."]}, "319c436d-44b8-40e0-bc31-5b51820b24d3": {"definition": "A ground-resistance tester (earth tester) is an instrument that measures the resistance of an earthing electrode or grounding system to the general mass of earth, most often by the fall-of-potential method using auxiliary stakes, or by a clamp-on method on an existing grounded loop. Test methods and instrument requirements are covered by IEC 61557-5 and by IEEE Std 81.", "plain_english": "A ground-resistance tester checks how well a ground rod or earthing system connects to the earth. A low resistance means a good, safe ground. Electricians use it to confirm that protective grounding will work in a fault.", "purpose_function": "It verifies that a grounding system has low enough resistance to carry fault current safely and let protective devices trip. A poor ground can leave equipment enclosures live and dangerous, so this test confirms the safety path is sound.", "practical_application": "A technician drives auxiliary stakes and runs a fall-of-potential test on a building's ground electrode to confirm its resistance meets the specified limit before energizing.", "category": "Electrical test instrument", "related_terms": ["Grounding electrode", "Bonding", "Fall-of-potential method", "Clamp meter", "Digital multimeter", "Earth resistivity"], "common_mistakes": ["UNSAFE: Treating a simple continuity check as proof of a good earth, when only a proper ground-resistance test confirms the electrode can carry fault current.", "Placing the auxiliary stakes too close together in the fall-of-potential method, so their resistance areas overlap and the reading is wrong.", "Ignoring soil moisture and temperature, which change earth resistance from season to season."], "scenario_contexts": ["Commissioning a new electrical installation's grounding electrode.", "Checking the ground system of a broadcast or antenna tower.", "Periodic testing of earthing at a substation or large venue."]}, "3183e6ba-280e-498b-ac43-e89e67c62cf2": {"definition": "An impedance bridge is an electrical test instrument that measures the impedance of a component - its resistance, capacitance, or inductance - by balancing the unknown element against known reference elements in a bridge (Wheatstone-derived) circuit. When the bridge is nulled, the unknown value is read from the calibrated reference settings, often together with a dissipation or quality factor.", "plain_english": "An impedance bridge measures how a part resists or stores electricity. It compares the unknown part against known parts in a balanced circuit. You adjust dials until the meter reads zero. Then you read the part's value from the dials.", "purpose_function": "It exists to measure resistance, capacitance, and inductance accurately using the null (balance) method, which is less sensitive to meter errors than direct reading. This lets a technician verify component values and match parts.", "practical_application": "A technician nulls the bridge against an unknown capacitor or inductor to confirm its true value, for example when matching components or checking a suspect crossover part.", "category": "Test instrument", "related_terms": ["LCR meter", "Impedance", "Capacitance", "Inductance", "Multimeter", "Wheatstone bridge"], "common_mistakes": ["Confusing an impedance bridge with a simple ohmmeter, when the bridge also measures capacitance and inductance.", "Reading a value before the bridge is fully nulled, which gives an inaccurate result.", "Ignoring the test frequency, since measured inductance and capacitance can vary with the frequency used."], "scenario_contexts": ["Matching capacitors or inductors for a loudspeaker crossover.", "Verifying the value of an unmarked or suspect component.", "Measuring the inductance of a transformer or coil during repair."]}, "acc4004f-0668-4f71-ad1f-bfd29ded2a44": {"definition": "An isolation transformer tester is a test instrument used to verify that an isolation transformer functions safely and correctly, typically by checking the insulation resistance between its primary and secondary windings, its turns (voltage) ratio, and winding continuity. Confirming galvanic isolation and correct ratio ensures the transformer still breaks the direct electrical connection between supply and load as intended.", "plain_english": "An isolation transformer keeps two circuits apart for safety. This tester checks that the two sides are still fully separate. It measures how well the insulation blocks current between them. It also checks the voltage ratio and looks for broken windings.", "purpose_function": "It exists to confirm that an isolation transformer still provides safe galvanic separation and the correct output voltage. This protects people and equipment from shock and ground-loop problems.", "practical_application": "A technician uses it to test insulation resistance and turns ratio during routine safety checks, or before returning a repaired isolation transformer to service.", "category": "Electrical safety tester", "related_terms": ["Isolation transformer", "Insulation resistance", "Leakage current", "Ground loop", "Turns ratio", "Megohmmeter"], "common_mistakes": ["UNSAFE: Testing a mains-connected transformer without following lockout/tagout and shock-safety practice, risking severe electric shock.", "Confusing insulation-resistance testing with a simple continuity check, which cannot reveal weak insulation.", "Assuming a transformer that powers up is safe, when its isolation insulation may still have degraded."], "scenario_contexts": ["Checking insulation resistance of an isolation transformer during a routine safety inspection.", "Verifying turns ratio after a transformer repair.", "Diagnosing a suspected breakdown in isolation causing shock hazard or hum."]}, "1c538ac6-b186-40e6-86b3-33b0d6136042": {"definition": "An LCR meter is an electronic test instrument that measures the inductance (L), capacitance (C), and resistance (R) of a component, typically by applying a known AC test signal and measuring the resulting voltage and current to derive impedance and phase. From these it reports the component's primary value plus secondary parameters such as dissipation factor (D), quality factor (Q), or equivalent series resistance (ESR), often at selectable test frequencies.", "plain_english": "An LCR meter measures three basic properties of electronic parts. These are inductance, capacitance, and resistance. It sends a small test signal through the part and reads how it responds. Technicians use it to check or sort components.", "purpose_function": "It exists to measure passive component values quickly and accurately, including secondary factors like ESR that reveal a part's quality. This lets a technician verify, match, or grade components.", "practical_application": "A technician uses an LCR meter to check a capacitor's value and ESR when hunting for a failed part in a power supply or crossover.", "category": "Test instrument", "related_terms": ["Impedance bridge", "Capacitance", "Inductance", "ESR", "Multimeter", "Dissipation factor"], "common_mistakes": ["Ignoring the test frequency, since measured capacitance and inductance can change with it.", "Not zeroing or compensating the leads, which adds error to small-value readings.", "Measuring a capacitor in-circuit, where parallel parts corrupt the reading."], "scenario_contexts": ["Checking a suspect capacitor's value and ESR during repair.", "Matching components for stereo channels or crossovers.", "Sorting a batch of parts by measured value."]}, "f4980cd3-b403-45b1-a094-1990161a3a1e": {"definition": "A leakage-current tester is a safety test instrument that measures the small unwanted current flowing from a device's energized parts to its accessible conductive surfaces or protective earth, verifying that this leakage stays within limits set by product-safety standards. It is used during electrical safety testing, often alongside insulation-resistance and earth-continuity tests, to confirm that equipment will not deliver a dangerous shock.", "plain_english": "Some current can leak from a device's live parts to its metal case. If too much leaks, touching the case could shock you. A leakage-current tester measures how much leaks. It confirms the amount stays within safe limits.", "purpose_function": "It exists to confirm that leakage current stays below safe limits, so a device cannot give a user a dangerous electric shock through its case or connections. This is a core part of electrical safety testing.", "practical_application": "A test technician runs a leakage-current test as part of a portable-appliance or production safety check, comparing the reading to the standard's pass/fail limit.", "category": "Electrical safety tester", "related_terms": ["Leakage current", "Insulation resistance", "Earth continuity", "Protective earth", "Portable appliance testing", "Ground fault"], "common_mistakes": ["UNSAFE: Touching the device under test or its case during a leakage test, since energized testing can shock you.", "Comparing readings to the wrong standard's limit, since limits differ by equipment class and type.", "Skipping earth-continuity and insulation tests, which check different failure modes than leakage alone."], "scenario_contexts": ["Portable appliance testing of studio and stage equipment.", "Production-line safety testing of a new audio product.", "Verifying safety after repairing a mains-powered device."]}, "5143b7a0-8142-499b-9c96-8e45550e65be": {"definition": "A loudspeaker polarity tester is a two-part test set - a pulse sender and an acoustic (or electrical) receiver - that verifies whether a loudspeaker, driver, or signal path preserves absolute polarity, meaning that a positive-going input produces an outward (positive-pressure) cone movement. The sender emits a polarized test pulse and the receiver indicates 'positive' or 'negative', revealing reversed wiring or an inverted stage.", "plain_english": "This tool checks that a speaker is wired the right way round. A positive signal should push the cone outward, not pull it in. A sender makes a special test pulse. A small receiver with a microphone shows whether the speaker is positive or negative.", "purpose_function": "It exists to confirm that drivers and signal paths keep the same polarity, so speakers push and pull together instead of cancelling. Correct polarity preserves bass and a solid stereo image.", "practical_application": "A technician sends the test pulse into a speaker and holds the receiver's mic in front of it to confirm the cone moves outward, catching reversed speaker wiring.", "category": "Service instrument", "related_terms": ["Polarity", "Phase", "Loudspeaker", "Absolute polarity", "Signal chain", "Driver"], "common_mistakes": ["Confusing polarity with phase, when polarity is a fixed sign flip and phase changes with frequency.", "Assuming matched wiring means correct polarity, since an inverted stage inside the chain can still flip it.", "Testing in a noisy space, where the acoustic receiver can misread the pulse."], "scenario_contexts": ["Checking that every box in a PA shares the same polarity before a show.", "Finding a speaker cable wired out of polarity.", "Confirming polarity through a signal chain from console to driver."]}, "d4948599-b937-456e-9cc2-8ee8aea90ebb": {"definition": "A microphone tester is a test device or instrument used to verify that a microphone and its cabling are working correctly, checking properties such as output signal presence and level, cable continuity, and, for condenser microphones, the presence of phantom power. More advanced units can measure sensitivity, frequency response, or self-noise, helping a technician confirm a mic is functional before use.", "plain_english": "A microphone tester checks that a microphone actually works. It confirms the mic sends out a signal at a fair level. It can check the cable for breaks. For condenser mics, it can check that phantom power reaches the mic.", "purpose_function": "It exists to quickly confirm a microphone and its cable are healthy, so faults are found in the shop rather than during a session or show. This saves time and avoids dead channels at critical moments.", "practical_application": "A technician plugs a suspect mic and cable into the tester to confirm it passes signal and, if a condenser, receives phantom power before deploying it.", "category": "Service instrument", "related_terms": ["Phantom-power tester", "Cable tester", "Condenser microphone", "Microphone sensitivity", "Signal chain", "XLR"], "common_mistakes": ["Blaming the microphone when a broken cable or dead phantom supply is the real fault.", "Testing a condenser mic without phantom power and assuming it is dead.", "Expecting a basic tester to measure frequency response, which needs a proper measurement setup."], "scenario_contexts": ["Checking a suspect microphone before a recording session.", "Sorting working from faulty mics in a rental inventory.", "Confirming that a condenser mic receives phantom power."]}, "d4e33970-22ff-4230-8f25-2fb4aa515d50": {"definition": "An oscilloscope probe is the accessory that connects a circuit's test point to an oscilloscope input, transferring the signal while minimizing loading and distortion. Passive probes commonly offer a switchable 10:1 attenuation that raises input impedance and bandwidth, and include an adjustable compensation capacitor that must be trimmed to the scope input so square waves display without tilt or overshoot.", "plain_english": "An oscilloscope probe is the lead that connects a circuit to an oscilloscope. It carries the signal without disturbing the circuit too much. Many probes cut the signal by ten times to work over a wider range. You adjust a small trimmer so a square-wave test looks correct.", "purpose_function": "It exists to deliver a faithful copy of a circuit's signal to the scope while adding as little loading and error as possible. Correct probe choice and compensation keep the displayed waveform accurate.", "practical_application": "A technician clips the probe ground to circuit ground, sets 10:1 for higher-frequency work, and compensates the probe on the scope's calibration output before measuring.", "category": "Test accessory", "related_terms": ["Oscilloscope", "Attenuation", "Input impedance", "Bandwidth", "Probe compensation", "Ground lead"], "common_mistakes": ["UNSAFE: Clipping the probe ground to a live or floating point in mains-powered gear, which can short circuits or cause shock.", "Forgetting to compensate the probe, so square waves show tilt or overshoot and readings mislead.", "Forgetting the 10:1 setting when reading amplitude, giving a value ten times wrong."], "scenario_contexts": ["Measuring a waveform at a circuit test point during repair.", "Compensating a probe on the scope's calibration output before use.", "Switching to 10:1 to view a high-frequency or higher-voltage signal."]}, "d2935663-593d-420f-8c34-224b724246b7": {"definition": "A patchbay tester is a test tool used to verify the wiring and connections of an audio patchbay and its patch cords, checking each point for correct continuity and for opens, shorts, or crossed connections between the tip, ring, and sleeve conductors. By confirming that every jack and normal connects as intended, it isolates wiring faults in a studio's patching system.", "plain_english": "A patchbay is a panel that links studio gear together. A patchbay tester checks that each connection is wired correctly. It looks for breaks, shorts, and swapped wires. This helps find a faulty jack or cord fast.", "purpose_function": "It exists to confirm that every patch point and cord passes signal on the correct conductors, so a wiring fault is found quickly. This prevents dead or crossed signals in the patching system.", "practical_application": "A technician runs the tester across each patch point and cord to find an open, short, or reversed connection when a channel goes dead.", "category": "Cable tester", "related_terms": ["Patchbay", "Cable tester", "Continuity", "TRS connector", "Signal chain", "Normalling"], "common_mistakes": ["Assuming the patchbay is at fault when the connected gear or a patch cord is the real problem.", "Testing only for continuity and missing a short between conductors.", "Overlooking how normalled connections change the expected signal path."], "scenario_contexts": ["Finding a dead patch point in a studio patchbay.", "Checking a batch of patch cords for faults.", "Verifying wiring after installing or re-terminating a patchbay."]}, "6757cc7f-4b38-4457-97d8-3fba20210704": {"definition": "A phantom-power tester is a test device that verifies the presence and correctness of phantom power - the DC voltage (nominally 48 V, per IEC 61938) supplied through a balanced microphone line to power condenser microphones and active DI boxes - typically by confirming that the voltage is present and equal on both signal conductors relative to the shield. It lets a technician confirm a console, preamp, or splitter is delivering usable phantom power.", "plain_english": "Condenser microphones need power sent down the mic cable. This is called phantom power, usually 48 volts. A phantom-power tester checks that this voltage is really there. It also checks the voltage is even on both signal wires.", "purpose_function": "It exists to confirm that a mic input or preamp is actually supplying correct phantom power, so a condenser mic will work. This quickly separates a phantom-supply fault from a faulty microphone.", "practical_application": "A technician plugs the tester into a console's mic input, switches on phantom, and reads whether the full voltage is present before trusting the channel with a condenser mic.", "category": "Service instrument", "related_terms": ["Phantom power", "Condenser microphone", "Microphone tester", "Balanced line", "XLR", "Preamplifier"], "common_mistakes": ["UNSAFE: Hot-patching a microphone while phantom power is on, which can pop speakers and stress inputs; mute or switch phantom off first.", "Assuming a dead condenser mic is faulty when the phantom supply is actually off or weak.", "Expecting exactly 48 V, when the standard also allows lower nominal voltages such as 12 V or 24 V."], "scenario_contexts": ["Checking that a console channel supplies phantom power before a session.", "Diagnosing why a condenser mic gives no output.", "Verifying that phantom passes through a mic splitter or long cable run."]}, "1c1e9565-64e1-4068-9249-f7485fcd600d": {"definition": "A phase analyzer is a measurement instrument or software function that measures and displays the phase relationship between two audio signals as a function of frequency, typically as part of a dual-channel transfer-function (FFT) measurement comparing a system's output to its input. The phase trace, shown in degrees versus frequency, reveals time offsets, polarity reversals, and crossover interactions that a magnitude-only response cannot show.", "plain_english": "A phase analyzer compares the timing of two sound signals at each frequency. It shows how far one lags the other, drawn as a curve. Engineers use it to line up speakers and subs. It also flags wires that are hooked up backwards.", "purpose_function": "It exists to reveal timing and polarity differences between signals across frequency, which control how sound sources combine. This information lets an engineer time-align and polarity-check loudspeakers so their outputs add rather than cancel.", "practical_application": "A system technician runs a transfer-function measurement and reads the phase trace to set delay between a subwoofer and main speakers so their outputs align through the crossover region.", "category": "Measurement analyzer", "related_terms": ["Transfer function", "Polarity", "Time alignment", "Crossover", "Real-time analyzer (RTA)", "Group delay"], "common_mistakes": ["Confusing phase with polarity, when polarity is a fixed sign flip and phase varies with frequency.", "Reading the phase trace where coherence is low, so the displayed phase is unreliable noise.", "Trying to correct phase by inverting polarity alone, which cannot fix a time offset between sources."], "scenario_contexts": ["Aligning a subwoofer to the main system by matching phase through the crossover frequency.", "Checking that all boxes in an array share the same polarity before a show.", "Diagnosing a dip in response caused by two arrivals cancelling out of phase."]}, "5316874c-cd34-4119-8d9b-bab393954ace": {"definition": "A pink-noise source is a signal generator that produces pink noise, a random broadband signal whose power spectral density is inversely proportional to frequency, giving equal energy in each octave (or fraction of an octave) and a spectrum that falls at 3 dB per octave. It is used as a stable, repeatable excitation signal for measuring loudspeakers, rooms, and systems with real-time analyzers.", "plain_english": "A pink-noise source makes a steady rushing sound that holds equal power in every octave. It sounds smooth, a bit like heavy rain. Engineers play it through a system to test how a room or speaker responds across the whole frequency range.", "purpose_function": "It provides a broadband test signal with equal energy per octave, which matches how analyzers and human hearing group frequencies. This makes it a reliable excitation for reading a system's frequency response and for tuning rooms.", "practical_application": "A technician feeds pink noise into a PA and reads the result on a real-time analyzer, then adjusts equalization until the measured response matches the target curve.", "category": "Test signal source", "related_terms": ["White noise", "Real-time analyzer (RTA)", "Pink noise", "Frequency response", "Octave band", "Equalization"], "common_mistakes": ["Confusing pink noise with white noise, which has equal energy per hertz and sounds much brighter.", "UNSAFE: Running pink noise at high level through drivers or into ears for long tests without limiting the level, risking driver or hearing damage.", "Expecting a flat RTA display to mean flat sound, when microphone placement and room reflections shape the reading."], "scenario_contexts": ["Ringing out a room by driving the PA with pink noise and adjusting a graphic equalizer.", "Measuring a loudspeaker's frequency response on a real-time analyzer.", "Setting relative levels between subwoofers and mains using a steady pink-noise signal."]}, "0bd5e771-cf8d-4f62-a287-7c2cc8949af6": {"definition": "A precision audio analyzer is a high-accuracy test instrument, typically combining a low-distortion signal generator with a calibrated analyzer, that measures audio performance parameters such as level, frequency response, total harmonic distortion plus noise (THD+N), signal-to-noise ratio, crosstalk, and phase for analog and digital equipment. Its own residual distortion and noise are far below those of the devices under test, and measurement methods follow standards such as AES17.", "plain_english": "A precision audio analyzer is a very accurate test box for audio gear. It sends a clean test tone in and measures what comes back. It reports things like distortion, noise, and frequency response. Its own errors are tiny, so it can grade high-end equipment.", "purpose_function": "It exists to measure audio quality to tight, repeatable tolerances that ordinary meters cannot reach. Engineers use it to verify that equipment meets published specifications and to catch faults during design and production.", "practical_application": "A test technician connects the analyzer's generator to a device input and its analyzer to the output, then runs an automated sequence to measure THD+N and frequency response against a pass/fail limit.", "category": "Audio analyzer", "related_terms": ["THD+N", "Signal-to-noise ratio", "Frequency response", "Precision oscillator", "AES17", "Crosstalk"], "common_mistakes": ["Trusting a reading without confirming the analyzer's residual distortion and noise are below the device being tested.", "Ignoring bandwidth and weighting settings, which change THD+N and noise figures significantly.", "Comparing two measurements taken with different filters or measurement bandwidths as if they were equivalent."], "scenario_contexts": ["Measuring THD+N and frequency response of a mixing console channel on a production line.", "Verifying that a new converter meets its published signal-to-noise specification.", "Troubleshooting distortion in a power amplifier by sweeping level and frequency."]}, "8f79ff84-2a34-46ec-8bd5-a58fd178ce4a": {"definition": "A precision oscillator is a signal generator that produces a sine wave of accurately known and stable frequency and amplitude with very low harmonic distortion, serving as a clean reference test signal for audio measurement. Its low residual distortion and flat amplitude across the band let it drive equipment under test without adding errors that would corrupt the measurement.", "plain_english": "A precision oscillator makes a very pure test tone. Its pitch and level stay steady and accurate. The tone has almost no added harshness. Engineers feed it into gear to test the gear, not the tone.", "purpose_function": "It exists to supply a clean, repeatable reference tone so that any distortion or level error measured at a device's output comes from the device, not the source. This makes accurate distortion and response tests possible.", "practical_application": "A technician sets the oscillator to a standard frequency such as 1 kHz, drives a device input, and measures the output distortion, knowing the source itself adds almost none.", "category": "Signal generator", "related_terms": ["Precision audio analyzer", "THD+N", "Sine wave", "Frequency response", "Signal generator", "Test tone"], "common_mistakes": ["Assuming any tone generator is clean enough, when a high-distortion source masks the device's true performance.", "Leaving the output level too high, which can overdrive and clip the device under test.", "Confusing frequency accuracy with amplitude flatness, which are two separate specifications."], "scenario_contexts": ["Sending a 1 kHz reference tone to line up levels across a signal chain.", "Measuring an amplifier's harmonic distortion with a known-clean input tone.", "Checking frequency response by stepping a pure tone across the audio band."]}, "76e6ab0b-afd1-4af8-aa4e-431c1b84f0f3": {"definition": "A pulse generator is a test instrument that produces electrical pulses with controllable amplitude, width, repetition rate, and edge timing, used to excite and characterize the transient and timing behavior of circuits and systems. In audio and acoustics it can supply short impulse-like signals to probe transient response, and impulse-based excitation underlies impulse-response and room-acoustics measurement methods.", "plain_english": "A pulse generator makes short bursts of voltage that you can shape and repeat. You control how tall, how wide, and how often the pulses are. Engineers use them to test how fast a circuit reacts. Short pulses can also help measure how a room responds.", "purpose_function": "It exists to deliver precisely shaped pulses so an engineer can study how a device or space responds to sudden changes. This reveals transient behavior, timing, and delays that steady tones do not show.", "practical_application": "A technician feeds pulses into a circuit and watches the output on an oscilloscope to check rise time, overshoot, and settling behavior.", "category": "Signal generator", "related_terms": ["Impulse response", "Oscilloscope", "Square-wave generator", "Transient response", "Rise time", "Signal generator"], "common_mistakes": ["Confusing a pulse generator with a function generator, when a pulse generator focuses on adjustable pulse timing and edges.", "Ignoring pulse width and repetition rate, which strongly affect what the test reveals.", "Assuming a single acoustic pulse gives a clean room measurement, when noise and level limits often favor swept or MLS methods."], "scenario_contexts": ["Checking a circuit's rise time and overshoot on an oscilloscope.", "Testing the transient behavior of a filter or amplifier stage.", "Using an impulse-like excitation to help capture a system or room impulse response."]}, "27923dbe-45bb-4bce-baba-566126c02b3d": {"definition": "A signal tracer is a troubleshooting instrument, usually containing a probe, an amplifier, and a loudspeaker or meter, used to follow an audio signal stage by stage through a circuit to find where the signal is lost, weakened, or distorted. By probing successive points from input to output, a technician isolates the faulty stage in an amplifier, mixer, or other signal path.", "plain_english": "A signal tracer lets you follow a sound signal through a piece of gear. You touch its probe to each point in turn and listen. Where the sound stops or turns bad, that stage is broken. It is a classic way to find faults in an amplifier.", "purpose_function": "It exists to localize a fault by letting a technician hear or read the signal at each point in a chain. This turns a vague 'no output' complaint into a specific failed stage.", "practical_application": "A repair technician injects or plays a test signal, then moves the tracer probe from stage to stage until the signal disappears, pinpointing the failed component or stage.", "category": "Service instrument", "related_terms": ["Signal generator", "Oscilloscope", "Multimeter", "Troubleshooting", "Test tone", "Signal chain"], "common_mistakes": ["UNSAFE: Probing live points inside mains-powered or tube gear without following lockout and shock-safety practice, risking severe electric shock.", "Tracing without a known-good input signal, so a silent point cannot be interpreted.", "Confusing a signal tracer with a signal generator; the tracer follows a signal while the generator supplies one."], "scenario_contexts": ["Finding the dead stage in an amplifier that has lost all output.", "Locating where hum or distortion enters a mixer channel.", "Following a test tone through a signal path to isolate an intermittent fault."]}, "b38e6523-3c7d-4c08-94f4-a416b0eba2b6": {"definition": "An SPL calibrator (acoustic calibrator) is a portable device that fits over a measurement microphone and generates a known, stable sound pressure level at a defined frequency - commonly 94 dB (1 pascal) or 114 dB at 1 kHz - so that a sound level meter or measurement system can be adjusted to read correctly. Its performance and accuracy classes are defined by IEC 60942.", "plain_english": "An SPL calibrator makes a known, exact loudness at a set pitch. You slip it over a measurement microphone before testing. Then you adjust the meter until it reads the right number. This makes sure your later readings are accurate.", "purpose_function": "It provides a traceable acoustic reference so a meter or microphone system can be set to read true sound pressure level. Without it, level readings can drift and cannot be trusted for safety or compliance work.", "practical_application": "Before a noise survey a technician fits the calibrator to the microphone, plays its 94 dB tone, and adjusts the meter's sensitivity until it reads 94 dB, then removes it and measures.", "category": "Acoustic calibrator", "related_terms": ["Sound level meter", "Measurement microphone", "Sound pressure level (SPL)", "Pistonphone", "Calibration", "A-weighting"], "common_mistakes": ["Skipping the calibration check before and after a measurement, so a drifted or faulty reading goes unnoticed.", "Using a calibrator whose diameter does not match the microphone, giving a poor seal and a wrong level.", "Forgetting that the calibrator's stated level assumes a standard atmospheric pressure, which shifts the reference at altitude."], "scenario_contexts": ["Calibrating a sound level meter before an occupational noise survey.", "Setting the reference level of a measurement microphone in room-acoustics work.", "Verifying at the end of a session that the meter has not drifted during measurements."]}, "7513bd31-cdc1-4dd8-a277-eff68c21cebe": {"definition": "A square-wave generator is a signal source that produces a square waveform - a signal that alternates sharply between two levels with fast rising and falling edges - used to test the transient and frequency behavior of audio circuits. Because a square wave contains a fundamental plus a series of odd harmonics, observing how a device reshapes it reveals bandwidth limits, ringing, phase shift, and slew-rate problems.", "plain_english": "A square-wave generator makes a signal that snaps between two levels, like a switch flipping on and off fast. This shape is really a tone plus many higher tones stacked together. When gear distorts the square shape, engineers can see problems such as limited bandwidth or ringing.", "purpose_function": "It exists to stress a device with sharp edges and a rich harmonic content, so its transient response and bandwidth show up as changes in the waveform's shape. This exposes faults that a single sine tone would hide.", "practical_application": "A technician sends a square wave into an amplifier or filter and watches the output on an oscilloscope, reading overshoot, tilt, and ringing to judge its response.", "category": "Signal generator", "related_terms": ["Pulse generator", "Oscilloscope", "Harmonics", "Transient response", "Slew rate", "Signal generator"], "common_mistakes": ["Reading square-wave shape changes without accounting for the generator's own edge speed, which limits how sharp the input can be.", "Assuming a rounded output means a fault, when limited bandwidth naturally softens the edges.", "Overdriving the device with too large a square wave, causing clipping that hides its real behavior."], "scenario_contexts": ["Judging an amplifier's high-frequency response by the sharpness of a square-wave output.", "Spotting ringing or overshoot in a filter using a square-wave test.", "Estimating slew-rate limits by driving a stage with a fast square wave."]}, "a376342f-d32e-408f-930b-407c1f635682": {"definition": "A studio calibration kit is a set of tools - typically a calibrated measurement microphone, an acoustic (SPL) calibrator, reference test signals, and analysis software - assembled to set a studio's monitoring for correct level and frequency response. It lets an engineer align each monitor to a defined sound pressure level for a reference signal and measure the in-room response so mixes translate consistently to other systems.", "plain_english": "A studio calibration kit is a bundle of tools for setting up studio monitors. It usually holds a measurement microphone, a level calibrator, test sounds, and software. You use it to set each speaker to the right loudness and to check the room's response. This helps your mixes sound right elsewhere.", "purpose_function": "It exists to give a studio a repeatable, measurement-based monitoring reference for level and tonal balance. Consistent monitoring is what lets mixes made in one room translate reliably to other rooms and playback systems.", "practical_application": "An engineer uses the kit's microphone and software to set each monitor so a reference signal reads a target SPL, then measures and corrects the in-room frequency response.", "category": "Calibration", "related_terms": ["Measurement microphone", "SPL calibrator", "Monitor calibration", "Real-time analyzer (RTA)", "Reference level", "Frequency response"], "common_mistakes": ["Trusting the analysis without a calibrated microphone, so the measured curve is inaccurate.", "Correcting the room only with equalization, when severe response problems need acoustic treatment first.", "Measuring at one microphone position, which can miss how response changes across the listening area."], "scenario_contexts": ["Setting each monitor to a reference SPL so level judgments are consistent day to day.", "Measuring and correcting a control room's in-room frequency response.", "Checking that a newly installed monitoring system matches an agreed target curve."]}, "4cd813c1-63d1-420e-b68c-2f588f068639": {"definition": "A sweep oscillator is a signal generator that produces a sine tone whose frequency changes continuously across a defined range, either linearly or logarithmically, over a set time. In acoustic and audio measurement it excites a system or room across the audio band as a swept-sine (log-sweep) stimulus so its frequency response, distortion, and impulse response can be captured.", "plain_english": "A sweep oscillator makes a tone that slides smoothly from low notes up to high notes. It plays each frequency in turn, like a siren rising in pitch. This lets you see how a speaker or room reacts at every frequency. Engineers record the result to measure the sound.", "purpose_function": "It exists to feed a known, controlled tone that covers the whole frequency range into a system under test. This lets an analyzer measure response and distortion frequency by frequency.", "practical_application": "A technician plays a logarithmic sine sweep through a loudspeaker and records it with measurement software to obtain the frequency and impulse response of the system in the room.", "category": "Signal generator", "related_terms": ["Swept-sine measurement", "Frequency response", "Impulse response", "Signal generator", "Function generator", "Total harmonic distortion (THD)"], "common_mistakes": ["Sweeping too fast, so the room or system cannot settle, which smears the measured response.", "Assuming a swept-sine and a stepped-tone measurement give identical results in a reverberant room.", "UNSAFE: Running a full-level sweep through headphones or monitors while close to them, risking hearing damage."], "scenario_contexts": ["Measuring the frequency response of a studio monitor using a logarithmic sine sweep.", "Capturing a room impulse response for reverberation-time analysis with a swept sine.", "Testing an amplifier for distortion at each frequency across the audio band."]}, "24437bf8-d674-4cb4-91bf-2bc1bc928266": {"definition": "Impulse (\"I\") time weighting is a standardized time-averaging characteristic for sound level meters, originally defined in the now-superseded IEC 60651, that uses a very fast 35 ms rise time constant and a much slower 1500 ms decay. It is not a normative time weighting in IEC 61672-1, which retains it only in an informative annex. It is designed to follow brief, impulsive sounds while holding the reading long enough to be read, and is now largely deprecated in favour of Fast, Slow, and true peak metrics.", "plain_english": "Impulse is a setting on a sound meter for very short, sharp sounds. It reacts fast when the sound hits, then drops slowly so you can read it. Think of a display that jumps up at once but eases back down. It is an old setting rarely used today.", "purpose_function": "It exists to make short bursts, like hammer blows or gunshots, visible on a meter that would otherwise miss them. The slow decay holds the momentary peak long enough for a person to read the display.", "practical_application": "A technician may find the Impulse setting on older sound level meters, but modern work generally uses Fast or Slow time weighting plus a separate true peak reading.", "category": "Time weighting", "related_terms": ["Sound level meter", "Fast time weighting", "Slow time weighting", "A-weighting", "Peak sound level", "Equivalent continuous level (Leq)"], "common_mistakes": ["Believing Impulse weighting measures true peak level, when a separate peak detector is required.", "Using Impulse for general noise surveys, when standards now specify Fast or Slow with Leq.", "Confusing the 35 ms rise with an instantaneous response, when true peak needs much faster detection."], "scenario_contexts": ["Reading an older sound level meter that offers Fast, Slow, and Impulse time weightings.", "Reviewing historical noise data that was recorded with Impulse weighting.", "Explaining why current occupational noise standards no longer rely on Impulse weighting."]}, "4cfeebbf-d3d2-47bc-a37b-09c44d8ed462": {"definition": "A tone burst generator is a signal source that produces a sine wave gated on for a specified number of cycles or duration and then off, creating a controlled short packet of tone separated by silence. It is used to test the transient and time-domain behaviour of loudspeakers, rooms, and audio equipment without the sustained energy of a continuous tone.", "plain_english": "A tone burst generator makes a short beep of one pitch, then stops, then repeats. The gaps let you see how gear reacts to a quick sound. It is like tapping a key once instead of holding it down. Engineers use it to test speakers and rooms.", "purpose_function": "It exists to deliver a brief, repeatable packet of a single frequency so a system's start-up, decay, and reflection behaviour can be observed apart from its steady-state response. The silence between bursts lets ringing or reflections be seen before the next burst arrives.", "practical_application": "A technician feeds tone bursts to a loudspeaker to check transient response and to separate the direct sound from early room reflections on an oscilloscope or analyzer.", "category": "Signal generator", "related_terms": ["Signal generator", "Sweep oscillator", "Impulse response", "Transient response", "Oscilloscope", "Early reflections"], "common_mistakes": ["Making the burst too long, so the room reaches steady state and the transient information is lost.", "Choosing a burst that does not start and end at zero crossings, adding clicks that inject spurious energy.", "Confusing a tone burst with a single impulse, when a burst still contains many cycles of one frequency."], "scenario_contexts": ["Testing a tweeter's transient response with a few-cycle high-frequency burst.", "Separating direct sound from first reflections when measuring a room.", "Evaluating amplifier or driver behaviour under short, high-level demands."]}, "9d123b5e-9949-4578-a929-45e0a81089fa": {"definition": "A tone injector is a compact test tool that introduces a known audio tone, commonly a fixed 1 kHz sine or a selectable frequency, into a signal path, cable, or input for tracing signal flow and confirming continuity and gain. It is typically used with a signal tracer or probe to follow the injected tone through a system and locate breaks or faulty stages.", "plain_english": "A tone injector sends a steady test tone into a cable or device. You then follow that tone through the system to find where the signal stops. It is like putting dye in a pipe to find a leak. It helps locate faults fast.", "purpose_function": "It exists to place a known signal into a system so a technician can trace where that signal goes and where it disappears. This turns silent, hard-to-find wiring and stage faults into something you can hear or measure.", "practical_application": "A technician injects a 1 kHz tone at a stage box and probes down the signal chain to find the cable or connector where the tone is lost.", "category": "Service instrument", "related_terms": ["Signal tracer", "Signal generator", "Continuity test", "Cable tester", "Signal flow", "Oscillator"], "common_mistakes": ["Injecting a hot line-level tone into a microphone input, overloading the preamp and giving a false result.", "Not matching the injected level to the stage under test, which gives misleading readings.", "Assuming a passed tone means the channel is fully working, when noise or distortion may remain."], "scenario_contexts": ["Tracing a dead channel from a stage box back to the console input.", "Verifying that a patch bay routes signal to the correct destination.", "Checking continuity of a long multicore run before a show."]}, "2a77635e-6b2d-42bc-9f34-e31c2b9b5166": {"definition": "A transfer-function analyzer is a dual-channel FFT measurement system that compares a reference input signal to the measured output of a device or system, computing the complex ratio between them to display magnitude (frequency response), phase, and coherence versus frequency. It can characterize a system using program material or noise as the stimulus, rather than requiring a controlled test tone.", "plain_english": "A transfer-function analyzer compares what goes into a system with what comes out. It shows how the sound changed at each frequency, plus the timing and how trustworthy the data is. It is like comparing a recipe's ingredients with the finished dish. Engineers use it to tune sound systems.", "purpose_function": "It exists to reveal how a system changes a signal in level, timing, and phase across frequency, using almost any signal as the source. This lets engineers set EQ, delay, and levels so the system reproduces the intended sound.", "practical_application": "A technician uses a transfer-function analyzer such as Smaart to compare a console output with a measurement microphone and adjust system EQ and speaker delays during setup.", "category": "Measurement analyzer", "related_terms": ["Transfer function", "Coherence", "Phase analyzer", "Real-time analyzer (RTA)", "FFT analyzer", "Impulse response"], "common_mistakes": ["Trusting magnitude and phase data where coherence is low, which gives unreliable readings.", "Failing to time-align the two channels with a delay finder before measuring, which corrupts the phase trace.", "Equalizing to flatten room reflections that the ear does not hear as coloration."], "scenario_contexts": ["Tuning a live PA by comparing the drive signal to a measurement microphone.", "Time-aligning subwoofers and mains using measured phase and delay.", "Verifying that an installed system meets a target response curve."]}, "21ec0019-2723-4b20-b53a-4def9a4942d4": {"definition": "A true-RMS multimeter computes the actual root-mean-square value of an AC voltage or current by integrating the squared waveform, giving an accurate reading for non-sinusoidal signals such as audio, dimmer-chopped mains, or complex noise. This contrasts with average-responding meters, which are calibrated for pure sine waves and misread distorted or complex waveforms.", "plain_english": "A true-RMS multimeter measures the real strength of an AC signal. It stays accurate even when the wave is not a clean sine shape. Cheaper meters assume a perfect wave, so they get complex signals wrong. It is like weighing something exactly instead of guessing. This matters for audio and mains power.", "purpose_function": "It exists to give a correct AC measurement for real-world waveforms that are not pure sine waves. Average-responding meters read only sine waves accurately, so distorted signals need true RMS.", "practical_application": "A technician uses a true-RMS meter to check mains voltage on a dimmer-fed circuit or to read the AC voltage on a loudspeaker line to estimate delivered power.", "category": "Test instrument", "related_terms": ["Multimeter", "RMS (root mean square)", "AC voltage", "Crest factor", "Oscilloscope", "Continuity test"], "common_mistakes": ["UNSAFE: Measuring mains with a meter or leads rated below the circuit's CAT category, risking arc flash or shock.", "UNSAFE: Leaving the probes in the current jacks and connecting across a live voltage source, causing a short circuit.", "Assuming an average-responding meter reads audio or dimmer waveforms correctly.", "Ignoring the meter's crest factor limit, which caps accurate readings of very peaky waveforms."], "scenario_contexts": ["Checking mains voltage on a phase-controlled dimmer circuit at a live event.", "Measuring the AC voltage across a loudspeaker to estimate delivered power.", "Verifying supply voltage before powering sensitive audio equipment."]}, "ded4375c-5042-4847-94b2-c2aede722a01": {"definition": "A white-noise source is a signal generator that produces white noise, a random broadband signal whose power spectral density is constant per hertz, so it contains equal power in every equal-width frequency band. Because equal power per hertz means the power doubles each octave, white noise sounds bright and is used as a test stimulus and, when filtered at 3 dB per octave, as the basis for pink noise.", "plain_english": "A white-noise source makes a steady hiss that holds equal power at every frequency step. Because high notes are packed closer together, it sounds bright and hissy, like radio static. Engineers use it to test gear and rooms. Filtering it makes pink noise.", "purpose_function": "It exists to provide a repeatable broadband test signal that excites all frequencies at once. This lets analyzers measure a system's response across the whole band quickly, and it serves as the raw signal for making pink noise.", "practical_application": "A technician feeds white noise into a system and views it on an analyzer, or filters it down to pink noise for room and loudspeaker measurements.", "category": "Test signal source", "related_terms": ["Pink-noise source", "Power spectral density", "Real-time analyzer (RTA)", "Frequency response", "Signal generator", "Octave band"], "common_mistakes": ["Confusing white noise with pink noise, when white noise rises 3 dB per octave on an octave-band analyzer.", "Expecting white noise to look flat on a fractional-octave (RTA) display, when pink noise is the flat one.", "UNSAFE: Playing broadband noise at high level through monitors while standing close, risking hearing damage."], "scenario_contexts": ["Driving an audio analyzer to check a device's broadband frequency response.", "Generating pink noise by filtering a white-noise source for room tuning.", "Testing for channel dropouts by sending steady noise through a signal path."]}, "bf46ddd1-3396-4d6c-b42c-b763a8d9bb4b": {"definition": "An XLR cable tester is a test instrument that verifies the pin-to-pin continuity and wiring integrity of balanced audio cables terminated in XLR (and often other) connectors, checking pins 1 (shield/ground), 2 (hot/+), and 3 (cold/-) for continuity, opens, shorts, and mis-wires. Many units also reveal intermittent faults by letting the operator flex the cable while indicating each conductor's status.", "plain_english": "An XLR cable tester checks that a mic cable is wired correctly end to end. It lights up each of the three pins to show good connections, breaks, or crossed wires. It is like a quick health check for a cable. It catches faults before they ruin a show.", "purpose_function": "It exists to quickly confirm that a balanced cable's three conductors are continuous and correctly wired before use. Catching an open, short, or swapped pin in advance prevents hum, dropouts, and lost signal during a session or show.", "practical_application": "A technician runs each mic cable through the tester before a gig, flexing the ends to catch intermittent breaks near the connectors.", "category": "Service instrument", "related_terms": ["Balanced audio", "XLR connector", "Continuity test", "Polarity", "Signal tracer", "Shielding"], "common_mistakes": ["Assuming a passed continuity test means a silent cable, when it can still be noisy or fail under flexing.", "Not flexing the cable at the connectors during the test, missing breaks that appear only under movement.", "Confusing a swapped pin 2 and pin 3 (polarity reversal) with a broken cable, when both show as a fault."], "scenario_contexts": ["Checking a batch of mic cables before a live event to pull the faulty ones.", "Diagnosing a channel with hum or no signal by testing its cable first.", "Verifying that a newly soldered XLR cable is wired pin-for-pin correctly."]}, "2a8ea3d1-dcd8-4a57-99eb-30392ceea859": {"definition": "An accelerometer measurement uses an accelerometer, a transducer whose output (voltage or charge) is proportional to acceleration, to quantify the vibration or mechanical motion of a structure or device. In audio and electroacoustics it characterizes the vibration of loudspeaker cabinets, transducer diaphragms, and mechanical assemblies, and its output can be integrated to yield velocity or displacement.", "plain_english": "An accelerometer measurement uses a small sensor stuck to an object. The sensor turns shaking into an electrical signal. Engineers read that signal to see how much a part vibrates. It helps find rattles and buzzes in speakers and gear.", "purpose_function": "It exists to turn mechanical vibration into a measurable electrical signal so motion can be quantified. This lets engineers study how parts move, resonate, and pass unwanted vibration into a system.", "practical_application": "A technician bonds an accelerometer to a loudspeaker cabinet or bracket, plays a test signal, and reads the vibration spectrum to locate resonances or buzzes.", "category": "Vibration measurement", "related_terms": ["Transducer", "Resonance", "Frequency response", "Piezoelectric sensor", "Charge amplifier", "Vibration analysis"], "common_mistakes": ["Ignoring the accelerometer's own added mass, which loads light structures and shifts their measured resonances.", "Forgetting that acceleration must be integrated to obtain velocity or displacement, which are different quantities.", "Mounting the sensor poorly, so a loose or soft attachment corrupts the high-frequency reading."], "scenario_contexts": ["Finding a buzz or rattle in a loudspeaker cabinet by mapping where it vibrates most.", "Measuring how much vibration a power transformer passes into a chassis.", "Checking cone or diaphragm motion during transducer development."]}, "af395bd6-2629-443f-b471-9cd0d70b3143": {"definition": "Acoustic transparency measurement quantifies how faithfully sound passes through a material, device, or feature with minimal attenuation or tonal coloration, such as a loudspeaker grille cloth, a microphone windscreen, or the hear-through (\"transparency\") mode of a headset. It typically compares the spectrum and level of sound with and without the object in the path, expressed as insertion loss or transmission versus frequency.", "plain_english": "Acoustic transparency measurement checks how well sound passes through something. Think of speaker grille cloth or a headset's listen-through mode. Engineers compare the sound with and without the object in the way. A clear result means the object barely changes the sound.", "purpose_function": "It exists to verify that a material or feature lets sound through without unwanted loss or tonal change. This confirms that grilles, windscreens, and hear-through modes work without harming sound quality.", "practical_application": "A technician measures a signal through the object or in a headset's transparency mode, then compares it to the open path to see how much the level and tone change.", "category": "Acoustic measurement", "related_terms": ["Insertion loss", "Frequency response", "Transfer function", "Measurement microphone", "Windscreen", "Attenuation"], "common_mistakes": ["Measuring overall level only and ignoring tonal change, which hides frequency-dependent losses.", "Forgetting that adding a grille or screen can cause reflections and resonances, not just simple attenuation.", "Comparing results without a consistent open-path reference measurement."], "scenario_contexts": ["Checking how much a loudspeaker grille cloth attenuates high frequencies.", "Evaluating a microphone windscreen's effect on the captured spectrum.", "Testing the hear-through mode of noise-cancelling headphones for natural sound."]}, "a255367e-8d3f-48b8-86af-085d6e5df3be": {"definition": "An ANSI measurement standard is a consensus standard approved by the American National Standards Institute (ANSI) that defines how a quantity is measured, including terminology, test conditions, instrument specifications, and procedures, so that results are consistent and comparable. ANSI accredits the developing bodies rather than writing standards itself; in acoustics these are developed by the Acoustical Society of America and designated, for example, ANSI/ASA S1.4 (sound level meters) and ANSI/ASA S1.11 (octave-band filters).", "plain_english": "An ANSI measurement standard is an agreed rulebook for how to measure something. It says what gear to use and how to run the test. Following it means different labs get matching results. In sound work these cover tools like sound level meters.", "purpose_function": "It exists to make measurements repeatable and comparable across people, labs, and instruments. Shared rules let a result from one lab be trusted and re-checked by another.", "practical_application": "A technician follows the relevant ANSI/ASA standard when choosing a sound level meter class and running a noise measurement, so the results are defensible and comparable.", "category": "Measurement standard", "related_terms": ["Sound level meter", "IEC 61672", "Calibration", "A-weighting", "Octave band", "Traceability"], "common_mistakes": ["Assuming ANSI writes the standards itself, when it approves standards developed by bodies such as the Acoustical Society of America.", "Treating an ANSI standard and its IEC counterpart as identical, when details and tolerances can differ.", "Citing a withdrawn or superseded edition instead of the current version."], "scenario_contexts": ["Choosing a sound level meter that meets the class required by an ANSI/ASA standard.", "Running an octave-band analysis to a defined ANSI filter specification.", "Documenting a noise survey method against the applicable ANSI standard."]}, "2e5b5420-fc93-425f-937b-8edb167a5dad": {"definition": "A calibration interval is the specified period of time or amount of use between successive calibrations of a measuring instrument, set so the instrument stays within its stated tolerance throughout the interval. It is chosen from factors such as the instrument's stability and drift history, manufacturer recommendation, how heavily it is used, and the consequences of an out-of-tolerance reading.", "plain_english": "A calibration interval is how long you can use a measuring tool before checking it again. Tools drift over time, so they need re-checking. A shorter interval catches that drift sooner. Labs set the interval based on how the tool is used.", "purpose_function": "It exists to keep instruments trustworthy by limiting how long they run between accuracy checks. A sensible interval balances confidence in the readings against the cost and downtime of calibration.", "practical_application": "A lab tags each instrument with a due date based on its calibration interval, then pulls it from service for recalibration when that date arrives.", "category": "Calibration", "related_terms": ["Calibration", "Traceability", "Drift", "Tolerance", "Reference standard", "Measurement uncertainty"], "common_mistakes": ["Treating the interval as fixed, when drift history and usage should be used to lengthen or shorten it.", "Using an instrument past its due date and trusting its readings anyway.", "Confusing a calibration check with an adjustment, which are separate steps."], "scenario_contexts": ["Scheduling annual calibration of a sound level meter to keep it standards-compliant.", "Shortening the interval for an instrument that keeps drifting near its tolerance limit.", "Auditing a lab's instruments to confirm none are overdue for calibration."]}, "df0563d7-af9a-4c06-a258-01de35cdcc90": {"definition": "A pistonphone is a precision acoustic calibrator that produces a known, highly stable sound pressure level at a low reference frequency by driving small pistons through a fixed displacement in a sealed coupler cavity into which the measurement microphone is inserted. A common type generates 124 dB SPL at 250 Hz, its output requires a barometric-pressure correction, and its performance classes are defined by IEC 60942.", "plain_english": "A pistonphone is a tool that makes an exact, steady sound level for calibration. Tiny pistons push air in a sealed space around the microphone. This gives a known loudness to set the meter against. You must correct its reading for air pressure.", "purpose_function": "It provides a very stable, traceable sound pressure reference so a measurement microphone and meter can be adjusted to read correctly. Its mechanical piston drive makes it more stable than simpler loudspeaker-based calibrators.", "practical_application": "A technician inserts the measurement microphone into the pistonphone coupler, applies the barometric-pressure correction, and adjusts the system to read the stated reference level before measuring.", "category": "Acoustic calibrator", "related_terms": ["SPL calibrator", "Measurement microphone", "Sound pressure level (SPL)", "Calibration", "IEC 60942", "Sound level meter"], "common_mistakes": ["Skipping the barometric-pressure correction, which shifts the true output from the nominal level.", "Using a microphone whose diameter does not match the coupler, spoiling the seal and the level.", "Confusing a pistonphone with a simpler loudspeaker-type calibrator of lower stability."], "scenario_contexts": ["Calibrating a measurement microphone in the lab to a traceable reference before field work.", "Setting the reference sensitivity of a sound level meter for a precision noise study.", "Verifying microphone sensitivity as part of periodic instrument calibration."]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"f1d70523-39eb-449a-9bb3-6d20765a8c53": {"definition": "Device-under-test (DUT) evaluation is the process of measuring and assessing the performance of the specific unit being tested by applying defined stimulus signals and measuring its responses against specifications or reference values. In audio it covers parameters such as frequency response, THD+N, noise, gain, and crosstalk, using a signal generator and analyzer connected to the DUT's inputs and outputs.", "plain_english": "Device-under-test evaluation means testing the exact piece of gear in front of you. You feed it known signals and measure what comes out. Then you compare the results to its specs. This shows whether the unit works correctly.", "purpose_function": "It exists to confirm that a specific unit meets its performance specification, or to find where it falls short. This supports design checks, production pass/fail testing, and repair verification.", "practical_application": "A technician connects a generator to the DUT input and an analyzer to its output, runs a test sequence, and compares measured frequency response and THD+N against pass/fail limits.", "category": "Test procedure", "related_terms": ["Precision audio analyzer", "Signal generator", "THD+N", "Frequency response", "Reference level", "Crosstalk"], "common_mistakes": ["Blaming the DUT for errors actually caused by test leads, adapters, or the analyzer's own residual limits.", "Failing to set correct input and output levels, which can clip the DUT or push it below its noise floor.", "Not documenting the test conditions, so the results cannot be reproduced."], "scenario_contexts": ["Production-line testing of a mixer channel against pass/fail limits.", "Verifying an amplifier's published specifications after a repair.", "Characterizing a new converter's performance during design."]}, "a942fe66-0d3e-4a79-b784-51bc207e8ef7": {"definition": "A diffuse-field chamber (reverberation room) is a hard-walled, highly reflective test room designed to produce an approximately diffuse sound field, in which sound energy density is uniform throughout and sound arrives from all directions with random phase. It is used for measurements that assume random-incidence conditions, such as sound power determination, absorption-coefficient testing, and diffuse-field microphone calibration.", "plain_english": "A diffuse-field chamber is a very reflective test room. Sound bounces so much that it fills the room evenly. It seems to come from every direction at once. Engineers use it to measure sound power and how well materials absorb sound.", "purpose_function": "It exists to create a uniform, all-directions sound field so measurements do not depend on where you stand or point. This suits tests, such as sound power and absorption, that assume random-incidence sound.", "practical_application": "A technician places a source or a material sample in the chamber and measures the reverberant field to determine sound power or an absorption coefficient.", "category": "Test chamber", "related_terms": ["Anechoic chamber", "Reverberation time", "Sound power", "Absorption coefficient", "Random incidence", "Measurement microphone"], "common_mistakes": ["Confusing a diffuse-field chamber with an anechoic chamber, which is the opposite, nearly reflection-free space.", "Assuming the field is diffuse at low frequencies, where sparse room modes break the assumption.", "Using a free-field microphone where a random-incidence or diffuse-field response is required."], "scenario_contexts": ["Measuring the sound power of a product to a standard method.", "Determining a material's random-incidence sound absorption coefficient.", "Calibrating or checking diffuse-field measurement microphones."]}, "b37277ce-adf5-49ac-a0f1-bd7cd8c3a8b3": {"definition": "Electroacoustic characterization is the systematic measurement of the performance of electroacoustic transducers and systems, such as microphones, loudspeakers, headphones, and telephones, that convert between electrical and acoustic energy. It quantifies parameters including frequency response, sensitivity, directivity, impedance, distortion, and maximum SPL under defined conditions, following standards such as the IEC 60268 series.", "plain_english": "This term means fully testing gear that changes electricity into sound, or sound into electricity. Speakers, microphones, and headphones all count. Engineers measure how it responds and how clean it stays. The results show how the device really performs.", "purpose_function": "It exists to describe how a transducer or system performs so it can be compared, verified against specifications, and used correctly in a design. Standard methods make these results trustworthy and comparable.", "practical_application": "An engineer measures a loudspeaker's or microphone's frequency response, sensitivity, and distortion in a controlled environment to produce a data sheet or verify a specification.", "category": "Electroacoustic measurement", "related_terms": ["Frequency response", "Sensitivity", "Directivity", "Total harmonic distortion", "Measurement microphone", "Anechoic chamber"], "common_mistakes": ["Measuring in an untreated room, so reflections corrupt the transducer's true response.", "Reporting sensitivity without stating the drive level and distance, which makes the number meaningless.", "Ignoring the standard's defined conditions, so results cannot be compared with others."], "scenario_contexts": ["Producing a loudspeaker data sheet from anechoic measurements.", "Verifying a microphone's sensitivity and frequency response against its specification.", "Characterizing headphones on a head-and-torso simulator."]}, "d2cdbe15-83da-4495-92c5-083d19121381": {"definition": "An environmental test chamber is an enclosure that creates and controls specified environmental conditions, such as temperature, humidity, and sometimes pressure, thermal cycling, or vibration, so equipment can be tested for performance and reliability under those conditions. In audio manufacturing it verifies that transducers and electronics meet their operating and storage specifications across the rated environmental range.", "plain_english": "An environmental test chamber is a sealed box that controls conditions like heat and humidity. Gear is placed inside and exposed to set conditions. Engineers then check that it still works. This proves products can survive harsh real-world use.", "purpose_function": "It exists to expose equipment to controlled, repeatable environmental stress so its performance and reliability can be verified. This catches temperature- and humidity-related failures before products reach the field.", "practical_application": "A technician places a device in the chamber, runs a temperature and humidity profile, and checks that it operates within specification during and after the exposure.", "category": "Test chamber", "related_terms": ["Device-under-test evaluation", "Diffuse-field chamber", "Reliability testing", "Thermal cycling", "Humidity", "Vibration analysis"], "common_mistakes": ["Overloading the chamber so airflow is blocked, giving uneven temperature around the device.", "Running a test without powering or monitoring the device, so intermittent faults go unseen.", "UNSAFE: Reaching into or unloading a chamber after extreme-temperature runs without following the manufacturer's handling procedure, risking burns, frostbite, or contact with hazardous condensate."], "scenario_contexts": ["Confirming a wireless microphone still works from cold outdoor to hot stage conditions.", "Running a humidity soak to check a mixer survives storage in a damp warehouse.", "Thermal cycling electronics to expose weak solder joints before shipping."]}, "527f1b1b-3098-4fac-ac2a-6cad1c9f6270": {"definition": "FFT overlap is a processing setting in FFT-based signal analysis in which each successive analysis frame (time window) shares a portion of the samples used by the previous frame, expressed as a percentage such as 50% or 75%. Overlapping frames compensates for the amplitude weighting of the window function, which attenuates data near each frame's edges, and increases the rate of spectral updates and the number of averages available in a given time.", "plain_english": "FFT overlap means each new chunk of sound the analyzer studies shares part of the last chunk. A window fades the edges of every chunk, so data there counts for less. Overlapping the chunks makes up for that lost data. It also gives smoother, faster updates on screen.", "purpose_function": "It exists to recover data lost to the tapering of the window function and to raise the update rate and averaging of an FFT measurement. This yields a steadier, more time-responsive spectrum without lengthening the analysis window.", "practical_application": "A system technician sets FFT overlap (often 50% or 75%) in analysis software so the transfer-function or spectrum display updates smoothly and responds quickly while tuning a live system.", "category": "FFT parameter", "related_terms": ["Fast Fourier transform (FFT)", "Window function", "Averaging", "Frequency resolution", "Spectrogram", "Transfer function"], "common_mistakes": ["Assuming higher overlap adds new information, when it only reuses samples and increases update rate and averaging.", "Confusing FFT overlap with frequency resolution, which is set by the window length and sample rate, not the overlap.", "Using very high overlap and interpreting closely spaced frames as statistically independent averages."], "scenario_contexts": ["Setting overlap in Smaart or similar software so a live transfer-function trace responds smoothly.", "Producing a detailed spectrogram where overlapping frames give better time continuity.", "Increasing averaging in a fixed measurement time by overlapping successive FFT frames."]}, "0e63e0ee-98f9-4d61-878f-33b56e9cf0b5": {"definition": "A free-field chamber (anechoic chamber) is a test room whose boundaries are lined with sound-absorbing wedges so that, above a cutoff frequency, they reflect negligible sound energy, approximating free-field conditions in which sound radiates outward without reflections. Such chambers are used for acoustic measurements of loudspeakers, microphones, and noise sources, and their qualification is defined by standards such as ISO 3745 and ISO 26101.", "plain_english": "A free-field chamber is a room built to have no echoes. Its walls, floor, and ceiling are covered in sound-soaking wedges. Sound leaves a source and never bounces back. This lets engineers measure a speaker or microphone on its own, without the room changing the result.", "purpose_function": "It exists to remove reflections so a device can be measured as if it were in open space with no boundaries. This gives clean, repeatable acoustic measurements that are not corrupted by room reflections.", "practical_application": "An acoustics technician measures a loudspeaker's on- and off-axis frequency response in a free-field chamber, knowing the result reflects the device itself rather than the room.", "category": "Test environment", "related_terms": ["Anechoic chamber", "Free field", "Reverberation chamber", "Sound power", "Measurement microphone", "Frequency response"], "common_mistakes": ["Assuming a chamber is anechoic at all frequencies, when absorption fails below the wedges' cutoff frequency.", "Confusing a full free-field (anechoic) chamber with a hemi-anechoic room that has a hard, reflective floor.", "Ignoring background noise and vibration isolation, which still limit low-level measurements in the chamber."], "scenario_contexts": ["Measuring a loudspeaker's anechoic frequency response for a datasheet.", "Determining a machine's sound power level under free-field conditions per ISO 3745.", "Calibrating or characterizing microphones without room reflections."]}, "afc92060-a04c-48cc-bd65-89289fa87efa": {"definition": "A humidity-controlled chamber is an enclosed test environment that actively maintains relative humidity (usually together with temperature) at defined, stable values, so that equipment can be conditioned or measured under controlled and repeatable atmospheric conditions. Controlled humidity matters because moisture affects electrical, mechanical, and acoustic behavior, and because reference conditions for calibration and environmental testing are specified in standards such as IEC 60068 and IEC 61094.", "plain_english": "A humidity-controlled chamber is a sealed space that holds the air's moisture at a set level. It usually holds temperature steady too. Damp or dry air can change how gear and microphones behave. Testing in fixed conditions makes results fair and repeatable.", "purpose_function": "It exists to keep humidity (and usually temperature) constant so measurements and conditioning happen under known, repeatable atmospheric conditions. This removes moisture and temperature as hidden variables in a test result.", "practical_application": "A test technician conditions or measures equipment, such as measurement microphones or electronics, inside the chamber so readings are taken at the reference humidity and temperature specified by the applicable standard.", "category": "Test environment", "related_terms": ["Environmental chamber", "Reference conditions", "Calibration", "Laboratory calibration microphone", "Temperature coefficient", "IEC 60068"], "common_mistakes": ["Recording measurements before the chamber and the item under test have stabilized at the set conditions.", "Ignoring how humidity and temperature shift microphone sensitivity and static pressure during precise acoustic work.", "Assuming controlled humidity alone is enough, when temperature and static pressure also affect the reference conditions."], "scenario_contexts": ["Conditioning devices at a set temperature and humidity before a calibration.", "Environmental testing of audio electronics against IEC 60068 damp-heat conditions.", "Holding reference conditions while calibrating measurement microphones."]}, "9764b169-a03d-4411-a2d6-4cb41366338d": {"definition": "An insertion-loss measurement quantifies the reduction in signal power (or level) delivered to a load caused by inserting a device or component into a transmission path, expressed in decibels as the ratio of the power delivered before insertion to the power delivered after insertion. It is applied to filters, attenuators, cables, connectors, and transformers electrically, and to barriers, silencers, and enclosures acoustically.", "plain_english": "Insertion loss is how much a signal drops when you add a part into its path. You measure the level before and after adding the part. The difference, in decibels, is the loss. Engineers use it to check filters, cables, and connectors.", "purpose_function": "It exists to characterize how much signal a component removes when placed in a path, so its effect on a system can be predicted and budgeted. This lets engineers verify parts meet specification and account for losses in a signal chain.", "practical_application": "A technician measures the reference level of a path, inserts the device under test, measures again, and reports the difference in decibels as the insertion loss across the frequency band of interest.", "category": "Measurement technique", "related_terms": ["Attenuation", "Return loss", "Frequency response", "Impedance matching", "Filter", "Decibel (dB)"], "common_mistakes": ["Confusing insertion loss with return loss; one measures transmitted loss, the other reflected energy.", "Failing to establish a proper reference measurement before inserting the device, giving a wrong loss value.", "Ignoring source and load impedance, which change the measured insertion loss of the same device."], "scenario_contexts": ["Measuring the insertion loss of an audio filter or attenuator across frequency.", "Checking loss added by long cable runs, connectors, or a patch bay.", "Rating the acoustic insertion loss of an enclosure, silencer, or barrier."]}, "9f289e93-2431-4563-9fcd-0cfcf7d18a01": {"definition": "International Electrotechnical Commission (IEC) compliance is the conformity of a product, measurement method, or test procedure with the relevant standards published by the IEC, the international standards body for electrical, electronic, and related technologies. In professional audio this includes standards such as IEC 60268 for sound system equipment, IEC 61672 for sound level meters, and IEC 61094 for measurement microphones.", "plain_english": "IEC compliance means a product or test follows rules from a group called the IEC. The IEC sets shared electrical and audio standards for the whole world. Meeting them helps gear stay safe. It also lets people trust test results.", "purpose_function": "It exists so that equipment and measurements meet internationally agreed technical requirements, making results comparable and equipment interoperable and safe. This gives manufacturers, labs, and buyers a common technical language.", "practical_application": "A technician measures or specifies equipment against the cited IEC standard, such as testing a sound level meter to IEC 61672, so the result can be stated as compliant with that standard.", "category": "Standards compliance", "related_terms": ["International Organization for Standardization compliance", "Laboratory accreditation", "IEC 61672", "IEC 60268", "Sound level meter", "Measurement microphone"], "common_mistakes": ["Confusing the IEC with the ISO; the IEC covers electrical and electronic standards specifically.", "Claiming general compliance without naming the specific IEC standard and class actually met.", "Assuming compliance is permanent, when it depends on the current edition of the standard and ongoing conformity."], "scenario_contexts": ["Testing a sound level meter to the class requirements of IEC 61672.", "Specifying sound system equipment against the IEC 60268 series.", "Selecting measurement microphones that meet IEC 61094 or IEC 61672 requirements."]}, "72b02ded-3faa-4d0f-8fbd-3a2256294e9c": {"definition": "International Organization for Standardization (ISO) compliance is the conformity of a product, process, laboratory, or measurement method with the relevant standards published by the ISO, an independent international body that develops voluntary consensus standards across many fields. In audio and acoustics this includes standards such as ISO 226 (equal-loudness contours), ISO 3382 (room acoustics), ISO 3745 (sound power), and, jointly with the IEC, ISO/IEC 17025 for testing and calibration laboratories.", "plain_english": "ISO compliance means following rules from a group called the ISO. The ISO writes agreed standards for many fields, including sound. Meeting them shows a product or lab works to a known, shared standard. People around the world accept that standard.", "purpose_function": "It exists so that products, processes, and measurements meet internationally agreed requirements, making results comparable and trusted worldwide. This supports quality, safety, and interoperability across borders and organizations.", "practical_application": "A technician performs a measurement to the cited ISO method, such as measuring reverberation time to ISO 3382, so the result can be reported as compliant with that standard.", "category": "Standards compliance", "related_terms": ["International Electrotechnical Commission compliance", "Laboratory accreditation", "ISO/IEC 17025", "ISO 3382", "Reverberation time", "Quality management"], "common_mistakes": ["Confusing ISO with the IEC, which specifically covers electrical and electronic standards.", "Stating compliance without citing the exact ISO standard, part, and edition followed.", "Assuming an ISO 9001 quality certificate proves technical measurement competence, which ISO/IEC 17025 covers."], "scenario_contexts": ["Measuring room reverberation time to the ISO 3382 method.", "Determining sound power under free-field conditions per ISO 3745.", "Running a testing laboratory to the requirements of ISO/IEC 17025."]}, "85520894-fbe4-4278-9238-64e4cfc5d6b3": {"definition": "Laboratory accreditation is the formal recognition, by an authoritative accreditation body, that a testing or calibration laboratory is technically competent to perform specific tests or calibrations, assessed against the international standard ISO/IEC 17025. Accreditation covers the laboratory's management system, personnel competence, methods, equipment, and measurement traceability, and is granted for a defined scope of activities.", "plain_english": "Laboratory accreditation is official proof that a lab is fit to do certain tests. An outside body checks the lab against a strict standard. If it passes, others can trust its results. It works a bit like a license that says the lab knows its job.", "purpose_function": "It exists to give independent, documented confidence that a laboratory's results are technically valid and traceable. This lets customers, regulators, and other labs rely on the laboratory's measurements without re-testing.", "practical_application": "A technician working in an accredited lab follows validated methods and keeps traceable calibration records so the lab keeps its accreditation and can issue results within its accredited scope.", "category": "Standards compliance", "related_terms": ["ISO/IEC 17025", "Metrological traceability", "Calibration", "Laboratory documentation", "International Organization for Standardization compliance", "Measurement uncertainty"], "common_mistakes": ["Confusing accreditation with certification; accreditation attests technical competence for a defined scope.", "Assuming accreditation covers every test a lab performs, rather than only its stated accredited scope.", "Treating accreditation as permanent, when it requires ongoing surveillance and periodic reassessment."], "scenario_contexts": ["An acoustics lab gaining ISO/IEC 17025 accreditation for sound level meter calibration.", "A client requiring test reports from an accredited laboratory for compliance evidence.", "An assessor auditing a lab's methods, records, and traceability during reassessment."]}, "e4ade6ed-9838-4781-881a-09b193092c8e": {"definition": "A laboratory calibration microphone is a high-precision, stable measurement microphone - typically a laboratory-standard (LS) condenser type defined by IEC 61094-1 - whose electroacoustic properties are accurately known and traceable to national standards, used as a reference for calibrating other microphones and measurement systems. Such microphones are calibrated by primary methods, notably reciprocity calibration per IEC 61094-2, and serve as the top of the traceability chain in acoustic metrology.", "plain_english": "A laboratory calibration microphone is a very exact reference mic. Labs use it to check and adjust other mics. Its own response is known and traceable to national standards. Think of it as a master ruler. Other tools are measured against it.", "purpose_function": "It exists to provide a highly stable, accurately characterized acoustic reference at the top of the measurement chain. This lets a laboratory calibrate working microphones and systems with known, traceable accuracy.", "practical_application": "A calibration technician uses a laboratory-standard microphone, often via reciprocity or comparison methods, to establish the sensitivity of working microphones against a traceable reference.", "category": "Measurement microphone", "related_terms": ["Measurement microphone", "IEC 61094", "Reciprocity calibration", "Metrological traceability", "SPL calibrator", "Laboratory accreditation"], "common_mistakes": ["Treating an ordinary measurement microphone as a laboratory standard, which lacks the required stability and characterization.", "Using pressure and free-field calibrations interchangeably, when they apply to different sound-field conditions.", "Ignoring temperature, humidity, and static pressure, which shift the microphone's sensitivity during precise work."], "scenario_contexts": ["Calibrating working measurement microphones against a laboratory-standard reference.", "Performing reciprocity calibration to establish a microphone's sensitivity per IEC 61094-2.", "Maintaining acoustic measurement traceability to national standards in an accredited lab."]}, "f09e94db-0f8c-4aa6-ae21-dc8e560aafcf": {"definition": "Laboratory documentation is the controlled set of documents and records a testing or calibration laboratory maintains to define how work is performed and to prove that results are valid and traceable, including test and calibration methods, procedures, equipment and calibration records, and reports. Under ISO/IEC 17025 such documentation and record control are mandatory, ensuring measurements are repeatable, defensible, and auditable.", "plain_english": "Laboratory documentation is the full set of records a lab keeps. It covers test methods, procedures, and calibration results. These records prove the lab did the work correctly and the same way each time. Without them, a measurement cannot be trusted or repeated.", "purpose_function": "It exists to record how tests are done and to provide evidence that results are valid, traceable, and repeatable. This supports quality control, audits, and the defensibility of every reported measurement.", "practical_application": "A technician records equipment used, calibration status, method followed, conditions, and results for each measurement, so the work is traceable and can pass an audit.", "category": "Quality documentation", "related_terms": ["ISO/IEC 17025", "Laboratory accreditation", "Metrological traceability", "Calibration", "Measurement uncertainty", "Quality management"], "common_mistakes": ["Recording results without noting equipment, method, and conditions, which breaks traceability.", "Using uncontrolled or outdated procedure versions instead of the current controlled document.", "Failing to keep calibration and maintenance records that support the validity of measurements."], "scenario_contexts": ["Keeping method, equipment, and calibration records to satisfy an ISO/IEC 17025 audit.", "Documenting a measurement fully so another technician can repeat it exactly.", "Maintaining controlled procedures and calibration logs in an accredited laboratory."]}, "c459359f-2184-4303-9d77-aad6d6350f15": {"definition": "Laboratory quality assurance is the systematic set of planned management-system activities a testing or calibration laboratory uses to ensure its measurement results are valid, accurate, repeatable, and traceable. In acoustic and audio test work it follows ISO/IEC 17025, covering method validation, equipment calibration and traceability, control of environmental conditions, competence of staff, and ongoing quality control such as proficiency testing.", "plain_english": "Lab quality assurance is the set of rules a test lab follows to keep its results correct. It checks that gear is calibrated and that test methods really work. It also records the steps taken. This lets people trust the numbers the lab reports.", "purpose_function": "It exists to give documented confidence that a laboratory's results are reliable and comparable, not one-off or biased. This underpins certification, compliance testing, and any decision made from the lab's measurements.", "practical_application": "A test technician follows written procedures, logs equipment calibration due dates, runs control checks, and keeps records so that each result can be defended and reproduced during an audit.", "category": "Quality assurance", "related_terms": ["Measurement uncertainty", "National Institute of Standards and Technology traceability", "Calibration", "Laboratory reference microphone", "Proficiency testing", "Method validation"], "common_mistakes": ["Treating quality assurance as paperwork done once, rather than an ongoing system of checks and records.", "Using instruments past their calibration due date, which breaks traceability and invalidates results.", "Confusing quality assurance (the whole system that builds confidence) with quality control (the specific checks within it)."], "scenario_contexts": ["Preparing an acoustics lab for ISO/IEC 17025 accreditation assessment.", "Maintaining calibration records and control charts for a loudspeaker test facility.", "Investigating why a measured result fell outside expected limits during routine quality control."]}, "697d05e1-d635-4260-9212-fe7eb1792fca": {"definition": "A laboratory reference microphone is a high-precision measurement microphone, typically a laboratory standard (LS) condenser microphone conforming to IEC 61094-1, whose sensitivity is accurately determined by calibration (often pressure reciprocity per IEC 61094-2) and traceable to national standards. It serves as the reference against which working measurement microphones and acoustic systems are calibrated.", "plain_english": "A lab reference microphone is a very accurate, calibrated microphone. Its exact response is known and tied to national standards. Labs treat it as a yardstick. They use it to check and set up other microphones and meters.", "purpose_function": "It provides a stable, precisely known acoustic reference so that other microphones and measurement chains can be calibrated against a trusted standard. Without it, absolute sound level readings could not be traced or trusted.", "practical_application": "A calibration technician uses the reference microphone, together with a coupler or reciprocity setup, to determine the sensitivity of working microphones and to verify sound calibrators.", "category": "Measurement microphone", "related_terms": ["Measurement microphone", "SPL calibrator", "Pistonphone", "National Institute of Standards and Technology traceability", "Reciprocity calibration", "Sound pressure level (SPL)"], "common_mistakes": ["Using a reference microphone in the field for routine work, exposing a costly, delicate standard to damage and drift.", "Ignoring the pressure, temperature, and humidity corrections that its stated sensitivity assumes.", "Confusing a laboratory standard (LS) microphone with an ordinary working-standard measurement microphone of lower accuracy."], "scenario_contexts": ["Calibrating a batch of working measurement microphones against a traceable reference.", "Determining microphone sensitivity by the pressure reciprocity method in a metrology lab.", "Verifying that an acoustic calibrator produces its stated reference level."]}, "196bad11-2dff-4342-903e-ebfff01fe233": {"definition": "A laboratory sound chamber is a purpose-built, acoustically controlled room used to make acoustic measurements under defined, repeatable conditions. Common types are the anechoic or hemi-anechoic chamber, which creates a reflection-free (free-field) environment per ISO 3745/ISO 26101, and the reverberation room, which creates a diffuse, highly reflective field per ISO 354; both isolate the test from outside noise and vibration.", "plain_english": "A lab sound chamber is a special room built for accurate sound tests. There are different types. Some soak up all echoes, like a heavily padded room. Others are hard and echoey on purpose. Each gives a controlled space that is sealed off from outside noise.", "purpose_function": "It exists to remove the uncontrolled reflections and background noise of ordinary rooms, so a measurement reflects the device or material and not the surroundings. This makes results accurate, repeatable, and comparable between labs.", "practical_application": "A technician places a loudspeaker in an anechoic chamber to measure its true free-field frequency response, or uses a reverberation room to measure sound power or a material's absorption.", "category": "Test environment", "related_terms": ["Anechoic chamber", "Reverberation room", "Material absorption measurement", "Sound power", "Free field", "Laboratory reference microphone"], "common_mistakes": ["Assuming a chamber works at all frequencies, when an anechoic room has a low-frequency cutoff set by its wedge depth.", "Trusting free-field measurements without qualifying the chamber to ISO 26101 first.", "Confusing an anechoic chamber (reflection-free) with a reverberation room (deliberately diffuse and reflective)."], "scenario_contexts": ["Measuring a microphone or loudspeaker's free-field response in an anechoic chamber.", "Determining a machine's sound power level in a reverberation room.", "Measuring random-incidence absorption of an acoustic panel in a reverberation chamber."]}, "fe057d94-1a85-4ca1-8df1-7d2afba6a4c3": {"definition": "Laser vibrometry is a non-contact optical technique that uses a laser Doppler vibrometer to measure the velocity and displacement of a vibrating surface from the Doppler frequency shift of laser light reflected off it. Because it adds no mass and needs no physical contact, it is used to measure vibration of loudspeaker diaphragms, transducers, and structures; scanning versions map vibration across a whole surface.", "plain_english": "Laser vibrometry measures how a surface vibrates using a laser beam. It touches nothing, so it adds no weight to the object. Engineers aim it at a speaker cone to see exactly how it moves. It reads the motion from tiny shifts in the reflected light.", "purpose_function": "It exists to measure vibration accurately without loading the object with a contact sensor, which matters for light or delicate parts like a speaker cone. It also lets engineers map how vibration varies across a surface.", "practical_application": "A transducer engineer uses a scanning laser vibrometer to map how a loudspeaker diaphragm flexes and breaks up across frequency, guiding cone and surround design.", "category": "Vibration measurement", "related_terms": ["Accelerometer", "Mechanical impedance measurement", "Particle-velocity measurement", "Cone breakup", "Transfer function", "Modal analysis"], "common_mistakes": ["Measuring a surface with poor optical reflectivity without treating it, giving a weak, noisy signal.", "Ignoring alignment and any relative motion between the instrument and target, which corrupts the reading.", "Assuming a single point represents the whole surface, when different areas of a diaphragm move very differently."], "scenario_contexts": ["Mapping loudspeaker cone breakup modes in a research lab.", "Measuring vibration of a small or lightweight part where an accelerometer would add too much mass.", "Studying resonances of a panel or enclosure surface without touching it."]}, "817d7f52-c80a-4ea8-b0ba-a2189fb5d764": {"definition": "Material absorption measurement is the determination of a material's sound absorption coefficient, the fraction of incident sound energy the material absorbs rather than reflects, as a function of frequency. Two standard methods dominate: the reverberation room method (ISO 354 / ASTM C423) gives random-incidence (Sabine) absorption, and the impedance-tube method (ISO 10534-2 / ASTM E1050) gives normal-incidence absorption.", "plain_english": "This measures how much sound a material soaks up instead of bouncing it back. One method uses a big, echoey test room. Another uses a tube with a speaker at one end and a small sample. The result guides choices of wall, ceiling, and panel treatment.", "purpose_function": "It exists to quantify how well materials absorb sound at each frequency, so designers can predict and control reverberation and noise. The data feeds room-acoustics design and product datasheets.", "practical_application": "An acoustics technician mounts a panel in a reverberation room and measures how much faster sound decays with the sample present, calculating its absorption coefficient per octave band.", "category": "Acoustic measurement", "related_terms": ["Absorption coefficient", "Reverberation room", "Impedance tube", "Reverberation time", "Laboratory sound chamber", "Acoustic impedance"], "common_mistakes": ["Comparing reverberation-room (random-incidence) and impedance-tube (normal-incidence) figures as if they were the same quantity.", "Reporting Sabine absorption coefficients above 1.0 as an error, when edge diffraction and mounting can legitimately produce them.", "Ignoring how the sample's mounting and area affect the measured coefficient."], "scenario_contexts": ["Rating an acoustic ceiling tile's absorption for a manufacturer's datasheet.", "Measuring normal-incidence absorption of a small foam sample in an impedance tube.", "Verifying a studio treatment's low-frequency absorption before installation."]}, "3b20c08d-e726-40df-b7c5-92b088bb3ebf": {"definition": "Measurement uncertainty is a value, always zero or positive, that quantifies how widely the results attributed to a measured quantity may spread given what is known about the measurement. Under the GUM (JCGM 100) it appears as a standard uncertainty, as a combined standard uncertainty that pools every contributing source, and as an expanded uncertainty formed by multiplying that combined figure by a coverage factor k to express a chosen level of confidence.", "plain_english": "Measurement uncertainty is the doubt that comes with any measurement. It gives a range where the true value most likely sits. No reading is ever perfect. So a result should state this range, which tells you how far to trust the number.", "purpose_function": "It exists because every measurement has error sources, and a result without a stated uncertainty is incomplete and cannot be compared or checked against a limit. Quantifying it lets people make sound decisions from data.", "practical_application": "A calibration technician adds up contributions from the instrument, the reference, the environment, and repeatability, then reports a value plus or minus an expanded uncertainty with its coverage factor.", "category": "Metrology", "related_terms": ["National Institute of Standards and Technology traceability", "Calibration", "Laboratory quality assurance", "Coverage factor", "Standard deviation", "Tolerance"], "common_mistakes": ["Confusing uncertainty with error; error is the deviation of one result, while uncertainty is the range of doubt around it.", "Reporting more significant figures than the uncertainty can justify.", "Quoting an expanded uncertainty without stating the coverage factor or confidence level it uses."], "scenario_contexts": ["Stating the plus-or-minus range on a calibration certificate for a sound level meter.", "Deciding whether a measured value truly passes or fails a specification limit.", "Building an uncertainty budget for an acoustic test method."]}, "b7c69d52-fb51-4bfb-b55a-7da9eb5e7ba5": {"definition": "Mechanical impedance measurement determines mechanical impedance, the complex ratio of applied force to the resulting velocity at a point on a structure, as a function of frequency. It typically uses an impedance head combining a force transducer and an accelerometer, with the structure driven by a shaker; the results reveal resonances, stiffness, damping, and mass behavior. ISO 7626 defines the experimental methods (as mobility, the inverse quantity).", "plain_english": "This measures how hard it is to make a part move when you push it. You apply a known force and read the motion that results. Comparing them across many pitches shows resonances and stiffness. Engineers use it in transducer and structure design.", "purpose_function": "It exists to characterize how a structure or component responds dynamically to force, exposing resonances and damping that affect performance. This guides the design of transducers, mounts, and vibration control.", "practical_application": "An engineer attaches an impedance head between a shaker and a test structure, sweeps frequency, and reads the force-to-velocity ratio to locate resonances and estimate stiffness and damping.", "category": "Vibration measurement", "related_terms": ["Mechanical impedance", "Accelerometer", "Laser vibrometry", "Resonance", "Modal analysis", "Acoustic impedance"], "common_mistakes": ["Adding significant mass with the sensor and fixture, which shifts the resonances being measured.", "Confusing mechanical impedance (force over velocity) with mechanical mobility, its inverse.", "Assuming a point measurement describes the whole structure, ignoring how impedance varies with location."], "scenario_contexts": ["Characterizing the dynamic response of a loudspeaker cone or suspension.", "Measuring how a vibration isolation mount responds across frequency.", "Locating structural resonances in an enclosure or chassis during design."]}, "4333d85e-3d63-4197-b1e8-54f46f87732d": {"definition": "National Institute of Standards and Technology (NIST) traceability is the property of a measurement result whereby it can be related to national or international reference standards through a documented, unbroken chain of calibrations, each with a stated measurement uncertainty, ultimately referencing standards maintained by NIST, the United States national metrology institute. It establishes that an instrument's readings are anchored to the SI and to recognized U.S. references.", "plain_english": "NIST traceability means a measurement links back to national standards. NIST is the U.S. lab that keeps the master references. An unbroken chain of calibrations connects your gear to those references. This proves your readings sit on the right, agreed scale.", "purpose_function": "It exists to give measurements a common, trusted anchor so results from different labs and instruments agree and can be compared. This supports fair trade, safety compliance, and defensible test data.", "practical_application": "A lab keeps calibration certificates showing each reference standard was calibrated against a higher standard, back to NIST, so any result can be shown to be traceable during an audit.", "category": "Metrology", "related_terms": ["Calibration", "Measurement uncertainty", "Laboratory quality assurance", "Reference standard", "SI units", "Laboratory reference microphone"], "common_mistakes": ["Believing a calibration sticker alone proves traceability, without the certificates and stated uncertainties behind it.", "Thinking traceability requires sending gear directly to NIST, when an accredited calibration lab provides the intermediate links.", "Letting a link lapse by using equipment past its calibration interval, which breaks the chain."], "scenario_contexts": ["Demonstrating traceability of test instruments during an ISO/IEC 17025 assessment.", "Selecting a calibration provider that issues traceable certificates for a sound level meter.", "Building a documented calibration chain for a production test bench."]}, "4b36e93f-fd89-446c-9075-d3112ad0acc4": {"definition": "Particle-velocity measurement determines acoustic particle velocity, the vector velocity of the oscillating medium particles in a sound field, as distinct from the scalar sound pressure. It can be measured directly with a particle-velocity sensor, such as a hot-wire anemometric transducer, or derived from the pressure gradient using a two-microphone (p-p) probe; combined with pressure it yields sound intensity.", "plain_english": "Sound makes tiny air particles jiggle back and forth. Particle-velocity measurement records how fast they move. This differs from sound pressure, which is how hard they push. A special sensor reads this motion, and it helps map how sound travels.", "purpose_function": "It exists to capture the velocity part of a sound field, which pressure alone cannot give. Together with pressure it yields sound intensity and direction, useful for locating sources and measuring sound power.", "practical_application": "A technician uses a particle-velocity or intensity probe to find where sound is radiating from a machine and to measure sound power in the presence of background noise.", "category": "Acoustic measurement", "related_terms": ["Sound intensity", "Sound pressure level (SPL)", "Sound power", "Acoustic impedance", "Intensity probe", "Pressure gradient"], "common_mistakes": ["Confusing particle velocity, the slow oscillation of air particles, with the speed of sound, which is the wave's propagation speed.", "Assuming a pressure microphone measures particle velocity; it does not, without a gradient or dedicated sensor.", "Ignoring the phase match between pressure and velocity channels, which is critical for accurate intensity."], "scenario_contexts": ["Locating a noise leak on a machine using a sound intensity probe.", "Measuring in-situ acoustic impedance and absorption at a surface.", "Determining sound power in a non-ideal field where pressure-only methods struggle."]}, "4ea176e9-1b40-4575-8365-e7fa6a454d23": {"definition": "A phase display is the part of an audio measurement instrument or analysis software that shows the phase relationship between signals as a function of frequency, typically the phase trace of a dual-channel transfer-function (FFT) measurement plotted in degrees versus frequency. It reveals time offsets, polarity reversals, and crossover interactions between a system's output and its input that a magnitude-only view cannot show.", "plain_english": "A phase display is the screen that shows the timing between two sound signals at each frequency. It draws how far one signal lags the other as a curve. Engineers read it to line up speakers and subs. It also shows wiring that is hooked up backwards.", "purpose_function": "It exists to make timing and polarity differences across frequency visible, since those differences decide how sound sources add or cancel. This lets an engineer time-align and polarity-check loudspeakers.", "practical_application": "A technician runs a transfer-function measurement and reads the phase display to set delay between a subwoofer and the mains so they align through the crossover region.", "category": "Measurement display", "related_terms": ["Transfer function", "Phase analyzer", "Polarity", "Time alignment", "Coherence", "Group delay"], "common_mistakes": ["Confusing phase with polarity, when polarity is a fixed sign flip and phase changes with frequency.", "Reading the phase trace where coherence is low, so the displayed phase is unreliable noise.", "Forgetting that the trace wraps at plus or minus 180 degrees, so a jump can be a wrap, not a real change."], "scenario_contexts": ["Aligning a subwoofer to the mains by matching phase through the crossover frequency.", "Checking that all boxes in an array share the same polarity before a show.", "Diagnosing a response dip caused by two arrivals cancelling out of phase."]}, "4cea5a8d-3b52-4ede-8b5d-3608e9e8457f": {"definition": "A precision acoustic calibrator is a portable Class 1 (or laboratory-standard) acoustic reference device, defined by IEC 60942, that fits over a measurement microphone and generates a known, stable sound pressure level at a specified frequency - commonly 94 dB (1 pascal) or 114 dB at 1 kHz. 'Precision' denotes the tightest tolerance class, with small level and frequency error and low sensitivity to temperature, humidity, and ambient pressure, so a sound level meter or measurement chain can be adjusted to read accurately.", "plain_english": "A precision acoustic calibrator makes one exact, steady loudness at a set pitch. You slide it over a measurement microphone before testing. Then you adjust the meter until it reads the right number. The word precision means its own error is very small.", "purpose_function": "It gives a traceable, high-accuracy acoustic reference so a meter or microphone can be set to read true sound pressure level. Its tight tolerance suits legal and safety measurements where accuracy matters.", "practical_application": "Before a noise survey a technician fits the calibrator to the microphone, plays its 94 dB tone, and adjusts the meter until it reads 94 dB.", "category": "Acoustic calibrator", "related_terms": ["SPL calibrator", "Pistonphone", "Sound level meter", "Measurement microphone", "Calibration", "Traceability"], "common_mistakes": ["Skipping the calibration check before and after a measurement, so drift goes unnoticed.", "Using a calibrator whose cavity does not match the microphone diameter, giving a poor seal and a wrong level.", "Forgetting that ambient pressure and altitude shift the reference level, especially for a pistonphone."], "scenario_contexts": ["Calibrating a Class 1 sound level meter before an occupational noise survey.", "Setting the reference sensitivity of a measurement microphone in room-acoustics work.", "Checking at the end of a session that the meter has not drifted."]}, "187a3c98-7f40-43c1-8a28-6cb25fe84649": {"definition": "A precision measurement chain is the complete, calibrated set of components used to make an accurate acoustic or audio measurement - typically a measurement microphone, preamplifier, signal conditioning/power supply, and analyzer or sound level meter - whose individual and overall accuracy is established and kept traceable to reference standards. Each element's tolerance contributes to the chain's total measurement uncertainty, and the whole chain is calibrated as a system, for example with an acoustic calibrator, before use.", "plain_english": "A precision measurement chain is the full string of gear used to take an accurate reading. It usually runs from a measurement microphone through a preamp to an analyzer. Every part must be calibrated so the final number can be trusted. A weak link adds error to the result.", "purpose_function": "It exists to turn sound into a trustworthy number by controlling accuracy at every stage from microphone to analyzer. Treating the parts as one calibrated system keeps the total measurement uncertainty known and small.", "practical_application": "A technician calibrates the whole chain with an acoustic calibrator, confirms each component's specifications, then measures, so the result carries a known uncertainty.", "category": "Measurement system", "related_terms": ["Measurement microphone", "Precision acoustic calibrator", "Sound level meter", "Traceability", "Measurement uncertainty", "Calibration"], "common_mistakes": ["Calibrating only the meter and ignoring the microphone and preamp, which also drift.", "Mixing components without checking they are matched and rated for the required accuracy class.", "Reporting a reading without stating its measurement uncertainty."], "scenario_contexts": ["Assembling a Class 1 chain for a compliance noise measurement.", "Verifying traceability of each instrument before an accredited acoustic test.", "Estimating total uncertainty by combining each component's contribution."]}, "9b156539-f2dc-4f0d-b506-bca6939ee65d": {"definition": "A pressure-field chamber is a small, rigid, enclosed cavity (coupler) whose dimensions are much smaller than the acoustic wavelength, so the sound pressure inside has essentially the same magnitude and phase at every point - a pressure field. It is used to establish a defined pressure field for calibrating pressure-field measurement microphones and for coupler-based methods such as pressure reciprocity calibration.", "plain_english": "A pressure-field chamber is a tiny sealed space. Inside it, the sound pressure is the same everywhere. This works because the space is far smaller than the sound wave. Engineers use it to calibrate some measurement mics. It gives a known, repeatable reference.", "purpose_function": "It exists to create a uniform, well-defined pressure field so pressure-field microphones can be calibrated accurately. A closed cavity removes the reflections and directional effects found in open rooms.", "practical_application": "A calibration technician couples a microphone to the small chamber and applies a known pressure to determine the microphone's sensitivity.", "category": "Calibration chamber", "related_terms": ["Pressure-field microphone", "Free field", "Coupler", "Measurement microphone", "Reciprocity calibration", "Precision acoustic calibrator"], "common_mistakes": ["Confusing a pressure field with a free field, which are different fields needing different microphone types.", "Using the chamber above the frequency where its size approaches the wavelength, breaking the uniform-pressure assumption.", "Assuming a pressure-field microphone reads correctly in an open free field without a correction."], "scenario_contexts": ["Calibrating a pressure-field measurement microphone by the coupler method.", "Performing pressure reciprocity calibration of laboratory standard microphones.", "Providing a known reference field in a metrology or acoustics laboratory."]}, "210577ad-284e-4161-bcb6-91d207a43c06": {"definition": "Repeatability measurement evaluates how tightly repeated readings of one quantity agree when nothing in the setup is deliberately changed. The same operator uses the same procedure, instrument, and location to remeasure over a short period of time. This random scatter under fixed conditions is reported as a repeatability standard deviation or limit.", "plain_english": "Repeatability measurement checks how close repeated readings are when nothing changes. The same person uses the same gear the same way over a short time. A small spread means good repeatability. It shows the random wobble in your measurement.", "purpose_function": "It exists to quantify the random variation of a measurement made under fixed conditions. Knowing that scatter tells you how much a single reading can be trusted.", "practical_application": "A technician measures the same source several times without changing anything and reports the spread as a repeatability figure.", "category": "Metrology concept", "related_terms": ["Reproducibility measurement", "Measurement uncertainty", "Precision", "Standard deviation", "Calibration", "Traceability"], "common_mistakes": ["Confusing repeatability with reproducibility, which deliberately changes operators, instruments, or locations.", "Confusing repeatability, which is random scatter, with accuracy or trueness, which is closeness to the true value.", "Taking too few repeats to estimate the spread reliably."], "scenario_contexts": ["Checking an analyzer's repeatability by re-running the same measurement several times.", "Establishing the short-term scatter of a noise measurement at one position.", "Qualifying a test method before it is used for compliance work."]}, "6811847f-5e3f-4232-9c58-4fa4e92fefe1": {"definition": "Reproducibility measurement evaluates how closely readings of one quantity agree when the conditions are deliberately changed, for instance different operators, instruments, locations, or laboratories, while the method itself stays the same. This spread, which is typically wider than repeatability, is reported as a reproducibility standard deviation or limit.", "plain_english": "Reproducibility measurement checks how steady readings stay when things change. The same test is run by different people, gear, or rooms. A small spread means good reproducibility. It shows whether a result holds up outside one setup.", "purpose_function": "It exists to quantify how much a measurement varies when realistic conditions change, not just one fixed setup. This shows whether a method gives consistent results across operators and labs.", "practical_application": "The same item is measured by different technicians on different instruments, and the spread of results is reported as reproducibility.", "category": "Metrology concept", "related_terms": ["Repeatability measurement", "Measurement uncertainty", "Precision", "Round-robin test", "Calibration", "Traceability"], "common_mistakes": ["Confusing reproducibility with repeatability, which keeps every condition the same.", "Changing the measurement method as well, so differences no longer reflect reproducibility alone.", "Using one lab's data to claim reproducibility, which needs varied conditions."], "scenario_contexts": ["Comparing the same measurement across several labs in a round-robin study.", "Checking that two technicians with different meters get matching results.", "Validating a standard test method for use across sites."]}, "f0faf44c-a428-49b4-8fb5-8b1135a220b8": {"definition": "A reverberation chamber (reverberation room) is a room with hard, sound-reflecting, non-parallel surfaces and a long reverberation time, designed to produce an approximately diffuse sound field in which acoustic energy is uniformly distributed and arrives from all directions. It is used for standardised acoustic tests such as measuring sound absorption coefficients (ISO 354) and determining the sound power of sources (ISO 3741), and is the diffuse-field counterpart to an anechoic (free-field) chamber.", "plain_english": "A reverberation chamber is a hard, echoey room built so sound bounces evenly in all directions. Nothing soaks up the sound, so it fills the room evenly. Engineers use it to measure how much materials absorb sound. They also use it to measure how much power a source puts out.", "purpose_function": "It provides a controlled diffuse field where sound energy is even throughout the room. That lets absorption and sound-power tests give repeatable, standard results.", "practical_application": "A technician places a sample or a running machine in the chamber and measures the reverberation time or average sound pressure to find absorption or sound power.", "category": "Acoustic test chamber", "related_terms": ["Anechoic chamber", "Diffuse field", "Reverberation time", "Sound-power measurement", "Absorption coefficient", "Sound level meter"], "common_mistakes": ["Confusing a reverberation chamber with an anechoic chamber, which is the opposite, non-reflective, free-field room.", "Measuring too close to a source or wall, where the field is not diffuse.", "Working at low frequencies where too few room modes break the diffuse-field assumption."], "scenario_contexts": ["Measuring the absorption coefficient of an acoustic material to ISO 354.", "Determining a machine's sound power in a diffuse field to ISO 3741.", "Testing the sound transmission loss of a partition between two chambers."]}, "aaaf70b2-388b-4fba-9f49-73c73d6d7e61": {"definition": "Sound-intensity measurement is the determination of sound intensity - the net flow of acoustic power per unit area, a vector with magnitude and direction - usually with a two-microphone (p-p) probe that computes intensity from the sound pressure and the pressure gradient between closely spaced, phase-matched microphones. Because it measures net power flow, it can be used in ordinary, non-ideal environments to locate noise sources and to determine sound power (ISO 9614), using instruments specified by IEC 61043.", "plain_english": "Sound-intensity measurement finds both how strong sound energy is and which way it flows. It usually uses two matched microphones set close together. Because it tracks net flow, it works even in noisy, real rooms. Engineers use it to find where noise comes from.", "purpose_function": "It exists to measure the direction and amount of acoustic power flow, not just pressure. That lets engineers find noise sources and measure sound power without a special quiet room.", "practical_application": "A technician scans a two-microphone intensity probe over a machine's surface to map where noise radiates and to calculate its sound power.", "category": "Acoustic measurement", "related_terms": ["Sound-power measurement", "Sound pressure level (SPL)", "Measurement microphone", "Reverberation chamber", "Anechoic chamber", "Phase matching"], "common_mistakes": ["Confusing sound intensity, a vector that is net power flow, with sound pressure, which is a scalar.", "Using microphones that are not phase-matched, which causes large intensity errors.", "Choosing the wrong microphone spacer for the frequency range, limiting accuracy."], "scenario_contexts": ["Locating the loudest radiating part of a machine with an intensity probe.", "Measuring sound power in place to ISO 9614 without an anechoic room.", "Ranking noise sources on equipment during product development."]}, "f6ea4d37-6746-43e2-aa33-cdcffed20e6d": {"definition": "Sound-power measurement is the determination of the total acoustic power (in watts, expressed as a sound power level in dB re 1 pW) radiated by a source - a property of the source itself that is independent of the surrounding environment and the distance to it. It is obtained under standardised conditions, from sound pressure in an anechoic or hemi-anechoic room (ISO 3745) or a reverberation room (ISO 3741), or from sound intensity (ISO 9614), and is used to rate and compare the noise emission of equipment.", "plain_english": "Sound-power measurement finds the total sound energy a source gives off each second. Unlike the loudness at your ear, it does not depend on the room or distance. That makes it fair for comparing machines. Makers use it to label how noisy a product is.", "purpose_function": "It exists to describe how much noise a source itself produces, separate from where you stand or the room. This gives a fair, comparable rating for equipment noise.", "practical_application": "A technician measures a product in a qualified room or with an intensity probe, then reports its sound power level for a noise-emission label or specification.", "category": "Acoustic measurement", "related_terms": ["Sound-intensity measurement", "Sound pressure level (SPL)", "Reverberation chamber", "Anechoic chamber", "Sound power level", "Measurement microphone"], "common_mistakes": ["Confusing sound power, a source property in watts, with sound pressure level, which depends on room and distance.", "Using an unqualified room, so the measured field does not meet the standard's requirements.", "Forgetting the background-noise and environmental corrections required by the standard."], "scenario_contexts": ["Rating a product's noise emission for a datasheet or regulatory label.", "Comparing two machines' noise output on an equal basis.", "Measuring sound power with an intensity probe on a factory floor."]}, "283689bc-753c-48d8-911b-45372880423b": {"definition": "A statistical confidence interval is a range of values, computed from measured data, that is expected to contain the true value of the measured quantity with a stated probability called the confidence level, such as 95%. It expresses the uncertainty of an estimate: if the measurement were repeated many times, that stated proportion of the computed intervals would bracket the true value.", "plain_english": "A confidence interval is a range around a measured result. It shows where the true value most likely sits. A 95% confidence interval will contain the true value about 95 times out of 100 if you repeat the test. A wider range means less certainty.", "purpose_function": "It exists to turn a single measured number into a range with a stated probability, so users know how much to trust the result. This lets engineers judge whether a difference between two results is real or just measurement scatter.", "practical_application": "When a technician reports the average of repeated measurements, they attach a confidence interval so others can see the margin of uncertainty around that value.", "category": "Measurement statistics", "related_terms": ["Measurement uncertainty", "Standard deviation", "Standard error", "Confidence level", "Statistical significance", "Averaging"], "common_mistakes": ["Reading a 95% confidence interval as if 95% of individual data points fall inside it, when it actually describes the estimate of the mean.", "Confusing a confidence interval with a tolerance or prediction interval, which describe individual values rather than the mean.", "Assuming a narrow interval proves the result is accurate, when it only reflects precision and not freedom from bias."], "scenario_contexts": ["Reporting the mean of repeated distortion readings with a range that shows the measurement's uncertainty.", "Deciding whether two loudspeakers truly differ in output or the gap falls within measurement scatter.", "Stating the uncertainty of a calibration result alongside the measured value."]}, "3a2b379d-a253-47cf-8343-733b22e67515": {"definition": "Structural resonance measurement is the process of determining the natural frequencies at which a mechanical structure vibrates most readily when excited, together with the associated mode shapes and damping. It typically uses an accelerometer or laser vibrometer to sense the response to a controlled excitation, such as an impact hammer or shaker, and an FFT analyzer to identify the resonant peaks.", "plain_english": "Every object has pitches at which it vibrates most easily. Structural resonance measurement finds those pitches for a real structure. Engineers tap or shake the object and measure how it moves. Peaks in the result mark the resonances. In audio this helps stop speaker cabinets from ringing.", "purpose_function": "It exists to reveal where a structure vibrates strongly, because resonances can add unwanted noise, coloration, or even mechanical failure. Knowing these frequencies lets designers add stiffening or damping to control them.", "practical_application": "A technician attaches an accelerometer to a loudspeaker cabinet, taps it with an impact hammer, and reads the FFT to find panel resonances that need bracing or damping.", "category": "Vibration measurement", "related_terms": ["Vibration analysis", "Accelerometer", "Resonance", "Modal analysis", "FFT analyzer", "Damping"], "common_mistakes": ["Ignoring the sensor's own mass, when a heavy accelerometer loads the structure and shifts the measured resonance downward.", "Exciting only one point and assuming it shows every mode, missing resonances that have a node at that point.", "Confusing a structural resonance with an acoustic room mode, which are different physical phenomena."], "scenario_contexts": ["Finding panel resonances in a loudspeaker enclosure that color the sound.", "Checking a microphone stand or camera rig for a resonance that transmits vibration.", "Verifying that a mounting bracket does not resonate within its operating frequency range."]}, "3899d693-5e7d-417f-8b5a-2f2307d278ff": {"definition": "A temperature-controlled chamber, also called an environmental or climatic chamber, is an insulated enclosure that holds a set temperature - and often humidity - stable within a defined tolerance, so devices can be calibrated, conditioned, or tested under known and repeatable conditions. Calibration and dimensional metrology commonly reference measurements to a standard reference temperature such as 20 degrees Celsius.", "plain_english": "A temperature-controlled chamber is a sealed box that holds a set temperature steady. Some also hold humidity steady. Engineers put gear inside to test or calibrate it under known conditions. This matters because heat and cold change how equipment behaves.", "purpose_function": "It exists to remove temperature as a hidden variable, so tests and calibrations are repeatable and can be compared fairly. It also lets engineers check how equipment performs across its rated temperature range.", "practical_application": "A calibration technician places a reference instrument in the chamber, waits for it to stabilize at the set temperature, then performs the calibration under those controlled conditions.", "category": "Test environment", "related_terms": ["Traceable calibration certificate", "Calibration", "Environmental testing", "Thermal drift", "Reference conditions", "Measurement uncertainty"], "common_mistakes": ["Reading measurements before the device has fully soaked and stabilized at the set temperature.", "Ignoring temperature gradients inside the chamber, so the device sits at a different temperature than the control sensor reads.", "Assuming the chamber controls humidity when it only controls temperature."], "scenario_contexts": ["Conditioning a reference microphone or instrument to a stable temperature before calibration.", "Testing how a device's output drifts across its rated temperature range.", "Maintaining standard reference conditions inside a calibration laboratory."]}, "74899e58-ef9c-402e-bbde-980727c59a6e": {"definition": "A traceable calibration certificate is a formal document recording a calibration's results and stated measurement uncertainty, along with evidence that the reference standards used are linked, through an unbroken chain of documented comparisons, to national or international measurement standards (the SI). This metrological traceability is a core requirement of ISO/IEC 17025 for accredited calibration.", "plain_english": "A traceable calibration certificate is a document that proves a test tool was checked properly. It shows the results and how much they might be off. It also shows an unbroken chain linking the tool back to national standards. This lets people trust that the tool reads true.", "purpose_function": "It exists to prove a measurement result can be trusted and compared anywhere, by tying an instrument's readings to recognized reference standards. It also records the uncertainty so users know the limits of the calibration.", "practical_application": "When buying or servicing a sound level meter, a technician keeps its traceable calibration certificate on file to prove the meter is accurate for compliance measurements.", "category": "Calibration", "related_terms": ["Calibration", "Measurement uncertainty", "SPL calibrator", "Reference standard", "Metrological traceability", "Sound level meter"], "common_mistakes": ["Treating any calibration sticker as proof of traceability, when only a documented chain back to national standards counts.", "Ignoring the stated measurement uncertainty when judging whether the instrument is fit for a task.", "Assuming a certificate stays valid forever, when calibration has a defined interval after which it must be repeated."], "scenario_contexts": ["Proving a sound level meter's accuracy for a legal or occupational noise measurement.", "Keeping calibration records for audio test gear to satisfy a quality audit.", "Checking the uncertainty stated on a certificate before relying on a reference microphone."]}, "e2143e54-e15b-4501-83bd-884914d22da4": {"definition": "Transmission-loss measurement determines how effectively a partition - such as a wall, floor, window, or enclosure panel - attenuates airborne sound passing through it, expressed in decibels as a function of frequency. It is measured by generating a known sound field in a source room and measuring the reduced level in an adjacent receiving room, following methods such as ASTM E90 or ISO 10140, and is often summarized by a single-number rating.", "plain_english": "Transmission loss measures how well a wall or window blocks sound. Engineers play loud sound in one room. Then they measure how much quieter it is in the next room. A bigger drop, in decibels, means better blocking. It is measured across many frequencies.", "purpose_function": "It exists to quantify how well a partition isolates sound, so designers can predict and control noise passing between spaces. The results guide the choice of walls, doors, and windows for studios, theaters, and control rooms.", "practical_application": "An acoustician measures the transmission loss between a control room and a live room to confirm a wall design blocks enough sound before the studio is finished.", "category": "Acoustic measurement", "related_terms": ["Sound transmission class (STC)", "Sound isolation", "Decibel", "Octave band", "Sound pressure level (SPL)", "Noise reduction"], "common_mistakes": ["Confusing transmission loss, a property of the partition, with noise reduction, which also depends on the receiving room's absorption.", "Judging a wall by its single-number rating alone, which can hide poor performance at low frequencies.", "Ignoring flanking paths, so sound travelling around the partition makes the real isolation worse than the lab value."], "scenario_contexts": ["Verifying that a studio wall blocks enough sound between a control room and a live room.", "Choosing a window or door assembly by its rated transmission loss.", "Diagnosing why a partition isolates less than expected because of flanking paths or gaps."]}, "84e7f7b4-cc53-4d7a-a13f-b5ac90482b6a": {"definition": "Vibration analysis is the measurement and interpretation of the oscillatory motion of a machine or structure, usually sensed by an accelerometer and examined in the frequency domain with an FFT analyzer, to characterize its behavior or diagnose faults. Distinct spectral components can be linked to causes such as imbalance, misalignment, looseness, or bearing wear, and overall vibration severity is evaluated against standards such as ISO 20816.", "plain_english": "Vibration analysis measures how a machine or structure shakes. A sensor picks up the motion, and software splits it into its frequencies. Certain frequencies point to certain problems, like a worn bearing or an unbalanced fan. It helps catch faults before they cause a failure.", "purpose_function": "It exists to turn a machine's vibration into a diagnostic signal that reveals developing faults and shows how severe the shaking is. This supports condition monitoring and helps prevent unexpected breakdowns.", "practical_application": "A technician mounts an accelerometer on a motor or fan, captures the vibration spectrum, and looks for peaks that reveal imbalance or bearing wear before the part fails.", "category": "Vibration measurement", "related_terms": ["Accelerometer", "Structural resonance measurement", "FFT analyzer", "Resonance", "Spectrum analyzer", "Frequency domain"], "common_mistakes": ["Mounting the accelerometer poorly, so a loose or soft mount corrupts the high-frequency readings.", "Reading only the overall vibration level and missing the spectrum detail that identifies the specific fault.", "Comparing readings taken at different points or in different directions as if they were equivalent."], "scenario_contexts": ["Monitoring a studio HVAC fan or motor for bearing wear that could add noise.", "Diagnosing an imbalance in a rotating machine from its vibration spectrum.", "Checking that equipment vibration stays within the limits of a severity standard."]}, "9d082366-115e-4ba8-9ff3-ee0b607ed782": {"definition": "The act of returning a mixing console to a defined default or initialized state, clearing or restoring channel, routing, and signal-processing settings to a factory baseline or a known starting scene. On digital consoles this is typically an 'initialize', 'factory set', or 'hard reset' function; it may be full (clears all data) or partial (resets mix/DSP settings while retaining show files).", "plain_english": "A console reset returns the mixing desk to its starting settings. It clears the last show so you can begin a new one from a clean, known state.", "purpose_function": "It gives the engineer a predictable, known starting point and removes leftover routing, gain, mute, or processing settings that could cause errors. This makes troubleshooting and building a new show file faster and more reliable.", "practical_application": "Before a rental or festival changeover, or after corrupted settings cause routing faults, a technician initializes the console (or recalls a default scene) to wipe previous settings and start clean.", "category": "Console operation", "related_terms": ["Mixing console", "Scene recall", "Signal flow", "Gain structure", "Default scene"], "common_mistakes": ["UNSAFE: Performing a console reset with power amplifiers on and outputs unmuted can unmute channels and send a sudden full-level signal to the PA, risking loudspeaker damage and hearing injury; mute or power down amps first.", "Confusing a full/hard reset (which erases all settings and show data) with recalling a default scene, and losing saved work as a result.", "Resetting the console to fix a problem without first saving the current show file, so recoverable settings are lost."], "scenario_contexts": ["Initializing a rental digital console to a factory state before building a new show file.", "Recalling a default/zero scene during a band changeover at a festival to clear the previous act's settings.", "Performing a hard reset after corrupted settings cause routing or output errors that normal adjustment cannot fix."]}, "5e4966b9-6ba1-4b4a-a583-9fcc88b10075": {"definition": "A stage in building a live or recorded mix in which the engineer works through the channels to add and set time-based and coloring effects, such as reverb, delay, and modulation, via effect sends and returns. It is normally carried out after gain, filtering, equalization, and dynamics are set, so effects are added to an already balanced mix.", "plain_english": "This is the step where the engineer adds effects like reverb and echo. It comes after the basic levels and tone are set. The aim is depth and polish, not fixing the raw sound.", "purpose_function": "It exists to add spatial depth, space, and character to a mix in an organized way, keeping effects consistent across channels instead of set at random.", "practical_application": "During soundcheck the engineer routes a vocal to a reverb and a delay, sets the return levels, and dials in the effect amount on each channel that needs it.", "category": "Soundcheck Workflow", "related_terms": ["Gain pass", "High-pass pass", "Reverb", "Delay", "Aux send", "Full soundcheck"], "common_mistakes": ["Adding effects before levels, gain, and EQ are set, so the mix is built on an unstable foundation.", "Using so much reverb or delay that vocals lose clarity in the room.", "Forgetting that effect returns add gain and can push monitors into feedback."], "scenario_contexts": ["Setting vocal reverb and delay during a full soundcheck.", "Building effect sends on a digital console before a show.", "Recreating a stored effects setup for a touring act at a new venue."]}, "dc3de67f-3556-4e8c-a3b1-ad5dc4c18efa": {"definition": "A soundcheck cue in which the engineer asks all the musicians to play together at the same time, after each input has been checked on its own. It marks the shift from checking individual channels to setting the balance of the full mix under near-performance conditions.", "plain_english": "It is the engineer telling the whole band to play at once. It happens after each instrument has been checked on its own. Now the engineer can balance the whole mix together.", "purpose_function": "It exists to let the engineer hear how all the sources interact and to set the overall balance, headroom, and feedback margin close to real show levels.", "practical_application": "After lining up each channel, the engineer keys talkback and calls 'everybody play' to set the full-band balance for front of house and monitors.", "category": "Soundcheck Communication", "related_terms": ["Give me the band", "Soundcheck", "Full soundcheck", "Talkback", "Monitor mix", "Gain structure"], "common_mistakes": ["Calling for the full band before individual channels are gained and checked.", "Not cueing the players clearly, so they start at different times.", "Forgetting to re-check the monitor mixes once everyone is playing loudly."], "scenario_contexts": ["Moving from a channel-by-channel check to a full-band run.", "Setting front-of-house balance with the whole band playing.", "Checking feedback and headroom at full-band levels."]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"33baab88-cd6b-48ce-904b-225ddc46bdab": {"definition": "A rapid line check carried out during a festival changeover, in the short gap between acts, to confirm that every input, microphone, and DI is patched, working, and arriving at the console. It substitutes for a full soundcheck when there is no time to build mixes before the act begins.", "plain_english": "At festivals, bands swap fast with little time. A line check quickly confirms every mic and input works. It does not build the full mix; the show starts almost right away.", "purpose_function": "It exists to catch dead, mis-patched, or noisy inputs before an act starts, when tight festival schedules leave no room for a proper soundcheck.", "practical_application": "During the changeover the engineer has each source tapped or played in patch order, confirming signal and clearing faults while the previous act's gear is struck.", "category": "Soundcheck Workflow", "related_terms": ["Line check", "Changeover line check", "Full soundcheck", "Patch list", "Stage plot", "Splitter"], "common_mistakes": ["Treating a line check as a soundcheck and expecting a finished mix from it.", "Skipping inputs to save time, then finding a dead channel during the first song.", "Not following a patch list, so a mis-patched input goes unnoticed."], "scenario_contexts": ["Verifying all inputs between two bands on a festival stage.", "Confirming a DI and vocal mic work after a fast backline swap.", "Checking the patch against the stage plot before an act with no soundcheck."]}, "697ff1a0-5b4f-4a7c-8d19-a95af8f1d19d": {"definition": "A complete soundcheck in which every input is checked and set individually and then the whole band plays, so front-of-house and monitor mixes can be built and refined before the performance. It contrasts with a line check or quick check, which only confirms that the inputs work.", "plain_english": "This is a complete soundcheck with plenty of time. Each input is set one by one. Then the band plays so the engineer can build the whole mix. A line check only proves things work.", "purpose_function": "It exists to build and fine-tune the entire mix and monitor system under near-show conditions, reducing surprises once the audience arrives.", "practical_application": "With a full soundcheck booked, the engineer sets gain and EQ on each channel, then has the band play songs to finalize the front-of-house and monitor mixes.", "category": "Soundcheck Workflow", "related_terms": ["Line check", "Festival line check", "Everybody play", "Gain pass", "Monitor mix", "Soundcheck"], "common_mistakes": ["Spending all the time on one instrument and leaving none for the full band.", "Setting mixes at low level, then finding the balance falls apart at show volume.", "Assuming a soundcheck in an empty room translates exactly to a full audience."], "scenario_contexts": ["A headline act with a scheduled slot to build complete mixes.", "Refining monitor mixes for each performer before doors open.", "Setting front-of-house tone and balance with the band running full songs."]}, "72057edf-b395-4ba8-abbf-18e958428b4c": {"definition": "A systematic sweep through every input channel to set the preamp gain or trim, establishing correct gain structure and headroom before equalization and dynamics are addressed. Each channel is driven at a realistic performance level while its input gain is adjusted for a strong signal without clipping.", "plain_english": "This is going through every channel to set its input level. You match each preamp to how loud the source really plays. Good gain gives a strong, clean signal with room to spare. It is done before tone and effects.", "purpose_function": "It exists to set proper gain structure so each channel has strong signal and safe headroom, which keeps noise low and stops clipping later in the chain.", "practical_application": "The engineer has each musician play at show level and raises each channel's gain until the meter reads healthy, leaving headroom before the clip point.", "category": "Soundcheck Workflow", "related_terms": ["Gain structure", "High-pass pass", "Headroom", "Preamp", "Clipping", "Full soundcheck"], "common_mistakes": ["Setting gain while the source plays softly, so it clips when the act performs at full level.", "UNSAFE: Chasing level by cranking a channel's gain until feedback howls through speakers or in-ears at damaging volume.", "Confusing input gain with the channel fader, and mis-setting the gain structure."], "scenario_contexts": ["Setting input trims across the console at the start of soundcheck.", "Re-gaining the mic of a guest vocalist who sings louder than the check level.", "Establishing gain structure before adding EQ and compression."]}, "aa9331f5-9d92-46c8-9413-da69d5d7af53": {"definition": "A soundcheck or line-check confirmation in which the front-of-house engineer signals that a given input has been received and set satisfactorily at the front-of-house position, clearing the check to move to the next channel. It is used where several positions verify the same split signal in turn.", "plain_english": "It is the front-of-house engineer saying an input is set and fine at their desk. It tells the stage the check can move to the next channel. Several teams may confirm the same input one after another.", "purpose_function": "It exists to coordinate a multi-position check, giving a clear spoken sign-off so line checks move quickly and no input is skipped.", "practical_application": "As each input is tapped, the front-of-house engineer replies 'good at front of house' once the channel reads correctly, and the check advances.", "category": "Soundcheck Communication", "related_terms": ["Good at monitors", "Good at record", "Line check", "Changeover line check", "Splitter", "Talkback"], "common_mistakes": ["Calling an input good before confirming it is the right channel and not a mis-patch.", "Confirming on level alone, without listening for hum, noise, or distortion.", "Not speaking clearly on talkback, so the stage moves on before you are ready."], "scenario_contexts": ["A split show where front of house, monitors, and record each confirm inputs.", "Confirming each channel during a fast festival line check.", "Signing off vocal mics before the band plays."]}, "c9ed72d3-e65e-4ae7-977f-c1bb25f70ac0": {"definition": "A soundcheck or line-check confirmation in which the monitor engineer signals that a given input has been received and set satisfactorily at the monitor console, clearing the check to advance. It is used where front-of-house, monitors, and sometimes record each verify the same split signal in turn.", "plain_english": "It is the monitor engineer saying an input is set and fine at their desk. Monitors carry the sound the band hears on stage. This sign-off lets the line check move to the next input.", "purpose_function": "It exists to coordinate the multi-position check from the monitor world, confirming the input the performers will hear is present and correct before moving on.", "practical_application": "During a line check the monitor engineer answers 'good at monitors' once a channel arrives correctly at the stage console, so the check can continue.", "category": "Soundcheck Communication", "related_terms": ["Good at front of house", "Good at record", "Monitor mix", "Line check", "Splitter", "In-ear monitor"], "common_mistakes": ["Confirming an input before checking it is routed to the correct monitor mixes.", "Approving on signal presence alone, without listening for noise or the wrong source.", "UNSAFE: Pushing a channel loud in in-ear monitors to confirm it, risking a sudden damaging level in a performer's ears."], "scenario_contexts": ["A split show where monitors, front of house, and record confirm inputs in turn.", "Confirming each wedge or in-ear feed during a line check.", "Signing off inputs at the monitor desk during a festival changeover."]}, "e26d9aa5-f7f6-4631-abe0-87080b0de0f2": {"definition": "A soundcheck or line-check confirmation in which the recording or broadcast engineer signals that a given input has been received and set satisfactorily at the record or broadcast position, clearing the check to advance. It applies where a split feed also goes to a multitrack or broadcast rig alongside front of house and monitors.", "plain_english": "It is the recording engineer saying an input is set and fine at the record rig. Live shows are often captured to multitrack or broadcast. This sign-off confirms that feed is ready before moving on.", "purpose_function": "It exists so the capture position can confirm each split input is present and set, making sure the recording or broadcast has every channel before the show starts.", "practical_application": "As each input is checked, the record engineer replies 'good at record' once the channel arrives and levels correctly at the multitrack or broadcast console.", "category": "Soundcheck Communication", "related_terms": ["Good at front of house", "Good at monitors", "Line check", "Splitter", "Multitrack recording", "Broadcast feed"], "common_mistakes": ["Confirming presence without arming the correct record track for that input.", "Checking level only, missing a polarity or wrong-source problem on the split.", "Assuming front-of-house settings apply, when the record feed is a separate isolated split."], "scenario_contexts": ["A broadcast or live recording taking an isolated split of the stage inputs.", "Confirming every channel is armed and levelled before a multitrack capture.", "A remote truck signing off inputs during a line check."]}, "d425ab98-dbee-4ca4-b4b2-db0dc6027146": {"definition": "A systematic sweep through the input channels to engage and set high-pass (low-cut) filters, removing unwanted low-frequency energy such as stage rumble, handling noise, and proximity buildup from channels that do not need low end. It is typically done early in soundcheck, before detailed equalization, to clean up the mix.", "plain_english": "This is going through channels to switch on low-cut filters. It removes deep rumble and boominess from inputs that do not need bass. Cutting that low mess makes the whole mix cleaner. It is done early, before fine tone shaping.", "purpose_function": "It exists to clear low-frequency clutter across many channels, freeing headroom and reducing rumble and feedback so the low end stays clean and controlled.", "practical_application": "The engineer sets a high-pass filter on vocals, overheads, and other mics around 80 to 120 Hz, moving higher on thin sources, while leaving kick and bass full-range.", "category": "Soundcheck Workflow", "related_terms": ["High-pass filter", "Gain pass", "Low-cut filter", "Equalization", "Proximity effect", "Feedback"], "common_mistakes": ["Applying a high-pass filter to the kick drum or bass and losing the low end.", "Setting the filter too high on vocals, making them sound thin.", "Assuming a high-pass filter removes feedback by itself, when it only reduces low-frequency energy."], "scenario_contexts": ["Cleaning stage rumble from vocal and overhead mics during soundcheck.", "Reducing low-frequency buildup before setting channel EQ.", "Freeing subwoofer headroom by cutting lows on non-bass channels."]}, "a4f13d9c-0d25-4979-abdd-267eb43a00cf": {"definition": "The soundcheck and optimization practice of producing a source - a musical instrument, backline, or the system's excitation signal - at the actual level it will reach during the performance, so that gain structure, EQ, monitor levels, feedback behavior, and loudspeaker/room response are all assessed under realistic, level-dependent conditions rather than at a quiet rehearsal level.", "plain_english": "Check the system while it is as loud as the real show. A guitar or a speaker acts differently soft versus loud. So set your levels at true show volume, not a quiet test.", "purpose_function": "It keeps setup decisions valid at performance level, because gain, feedback, limiter action, and loudspeaker behavior all change with level, and perceived tonal balance shifts with loudness. Adjustments made quietly can fail when the band plays hard.", "practical_application": "A technician asks the drummer or guitarist to play as hard as they will in the show before setting gains and monitors, and a system engineer excites the PA with pink noise or music at show SPL when tuning.", "category": "Measurement & Calibration", "related_terms": ["Known state", "Music check", "Monitor pass", "Gain structure", "Soundcheck"], "common_mistakes": ["Setting gains and EQ while the musician plays quietly, then finding feedback and clipping once they play at full volume.", "Assuming a limiter's or loudspeaker's behavior at low level predicts its behavior at show level.", "UNSAFE: Running extended tuning at show SPL close to the ears without hearing protection, risking noise-induced hearing loss."], "scenario_contexts": ["Soundcheck where the band plays a full-energy song so FOH can set true gain structure.", "System tuning where the PA is driven at show SPL so limiter and room effects are captured."]}, "dda431ae-6f60-490f-b002-eccaa6f061af": {"definition": "A documented, repeatable baseline configuration in which every relevant parameter - levels, EQ, dynamics, routing, and mutes - sits at a defined and recorded value, so the system's behavior is predictable and any subsequent change can be measured against a trusted reference.", "plain_english": "This is a setup where you know every single setting. It is like a saved starting point. If things go wrong, you can return to it and compare.", "purpose_function": "It gives a trusted reference so faults can be isolated and changes evaluated. You should never troubleshoot or tune a system whose settings are unknown.", "practical_application": "Before tuning, a technician resets processors to unity and flat, then documents it, establishing a known state to measure from; consoles are recalled to a known state before each show.", "category": "Measurement & Calibration", "related_terms": ["Last-known-good file", "Unity gain", "Signal flow", "System verification", "Recall"], "common_mistakes": ["Beginning to troubleshoot without first returning the system to a known state, so results cannot be trusted.", "Assuming default settings equal a known state when undocumented tweaks may remain in the signal path.", "Not writing down the baseline, so it cannot be reproduced later."], "scenario_contexts": ["The start of system optimization, with all processing reset flat and documented.", "Troubleshooting a fault by returning each device to a known state to isolate the change."]}, "51909f4e-fa04-422e-90e4-045ea2936a78": {"definition": "A dedicated run through a console or system during which every channel, input, output, bus, and scene is named clearly and consistently, performed as a single focused task during show preparation so paths are identifiable at a glance.", "plain_english": "You go through the mixer once just to name each channel. Clear names like 'Kick' or 'Lead Vocal' stop mix-ups. You do it all in one focused sweep.", "purpose_function": "It makes every signal path instantly identifiable, which speeds operation and prevents wrong-fader errors during the pressure of a live show.", "practical_application": "During patching or virtual soundcheck, the technician does a label pass so channel names match the input list and stage plot before doors open.", "category": "Console Preparation", "related_terms": ["Mute pass", "Notes pass", "Input list", "Patch list", "Channel strip"], "common_mistakes": ["Leaving default names such as 'Ch 12', causing wrong-fader mistakes during the show.", "Labels that do not match the input list or stage plot.", "Labeling only inputs and skipping outputs, buses, and scenes."], "scenario_contexts": ["Console prep before a festival changeover, aligning labels to the input list.", "Building a template file in which every channel is pre-labeled."]}, "2ad6a0e1-aee2-44f8-882f-733d7c54341b": {"definition": "The most recent saved show or session file that was confirmed to work correctly, retained as a fallback so the system can be restored to a verified working configuration if a later file becomes corrupted, misconfigured, or fails to load.", "plain_english": "This is the last saved show file you know worked. If a new file breaks, you load this one. It is a safety copy to fall back on.", "purpose_function": "It provides fast recovery from corruption, a bad edit, or a crash without rebuilding the show from scratch, minimizing downtime and risk during an event.", "practical_application": "A technician saves incrementally and keeps a backup on external media; if the console crashes or a file will not load, they reload the last-known-good file to restore a working show.", "category": "Show File Management", "related_terms": ["Known state", "Show file", "Snapshot", "Incremental save", "Backup"], "common_mistakes": ["Overwriting the only good file, leaving no fallback after a bad edit.", "Never testing the backup, so it fails to load when it is actually needed.", "Keeping the backup only on the console rather than also on external media."], "scenario_contexts": ["A console crash mid-festival, reloading the last-known-good file to restore the show.", "A corrupted save discovered on load, reverting to the previous verified file."]}, "4538ce10-4711-445e-8a20-f545d2461b36": {"definition": "A quick line-check technique in which a technician lightly taps or scratches a microphone's grille to confirm the mic is live, correctly patched, and producing signal at the intended console channel or measurement analyzer.", "plain_english": "You gently tap a mic to check it works. You watch the meter jump on the right channel. It is a fast way to confirm the mic is plugged in and routed correctly.", "purpose_function": "It verifies signal presence and correct routing one input at a time before soundcheck, catching patch and labeling errors early.", "practical_application": "During line check, a stagehand taps each mic while the engineer confirms that the correct channel shows signal on the meter and is labeled correctly; the same check confirms a measurement mic registers in the analyzer.", "category": "Line Check", "related_terms": ["Line check", "Label pass", "Patch list", "Phantom power", "Soundcheck"], "common_mistakes": ["Blowing into a microphone instead of tapping it, which can damage ribbon and condenser capsules.", "Hard-tapping a fragile ribbon or condenser mic instead of gently scratching the grille or speaking into it.", "Tapping the mic but not confirming which channel actually receives the signal."], "scenario_contexts": ["Line check before soundcheck, tapping each mic to verify patch and labeling.", "Confirming a measurement microphone registers in the analyzer before a transfer-function measurement."]}, "2acddfed-649b-4103-952e-6be871e82416": {"definition": "A focused stage of soundcheck dedicated to building and refining the performers' monitor mixes - wedges or in-ear monitors - by setting sends and levels and ringing out feedback, handled separately from the front-of-house mix.", "plain_english": "This is the soundcheck step for what the players hear on stage. You set each person's own mix. It is done on its own, apart from the crowd mix.", "purpose_function": "It ensures each performer can hear what they need to play well, while controlling stage volume and feedback, before attention shifts to the audience mix.", "practical_application": "The monitor engineer works through each performer's requests during the monitor pass, building wedge and in-ear mixes and ringing out feedback-prone wedges.", "category": "Soundcheck Workflow", "related_terms": ["Monitor mix", "In-ear monitors", "Wedge", "Feedback", "Ring out"], "common_mistakes": ["Building monitor mixes too loud, which raises stage volume and feedback risk for the whole show.", "UNSAFE: Sending a sudden high-level signal into in-ear monitors while they are in a performer's ears, risking hearing injury.", "Setting monitors before the source is at show level, so the mixes change once the band plays hard."], "scenario_contexts": ["Soundcheck where each musician gets their wedge or in-ear mix set.", "Ringing out a vocal wedge to raise gain-before-feedback."]}, "ac609ed3-de20-43a2-9bca-b3b27f2078ba": {"definition": "Playing familiar, well-produced reference music through the sound system to judge and refine overall tonal balance, coverage, imaging, and level, typically as a subjective verification after measurement-based tuning and before or between acts.", "plain_english": "You play songs you know well through the PA to judge the sound. Familiar songs show if it is too bright, dull, or uneven. It is an ear check after the meters.", "purpose_function": "It gives a real-program, subjective cross-check of the tuning, catching tonal or coverage problems that measurements alone may miss, using a known reference.", "practical_application": "After tuning with pink noise and an analyzer, the system technician plays reference tracks over the PA and walks the coverage area to confirm even, natural sound.", "category": "System Verification", "related_terms": ["Known state", "System tuning", "Reference track", "Pink noise", "Coverage"], "common_mistakes": ["Judging the system with unfamiliar tracks, so system coloration cannot be told apart from the recording.", "Using heavily compressed or low-quality files as the reference.", "Not walking the room, so uneven coverage goes unnoticed."], "scenario_contexts": ["A final check after system tuning, playing reference tracks while walking the coverage area.", "Playing music between soundcheck and doors to confirm the system sounds right at show level."]}, "03449af6-1ac9-4f23-924d-bb51e80e33f2": {"definition": "A single focused run through the console to set every channel's mute state correctly for the start of a show or scene, verifying that only intended inputs are open and all unused channels are muted.", "plain_english": "You go through the mixer once to set which channels are on or off. Turn on only what you need. Mute the rest to cut noise and mistakes.", "purpose_function": "It stops unused open mics from adding noise, comb filtering, and feedback, and sets a clean, predictable starting point for the show.", "practical_application": "Before doors, the engineer does a mute pass so only the intro channels are live, while unused inputs and offstage mics stay muted in the opening scene.", "category": "Console Preparation", "related_terms": ["Label pass", "Notes pass", "Mute group", "Scene", "Gain before feedback"], "common_mistakes": ["Leaving unused mics open, which adds stage noise, comb filtering, and feedback risk.", "Muting a channel needed at the top of the show, causing a missed cue.", "Confusing a channel mute with a mute-group state, so a channel stays open unexpectedly."], "scenario_contexts": ["Setting the opening scene so only the intro inputs are unmuted.", "Cleaning up a template by muting all unused channels before patching."]}, "69869aae-06f6-4fdf-9fa8-26ccc5865de8": {"definition": "A dedicated stage in which the engineer reviews and works through the list of notes - problems, requests, and adjustments recorded during soundcheck or a previous show - resolving each item before the performance.", "plain_english": "You go back through your list of notes and fix each one. In soundcheck you jot down problems. Later you work the list so nothing is forgotten.", "purpose_function": "It ensures issues and requests captured earlier are actually resolved rather than lost, improving reliability from one show to the next.", "practical_application": "After soundcheck the engineer does a notes pass, adjusting an EQ a singer asked about, fixing a buzzing DI, or updating a snapshot, checking off each item.", "category": "Soundcheck Workflow", "related_terms": ["Label pass", "Mute pass", "Soundcheck", "Snapshot", "Show file"], "common_mistakes": ["Taking notes but never working through them before the show.", "Keeping notes only in memory, so items are forgotten under pressure.", "Marking an item done without verifying that the fix actually worked."], "scenario_contexts": ["Post-soundcheck cleanup, resolving each logged issue before doors.", "A pre-show review of notes carried over from the previous night."]}, "5cb4cc90-b812-4c9a-b230-db23373bffa1": {"definition": "'One at a time' is the practice of checking, measuring, or optimising a single input, loudspeaker, or subsystem in isolation before adding the next one, so any fault or interaction can be attributed to a known source. In soundcheck it is the line-check approach of bringing up one channel at a time; in system optimisation it is measuring each loudspeaker or subsystem alone before taking combined measurements.", "plain_english": "You test one thing at a time instead of everything at once. Bring up one microphone or speaker, check it, then move to the next. If something is wrong, you know which one caused it. It stops problems from hiding behind each other.", "purpose_function": "It isolates each source so a fault or unexpected response can be traced to one channel or loudspeaker rather than the whole system. This makes troubleshooting and tuning faster and more reliable.", "practical_application": "During a line check the engineer unmutes one input at a time to confirm signal, gain, and phantom power before the band plays together.", "category": "Soundcheck procedure", "related_terms": ["Line check", "Soundcheck", "Gain structure", "Polarity pass", "Phantom pass", "System optimization"], "common_mistakes": ["Unmuting several inputs at once, so you cannot tell which channel has the problem.", "Skipping the individual check and going straight to the full band, which hides faults.", "Forgetting to re-mute a channel before moving on to the next one."], "scenario_contexts": ["Line-checking a drum kit one microphone at a time before the band plays.", "Measuring each loudspeaker alone before taking a combined system measurement.", "Tracing a buzz by bringing up inputs individually until it appears."]}, "8f1d47d2-c328-4f2d-b93c-237358a96dea": {"definition": "A partial soundcheck is a soundcheck in which only some of a system's inputs, instruments, or subsystems are checked rather than the full input list and complete performance setup. It is used when time, personnel, or stage access is limited, typically covering only the sources that have changed or that most affect the mix, with the remaining channels set from a saved show file.", "plain_english": "A partial soundcheck means you check only some sound sources, not all of them. Teams do this when time is short. They test the most important or newly changed inputs. The rest are set from a saved file.", "purpose_function": "It exists to get a system usable when there is not enough time to check everything, by focusing effort on the inputs that matter most or have changed. It trades completeness for speed.", "practical_application": "At a festival with tight changeovers the engineer checks only vocals, kick, and snare, then relies on the saved show file for the remaining inputs.", "category": "Soundcheck procedure", "related_terms": ["Soundcheck", "Line check", "Show file", "Changeover", "Virtual soundcheck", "Input list"], "common_mistakes": ["Assuming a partial check means the whole system is verified, when untested inputs may still fail.", "Not recalling or loading the saved settings for the inputs that were skipped.", "Skipping feedback-margin or phantom-power checks on channels that were not tested."], "scenario_contexts": ["A festival changeover where only the headline inputs get checked.", "Rechecking only the channels that changed since the last show.", "A corporate event where only the lectern mic and playback are tested before doors."]}, "70b0c47e-eb7f-4e22-b253-8a2f3d10b9a4": {"definition": "A phantom pass is a systematic check across a console's input channels to confirm that phantom power (typically 48 V, P48) is switched on for every source that requires it - condenser microphones and active direct boxes - and switched off for sources that do not, such as ribbon microphones. It is one step in preparing and verifying an input list before or during soundcheck.", "plain_english": "A phantom pass is a check that the 48-volt power is on for every microphone that needs it. Condenser mics and active DI boxes need this power to work. You go channel by channel and switch it on where needed. You also make sure it is off where it could cause damage.", "purpose_function": "It ensures every channel that needs phantom power actually has it, so condenser mics and active DIs work, while keeping it off channels where it could cause damage or noise. This prevents dead or faulty inputs from being discovered mid-show.", "practical_application": "Before soundcheck the engineer steps through the input list, enabling 48 V on each condenser and active-DI channel and confirming it is off on ribbon and line inputs.", "category": "Soundcheck procedure", "related_terms": ["Phantom power", "Condenser microphone", "Direct box (DI)", "Ribbon microphone", "Line check", "Input list"], "common_mistakes": ["UNSAFE: Applying phantom power to a vintage ribbon microphone, which can damage its element.", "UNSAFE: Toggling phantom power with channels unmuted and faders up, sending a loud thump that can harm ears and drivers.", "Assuming phantom power reaches the mic when a patchbay, splitter, or transformer blocks it."], "scenario_contexts": ["Verifying phantom power on all condenser overheads before a drum check.", "Confirming a DI box that needs phantom is powered when its signal is missing.", "Checking that phantom power is off before patching a ribbon microphone."]}, "f623df51-fe22-4293-9a95-7ad3f2e86073": {"definition": "A playback check is the practice of playing known recorded material - reference music or program content - through the sound system to confirm that playback sources, routing, and the main system are working, and to judge the system's tonal balance and coverage against a familiar reference. It verifies the playback signal path and provides a consistent, repeatable source when live sources are not available.", "plain_english": "A playback check means playing a known recording through the PA to test it. Because you know how the track should sound, problems stand out. It confirms the music player and routing work. It also lets you judge the system's tone before the band arrives.", "purpose_function": "It provides a consistent, repeatable audio source to verify the playback path and to evaluate system tone and coverage without needing live musicians. Familiar material makes faults and tonal issues easy to hear.", "practical_application": "An engineer plays a well-known reference track through the mains and walks the room to check coverage and tonal balance before soundcheck.", "category": "Soundcheck procedure", "related_terms": ["Reference track", "Playback soundcheck", "Program material", "System tuning", "Coverage", "Pink noise"], "common_mistakes": ["Judging the system with an unfamiliar or poorly mastered track, so you cannot separate system from source.", "Checking at a level far below show level, which hides balance problems that appear when loud.", "Assuming a good playback check means every live input is also ready."], "scenario_contexts": ["Playing a reference song to set overall EQ and level before doors.", "Confirming the walk-in music laptop is routed and audible.", "Comparing left and right coverage with a familiar stereo track."]}, "54098275-ee88-46fb-b1c4-9a48fefd4113": {"definition": "A playback soundcheck (a form of virtual soundcheck) is a soundcheck carried out by playing a previously recorded multitrack of the performance back into the console's input channels - via a DAW or the console's own recorder - instead of using live musicians, so the engineer can build and refine the mix, tune the system, and test signal paths without the band present. Each recorded track returns on its normal channel, reproducing the real inputs.", "plain_english": "A playback soundcheck uses a recording of the band instead of the live players. Each recorded track plays back on its own channel, just like the real inputs. This lets the engineer set the mix and tune the system without the musicians. It helps when the band cannot be there in time.", "purpose_function": "It lets an engineer set levels, EQ, effects, and system tuning using a realistic multitrack when the band is unavailable or stage time is short. It also frees the musicians from long soundchecks.", "practical_application": "Using a multitrack captured at the last show, the engineer runs a playback soundcheck to rebuild the mix in a new room before the band arrives.", "category": "Soundcheck procedure", "related_terms": ["Virtual soundcheck", "Multitrack recording", "Record check", "Playback check", "Show file", "DAW"], "common_mistakes": ["Forgetting that playback bypasses stage sources, so mic-placement and bleed differences are not captured.", "Routing the recorded tracks to the wrong channels, so the mix does not match the live patch.", "Tuning the system to a recording made in a different room without allowing for the new acoustics."], "scenario_contexts": ["Rebuilding a festival mix from last night's multitrack before the set.", "Training a new engineer on the show mix without the band present.", "Testing new plug-ins or console settings against a real recording."]}, "2f2bf7a7-0e55-49ef-b8f7-0c289ef8979d": {"definition": "A polarity pass is a systematic check through a system's inputs, cables, and loudspeakers to confirm that polarity (the plus/minus orientation of each signal) is consistent, with no reversed connections that would cause signals to subtract rather than add. It is performed with a polarity tester, a dual-channel measurement system, or by ear, and catches miswired cables, reversed drivers, and inverted channels.", "plain_english": "A polarity pass checks that every signal's plus and minus are wired the right way round. If one is flipped, sounds cancel instead of add, and bass gets weak. You step through inputs and speakers to find any that are reversed. A tester makes this quick.", "purpose_function": "It ensures sources and loudspeakers add together instead of cancelling, which protects low-frequency level and overall coherence. Catching a reversed connection early prevents a weak, hollow sound at showtime.", "practical_application": "Using a polarity tester through the rig, the technician sends a pulse down each line and confirms every input and loudspeaker reads correct polarity.", "category": "Soundcheck procedure", "related_terms": ["Polarity", "Phase", "Polarity tester", "Loudspeaker", "Time alignment", "Transfer function"], "common_mistakes": ["Confusing polarity, a fixed plus/minus flip, with phase, which changes with frequency.", "Checking only the inputs and forgetting the loudspeakers, or the reverse.", "Trusting a single test signal through a multiway speaker, where separate drivers may differ."], "scenario_contexts": ["Running a polarity tester down every microphone line before a show.", "Confirming that all boxes in an array share the same polarity.", "Finding a reversed speaker cable that made the subs sound thin."]}, "fd9387c5-272a-4905-8b9d-7a8ea1f4fbac": {"definition": "A post-soundcheck save is the step of storing the console's current settings - as a scene, snapshot, show file, or session - immediately after soundcheck is finished, usually with a backup to external media, so the tuned state can be recalled for the performance and recovered if the console is reset or fails. It captures gains, EQ, dynamics, routing, and mix levels as verified during soundcheck.", "plain_english": "A post-soundcheck save means saving the console settings right after soundcheck. It stores all the levels, EQ, and routing you just set. If the desk crashes or gets reset, you can load it back fast. Most engineers also save a copy to a USB drive.", "purpose_function": "It preserves the verified soundcheck state so it can be recalled for the show and restored quickly after a reset or failure. Saving a backup off the console guards against data loss.", "practical_application": "As soon as soundcheck ends the engineer stores the scene, names it clearly, and copies the show file to a USB stick before doors open.", "category": "Soundcheck procedure", "related_terms": ["Show file", "Scene recall", "Snapshot", "Backup", "Soundcheck", "Console"], "common_mistakes": ["Making live changes after the save without re-saving, so the backup no longer matches the desk.", "Overwriting the previous good file instead of saving a new, named version.", "Keeping the only copy on the console, with no external backup."], "scenario_contexts": ["Saving and naming the show scene right after soundcheck.", "Copying the show file to USB as a backup before the performance.", "Restoring the saved file after a console reboot during a changeover."]}, "1f90b061-d76d-499f-ba21-702727be09e3": {"definition": "A problem song is a song in a performance's set list that consistently exposes mixing or system difficulties - such as feedback, dynamic extremes, a dense arrangement, or tonal imbalance - and is therefore run deliberately during soundcheck to test and refine the mix and system for those conditions. Checking with the most demanding material helps ensure the system holds up at the show's hardest moments.", "plain_english": "A problem song is the song in the set that is hardest to mix well. It might be very loud, very quiet, or very busy. Engineers check it on purpose during soundcheck. If the system handles the worst song, the easier ones are safe.", "purpose_function": "It exists to test the system and mix against the most demanding material in the set rather than only easy songs. Solving the hardest case first makes the rest of the show more reliable.", "practical_application": "The engineer asks the band to run their loudest, most dynamic number in soundcheck to set limiter thresholds and gain-before-feedback margins.", "category": "Soundcheck procedure", "related_terms": ["Soundcheck", "Feedback", "Gain before feedback", "Headroom", "Reference track", "Dynamic range"], "common_mistakes": ["Soundchecking only easy songs, so problems surface for the first time during the show.", "Fixing the problem song at the expense of every other song's balance.", "Not noting the settings that solved the problem song for later recall."], "scenario_contexts": ["Running the band's loudest song to set safe limiter thresholds.", "Checking a quiet ballad where feedback and noise are most exposed.", "Testing a dense song to confirm the lead vocal stays intelligible."]}, "947ee89c-0c4a-4f81-8567-23c489e04b92": {"definition": "A record check is the step of confirming that a multitrack recording or capture system is correctly armed and capturing every intended input - with signal present on each track, sensible levels, no clipping, and the correct sample rate and routing - before relying on that recording, for example for a playback (virtual) soundcheck or a show archive. It verifies the record signal path end to end.", "plain_english": "A record check makes sure the recorder is really capturing every channel. You confirm each track shows signal at a safe level, with no clipping. You do this before the show or before a playback soundcheck. It stops you finding out too late that nothing was recorded.", "purpose_function": "It ensures the capture system is truly recording all inputs at usable levels before it is needed, so a virtual soundcheck or show archive is not lost to a routing or arm error. It catches silent or clipped tracks early.", "practical_application": "Before a show the engineer arms all tracks, confirms meters move on every input, and records a short test to verify the files are written correctly.", "category": "Soundcheck procedure", "related_terms": ["Multitrack recording", "Virtual soundcheck", "Playback soundcheck", "Clipping", "Sample rate", "DAW"], "common_mistakes": ["Arming the transport but not the individual tracks, so nothing is captured.", "Recording at levels so hot that tracks clip and become unusable.", "Not playing back a test capture to confirm the files actually saved."], "scenario_contexts": ["Verifying every channel records before a show you plan to virtual-soundcheck from.", "Checking a stage-box-to-DAW capture over a network before doors.", "Confirming sample rate and routing match between console and recorder."]}, "5ced8410-0710-455a-ab83-6f5173b6d22f": {"definition": "A rolling soundcheck is a live-sound workflow in which acts or inputs are checked in quick, continuous succession rather than in one long dedicated block. It is most common at festivals and multi-act shows, where each band gets only a brief line check during the changeover and the engineer refines the system and mix on the fly as the performance begins. It trades a full stationary soundcheck for speed, keeping the schedule moving while still verifying signal and setting gain.", "plain_english": "A rolling soundcheck checks each act quickly, one after another. It is common at festivals with many bands. There is no time for a long, separate check. The engineer sets levels fast and fixes the mix as the show starts.", "purpose_function": "It exists to get many acts through with usable sound when there is no time for a full soundcheck. It keeps a tight festival schedule moving while still confirming that each input works and is roughly set.", "practical_application": "At a festival changeover, a technician does a fast line check on the new band, sets gain on the key channels, then trims the system and monitors during the first song.", "category": "Soundcheck workflow", "related_terms": ["Line check", "Soundcheck", "Changeover", "Virtual soundcheck", "Monitor mix", "Gain structure"], "common_mistakes": ["Treating a rolling soundcheck like a full soundcheck and running out of time before doors.", "Skipping the line check, so a dead or mis-patched channel is not found until the band is playing.", "Setting gain from a single quiet one-two and having no headroom once the band plays at full level."], "scenario_contexts": ["Running back-to-back acts on a festival stage with 20-minute changeovers.", "A multi-band club night where only the headliner gets a real soundcheck.", "A corporate event where several speakers and a band share one short check window."]}, "5347dafb-be7f-4721-b46e-589077c42e3b": {"definition": "A routing pass is a systematic check through a console's or system's signal routing in which the engineer verifies, step by step, that every input is patched and assigned to its correct destinations - input channels, groups, aux/monitor sends, matrices, main outputs, and any recording or broadcast feeds - before or early in soundcheck. It confirms the signal path end to end so that no source is mis-patched, unrouted, or duplicated.", "plain_english": "A routing pass is a careful check of where every signal goes. You follow each input from its channel to every output it should feed. This catches wrong or missing patches before the show. Think of it as tracing each wire on a map.", "purpose_function": "It exists to confirm the whole signal path is correct before you rely on it, since one mis-patch can silence or misdirect a source. Doing it as one deliberate pass catches routing errors early, not mid-show.", "practical_application": "After loading a show file, a technician steps through each channel to confirm its patch, group and aux assignments, and output routing before line check.", "category": "Signal routing", "related_terms": ["Patching", "Signal flow", "Line check", "Bus", "Matrix routing", "Aux send"], "common_mistakes": ["Assuming a recalled show file is routed correctly and skipping the pass entirely.", "Checking that inputs make sound but not confirming they reach every needed output, like monitors or a recording feed.", "Leaving old routing from a previous show, so a channel feeds the wrong bus."], "scenario_contexts": ["Verifying a recalled festival file matches the actual stage patch.", "Confirming every input also feeds the multitrack recorder before the set.", "Tracing why a vocal is present at FOH but missing from a monitor mix."]}, "26ccb9db-1469-4264-9d06-bbde46f93e7d": {"definition": "'Run the closer' is an instruction, during soundcheck or a system-tuning rehearsal, for the band to play the last (closing) song of their set - typically the biggest, loudest, or most demanding number - so the engineer can check that the system, mix, and any programmed scenes hold up under the show's peak conditions.", "plain_english": "'Run the closer' means play the last song of the set. This song is often the loudest and busiest. The engineer uses it to test the system at its hardest moment. It shows if anything breaks up when everything runs at once.", "purpose_function": "It exists to test the system and mix under the show's most demanding moment before the audience arrives. Checking the finale early avoids surprises when levels, effects, and cues all peak at the end.", "practical_application": "A technician asks the band to play the closer to confirm the mains and monitors have headroom, limiters behave, and the closing scene recalls correctly.", "category": "Soundcheck workflow", "related_terms": ["Soundcheck", "Run the opener", "Run the loud song", "Headroom", "Scene recall", "Limiter"], "common_mistakes": ["Only checking mid-set songs, so the loud, busy finale is never tested until the show.", "Running the closer far below show level, which hides headroom and limiter problems.", "Forgetting to test the closing scene or cue that the song triggers."], "scenario_contexts": ["Confirming the loud closing number does not overload the mains or subs.", "Rehearsing the final scene recall on the console before doors.", "Testing monitor levels for a big singalong closer."]}, "53a0158e-8d64-4704-9d90-df3a1b80b318": {"definition": "'Run the loud song' is an instruction, during soundcheck, for the performers to play their loudest, highest-energy material so the engineer can assess the system at maximum realistic level - checking headroom, amplifier and limiter behaviour, subwoofer output, feedback margin, and overall SPL - and set the mix and system protection for worst-case conditions.", "plain_english": "'Run the loud song' means play your loudest number. The engineer needs to hear the system at its peak. This checks for distortion, clipping, and feedback when things get loud. It sets safe limits before the real show.", "purpose_function": "It exists to reveal how the system behaves at its highest levels, where clipping, limiting, and feedback appear. Setting for the worst case protects the gear and keeps the sound clean all night.", "practical_application": "A technician has the band play their loudest song to set limiter thresholds, confirm headroom, and check that no channel or output clips at show level.", "category": "Soundcheck workflow", "related_terms": ["Headroom", "Limiter", "Clipping", "Gain structure", "Feedback", "Sound pressure level (SPL)"], "common_mistakes": ["Setting gain and limiters from quiet playing, then clipping when the loud song finally hits.", "UNSAFE: Running the loud song at full concert SPL in an empty room without hearing protection, risking hearing damage.", "Judging low-end from one loud song without checking subwoofer headroom."], "scenario_contexts": ["Setting drive-rack limiters so the PA is protected at peak level.", "Checking feedback margin on vocal mics during the loudest number.", "Confirming the subs have headroom for a bass-heavy song."]}, "e0d5317b-d7eb-476c-b4f7-5923149479e1": {"definition": "'Run the opener' is an instruction, during soundcheck, for the band to play the first (opening) song of the set so the engineer can set the system and mix for the exact conditions at the top of the show - the moment the audience first hears the act. It is often used to finish a soundcheck, leaving the console and system set for the show's start.", "plain_english": "'Run the opener' means play the first song of the set. The engineer sets everything for the very start of the show. That first moment is what the crowd hears first. Ending the check on it leaves the desk ready to go.", "purpose_function": "It exists to set the mix and system for the show's opening, the first impression the audience gets. Finishing on the opener leaves every level and scene ready for the top of the set.", "practical_application": "A technician finishes soundcheck by running the opener, then saves that scene so the desk recalls the correct starting state before the show.", "category": "Soundcheck workflow", "related_terms": ["Soundcheck", "Run the closer", "Scene recall", "Console snapshot", "Set list", "Line check"], "common_mistakes": ["Ending soundcheck on a random song, leaving the desk set wrong for the actual first number.", "Not saving the opener's settings as a scene, so the start of the show is set from memory.", "Forgetting that the opener may need different monitor levels than the song checked last."], "scenario_contexts": ["Finishing a soundcheck set for the top of the show, per common FOH practice.", "Saving an opening scene so the console recalls it before the band walks on.", "Setting intro effects or a cold vocal for the first song."]}, "289dd576-1faf-4fc6-b828-6957074934e5": {"definition": "'Run the quiet song' is an instruction, during soundcheck, for the performers to play their quietest, most dynamic or sparse material so the engineer can check the system at low level - the noise floor, hum and buzz, gate and expander behaviour, intelligibility, and gain-before-feedback with open microphones - conditions a loud song can mask.", "plain_english": "'Run the quiet song' means play your softest number. Soft moments show problems that loud songs hide. The engineer listens for hiss, hum, and feedback with mics open. It also checks that quiet vocals stay clear and easy to hear.", "purpose_function": "It exists to test the system where loud material cannot - at low level, where noise, hum, and feedback stand out. It also confirms quiet passages stay clear and intelligible.", "practical_application": "A technician has the band play a quiet song to check the noise floor, set gate thresholds, and confirm vocals stay intelligible with the mics open.", "category": "Soundcheck workflow", "related_terms": ["Noise floor", "Gain before feedback", "Noise gate", "Dynamic range", "Intelligibility", "Run the loud song"], "common_mistakes": ["Only checking loud material, so hum and hiss are not noticed until a quiet moment on stage.", "Setting gate thresholds from loud playing, so gates chatter or cut off soft notes.", "Pushing gain so high in quiet parts that the system rings or feeds back."], "scenario_contexts": ["Checking the noise floor and hum before an acoustic intro.", "Setting noise gates on drums using a soft passage.", "Confirming a whispered or spoken section stays intelligible."]}, "62d65ddf-7a20-4f75-94d0-921bb0b6901b": {"definition": "'Run the set' is an instruction to play through the entire show set, in order, either live at soundcheck or via recorded multitrack in a virtual soundcheck, so the engineer can rehearse and verify the whole mix, all scene/snapshot changes, and system behaviour from start to finish rather than checking isolated songs.", "plain_english": "'Run the set' means play the whole show from start to finish. It can be the live band or a recording of them. The engineer checks every song and every change in order. This makes sure nothing is missed before the real show.", "purpose_function": "It exists to test the complete show as it will actually run, including every transition and scene change, not just single songs. This catches problems that only appear in sequence.", "practical_application": "Using a recorded multitrack for a virtual soundcheck, a technician runs the set to rehearse fader moves and confirm every scene recalls correctly.", "category": "Soundcheck workflow", "related_terms": ["Virtual soundcheck", "Set list", "Scene recall", "Console snapshot", "Run the transitions", "Multitrack recording"], "common_mistakes": ["Only checking a few songs, so a mid-set scene change fails during the show.", "Running the set once and not saving the corrected scenes.", "Relying on an old recording whose channel list no longer matches the live patch."], "scenario_contexts": ["Rehearsing a full show mix from a recorded multitrack before doors.", "Checking every snapshot in order on a theatre or musical production.", "Tuning system and mix over a whole set during a production day."]}, "8f8fe3c9-2fc8-4757-a557-666e690f6b9f": {"definition": "'Run the transitions' is an instruction to rehearse only the joins between songs or scenes - the moments where the console recalls a new snapshot/scene, mute groups change, inputs swap, or tempo and level shift - so the engineer can confirm these changes happen cleanly and on cue without gaps, pops, or wrong states.", "plain_english": "'Run the transitions' means practice only the changes between songs. These are the risky moments when settings switch fast. The engineer checks that each change is clean and on time. It is like rehearsing the handoffs, not the whole race.", "purpose_function": "It exists to test the risky moments between songs, where scene recalls and mute changes can go wrong. Rehearsing just the joins makes cue changes reliable during the show.", "practical_application": "A technician steps through each song-to-song change to confirm the right scene recalls, mutes fire, and no channel pops or is left in the wrong state.", "category": "Soundcheck workflow", "related_terms": ["Scene recall", "Console snapshot", "Mute group", "Cue", "Run the set", "Set list"], "common_mistakes": ["Checking songs in isolation but never the change between them, so a bad recall shows up live.", "Leaving a channel muted or on the wrong scene after a transition.", "Recalling a scene that overwrites a level the engineer just set by hand."], "scenario_contexts": ["Rehearsing snapshot changes between numbers in a musical.", "Checking a fast segue where inputs swap from one act to the next.", "Confirming mute groups fire cleanly between songs."]}, "f891b976-978e-4592-8620-37975e0ec538": {"definition": "Sandbagging soundcheck is an informal term for a soundcheck in which the performers hold back - playing more quietly, less fully, or less energetically than they will during the show - so that the levels, gain structure, and mix the engineer sets are not representative of actual performance conditions and must be corrected once the band plays for real.", "plain_english": "Sandbagging a soundcheck is when a band plays softer or easier than they will live. 'Sandbagging' means holding back on purpose. The settings the engineer makes then do not match the real show. So the mix has to be fixed once the band plays for real.", "purpose_function": "Naming this problem warns engineers that a soundcheck done below show intensity gives false settings. It reminds crews to insist on representative levels so the show is not the first true test.", "practical_application": "When a technician notices the band is sandbagging, they ask for the loudest song at real level, then reset gain, limiters, and monitor sends to match show conditions.", "category": "Soundcheck workflow", "related_terms": ["Soundcheck", "Run the loud song", "Gain structure", "Headroom", "Monitor mix", "Feedback"], "common_mistakes": ["Trusting soundcheck levels from a band that played at half volume, then scrambling when the show is far louder.", "Not asking for the loudest, fullest material, so feedback and clipping first appear during the show.", "Blaming the system for problems really caused by non-representative check levels."], "scenario_contexts": ["A band that plays softly at soundcheck but hits full volume on stage.", "A singer who marks vocals lightly at check, then belts during the show.", "A drummer who taps at check but plays hard live, changing gate and gain needs."]}, "365502c9-c3ad-45d4-8456-2190e7f1a503": {"definition": "To adjust the analog input gain of a channel's head amp (HA) — the microphone/line preamplifier stage on a mixing console — so the source arrives at the correct working level. On Yamaha and similar digital consoles this parameter is labelled HA gain and is set as high as possible without lighting the meter's OVER/clip segment at the loudest input.", "plain_english": "The head amp is the first volume knob for each input. Setting it means turning up each mic just enough to be strong but not distort.", "purpose_function": "It sets correct gain structure at the very first stage of the signal path, giving a strong signal-to-noise ratio while leaving headroom so peaks do not clip the preamp or converter.", "practical_application": "During line check the engineer sets each channel's head amp gain while the performer plays or sings at show level, watching the input meter to stay below clipping.", "category": "Gain Structure", "related_terms": ["Gain structure", "Signal present", "Line check", "Clip indicator", "Headroom", "Input gain"], "common_mistakes": ["Setting head amp gain by ear at a quiet level, then finding it clips once the performer plays at full volume.", "Using the channel fader to make up for a badly set head amp instead of correcting the gain itself.", "Confusing head amp analog gain with digital trim or fader level, so the gain structure ends up wrong.", "UNSAFE: Cranking head amp gain feeding a monitor or in-ear mix, causing sudden loud feedback that can damage hearing."], "scenario_contexts": ["Line-checking a drum kit before doors, setting each mic's head amp as the drummer hits at show level.", "Rebalancing a guest vocalist's channel whose head amp was left too low by the previous act.", "Setting head amp gain on a networked stagebox so the shared analog gain suits both FOH and monitors."]}, "8a4910c5-51e0-4c8d-a316-dbdecc5586b7": {"definition": "The condition in which an audio system and its control setup have been fully patched, line-checked, gain-structured and verified, with all known faults resolved and settings stored, so the performance can begin without further preparation.", "plain_english": "It means everything is checked, working and set, so the show could start right now. Nothing is left to fix or plug in.", "purpose_function": "It marks a clear finish line for setup and handover, confirming the system is safe, routed and stored so the performance can start reliably on cue.", "practical_application": "Before doors open, the engineer confirms the rig is show-ready: patch verified, console file loaded, levels set, and any problem channels fixed.", "category": "Soundcheck Workflow", "related_terms": ["System check", "Soundcheck", "Line check", "Show file", "Signal present", "Stop and fix"], "common_mistakes": ["Calling a system show-ready before every input has been line-checked, so a dead channel appears mid-show.", "Forgetting to save the console file, so a power cycle loses the show-ready settings.", "Assuming show-ready once audio simply passes, without checking backup or redundant signal paths."], "scenario_contexts": ["A touring engineer reports the rig show-ready to the stage manager once patch, gains and mix are set.", "At a festival, each act's console file is loaded and verified to a show-ready state before changeover ends.", "A house tech leaves a venue system show-ready so a visiting band can plug in and start quickly."]}, "2418d51d-1df3-49df-a5b8-329d02097bbc": {"definition": "An indication that audio signal above a low reference threshold is reaching a given point in the chain, usually shown by a 'signal' or 'signal present' LED or meter segment. On amplifiers and processors the indicator commonly lights at a set level below rated output — for example about 30 dB below full output on some QSC amplifiers.", "plain_english": "It shows that sound is actually reaching a device, not silence. A small light or meter turns on once even a quiet signal arrives.", "purpose_function": "It gives fast, at-a-glance confirmation that a stage is receiving audio, so a technician can see where signal stops when tracing a fault.", "practical_application": "During line check the engineer plays or taps a source and watches the signal-present LEDs at the stagebox, console and amplifier to confirm the path is unbroken.", "category": "Signal Indication", "related_terms": ["Clip indicator", "Metering", "Line check", "Signal chain", "Set head amp", "Source check"], "common_mistakes": ["Assuming signal present means correct level; the light only shows that some signal exists, not proper gain.", "Reading a clip LED as signal present, or the reverse, and misjudging the actual level.", "Forgetting that a signal-present light can be lit by hum or noise rather than the intended source."], "scenario_contexts": ["Tracing a dead vocal channel by following the signal-present LEDs from mic to amplifier.", "Confirming a Dante or MADI stream is live by watching signal-present meters at the receiving device.", "Checking that a playback source reaches the console before the signal-present indicator is trusted for the mix."]}, "56dbeb9b-6803-42dd-8246-840e4a9820c7": {"definition": "A familiar, well-known piece of music that the performers play, or that is played back, during soundcheck so the engineer can set and judge the mix using realistic, representative program material rather than isolated notes.", "plain_english": "It is a song the band knows well, played during soundcheck. It lets the engineer set the sound using real music, not just single notes.", "purpose_function": "It provides consistent, full-band program material so the engineer can balance levels, tone and effects the way they will behave during the actual performance.", "practical_application": "After line check, the engineer asks the band to play a soundcheck song that spans their loudest and quietest moments so the mix is set for the real range.", "category": "Soundcheck Workflow", "related_terms": ["Soundcheck", "Line check", "Show-ready state", "System check", "Ring out", "Reference track"], "common_mistakes": ["Choosing a soundcheck song that is not representative, so the mix falls apart on louder or busier numbers.", "Playing the soundcheck song far quieter than the show, giving levels that do not match the performance.", "Relying only on recorded playback and never checking the live band's own soundcheck song."], "scenario_contexts": ["A band runs a full soundcheck song so the engineer can set vocal-to-band balance before doors.", "A monitor engineer uses the soundcheck song to build each performer's in-ear mix.", "A support act with a short slot picks one dynamic soundcheck song to cover the whole set's range."]}, "c4db6677-fde9-4542-a453-f76f2ce55fdc": {"definition": "The stage of setup in which each input source is confirmed to be connected, correctly routed to its intended channel, and producing signal, usually by activating each source in turn and verifying it appears where expected.", "plain_english": "It is checking that every mic and instrument is plugged in and shows up on the right channel. You test each input one by one.", "purpose_function": "It verifies input connectivity and routing before mixing begins, catching dead, swapped or mispatched sources early rather than during the show.", "practical_application": "During line check the engineer runs a source check, having each input activated in turn while confirming the correct channel shows signal present.", "category": "Soundcheck Workflow", "related_terms": ["Line check", "Signal present", "Patch", "Start at channel one", "System check", "Set head amp"], "common_mistakes": ["Skipping the source check and only discovering a swapped or dead input during the performance.", "Confirming a source is present but not that it lands on the correct channel.", "Doing the source check only at the console, missing a fault at the stagebox or splitter."], "scenario_contexts": ["Before soundcheck, the tech runs a source check so every mic maps to its labelled channel.", "After a stagebox is repatched, a source check confirms nothing was crossed.", "At a festival changeover, a quick source check verifies the incoming act's inputs."]}, "3c46ea4a-cd3e-4244-81b3-a08a89b5498c": {"definition": "The line-check convention of verifying inputs in a fixed sequence, beginning at channel one and working upward, so every channel is checked in order and none is accidentally skipped.", "plain_english": "It means checking inputs in order, starting with the first channel. Going one by one stops you from missing any input.", "purpose_function": "It imposes a repeatable, systematic order on the line check so the process stays complete and consistent, reducing the chance of an unchecked channel.", "practical_application": "The engineer starts at channel one and checks each input in turn, calling the channel so the stage tech activates the matching source.", "category": "Soundcheck Workflow", "related_terms": ["Line check", "Source check", "Signal present", "Stop and fix", "Set head amp", "Show-ready state"], "common_mistakes": ["Jumping around the channel list instead of working in order, then losing track of what was checked.", "Starting at channel one but not agreeing the channel order with the stage tech first.", "Skipping spare, playback or effects-return channels because the count started only at the obvious inputs."], "scenario_contexts": ["A large festival patch is line-checked starting at channel one so all inputs are covered before doors.", "Two techs coordinate over talkback, starting at channel one to stay in sync.", "A new engineer follows the start-at-channel-one habit to build a reliable line-check routine."]}}$ape$::jsonb)) d WHERE g.id=d.id;
COMMIT;
